CREATE OR REPLACE FUNCTION "public"."acordo_cancelar"("p_acordo_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_acordo public.acordos_pagamento%ROWTYPE;
BEGIN
  SELECT * INTO v_acordo FROM public.acordos_pagamento WHERE id = p_acordo_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Acordo não encontrado.';
  END IF;

  -- COALESCE(..., false): mesmo motivo de acordo_parcela_liquidar — sem
  -- sessão, get_current_org_id() é NULL e o guard tem de falhar fechado.
  IF NOT COALESCE(
    v_acordo.org_id = public.get_current_org_id() AND public.has_renting_faturacao_access(),
    false
  ) THEN
    RAISE EXCEPTION 'Sem permissão para cancelar este acordo.';
  END IF;

  IF v_acordo.estado NOT IN ('ativo', 'incumprimento') THEN
    RAISE EXCEPTION 'Só é possível cancelar um acordo ativo ou em incumprimento (estado atual: %).', v_acordo.estado;
  END IF;

  -- Nenhuma parcela pode já ter dinheiro registado — cancelar um acordo com
  -- pagamentos em curso deixaria recibos/liquidacao_pendente órfãos, sem
  -- acordo vivo a que pertencer. Cancela-se só um acordo "limpo" (erro de
  -- criação); um acordo com progresso real fica fora do âmbito desta correção.
  IF EXISTS (
    SELECT 1 FROM public.acordo_parcelas
     WHERE acordo_id = p_acordo_id AND estado NOT IN ('agendada', 'avisada', 'vencida')
  ) THEN
    RAISE EXCEPTION 'Não é possível cancelar: existem parcelas com pagamento já registado.';
  END IF;

  UPDATE public.acordos_pagamento SET estado = 'cancelado' WHERE id = p_acordo_id;
  UPDATE public.acordo_parcelas SET estado = 'cancelada' WHERE acordo_id = p_acordo_id;

  IF v_acordo.cessao_aplicada THEN
    INSERT INTO public.conta_movimentos
      (org_id, entidade_id, tipo, valor, origem, contrato_id, acordo_id, descricao)
    SELECT v_acordo.org_id, v_acordo.titular_id, 'debito', v_acordo.valor_total, 'cessao',
           cc.contrato_id, v_acordo.id, 'Reversão de cessão (acordo cancelado)'
      FROM public.contrato_cobrancas cc WHERE cc.id = v_acordo.cobranca_id;

    IF v_acordo.responsavel_motorista_id IS NOT NULL THEN
      INSERT INTO public.motorista_financeiro
        (org_id, motorista_id, tipo, categoria, descricao, valor, data_movimento, status, acordo_id)
      VALUES
        (v_acordo.org_id, v_acordo.responsavel_motorista_id, 'credito', 'outro',
         'Reversão de cessão (acordo cancelado)', v_acordo.valor_total, current_date, 'pendente', v_acordo.id);
    ELSE
      INSERT INTO public.conta_movimentos
        (org_id, entidade_id, tipo, valor, origem, contrato_id, acordo_id, descricao)
      SELECT v_acordo.org_id, v_acordo.responsavel_cliente_id, 'credito', v_acordo.valor_total, 'cessao',
             cc.contrato_id, v_acordo.id, 'Reversão de cessão (acordo cancelado)'
        FROM public.contrato_cobrancas cc WHERE cc.id = v_acordo.cobranca_id;
    END IF;

    UPDATE public.acordos_pagamento SET cessao_aplicada = false WHERE id = p_acordo_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."acordo_cancelar"("p_acordo_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acordo_cancelar"("p_acordo_id" "uuid") IS 'Cancela um acordo sem pagamentos registados e reverte a cessão de dívida se foi aplicada (par crédito/débito inverso ao de acordo_criar). Recusa se qualquer parcela já tiver pagamento registado.';



CREATE OR REPLACE FUNCTION "public"."acordo_cancelar_por_fatura_anulada"("p_cobranca_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_acordo public.acordos_pagamento%ROWTYPE;
BEGIN
  SELECT * INTO v_acordo FROM public.acordos_pagamento
   WHERE cobranca_id = p_cobranca_id AND estado IN ('ativo', 'incumprimento')
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF NOT COALESCE(
    v_acordo.org_id = public.get_current_org_id() AND public.has_renting_faturacao_access(),
    false
  ) THEN
    RAISE EXCEPTION 'Sem permissão para cancelar este acordo.';
  END IF;

  UPDATE public.acordo_parcelas
     SET estado = 'cancelada'
   WHERE acordo_id = v_acordo.id
     AND estado <> 'cancelada';

  UPDATE public.acordos_pagamento
     SET estado = 'cancelado',
         observacoes = NULLIF(
           trim(both ' | ' from COALESCE(observacoes, '') || ' | ' ||
                'Cancelado automaticamente — fatura de origem anulada.'),
           ''
         )
   WHERE id = v_acordo.id;

  IF v_acordo.cessao_aplicada THEN
    INSERT INTO public.conta_movimentos
      (org_id, entidade_id, tipo, valor, origem, contrato_id, acordo_id, descricao)
    SELECT v_acordo.org_id, v_acordo.titular_id, 'debito', v_acordo.valor_total, 'cessao',
           cc.contrato_id, v_acordo.id, 'Reversão de cessão (fatura anulada)'
      FROM public.contrato_cobrancas cc WHERE cc.id = v_acordo.cobranca_id;

    IF v_acordo.responsavel_motorista_id IS NOT NULL THEN
      INSERT INTO public.motorista_financeiro
        (org_id, motorista_id, tipo, categoria, descricao, valor, data_movimento, status, acordo_id)
      VALUES
        (v_acordo.org_id, v_acordo.responsavel_motorista_id, 'credito', 'outro',
         'Reversão de cessão (fatura anulada)', v_acordo.valor_total, current_date, 'pendente', v_acordo.id);
    ELSE
      INSERT INTO public.conta_movimentos
        (org_id, entidade_id, tipo, valor, origem, contrato_id, acordo_id, descricao)
      SELECT v_acordo.org_id, v_acordo.responsavel_cliente_id, 'credito', v_acordo.valor_total, 'cessao',
             cc.contrato_id, v_acordo.id, 'Reversão de cessão (fatura anulada)'
        FROM public.contrato_cobrancas cc WHERE cc.id = v_acordo.cobranca_id;
    END IF;

    UPDATE public.acordos_pagamento SET cessao_aplicada = false WHERE id = v_acordo.id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."acordo_cancelar_por_fatura_anulada"("p_cobranca_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acordo_cancelar_por_fatura_anulada"("p_cobranca_id" "uuid") IS 'Fecha incondicionalmente o acordo de pagamento (e todas as parcelas) da cobrança indicada, quando a fatura de origem é anulada — ao contrário de acordo_cancelar, nunca recusa por já haver pagamentos registados. Reverte a cessão se aplicada. No-op silencioso se não houver acordo ativo para esta cobrança.';



CREATE OR REPLACE FUNCTION "public"."acordo_criar"("p_cobranca_id" "uuid", "p_responsavel_papel" "text", "p_responsavel_id" "uuid", "p_parcelas" "jsonb", "p_frequencia" "text", "p_dia_vencimento" smallint DEFAULT NULL::smallint, "p_aviso_antecedencia_dias" smallint DEFAULT 3, "p_observacoes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cob      public.contrato_cobrancas%ROWTYPE;
  v_saldo    numeric(12,2);
  v_soma     numeric(12,2);
  v_acordo   uuid;
  v_titular  public.clientes%ROWTYPE;
  v_resp_nome text;
  v_invoice  uuid;
  v_org      uuid;
  v_ja_cedido_a_este boolean;
  p          jsonb;
BEGIN
  SELECT * INTO v_cob FROM public.contrato_cobrancas WHERE id = p_cobranca_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cobrança não encontrada.';
  END IF;
  v_org := v_cob.org_id;

  IF v_cob.estado NOT IN ('emitida','paga') THEN
    RAISE EXCEPTION 'Só é possível parcelar uma cobrança já emitida (estado atual: %).', v_cob.estado;
  END IF;

  -- Fatura-Recibo já nasce liquidada — não há dívida para parcelar.
  IF TRIM(v_cob.descricao) ILIKE 'factura-recibo%' OR TRIM(v_cob.descricao) ILIKE 'fatura-recibo%' THEN
    RAISE EXCEPTION 'Faturas-Recibo (FR) já estão liquidadas e não podem ser parceladas.';
  END IF;

  v_ja_cedido_a_este := v_cob.responsavel_motorista_id IS NOT NULL
    AND p_responsavel_papel = 'motorista'
    AND p_responsavel_id = v_cob.responsavel_motorista_id;

  IF v_cob.responsavel_motorista_id IS NOT NULL AND NOT v_ja_cedido_a_este THEN
    RAISE EXCEPTION
      'Esta fatura já foi cedida a um motorista na emissão — só é possível parcelar para esse mesmo motorista.';
  END IF;

  SELECT id INTO v_invoice FROM public.invoices
   WHERE cobranca_id = p_cobranca_id AND status = 'emitida' AND tipo = 'FT'
   ORDER BY created_at DESC LIMIT 1;

  v_saldo := public.cobranca_saldo_por_liquidar(p_cobranca_id);
  IF v_saldo <= 0.005 THEN
    RAISE EXCEPTION 'Esta fatura não tem saldo por liquidar.';
  END IF;

  IF EXISTS (SELECT 1 FROM public.acordos_pagamento
              WHERE cobranca_id = p_cobranca_id AND estado IN ('ativo','incumprimento')) THEN
    RAISE EXCEPTION 'Esta fatura já tem um acordo de pagamento ativo.';
  END IF;

  IF EXISTS (SELECT 1 FROM public.acordos_pagamento
              WHERE cobranca_id = p_cobranca_id
                AND estado = 'cancelado' AND cessao_aplicada = true) THEN
    RAISE EXCEPTION 'Existe uma cessão de dívida por reverter nesta fatura. Reverta o acordo cancelado antes de criar um novo.';
  END IF;

  IF p_parcelas IS NULL OR jsonb_array_length(p_parcelas) = 0 THEN
    RAISE EXCEPTION 'O plano tem de ter pelo menos uma parcela.';
  END IF;

  IF (SELECT count(*) FROM jsonb_array_elements(p_parcelas) e
       WHERE (e->>'numero')::int > 0) > 24 THEN
    RAISE EXCEPTION 'O plano não pode ter mais de 24 parcelas.';
  END IF;

  SELECT COALESCE(SUM((e->>'valor')::numeric), 0) INTO v_soma
    FROM jsonb_array_elements(p_parcelas) e;

  IF abs(v_soma - v_saldo) >= 0.005 THEN
    RAISE EXCEPTION 'A soma das parcelas (%) não corresponde ao saldo por liquidar (%).',
      v_soma, v_saldo;
  END IF;

  SELECT * INTO v_titular FROM public.clientes WHERE id = v_cob.destinatario_id;

  IF p_responsavel_papel = 'motorista' THEN
    SELECT nome INTO v_resp_nome FROM public.motoristas_ativos WHERE id = p_responsavel_id;
  ELSE
    SELECT nome INTO v_resp_nome FROM public.clientes WHERE id = p_responsavel_id;
  END IF;
  IF v_resp_nome IS NULL THEN
    RAISE EXCEPTION 'Entidade responsável não encontrada.';
  END IF;

  INSERT INTO public.acordos_pagamento (
    org_id, cobranca_id, invoice_id,
    titular_id, titular_nome, titular_nif,
    responsavel_cliente_id, responsavel_motorista_id, responsavel_papel, responsavel_nome,
    valor_total, frequencia, dia_vencimento, aviso_antecedencia_dias, observacoes
  ) VALUES (
    v_org, p_cobranca_id, v_invoice,
    v_cob.destinatario_id, COALESCE(v_titular.nome, v_cob.destinatario_nome), v_titular.nif,
    CASE WHEN p_responsavel_papel = 'motorista' THEN NULL ELSE p_responsavel_id END,
    CASE WHEN p_responsavel_papel = 'motorista' THEN p_responsavel_id ELSE NULL END,
    p_responsavel_papel, v_resp_nome,
    v_saldo, p_frequencia, p_dia_vencimento, COALESCE(p_aviso_antecedencia_dias, 3), p_observacoes
  ) RETURNING id INTO v_acordo;

  FOR p IN SELECT * FROM jsonb_array_elements(p_parcelas) LOOP
    INSERT INTO public.acordo_parcelas (org_id, acordo_id, numero, data_vencimento, valor)
    VALUES (v_org, v_acordo, (p->>'numero')::smallint,
            (p->>'data_vencimento')::date, (p->>'valor')::numeric);
  END LOOP;

  -- ── Cessão de dívida ──────────────────────────────────────────────────
  -- Já cedida a este mesmo motorista na emissão (v_ja_cedido_a_este): a
  -- dívida já está lá — só falta o plano de parcelas, sem novo lançamento
  -- (evitaria duplicar o crédito ao titular e a dívida do motorista).
  IF NOT v_ja_cedido_a_este
     AND NOT (p_responsavel_papel <> 'motorista' AND p_responsavel_id = v_cob.destinatario_id) THEN
    INSERT INTO public.conta_movimentos
      (org_id, entidade_id, tipo, valor, origem, contrato_id, acordo_id, descricao)
    VALUES
      (v_org, v_cob.destinatario_id, 'credito', v_saldo, 'cessao', v_cob.contrato_id, v_acordo,
       'Dívida cedida a ' || v_resp_nome);

    IF p_responsavel_papel = 'motorista' THEN
      INSERT INTO public.motorista_financeiro
        (org_id, motorista_id, tipo, categoria, descricao, valor, data_movimento, status, acordo_id)
      VALUES
        (v_org, p_responsavel_id, 'debito', 'outro',
         'Dívida assumida (cedida por ' || COALESCE(v_titular.nome, '—') || ')',
         v_saldo, current_date, 'pendente', v_acordo);
    ELSE
      INSERT INTO public.conta_movimentos
        (org_id, entidade_id, tipo, valor, origem, contrato_id, acordo_id, descricao)
      VALUES
        (v_org, p_responsavel_id, 'debito', v_saldo, 'cessao', v_cob.contrato_id, v_acordo,
         'Dívida assumida (cedida por ' || COALESCE(v_titular.nome, '—') || ')');
    END IF;

    UPDATE public.acordos_pagamento SET cessao_aplicada = true WHERE id = v_acordo;
  END IF;

  RETURN v_acordo;
END;
$$;


ALTER FUNCTION "public"."acordo_criar"("p_cobranca_id" "uuid", "p_responsavel_papel" "text", "p_responsavel_id" "uuid", "p_parcelas" "jsonb", "p_frequencia" "text", "p_dia_vencimento" smallint, "p_aviso_antecedencia_dias" smallint, "p_observacoes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acordo_criar"("p_cobranca_id" "uuid", "p_responsavel_papel" "text", "p_responsavel_id" "uuid", "p_parcelas" "jsonb", "p_frequencia" "text", "p_dia_vencimento" smallint, "p_aviso_antecedencia_dias" smallint, "p_observacoes" "text") IS 'Cria um acordo de pagamento, as suas parcelas e (se responsável ≠ titular, e ainda não cedida ao mesmo motorista na emissão) os dois movimentos de cessão de dívida — tudo numa só transação. Suporta motorista (TVDE) como responsável desde 30/07/2026, e recusa parcelar para um responsável diferente do motorista a quem a cobrança já foi cedida na emissão (cobranca_ceder_a_motorista).';



CREATE OR REPLACE FUNCTION "public"."acordo_parcela_liquidar"("p_parcela_id" "uuid", "p_invoice_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_parcela public.acordo_parcelas%ROWTYPE;
  v_acordo  public.acordos_pagamento%ROWTYPE;
  v_saldo   numeric(12,2);
BEGIN
  SELECT * INTO v_parcela FROM public.acordo_parcelas WHERE id = p_parcela_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Parcela não encontrada.';
  END IF;

  -- COALESCE(..., false) é obrigatório aqui: sem sessão nenhuma, tanto
  -- auth.role() como get_current_org_id() devolvem NULL, e `NULL = 'x'`
  -- avalia a NULL (não a false). Em PL/pgSQL, `IF NOT (NULL) THEN` NÃO
  -- entra no ramo — o guard falhava ABERTO exactamente para quem não tem
  -- sessão nenhuma, o pior caso possível. O COALESCE fecha isso.
  IF NOT COALESCE(
    auth.role() = 'service_role'
    OR (v_parcela.org_id = public.get_current_org_id() AND public.has_renting_faturacao_access()),
    false
  ) THEN
    RAISE EXCEPTION 'Sem permissão para liquidar esta parcela.';
  END IF;

  IF v_parcela.recibo_id IS NULL THEN
    RAISE EXCEPTION 'A parcela não tem recibo associado — o pagamento não foi registado.';
  END IF;

  -- Idempotente: reprocessar a mesma parcela (retry do worker) não faz mal.
  IF v_parcela.estado = 'paga' THEN
    RETURN;
  END IF;

  UPDATE public.acordo_parcelas
     SET estado = 'paga', invoice_rc_id = p_invoice_id, pago_em = now()
   WHERE id = p_parcela_id;

  SELECT * INTO v_acordo FROM public.acordos_pagamento WHERE id = v_parcela.acordo_id;

  -- Acordo liquidado quando não sobra nenhuma parcela por pagar.
  IF NOT EXISTS (
    SELECT 1 FROM public.acordo_parcelas
     WHERE acordo_id = v_acordo.id AND estado NOT IN ('paga','cancelada')
  ) THEN
    UPDATE public.acordos_pagamento
       SET estado = 'liquidado' WHERE id = v_acordo.id AND estado <> 'cancelado';

    -- A cobrança só fecha se a dívida estiver mesmo coberta. Usa o saldo real
    -- (recibos + NC), não a contagem de parcelas — assim uma NC emitida entretanto
    -- não deixa a cobrança presa em aberto.
    v_saldo := public.cobranca_saldo_por_liquidar(v_acordo.cobranca_id);
    IF v_saldo <= 0.005 THEN
      UPDATE public.contrato_cobrancas
         SET estado = 'paga', pago_em = now()
       WHERE id = v_acordo.cobranca_id AND estado = 'emitida';
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "public"."acordo_parcela_liquidar"("p_parcela_id" "uuid", "p_invoice_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acordo_parcela_liquidar"("p_parcela_id" "uuid", "p_invoice_id" "uuid") IS 'Único caminho que marca uma acordo_parcelas como paga. Idempotente (reprocessar a mesma parcela não faz nada). Fecha o acordo quando não sobram parcelas por pagar, e a cobrança quando o saldo real (cobranca_saldo_por_liquidar) chega a zero. SECURITY DEFINER com guard interno: só service_role ou staff de faturação da mesma org da parcela.';



CREATE OR REPLACE FUNCTION "public"."acordo_parcela_registar_pagamento"("p_parcela_id" "uuid", "p_valor" numeric, "p_data" "date", "p_metodo" "text", "p_entidade_id" "uuid", "p_contrato_id" "uuid", "p_cobranca_id" "uuid", "p_descricao" "text", "p_tem_documento_fiscal" boolean, "p_payload" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_parcela          public.acordo_parcelas%ROWTYPE;
  v_recibo_id        uuid;
  v_acordo_papel     text;
  v_acordo_motorista uuid;
  v_acordo_titular   uuid;
  v_entidade_recibo  uuid;
BEGIN
  SELECT * INTO v_parcela FROM public.acordo_parcelas WHERE id = p_parcela_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Parcela não encontrada.';
  END IF;

  IF NOT COALESCE(
    v_parcela.org_id = public.get_current_org_id() AND public.has_renting_faturacao_access(),
    false
  ) THEN
    RAISE EXCEPTION 'Sem permissão para registar pagamento nesta parcela.';
  END IF;

  IF v_parcela.recibo_id IS NOT NULL
     OR v_parcela.estado NOT IN ('agendada', 'avisada', 'vencida') THEN
    RAISE EXCEPTION 'Esta parcela já tem um pagamento registado ou não está aberta a pagamento (estado: %).', v_parcela.estado;
  END IF;

  -- Responsável lido do PRÓPRIO acordo — nunca confiado ao chamador.
  SELECT responsavel_papel, responsavel_motorista_id, titular_id
    INTO v_acordo_papel, v_acordo_motorista, v_acordo_titular
    FROM public.acordos_pagamento WHERE id = v_parcela.acordo_id;

  v_entidade_recibo := CASE WHEN v_acordo_papel = 'motorista' THEN v_acordo_titular ELSE p_entidade_id END;

  INSERT INTO public.recibos (
    org_id, entidade_id, contrato_id, valor, data_recibo, metodo, referencia, observacoes, estado
  ) VALUES (
    v_parcela.org_id, v_entidade_recibo, p_contrato_id, p_valor, p_data, p_metodo,
    p_cobranca_id::text, p_descricao, 'ativo'
  ) RETURNING id INTO v_recibo_id;

  IF v_acordo_papel = 'motorista' THEN
    INSERT INTO public.conta_movimentos
      (org_id, entidade_id, tipo, valor, origem, contrato_id, acordo_id, recibo_id, descricao)
    VALUES
      (v_parcela.org_id, v_acordo_titular, 'debito', p_valor, 'ajuste', p_contrato_id,
       v_parcela.acordo_id, v_recibo_id,
       'Ajuste — dívida desta parcela é do motorista responsável, não do titular');

    -- status='pendente' (não 'pago'): tem de se compensar, no mesmo balde
    -- somado pelo cartão "Saldo Atual" do motorista, com o débito total da
    -- cessão (também 'pendente') — ver nota (1) no cabeçalho da migração.
    INSERT INTO public.motorista_financeiro
      (org_id, motorista_id, tipo, categoria, descricao, valor, data_movimento, status, acordo_id)
    VALUES
      (v_parcela.org_id, v_acordo_motorista, 'credito', 'outro',
       'Pagamento da parcela ' || v_parcela.numero, p_valor, p_data, 'pendente', v_parcela.acordo_id);
  END IF;

  UPDATE public.acordo_parcelas
     SET estado = 'liquidacao_pendente', recibo_id = v_recibo_id
   WHERE id = p_parcela_id;

  IF NOT p_tem_documento_fiscal THEN
    PERFORM public.acordo_parcela_liquidar(p_parcela_id, NULL);
    RETURN jsonb_build_object('recibo_id', v_recibo_id, 'estado', 'paga');
  END IF;

  INSERT INTO public.faturacao_outbox (
    org_id, tipo, idempotency_key, parcela_id, payload, estado, started_at
  ) VALUES (
    v_parcela.org_id, 'RC', 'RC:parcela:' || p_parcela_id::text, p_parcela_id, p_payload, 'em_curso', now()
  );

  RETURN jsonb_build_object('recibo_id', v_recibo_id, 'estado', 'liquidacao_pendente');
END;
$$;


ALTER FUNCTION "public"."acordo_parcela_registar_pagamento"("p_parcela_id" "uuid", "p_valor" numeric, "p_data" "date", "p_metodo" "text", "p_entidade_id" "uuid", "p_contrato_id" "uuid", "p_cobranca_id" "uuid", "p_descricao" "text", "p_tem_documento_fiscal" boolean, "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acordo_parcela_registar_pagamento"("p_parcela_id" "uuid", "p_valor" numeric, "p_data" "date", "p_metodo" "text", "p_entidade_id" "uuid", "p_contrato_id" "uuid", "p_cobranca_id" "uuid", "p_descricao" "text", "p_tem_documento_fiscal" boolean, "p_payload" "jsonb") IS 'Registo atómico do pagamento de uma parcela. Quando o responsável é um motorista, credita motorista_financeiro com status=pendente (compensa o débito da cessão no mesmo balde) em vez de recibos.entidade_id, que só aceita clientes, e lança um ajuste que anula o crédito automático ao titular.';



CREATE OR REPLACE FUNCTION "public"."acordo_parcela_reverter_pagamento"("p_recibo_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_parcela          public.acordo_parcelas%ROWTYPE;
  v_acordo_papel     text;
  v_acordo_motorista uuid;
  v_acordo_titular   uuid;
  v_valor_recibo     numeric(12,2);
  v_contrato_id      uuid;
BEGIN
  SELECT * INTO v_parcela FROM public.acordo_parcelas WHERE recibo_id = p_recibo_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;

  IF NOT COALESCE(
    v_parcela.org_id = public.get_current_org_id() AND public.has_renting_faturacao_access(),
    false
  ) THEN
    RAISE EXCEPTION 'Sem permissão para reverter esta parcela.';
  END IF;

  SELECT responsavel_papel, responsavel_motorista_id, titular_id
    INTO v_acordo_papel, v_acordo_motorista, v_acordo_titular
    FROM public.acordos_pagamento WHERE id = v_parcela.acordo_id;

  IF v_acordo_papel = 'motorista' THEN
    SELECT valor, contrato_id INTO v_valor_recibo, v_contrato_id
      FROM public.recibos WHERE id = p_recibo_id;

    INSERT INTO public.conta_movimentos
      (org_id, entidade_id, tipo, valor, origem, contrato_id, acordo_id, recibo_id, descricao)
    VALUES
      (v_parcela.org_id, v_acordo_titular, 'credito', v_valor_recibo, 'ajuste', v_contrato_id,
       v_parcela.acordo_id, p_recibo_id, 'Ajuste — reversão (recibo anulado, dívida volta ao motorista)');

    INSERT INTO public.motorista_financeiro
      (org_id, motorista_id, tipo, categoria, descricao, valor, data_movimento, status, acordo_id)
    VALUES
      (v_parcela.org_id, v_acordo_motorista, 'debito', 'outro',
       'Estorno de pagamento (recibo anulado) — parcela ' || v_parcela.numero,
       v_valor_recibo, current_date, 'pendente', v_parcela.acordo_id);
  END IF;

  UPDATE public.acordo_parcelas
     SET estado = CASE WHEN data_vencimento < current_date THEN 'vencida' ELSE 'agendada' END,
         recibo_id = NULL, invoice_rc_id = NULL, pago_em = NULL
   WHERE id = v_parcela.id;

  UPDATE public.faturacao_outbox
     SET estado = 'falhado',
         ultimo_erro = 'Recibo anulado manualmente — idempotency key libertada para nova tentativa',
         idempotency_key = idempotency_key || ':anulado:' || id::text
   WHERE parcela_id = v_parcela.id
     AND estado IN ('pendente', 'em_curso', 'sucesso');
END; $$;


ALTER FUNCTION "public"."acordo_parcela_reverter_pagamento"("p_recibo_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acordo_parcela_reverter_pagamento"("p_recibo_id" "uuid") IS 'Reabre uma parcela e retira a outbox associada. Quando o responsável é um motorista, reverte também o ajuste ao titular e devolve a dívida a motorista_financeiro.';



CREATE OR REPLACE FUNCTION "public"."acordo_vista_devedor"("p_acordo_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_acordo public.acordos_pagamento%ROWTYPE;
  v_autorizado boolean := false;
BEGIN
  SELECT * INTO v_acordo FROM public.acordos_pagamento WHERE id = p_acordo_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Acordo não encontrado.';
  END IF;

  -- Motorista responsável identifica-se por motoristas_ativos.user_id.
  IF v_acordo.responsavel_motorista_id IS NOT NULL THEN
    SELECT EXISTS (SELECT 1 FROM public.motoristas_ativos
                    WHERE id = v_acordo.responsavel_motorista_id AND user_id = auth.uid())
      INTO v_autorizado;
  END IF;

  -- Staff da própria organização também pode ver (pré-visualizar o que o devedor vê).
  -- COALESCE(..., false) pela mesma razão do guard de acordo_parcela_liquidar:
  -- sem sessão, get_current_org_id() é NULL, `uuid = NULL` é NULL, e atribuir
  -- NULL a v_autorizado faria o "IF NOT v_autorizado" seguinte falhar aberto.
  IF NOT v_autorizado THEN
    v_autorizado := COALESCE(v_acordo.org_id = public.get_current_org_id()
                     AND public.has_renting_faturacao_access(), false);
  END IF;

  IF NOT v_autorizado THEN
    RAISE EXCEPTION 'Sem permissão para consultar este acordo.';
  END IF;

  RETURN jsonb_build_object(
    'id', v_acordo.id,
    'codigo', v_acordo.codigo,
    'estado', v_acordo.estado,
    'valor_total', v_acordo.valor_total,
    'falta_pagar', public.cobranca_saldo_por_liquidar(v_acordo.cobranca_id),
    'parcelas', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'numero', p.numero,
        'data_vencimento', p.data_vencimento,
        'valor', p.valor,
        -- 'liquidacao_pendente' é operação interna: para o devedor o pagamento
        -- já foi feito. Mostra-se como 'paga'.
        'estado', CASE WHEN p.estado = 'liquidacao_pendente' THEN 'paga' ELSE p.estado END,
        'tem_recibo', p.invoice_rc_id IS NOT NULL
      ) ORDER BY p.numero)
      FROM public.acordo_parcelas p WHERE p.acordo_id = v_acordo.id
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."acordo_vista_devedor"("p_acordo_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acordo_vista_devedor"("p_acordo_id" "uuid") IS 'Vista do devedor sobre o seu acordo de pagamento. SECURITY DEFINER de âmbito fechado (não existe policy de auto-acesso a clientes/motoristas_ativos para isto). Nunca devolve titular_nif nem estado interno de outbox/API — liquidacao_pendente aparece como paga.';



CREATE OR REPLACE FUNCTION "public"."acordos_manutencao_diaria"("p_hoje" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_incumprimentos int;
  v_liquidados     int;
  v_revisao        int;
BEGIN
  -- ③ Incumprimento: 2+ parcelas vencidas, ou 1 vencida há mais de 30 dias.
  WITH alvo AS (
    SELECT a.id
      FROM public.acordos_pagamento a
     WHERE a.estado = 'ativo'
       AND (
         (SELECT count(*) FROM public.acordo_parcelas p
           WHERE p.acordo_id = a.id AND p.estado = 'vencida') >= 2
         OR EXISTS (SELECT 1 FROM public.acordo_parcelas p
                     WHERE p.acordo_id = a.id AND p.estado = 'vencida'
                       AND p.data_vencimento < p_hoje - 30)
       )
  )
  UPDATE public.acordos_pagamento a SET estado = 'incumprimento'
    FROM alvo WHERE a.id = alvo.id;
  GET DIAGNOSTICS v_incumprimentos = ROW_COUNT;

  -- ④ Liquidados (rede de segurança; o caminho normal é acordo_parcela_liquidar).
  WITH alvo AS (
    SELECT a.id FROM public.acordos_pagamento a
     WHERE a.estado IN ('ativo','incumprimento')
       AND NOT EXISTS (SELECT 1 FROM public.acordo_parcelas p
                        WHERE p.acordo_id = a.id AND p.estado NOT IN ('paga','cancelada'))
  )
  UPDATE public.acordos_pagamento a SET estado = 'liquidado'
    FROM alvo WHERE a.id = alvo.id;
  GET DIAGNOSTICS v_liquidados = ROW_COUNT;

  -- ⑤ Divergência (ex.: NC emitida depois do acordo). NÃO altera valores:
  -- mexer num acordo já aceite pelo devedor é decisão de negócio, não de cron.
  WITH alvo AS (
    SELECT a.id FROM public.acordos_pagamento a
     WHERE a.estado IN ('ativo','incumprimento')
       AND a.precisa_revisao = false
       AND abs(a.valor_total - public.cobranca_saldo_por_liquidar(a.cobranca_id)
               - COALESCE((SELECT SUM(p.valor) FROM public.acordo_parcelas p
                            WHERE p.acordo_id = a.id AND p.estado IN ('paga', 'liquidacao_pendente')), 0)) >= 0.005
  )
  UPDATE public.acordos_pagamento a SET precisa_revisao = true
    FROM alvo WHERE a.id = alvo.id;
  GET DIAGNOSTICS v_revisao = ROW_COUNT;

  RETURN jsonb_build_object(
    'incumprimentos', v_incumprimentos,
    'liquidados', v_liquidados,
    'revisao', v_revisao);
END;
$$;


ALTER FUNCTION "public"."acordos_manutencao_diaria"("p_hoje" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acordos_manutencao_diaria"("p_hoje" "date") IS 'Varrimento diário de acordos_pagamento: promove a incumprimento, liquida como rede de segurança e marca precisa_revisao em caso de divergência de saldo. Idempotente — deriva tudo do estado actual, nunca de "quando correu da última vez". SECURITY DEFINER restrito a service_role (chamada só pelo worker acordos-parcelas-diario via cron).';



