CREATE OR REPLACE FUNCTION "public"."aprovar_candidatura_motorista"("p_candidatura_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_candidatura RECORD;
    v_motorista_id UUID;
BEGIN
    SELECT * INTO v_candidatura
    FROM motorista_candidaturas
    WHERE id = p_candidatura_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Candidatura não encontrada';
    END IF;

    IF v_candidatura.status != 'submetido' THEN
        RAISE EXCEPTION 'Candidatura não está em estado de análise';
    END IF;

    INSERT INTO motoristas_ativos (
        nome, email, telefone, nif, morada, cidade,
        codigo_postal,
        documento_tipo, documento_numero, documento_validade,
        carta_conducao, carta_categorias, carta_validade,
        licenca_tvde_numero, licenca_tvde_validade,
        documento_ficheiro_url, documento_identificacao_verso_url,
        carta_ficheiro_url, carta_conducao_verso_url,
        licenca_tvde_ficheiro_url, registo_criminal_url,
        comprovativo_morada_url, comprovativo_iban_url,
        observacoes, data_contratacao, status_ativo, user_id
    ) VALUES (
        v_candidatura.nome, v_candidatura.email, v_candidatura.telefone,
        v_candidatura.nif, v_candidatura.morada, v_candidatura.cidade,
        v_candidatura.codigo_postal,
        v_candidatura.documento_tipo, v_candidatura.documento_numero,
        v_candidatura.documento_validade,
        v_candidatura.carta_conducao, v_candidatura.carta_categorias,
        v_candidatura.carta_validade,
        v_candidatura.licenca_tvde_numero, v_candidatura.licenca_tvde_validade,
        v_candidatura.documento_ficheiro_url,
        v_candidatura.documento_identificacao_verso_url,
        v_candidatura.carta_ficheiro_url, v_candidatura.carta_conducao_verso_url,
        v_candidatura.licenca_tvde_ficheiro_url, v_candidatura.registo_criminal_url,
        v_candidatura.comprovativo_morada_url, v_candidatura.comprovativo_iban_url,
        v_candidatura.observacoes, CURRENT_DATE, true, v_candidatura.user_id
    )
    RETURNING id INTO v_motorista_id;

    UPDATE motorista_candidaturas
    SET status = 'aprovado', data_decisao = NOW(), decidido_por = auth.uid()
    WHERE id = p_candidatura_id;

    RETURN v_motorista_id;
END;
$$;


ALTER FUNCTION "public"."aprovar_candidatura_motorista"("p_candidatura_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_gestors_from_history"() RETURNS TABLE("lead_id" "uuid", "gestor_nome" "text", "first_interaction" timestamp without time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH first_interactions AS (
    SELECT DISTINCT ON (h.lead_id)
      h.lead_id,
      h.alterado_por,
      h.alterado_em,
      p.nome as gestor_nome
    FROM lead_status_history h
    LEFT JOIN profiles p ON h.alterado_por = p.id
    WHERE h.alterado_por IS NOT NULL 
      AND p.nome IS NOT NULL
    ORDER BY h.lead_id, h.alterado_em ASC
  )
  SELECT 
    fi.lead_id,
    fi.gestor_nome,
    fi.alterado_em as first_interaction
  FROM first_interactions fi
  JOIN leads_dasprent l ON fi.lead_id = l.id
  WHERE l.gestor_responsavel IS NULL OR l.gestor_responsavel = '';
$$;


ALTER FUNCTION "public"."assign_gestors_from_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_lead_on_first_view"("lead_id_param" "uuid", "user_id_param" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  user_name TEXT;
  user_cargo TEXT;
  lead_current_gestor TEXT;
BEGIN
  -- Buscar informações do usuário
  SELECT nome, cargo INTO user_name, user_cargo 
  FROM profiles 
  WHERE id = user_id_param;
  
  -- Se não encontrou o usuário/nome ou não é gestor TVDE, retornar false
  IF user_name IS NULL OR user_cargo != 'Gestor TVDE' THEN
    RETURN FALSE;
  END IF;
  
  -- Buscar o gestor atual do lead
  SELECT gestor_responsavel INTO lead_current_gestor 
  FROM leads_dasprent 
  WHERE id = lead_id_param;
  
  -- Se o lead não existe, retornar false
  IF NOT FOUND THEN
    RETURN FALSE;
  END IF;
  
  -- Se o lead já tem gestor atribuído, retornar false (não pode reatribuir)
  IF lead_current_gestor IS NOT NULL AND lead_current_gestor != '' THEN
    RETURN FALSE;
  END IF;
  
  -- Atribuir o lead apenas ao gestor TVDE que visualizou primeiro
  UPDATE leads_dasprent 
  SET gestor_responsavel = user_name 
  WHERE id = lead_id_param 
    AND (gestor_responsavel IS NULL OR gestor_responsavel = '');
  
  -- Verificar se foi atualizado
  IF FOUND THEN
    -- Registrar no histórico
    INSERT INTO lead_status_history (lead_id, status_anterior, status_novo, alterado_por, observacoes)
    VALUES (lead_id_param, 'novo', 'visualizado', user_id_param, 'Lead atribuído automaticamente na primeira visualização');
    
    RETURN TRUE;
  END IF;
  
  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."assign_lead_on_first_view"("lead_id_param" "uuid", "user_id_param" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."associar_cartao_combustivel"("p_plataforma" "text", "p_card" "text", "p_motorista" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  afetadas integer := 0;
  v_org uuid := public.get_current_org_id();
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Sem organização activa.' USING ERRCODE = '42501';
  END IF;

  IF NOT (public.can_view_financeiro()
          OR public.has_permission(auth.uid(), 'administrativo_cartoes')) THEN
    RAISE EXCEPTION 'Sem permissão para associar cartões de combustível.'
      USING ERRCODE = '42501';
  END IF;

  -- O motorista de destino tem de ser da organização de quem chama.
  IF NOT EXISTS (
    SELECT 1 FROM public.motoristas_ativos
     WHERE id = p_motorista AND org_id = v_org
  ) THEN
    RAISE EXCEPTION 'Motorista não pertence à organização activa.'
      USING ERRCODE = '42501';
  END IF;

  IF p_plataforma = 'bp' THEN
    UPDATE motoristas_ativos
    SET cartao_bp = CASE WHEN COALESCE(cartao_bp,'')='' THEN p_card ELSE cartao_bp || ' / ' || p_card END
    WHERE id = p_motorista;
    UPDATE bp_transacoes SET motorista_id = p_motorista
    WHERE motorista_id IS NULL AND raw_data->>'Nº cartão' = p_card
      AND org_id = v_org;
    GET DIAGNOSTICS afetadas = ROW_COUNT;
  ELSIF p_plataforma = 'repsol' THEN
    UPDATE motoristas_ativos
    SET cartao_repsol = CASE WHEN COALESCE(cartao_repsol,'')='' THEN p_card ELSE cartao_repsol || ' / ' || p_card END
    WHERE id = p_motorista;
    UPDATE repsol_transacoes SET motorista_id = p_motorista
    WHERE motorista_id IS NULL AND card_number = p_card
      AND org_id = v_org;
    GET DIAGNOSTICS afetadas = ROW_COUNT;
  ELSIF p_plataforma = 'edp' THEN
    UPDATE motoristas_ativos
    SET cartao_edp = CASE WHEN COALESCE(cartao_edp,'')='' THEN p_card ELSE cartao_edp || ' / ' || p_card END
    WHERE id = p_motorista;
    UPDATE edp_transacoes SET motorista_id = p_motorista
    WHERE motorista_id IS NULL AND card_number = p_card
      AND org_id = v_org;
    GET DIAGNOSTICS afetadas = ROW_COUNT;
  END IF;

  RETURN afetadas;
END;
$$;


ALTER FUNCTION "public"."associar_cartao_combustivel"("p_plataforma" "text", "p_card" "text", "p_motorista" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."atribuir_cartao_frota"("p_cartao_id" "uuid", "p_motorista_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org    uuid;
  v_tipo   text;
  v_numero text;
begin
  v_org := get_current_org_id();
  if v_org is null then
    raise exception 'Sem organização activa';
  end if;

  if not (
    is_current_user_admin()
    or has_permission(auth.uid(), 'administrativo_cartoes', 'editar')
  ) then
    raise exception 'Sem permissão para gerir cartões de frota';
  end if;

  -- Trava a linha: sem isto, duas atribuições concorrentes do mesmo cartão
  -- passavam ambas e a última ganhava, sem ninguém saber.
  select tipo, numero into v_tipo, v_numero
  from public.cartoes_frota
  where id = p_cartao_id and org_id = v_org
  for update;

  if not found then
    raise exception 'Cartão inexistente ou de outra organização';
  end if;

  if v_tipo not in ('bp', 'repsol', 'edp') then
    raise exception 'Tipo de cartão desconhecido: %', v_tipo;
  end if;

  if not exists (
    select 1 from public.motoristas_ativos
    where id = p_motorista_id and org_id = v_org
  ) then
    raise exception 'Motorista inexistente ou de outra organização';
  end if;

  update public.cartoes_frota
  set motorista_id = p_motorista_id,
      status       = 'em_uso',
      data_entrega = current_date
  where id = p_cartao_id and org_id = v_org;

  update public.motoristas_ativos
  set cartao_bp     = case when v_tipo = 'bp'     then v_numero else cartao_bp end,
      cartao_repsol = case when v_tipo = 'repsol' then v_numero else cartao_repsol end,
      cartao_edp    = case when v_tipo = 'edp'    then v_numero else cartao_edp end
  where id = p_motorista_id and org_id = v_org;
end;
$$;


ALTER FUNCTION "public"."atribuir_cartao_frota"("p_cartao_id" "uuid", "p_motorista_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."atribuir_cartao_frota"("p_cartao_id" "uuid", "p_motorista_id" "uuid") IS 'Atribui um cartão de frota a um motorista: marca o cartão em uso E grava o número na ficha (cartao_<tipo>), numa só transacção. tipo/número vêm do cartão, não do cliente.';



