SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."automation_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "rule_id" "uuid" NOT NULL,
    "org_id" "uuid" NOT NULL,
    "trigger_event_id" "uuid",
    "job_type" "text" DEFAULT 'automation_rule'::"text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "priority" smallint DEFAULT 5 NOT NULL,
    "attempt" smallint DEFAULT 0 NOT NULL,
    "max_attempts" smallint DEFAULT 3 NOT NULL,
    "next_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "entity_table" "text",
    "entity_id" "uuid",
    CONSTRAINT "automation_runs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."automation_runs" OWNER TO "postgres";


COMMENT ON TABLE "public"."automation_runs" IS 'Fila de execução do Automation Executor. Escrita só via automation_runs_claim()/_complete()/_fail() (SECURITY DEFINER) — sem INSERT/UPDATE direto do cliente.';



COMMENT ON COLUMN "public"."automation_runs"."entity_table" IS 'Copiado de domain_events.entity_table no momento da criação do run — usado pela unicidade por regra+entidade.';



COMMENT ON COLUMN "public"."automation_runs"."entity_id" IS 'Copiado de domain_events.entity_id no momento da criação do run.';



CREATE OR REPLACE FUNCTION "public"."automation_runs_claim"("p_max" integer DEFAULT 10) RETURNS SETOF "public"."automation_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_stale record;
begin
  for v_stale in
    select id from public.automation_runs
    where status = 'running' and started_at < now() - interval '15 minutes'
  loop
    perform public.automation_runs_fail(v_stale.id, 'timeout: running há mais de 15 minutos');
  end loop;

  return query
  update public.automation_runs r
  set status = 'running',
      started_at = now(),
      attempt = r.attempt + 1
  from (
    select id
    from public.automation_runs
    where status = 'pending'
      and next_attempt_at <= now()
    order by priority asc, created_at asc
    limit p_max
    for update skip locked
  ) claimed
  where r.id = claimed.id
  returning r.*;
end;
$$;


ALTER FUNCTION "public"."automation_runs_claim"("p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_runs_complete"("p_run_id" "uuid", "p_detalhe" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."automation_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run public.automation_runs;
  v_duracao_ms integer;
begin
  update public.automation_runs
  set status = 'completed', completed_at = now()
  where id = p_run_id
  returning * into v_run;

  v_duracao_ms := extract(epoch from (v_run.completed_at - v_run.started_at)) * 1000;

  insert into public.automation_logs (run_id, rule_id, org_id, evento, detalhe, duracao_ms)
  values (v_run.id, v_run.rule_id, v_run.org_id, 'executada', p_detalhe, v_duracao_ms);

  return v_run;
end;
$$;


ALTER FUNCTION "public"."automation_runs_complete"("p_run_id" "uuid", "p_detalhe" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_runs_fail"("p_run_id" "uuid", "p_error" "text") RETURNS "public"."automation_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run public.automation_runs;
  v_duracao_ms integer;
begin
  select * into v_run from public.automation_runs where id = p_run_id for update;

  if v_run.attempt >= v_run.max_attempts then
    update public.automation_runs
    set status = 'failed', error_message = p_error, completed_at = now()
    where id = p_run_id
    returning * into v_run;

    v_duracao_ms := extract(epoch from (v_run.completed_at - v_run.started_at)) * 1000;

    insert into public.failed_jobs (source_table, source_id, org_id, job_type, payload, attempts, last_error)
    values ('automation_runs', v_run.id, v_run.org_id, v_run.job_type, v_run.payload, v_run.attempt, p_error);
  else
    update public.automation_runs
    set status = 'pending',
        error_message = p_error,
        next_attempt_at = now() + (power(2, v_run.attempt) * interval '1 minute')
    where id = p_run_id
    returning * into v_run;

    v_duracao_ms := null;
  end if;

  insert into public.automation_logs (run_id, rule_id, org_id, evento, detalhe, duracao_ms)
  values (v_run.id, v_run.rule_id, v_run.org_id, 'falhou', jsonb_build_object('erro', p_error, 'attempt', v_run.attempt), v_duracao_ms);

  return v_run;
end;
$$;


ALTER FUNCTION "public"."automation_runs_fail"("p_run_id" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bolt_actualizar_bolt_id_recente"("p_integracao_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_linhas integer;
BEGIN
  WITH candidatos AS (
    SELECT mp.motorista_id, mp.driver_uuid AS uuid_escolhido, 1 AS prioridade, NULL::date AS quando
      FROM public.bolt_mapeamento_motoristas mp
      JOIN public.bolt_drivers d ON d.driver_uuid = mp.driver_uuid
     WHERE d.status = 'active'
       AND (p_integracao_id IS NULL OR mp.integracao_id = p_integracao_id)
    UNION ALL
    SELECT r.motorista_id, r.identificador_motorista, 2, r.periodo_inicio
      FROM public.bolt_resumos_semanais r
     WHERE r.motorista_id IS NOT NULL AND r.identificador_motorista IS NOT NULL
       AND r.periodo_inicio IS NOT NULL AND r.ganhos_brutos_app > 0
       AND (p_integracao_id IS NULL OR r.integracao_id = p_integracao_id)
  ),
  escolhido AS (
    SELECT DISTINCT ON (motorista_id) motorista_id, uuid_escolhido
      FROM candidatos
     ORDER BY motorista_id, prioridade, quando DESC NULLS LAST, uuid_escolhido
  )
  UPDATE public.motoristas_ativos m
     SET bolt_id = e.uuid_escolhido, updated_at = now()
    FROM escolhido e
   WHERE m.id = e.motorista_id
     AND m.bolt_id IS DISTINCT FROM e.uuid_escolhido
     AND NOT EXISTS (
       SELECT 1 FROM public.motoristas_ativos outro
        WHERE outro.org_id = m.org_id AND outro.bolt_id = e.uuid_escolhido AND outro.id <> m.id
     );
  GET DIAGNOSTICS v_linhas = ROW_COUNT;
  RETURN v_linhas;
END;
$$;


ALTER FUNCTION "public"."bolt_actualizar_bolt_id_recente"("p_integracao_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bolt_actualizar_bolt_id_recente"("p_integracao_id" "uuid") IS 'Poe em motoristas_ativos.bolt_id o uuid que a Bolt diz estar active; na falta dele, o da semana mais recente com ganhos. Ver migracao 20260813170000.';



CREATE OR REPLACE FUNCTION "public"."bolt_normalizar_nome"("p_nome" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT NULLIF(btrim(regexp_replace(regexp_replace(lower(translate(coalesce(p_nome,''),
    'áàâãäéèêëíìîïóòôõöúùûüçñÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑ',
    'aaaaaeeeeiiiiooooouuuucnaaaaaeeeeiiiiooooouuuucn')),
    '[^a-z0-9]+',' ','g'), '\s+',' ','g')), '');
$$;


ALTER FUNCTION "public"."bolt_normalizar_nome"("p_nome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bolt_resumo_merge_api"("p_integracao_id" "uuid", "p_org_id" "uuid", "p_periodo_inicio" "date", "p_periodo_fim" "date", "p_identificador_motorista" "text" DEFAULT NULL::"text", "p_motorista_nome" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_telefone" "text" DEFAULT NULL::"text", "p_motorista_id" "uuid" DEFAULT NULL::"uuid", "p_periodo" "text" DEFAULT NULL::"text", "p_ganhos_brutos_app" numeric DEFAULT 0, "p_ganhos_brutos_dinheiro" numeric DEFAULT 0, "p_gorjetas" numeric DEFAULT 0, "p_taxas_cancelamento" numeric DEFAULT 0, "p_comissoes" numeric DEFAULT 0, "p_portagens" numeric DEFAULT 0, "p_taxas_reserva" numeric DEFAULT 0, "p_viagens_terminadas" integer DEFAULT 0, "p_distancia_total_km" numeric DEFAULT 0, "p_distancia_media_km" numeric DEFAULT 0, "p_api_ride_price" numeric DEFAULT NULL::numeric, "p_api_booking_fee" numeric DEFAULT NULL::numeric, "p_api_toll_fee" numeric DEFAULT NULL::numeric, "p_api_cancellation_fee" numeric DEFAULT NULL::numeric, "p_api_tip" numeric DEFAULT NULL::numeric, "p_api_net_earnings" numeric DEFAULT NULL::numeric, "p_api_cash_discount" numeric DEFAULT NULL::numeric, "p_api_in_app_discount" numeric DEFAULT NULL::numeric, "p_api_commission" numeric DEFAULT NULL::numeric, "p_api_orders_total" integer DEFAULT NULL::integer, "p_api_orders_finished" integer DEFAULT NULL::integer, "p_api_orders_cash" integer DEFAULT NULL::integer, "p_api_ride_distance" numeric DEFAULT NULL::numeric) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_chave text; v_periodo text; v_org uuid; v_id uuid; v_linhas integer;
BEGIN
  IF p_integracao_id IS NULL THEN
    RAISE EXCEPTION 'bolt_resumo_merge_api: p_integracao_id e obrigatorio.'; END IF;
  IF p_periodo_inicio IS NULL OR p_periodo_fim IS NULL THEN
    RAISE EXCEPTION 'bolt_resumo_merge_api: periodo_inicio e periodo_fim sao obrigatorios.'; END IF;

  v_periodo := COALESCE(NULLIF(btrim(p_periodo),''),
    to_char(p_periodo_inicio,'YYYY-MM-DD') || ' a ' || to_char(p_periodo_fim,'YYYY-MM-DD'));

  v_chave := COALESCE(NULLIF(btrim(p_identificador_motorista),''),
                      NULLIF(lower(btrim(p_email)),''),
                      public.bolt_normalizar_nome(p_motorista_nome));
  IF v_chave IS NULL THEN
    RAISE EXCEPTION 'bolt_resumo_merge_api: motorista sem identificador, email ou nome (integracao %, periodo %).',
      p_integracao_id, v_periodo; END IF;

  SELECT org_id INTO v_org FROM public.plataformas_configuracao WHERE id = p_integracao_id;
  IF v_org IS NULL THEN v_org := p_org_id;
  ELSIF p_org_id IS NOT NULL AND p_org_id <> v_org THEN
    RAISE EXCEPTION 'bolt_resumo_merge_api: p_org_id (%) nao e a org da integracao % (%).',
      p_org_id, p_integracao_id, v_org; END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'bolt_resumo_merge_api: sem org_id para a integracao %.', p_integracao_id; END IF;

  INSERT INTO public.bolt_resumos_semanais AS r (
    integracao_id, org_id, periodo, periodo_inicio, periodo_fim,
    chave_motorista, identificador_motorista, motorista_nome, email, telefone, motorista_id,
    ganhos_brutos_app, ganhos_brutos_dinheiro, gorjetas, taxas_cancelamento,
    comissoes, portagens, taxas_reserva, viagens_terminadas, distancia_total_km, distancia_media_km,
    ganhos_liquidos, pagamento_previsto,
    api_ride_price, api_booking_fee, api_toll_fee, api_cancellation_fee, api_tip,
    api_net_earnings, api_cash_discount, api_in_app_discount, api_commission,
    api_orders_total, api_orders_finished, api_orders_cash, api_ride_distance,
    fonte_viagens, api_sincronizado_em, updated_at
  ) VALUES (
    p_integracao_id, v_org, v_periodo, p_periodo_inicio, p_periodo_fim,
    v_chave, NULLIF(btrim(p_identificador_motorista),''), NULLIF(btrim(p_motorista_nome),''),
    NULLIF(lower(btrim(p_email)),''), NULLIF(btrim(p_telefone),''), p_motorista_id,
    COALESCE(p_ganhos_brutos_app,0), COALESCE(p_ganhos_brutos_dinheiro,0),
    COALESCE(p_gorjetas,0), COALESCE(p_taxas_cancelamento,0), COALESCE(p_comissoes,0),
    COALESCE(p_portagens,0), COALESCE(p_taxas_reserva,0), COALESCE(p_viagens_terminadas,0),
    COALESCE(p_distancia_total_km,0), COALESCE(p_distancia_media_km,0),
    p_api_net_earnings, p_api_net_earnings,
    p_api_ride_price, p_api_booking_fee, p_api_toll_fee, p_api_cancellation_fee, p_api_tip,
    p_api_net_earnings, p_api_cash_discount, p_api_in_app_discount, p_api_commission,
    p_api_orders_total, p_api_orders_finished, p_api_orders_cash, p_api_ride_distance,
    'api', now(), now()
  )
  ON CONFLICT (integracao_id, periodo, chave_motorista) DO UPDATE SET
    org_id = COALESCE(r.org_id, EXCLUDED.org_id),
    periodo_inicio = COALESCE(EXCLUDED.periodo_inicio, r.periodo_inicio),
    periodo_fim = COALESCE(EXCLUDED.periodo_fim, r.periodo_fim),
    identificador_motorista = COALESCE(r.identificador_motorista, EXCLUDED.identificador_motorista),
    motorista_nome = COALESCE(EXCLUDED.motorista_nome, r.motorista_nome),
    email = COALESCE(EXCLUDED.email, r.email),
    telefone = COALESCE(EXCLUDED.telefone, r.telefone),
    motorista_id = COALESCE(r.motorista_id, EXCLUDED.motorista_id),
    ganhos_brutos_app = EXCLUDED.ganhos_brutos_app,
    ganhos_brutos_dinheiro = EXCLUDED.ganhos_brutos_dinheiro,
    gorjetas = EXCLUDED.gorjetas,
    taxas_cancelamento = EXCLUDED.taxas_cancelamento,
    comissoes = EXCLUDED.comissoes,
    portagens = EXCLUDED.portagens,
    taxas_reserva = EXCLUDED.taxas_reserva,
    viagens_terminadas = EXCLUDED.viagens_terminadas,
    distancia_total_km = EXCLUDED.distancia_total_km,
    distancia_media_km = EXCLUDED.distancia_media_km,
    ganhos_liquidos = COALESCE(EXCLUDED.ganhos_liquidos, r.ganhos_liquidos),
    pagamento_previsto = COALESCE(EXCLUDED.pagamento_previsto, r.pagamento_previsto),
    api_ride_price = EXCLUDED.api_ride_price,
    api_booking_fee = EXCLUDED.api_booking_fee,
    api_toll_fee = EXCLUDED.api_toll_fee,
    api_cancellation_fee = EXCLUDED.api_cancellation_fee,
    api_tip = EXCLUDED.api_tip,
    api_net_earnings = EXCLUDED.api_net_earnings,
    api_cash_discount = EXCLUDED.api_cash_discount,
    api_in_app_discount = EXCLUDED.api_in_app_discount,
    api_commission = EXCLUDED.api_commission,
    api_orders_total = EXCLUDED.api_orders_total,
    api_orders_finished = EXCLUDED.api_orders_finished,
    api_orders_cash = EXCLUDED.api_orders_cash,
    api_ride_distance = EXCLUDED.api_ride_distance,
    fonte_viagens = 'api', api_sincronizado_em = now(), updated_at = now()
  RETURNING r.id INTO v_id;

  GET DIAGNOSTICS v_linhas = ROW_COUNT;
  IF v_id IS NOT NULL THEN PERFORM public.bolt_resumo_recalcular_total(v_id); END IF;
  RETURN v_linhas;
END;
$$;


ALTER FUNCTION "public"."bolt_resumo_merge_api"("p_integracao_id" "uuid", "p_org_id" "uuid", "p_periodo_inicio" "date", "p_periodo_fim" "date", "p_identificador_motorista" "text", "p_motorista_nome" "text", "p_email" "text", "p_telefone" "text", "p_motorista_id" "uuid", "p_periodo" "text", "p_ganhos_brutos_app" numeric, "p_ganhos_brutos_dinheiro" numeric, "p_gorjetas" numeric, "p_taxas_cancelamento" numeric, "p_comissoes" numeric, "p_portagens" numeric, "p_taxas_reserva" numeric, "p_viagens_terminadas" integer, "p_distancia_total_km" numeric, "p_distancia_media_km" numeric, "p_api_ride_price" numeric, "p_api_booking_fee" numeric, "p_api_toll_fee" numeric, "p_api_cancellation_fee" numeric, "p_api_tip" numeric, "p_api_net_earnings" numeric, "p_api_cash_discount" numeric, "p_api_in_app_discount" numeric, "p_api_commission" numeric, "p_api_orders_total" integer, "p_api_orders_finished" integer, "p_api_orders_cash" integer, "p_api_ride_distance" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bolt_resumo_merge_api"("p_integracao_id" "uuid", "p_org_id" "uuid", "p_periodo_inicio" "date", "p_periodo_fim" "date", "p_identificador_motorista" "text", "p_motorista_nome" "text", "p_email" "text", "p_telefone" "text", "p_motorista_id" "uuid", "p_periodo" "text", "p_ganhos_brutos_app" numeric, "p_ganhos_brutos_dinheiro" numeric, "p_gorjetas" numeric, "p_taxas_cancelamento" numeric, "p_comissoes" numeric, "p_portagens" numeric, "p_taxas_reserva" numeric, "p_viagens_terminadas" integer, "p_distancia_total_km" numeric, "p_distancia_media_km" numeric, "p_api_ride_price" numeric, "p_api_booking_fee" numeric, "p_api_toll_fee" numeric, "p_api_cancellation_fee" numeric, "p_api_tip" numeric, "p_api_net_earnings" numeric, "p_api_cash_discount" numeric, "p_api_in_app_discount" numeric, "p_api_commission" numeric, "p_api_orders_total" integer, "p_api_orders_finished" integer, "p_api_orders_cash" integer, "p_api_ride_distance" numeric) IS 'Merge por fonte do resumo semanal Bolt. A API e dona das viagens E do liquido (ganhos_liquidos/pagamento_previsto); o CSV e dono de ganhos_campanha e reembolsos_despesas, que a API nao devolve. ganhos_liquidos e o campo canonico que os ecras leem, venha de onde vier. Ver migracao 20260813210000.';



CREATE OR REPLACE FUNCTION "public"."bolt_resumo_merge_csv"("p_integracao_id" "uuid", "p_org_id" "uuid", "p_periodo_inicio" "date", "p_periodo_fim" "date", "p_valores" "jsonb", "p_periodo" "text" DEFAULT NULL::"text", "p_motorista_id" "uuid" DEFAULT NULL::"uuid", "p_escrever_viagens" boolean DEFAULT NULL::boolean, "p_importado_em" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rec             public.bolt_resumos_semanais%ROWTYPE;
  v_linha           public.bolt_resumos_semanais%ROWTYPE;
  v_chave           text;
  v_periodo         text;
  v_org             uuid;
  v_id              uuid;
  v_linhas          integer := 0;
  v_traz_viagens    boolean;
  v_escreve_viagens boolean;
  v_auth_mode       text;
  v_quando          timestamptz := COALESCE(p_importado_em, now());
BEGIN
  IF p_integracao_id IS NULL THEN
    RAISE EXCEPTION 'bolt_resumo_merge_csv: p_integracao_id e obrigatorio.';
  END IF;
  IF p_periodo_inicio IS NULL OR p_periodo_fim IS NULL THEN
    RAISE EXCEPTION 'bolt_resumo_merge_csv: p_periodo_inicio e p_periodo_fim sao obrigatorios.';
  END IF;

  v_rec := jsonb_populate_record(NULL::public.bolt_resumos_semanais, COALESCE(p_valores, '{}'::jsonb));

  v_periodo := COALESCE(
    NULLIF(btrim(p_periodo), ''),
    to_char(p_periodo_inicio, 'YYYY-MM-DD') || ' a ' || to_char(p_periodo_fim, 'YYYY-MM-DD')
  );

  v_chave := COALESCE(
    NULLIF(btrim(v_rec.chave_motorista), ''),
    NULLIF(btrim(v_rec.identificador_motorista), ''),
    NULLIF(lower(btrim(v_rec.email)), ''),
    public.bolt_normalizar_nome(v_rec.motorista_nome)
  );
  IF v_chave IS NULL THEN
    RAISE EXCEPTION
      'bolt_resumo_merge_csv: linha sem identificador, email ou nome (integracao %, periodo %).',
      p_integracao_id, v_periodo;
  END IF;

  SELECT org_id, auth_mode INTO v_org, v_auth_mode
    FROM public.plataformas_configuracao
   WHERE id = p_integracao_id;

  IF v_org IS NULL THEN
    v_org := p_org_id;
  ELSIF p_org_id IS NOT NULL AND p_org_id <> v_org THEN
    RAISE EXCEPTION
      'bolt_resumo_merge_csv: p_org_id (%) nao e a org da integracao % (%).',
      p_org_id, p_integracao_id, v_org;
  END IF;

  IF v_org IS NULL THEN
    RAISE EXCEPTION
      'bolt_resumo_merge_csv: sem org_id para a integracao %.',
      p_integracao_id;
  END IF;

  v_traz_viagens := COALESCE(
    p_valores ?| ARRAY[
      'ganhos_brutos_app', 'ganhos_brutos_dinheiro', 'gorjetas', 'taxas_cancelamento',
      'comissoes', 'portagens', 'taxas_reserva', 'viagens_terminadas',
      'distancia_total_km', 'distancia_media_km'
    ],
    false
  );
  v_escreve_viagens := COALESCE(p_escrever_viagens, v_traz_viagens);

  IF v_auth_mode = 'oauth' AND p_escrever_viagens IS DISTINCT FROM true THEN
    v_escreve_viagens := false;
  END IF;

  SELECT * INTO v_linha
    FROM public.bolt_resumos_semanais
   WHERE integracao_id = p_integracao_id
     AND periodo = v_periodo
     AND chave_motorista = v_chave
   FOR UPDATE;

  IF FOUND
     AND v_linha.fonte_viagens = 'api'
     AND v_linha.api_sincronizado_em IS NOT NULL
     AND v_linha.api_sincronizado_em > v_quando
  THEN
    v_escreve_viagens := false;
  END IF;

  IF v_linha.id IS NULL THEN
    INSERT INTO public.bolt_resumos_semanais (
      integracao_id, org_id, periodo, periodo_inicio, periodo_fim,
      chave_motorista, identificador_motorista, identificador_individual,
      motorista_nome, email, telefone, motorista_id,
      ganhos_campanha, reembolsos_despesas,
      iva_ganhos_app, iva_ganhos_dinheiro, iva_taxas_cancelamento, iva_taxas_reserva,
      dinheiro_recebido, total_taxas, outras_taxas, reembolsos_passageiros,
      ganhos_liquidos, pagamento_previsto, ganhos_brutos_hora, ganhos_liquidos_hora,
      desconto_comissao_app, desconto_comissao_dinheiro,
      nivel, categorias_ativas, viagens_dinheiro_ativadas, pontuacao_motorista,
      taxa_aceitacao, tempo_online_min, utilizacao,
      taxa_finalizacao_todas, taxa_finalizacao_aceites, classificacao_media,
      raw_data,
      ganhos_brutos_app, ganhos_brutos_dinheiro, gorjetas, taxas_cancelamento,
      comissoes, portagens, taxas_reserva,
      viagens_terminadas, distancia_total_km, distancia_media_km,
      fonte_viagens, fonte_extras, csv_importado_em, updated_at
    ) VALUES (
      p_integracao_id, v_org, v_periodo, p_periodo_inicio, p_periodo_fim,
      v_chave,
      NULLIF(btrim(v_rec.identificador_motorista), ''),
      NULLIF(btrim(v_rec.identificador_individual), ''),
      NULLIF(btrim(v_rec.motorista_nome), ''),
      NULLIF(lower(btrim(v_rec.email)), ''),
      NULLIF(btrim(v_rec.telefone), ''),
      COALESCE(p_motorista_id, v_rec.motorista_id),
      COALESCE(v_rec.ganhos_campanha, 0), COALESCE(v_rec.reembolsos_despesas, 0),
      COALESCE(v_rec.iva_ganhos_app, 0), COALESCE(v_rec.iva_ganhos_dinheiro, 0),
      COALESCE(v_rec.iva_taxas_cancelamento, 0), COALESCE(v_rec.iva_taxas_reserva, 0),
      COALESCE(v_rec.dinheiro_recebido, 0), COALESCE(v_rec.total_taxas, 0),
      COALESCE(v_rec.outras_taxas, 0), COALESCE(v_rec.reembolsos_passageiros, 0),
      COALESCE(v_rec.ganhos_liquidos, 0), COALESCE(v_rec.pagamento_previsto, 0),
      COALESCE(v_rec.ganhos_brutos_hora, 0), COALESCE(v_rec.ganhos_liquidos_hora, 0),
      COALESCE(v_rec.desconto_comissao_app, 0), COALESCE(v_rec.desconto_comissao_dinheiro, 0),
      v_rec.nivel, v_rec.categorias_ativas, v_rec.viagens_dinheiro_ativadas,
      COALESCE(v_rec.pontuacao_motorista, 0), COALESCE(v_rec.taxa_aceitacao, 0),
      COALESCE(v_rec.tempo_online_min, 0), COALESCE(v_rec.utilizacao, 0),
      COALESCE(v_rec.taxa_finalizacao_todas, 0), COALESCE(v_rec.taxa_finalizacao_aceites, 0),
      COALESCE(v_rec.classificacao_media, 0),
      v_rec.raw_data,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.ganhos_brutos_app, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.ganhos_brutos_dinheiro, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.gorjetas, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.taxas_cancelamento, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.comissoes, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.portagens, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.taxas_reserva, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.viagens_terminadas, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.distancia_total_km, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.distancia_media_km, 0) ELSE 0 END,
      CASE WHEN v_escreve_viagens THEN 'csv' ELSE NULL END,
      'csv', v_quando, now()
    )
    ON CONFLICT (integracao_id, periodo, chave_motorista) DO NOTHING
    RETURNING id INTO v_id;

    GET DIAGNOSTICS v_linhas = ROW_COUNT;
  END IF;

  IF v_id IS NULL THEN
    UPDATE public.bolt_resumos_semanais SET
      org_id                  = COALESCE(org_id, v_org),
      periodo_inicio          = COALESCE(p_periodo_inicio, periodo_inicio),
      periodo_fim             = COALESCE(p_periodo_fim, periodo_fim),
      identificador_motorista = COALESCE(NULLIF(btrim(v_rec.identificador_motorista), ''), identificador_motorista),
      identificador_individual = COALESCE(NULLIF(btrim(v_rec.identificador_individual), ''), identificador_individual),
      motorista_nome          = COALESCE(NULLIF(btrim(v_rec.motorista_nome), ''), motorista_nome),
      email                   = COALESCE(NULLIF(lower(btrim(v_rec.email)), ''), email),
      telefone                = COALESCE(NULLIF(btrim(v_rec.telefone), ''), telefone),
      motorista_id            = COALESCE(motorista_id, p_motorista_id, v_rec.motorista_id),

      ganhos_campanha            = COALESCE(v_rec.ganhos_campanha, ganhos_campanha),
      reembolsos_despesas        = COALESCE(v_rec.reembolsos_despesas, reembolsos_despesas),
      iva_ganhos_app             = COALESCE(v_rec.iva_ganhos_app, iva_ganhos_app),
      iva_ganhos_dinheiro        = COALESCE(v_rec.iva_ganhos_dinheiro, iva_ganhos_dinheiro),
      iva_taxas_cancelamento     = COALESCE(v_rec.iva_taxas_cancelamento, iva_taxas_cancelamento),
      iva_taxas_reserva          = COALESCE(v_rec.iva_taxas_reserva, iva_taxas_reserva),
      dinheiro_recebido          = COALESCE(v_rec.dinheiro_recebido, dinheiro_recebido),
      total_taxas                = COALESCE(v_rec.total_taxas, total_taxas),
      outras_taxas               = COALESCE(v_rec.outras_taxas, outras_taxas),
      reembolsos_passageiros     = COALESCE(v_rec.reembolsos_passageiros, reembolsos_passageiros),
      ganhos_liquidos            = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.ganhos_liquidos, ganhos_liquidos) ELSE ganhos_liquidos END,
      pagamento_previsto         = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.pagamento_previsto, pagamento_previsto) ELSE pagamento_previsto END,
      ganhos_brutos_hora         = COALESCE(v_rec.ganhos_brutos_hora, ganhos_brutos_hora),
      ganhos_liquidos_hora       = COALESCE(v_rec.ganhos_liquidos_hora, ganhos_liquidos_hora),
      desconto_comissao_app      = COALESCE(v_rec.desconto_comissao_app, desconto_comissao_app),
      desconto_comissao_dinheiro = COALESCE(v_rec.desconto_comissao_dinheiro, desconto_comissao_dinheiro),
      nivel                      = COALESCE(v_rec.nivel, nivel),
      categorias_ativas          = COALESCE(v_rec.categorias_ativas, categorias_ativas),
      viagens_dinheiro_ativadas  = COALESCE(v_rec.viagens_dinheiro_ativadas, viagens_dinheiro_ativadas),
      pontuacao_motorista        = COALESCE(v_rec.pontuacao_motorista, pontuacao_motorista),
      taxa_aceitacao             = COALESCE(v_rec.taxa_aceitacao, taxa_aceitacao),
      tempo_online_min           = COALESCE(v_rec.tempo_online_min, tempo_online_min),
      utilizacao                 = COALESCE(v_rec.utilizacao, utilizacao),
      taxa_finalizacao_todas     = COALESCE(v_rec.taxa_finalizacao_todas, taxa_finalizacao_todas),
      taxa_finalizacao_aceites   = COALESCE(v_rec.taxa_finalizacao_aceites, taxa_finalizacao_aceites),
      classificacao_media        = COALESCE(v_rec.classificacao_media, classificacao_media),
      raw_data                   = COALESCE(v_rec.raw_data, raw_data),

      ganhos_brutos_app      = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.ganhos_brutos_app, ganhos_brutos_app) ELSE ganhos_brutos_app END,
      ganhos_brutos_dinheiro = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.ganhos_brutos_dinheiro, ganhos_brutos_dinheiro) ELSE ganhos_brutos_dinheiro END,
      gorjetas               = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.gorjetas, gorjetas) ELSE gorjetas END,
      taxas_cancelamento     = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.taxas_cancelamento, taxas_cancelamento) ELSE taxas_cancelamento END,
      comissoes              = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.comissoes, comissoes) ELSE comissoes END,
      portagens              = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.portagens, portagens) ELSE portagens END,
      taxas_reserva          = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.taxas_reserva, taxas_reserva) ELSE taxas_reserva END,
      viagens_terminadas     = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.viagens_terminadas, viagens_terminadas) ELSE viagens_terminadas END,
      distancia_total_km     = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.distancia_total_km, distancia_total_km) ELSE distancia_total_km END,
      distancia_media_km     = CASE WHEN v_escreve_viagens THEN COALESCE(v_rec.distancia_media_km, distancia_media_km) ELSE distancia_media_km END,
      fonte_viagens          = CASE WHEN v_escreve_viagens THEN 'csv' ELSE fonte_viagens END,

      fonte_extras           = 'csv',
      csv_importado_em       = v_quando,
      updated_at             = now()
    WHERE integracao_id = p_integracao_id
      AND periodo = v_periodo
      AND chave_motorista = v_chave
    RETURNING id INTO v_id;

    GET DIAGNOSTICS v_linhas = ROW_COUNT;
  END IF;

  IF v_id IS NOT NULL THEN
    PERFORM public.bolt_resumo_recalcular_total(v_id);
  END IF;

  RETURN v_linhas;
END;
$$;


ALTER FUNCTION "public"."bolt_resumo_merge_csv"("p_integracao_id" "uuid", "p_org_id" "uuid", "p_periodo_inicio" "date", "p_periodo_fim" "date", "p_valores" "jsonb", "p_periodo" "text", "p_motorista_id" "uuid", "p_escrever_viagens" boolean, "p_importado_em" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bolt_resumo_merge_csv"("p_integracao_id" "uuid", "p_org_id" "uuid", "p_periodo_inicio" "date", "p_periodo_fim" "date", "p_valores" "jsonb", "p_periodo" "text", "p_motorista_id" "uuid", "p_escrever_viagens" boolean, "p_importado_em" timestamp with time zone) IS 'Merge do CSV do portal Bolt no resumo semanal. Numa integracao em auth_mode=''oauth'' as viagens E o liquido sao da API - o CSV entra so com os extras que so ele traz (campanhas, reembolsos de despesas, IVA, metricas). Ver migracao 20260813220000.';



CREATE OR REPLACE FUNCTION "public"."bolt_resumo_recalcular_total"("p_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_total numeric;
BEGIN
  UPDATE public.bolt_resumos_semanais
     SET ganhos_brutos_total =
           COALESCE(ganhos_brutos_app,0) + COALESCE(ganhos_brutos_dinheiro,0)
         + COALESCE(gorjetas,0) + COALESCE(taxas_cancelamento,0)
         + COALESCE(ganhos_campanha,0) + COALESCE(reembolsos_despesas,0),
         updated_at = now()
   WHERE id = p_id
  RETURNING ganhos_brutos_total INTO v_total;
  RETURN v_total;
END;
$$;


ALTER FUNCTION "public"."bolt_resumo_recalcular_total"("p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bolt_resumo_recalcular_total"("p_id" "uuid") IS 'Recalcula ganhos_brutos_total das parcelas ja gravadas: app + dinheiro + gorjetas + cancelamentos + campanha + reembolsos. Identidade provada sobre 4312 linhas.';



CREATE TABLE IF NOT EXISTS "public"."bolt_sync_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "integracao_id" "uuid" NOT NULL,
    "org_id" "uuid" NOT NULL,
    "periodo_inicio" "date" NOT NULL,
    "periodo_fim" "date" NOT NULL,
    "formula_id" "text",
    "origem" "text" DEFAULT 'cron'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "resultado" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "error_message" "text",
    "fase" "text" DEFAULT 'completo'::"text" NOT NULL,
    "semana_inicio" "date",
    "alertado_em" timestamp with time zone,
    CONSTRAINT "bolt_sync_queue_fase_check" CHECK (("fase" = ANY (ARRAY['completo'::"text", 'viagens'::"text", 'agregar'::"text"]))),
    CONSTRAINT "bolt_sync_queue_origem_check" CHECK (("origem" = ANY (ARRAY['cron'::"text", 'manual'::"text"]))),
    CONSTRAINT "bolt_sync_queue_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."bolt_sync_queue" OWNER TO "postgres";


COMMENT ON TABLE "public"."bolt_sync_queue" IS 'Fila do sync semanal da Bolt pela API oficial. Uma linha = uma integracao x uma semana. Enfileirada por bolt-sync-agendado (cron ou botao Atualizar); processada por bolt-sync-drain.';



COMMENT ON COLUMN "public"."bolt_sync_queue"."resultado" IS 'Corpo devolvido por bolt-sync-semana: contagens, formula usada e as 4 variantes. E daqui que se le a calibracao sem ir aos logs.';



COMMENT ON COLUMN "public"."bolt_sync_queue"."fase" IS 'completo = busca e agrega numa passagem (frotas pequenas). viagens = so busca a API e grava bolt_viagens (um job por dia). agregar = so le a BD e grava os resumos da semana. Ver migracao 20260813100000.';



COMMENT ON COLUMN "public"."bolt_sync_queue"."semana_inicio" IS 'Segunda-feira da semana a que este job pertence. Nos jobs diarios difere de periodo_inicio; nos semanais e igual.';



CREATE OR REPLACE FUNCTION "public"."bolt_sync_queue_claim"("p_max" integer) RETURNS SETOF "public"."bolt_sync_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_running integer; v_capacity integer;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('bolt_sync_queue_claim')) THEN RETURN; END IF;

  UPDATE public.bolt_sync_queue
     SET status='failed', completed_at=now(),
         error_message='Timeout: execução ultrapassou 15 minutos'
   WHERE status='running' AND started_at < now() - interval '15 minutes';

  SELECT count(*) INTO v_running FROM public.bolt_sync_queue WHERE status='running';
  v_capacity := GREATEST(p_max - v_running, 0);
  IF v_capacity = 0 THEN RETURN; END IF;

  -- Em CTEs separadas de proposito: FOR UPDATE nao pode viver no mesmo nivel
  -- de uma funcao de janela. Ordena-se primeiro, tranca-se depois.
  RETURN QUERY
  WITH ordenadas AS (
    SELECT id,
           row_number() OVER (PARTITION BY integracao_id
                              ORDER BY created_at ASC, periodo_inicio ASC) AS rodada,
           created_at, periodo_inicio
      FROM public.bolt_sync_queue WHERE status='pending'
  ),
  escolhidas AS (
    SELECT id FROM ordenadas
     ORDER BY rodada ASC, created_at ASC, periodo_inicio ASC LIMIT v_capacity
  ),
  travadas AS (
    SELECT q.id FROM public.bolt_sync_queue q
      JOIN escolhidas e ON e.id = q.id
     WHERE q.status='pending'
     FOR UPDATE OF q SKIP LOCKED
  )
  UPDATE public.bolt_sync_queue q
     SET status='running', started_at=now()
    FROM travadas t WHERE q.id = t.id
  RETURNING q.*;
END;
$$;


ALTER FUNCTION "public"."bolt_sync_queue_claim"("p_max" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bolt_sync_queue_claim"("p_max" integer) IS 'Reclama ate p_max linhas pendentes, alternando entre integracoes (round-robin) para nenhuma ficar a fome. Ver migracao 20260812200000.';



CREATE OR REPLACE FUNCTION "public"."calcular_valor_aluguer"("p_tarifa_id" "uuid", "p_regime" "public"."contrato_regime_enum", "p_dias" integer) RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tarifa  record;
  v_meses   integer;
  v_resto   integer;
  v_semanas integer;
BEGIN
  IF p_dias IS NULL OR p_dias <= 0 THEN
    RETURN 0;
  END IF;

  SELECT * INTO v_tarifa FROM public.renting_tarifas WHERE id = p_tarifa_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- TVDE → semanal
  IF p_regime = 'tvde' THEN
    IF v_tarifa.preco_semana IS NULL THEN
      RETURN NULL;
    END IF;
    v_semanas := ceil(p_dias / 7.0);
    RETURN round(v_semanas * v_tarifa.preco_semana, 2);
  END IF;

  -- rent_a_car → mensal + diário
  IF v_tarifa.preco_dia IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_tarifa.preco_mes IS NOT NULL THEN
    v_meses := p_dias / 30;     -- divisão inteira
    v_resto := p_dias % 30;
    RETURN round(v_meses * v_tarifa.preco_mes + v_resto * v_tarifa.preco_dia, 2);
  END IF;

  RETURN round(p_dias * v_tarifa.preco_dia, 2);
END;
$$;


ALTER FUNCTION "public"."calcular_valor_aluguer"("p_tarifa_id" "uuid", "p_regime" "public"."contrato_regime_enum", "p_dias" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calcular_valor_aluguer"("p_tarifa_id" "uuid", "p_regime" "public"."contrato_regime_enum", "p_dias" integer) IS 'Valor do aluguer (sem IVA) a partir da tarifa e do regime. rent_a_car = meses×preco_mes + dias×preco_dia; tvde = semanas×preco_semana.';



CREATE OR REPLACE FUNCTION "public"."calendario_evento_cascata_contrato"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_novo_estado    text;
  v_estado_origem  text;
BEGIN
  -- Só age quando o evento PASSA a realizado (NULL -> not null).
  IF NEW.realizado_em IS NULL OR OLD.realizado_em IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Só eventos gerados por contratos de renting.
  IF NEW.origem_tipo <> 'contrato_renting' OR NEW.origem_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Mapeia tipo de evento -> transição do contrato (e estado de origem exigido).
  CASE NEW.tipo
    WHEN 'entrega' THEN v_estado_origem := 'agendado'; v_novo_estado := 'em_curso';
    WHEN 'recolha' THEN v_estado_origem := 'em_curso'; v_novo_estado := 'devolvido';
    ELSE RETURN NEW;  -- 'troca' e outros nao mexem no estado_operacional
  END CASE;

  -- Avança o contrato só se estiver mesmo no estado de origem esperado --
  -- idempotente e seguro.
  UPDATE public.contratos_renting
     SET estado_operacional = v_novo_estado::contrato_estado_operacional_enum,
         updated_by         = COALESCE(NEW.realizado_por_id, updated_by)
   WHERE id                 = NEW.origem_id
     AND substituido_em     IS NULL
     AND deleted_at         IS NULL
     AND estado_operacional = v_estado_origem::contrato_estado_operacional_enum;

  RETURN NEW;
END;
$$;


