CREATE OR REPLACE FUNCTION "public"."cobranca_ceder_a_motorista"("p_cobranca_id" "uuid", "p_motorista_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cob  public.contrato_cobrancas%ROWTYPE;
  v_nome text;
BEGIN
  SELECT * INTO v_cob FROM public.contrato_cobrancas WHERE id = p_cobranca_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cobrança não encontrada.';
  END IF;

  IF NOT COALESCE(
    v_cob.org_id = public.get_current_org_id() AND public.has_renting_faturacao_access(),
    false
  ) THEN
    RAISE EXCEPTION 'Sem permissão para ceder esta cobrança.';
  END IF;

  IF v_cob.responsavel_motorista_id IS NOT NULL THEN
    RAISE EXCEPTION 'Esta cobrança já foi cedida a um motorista.';
  END IF;

  IF v_cob.valor_total IS NULL OR v_cob.valor_total <= 0 THEN
    RETURN;
  END IF;

  SELECT nome INTO v_nome FROM public.motoristas_ativos WHERE id = p_motorista_id;
  IF v_nome IS NULL THEN
    RAISE EXCEPTION 'Motorista não encontrado.';
  END IF;

  UPDATE public.contrato_cobrancas
     SET responsavel_motorista_id = p_motorista_id
   WHERE id = p_cobranca_id;

  INSERT INTO public.conta_movimentos
    (org_id, entidade_id, tipo, valor, origem, cobranca_id, contrato_id, descricao)
  VALUES
    (v_cob.org_id, v_cob.destinatario_id, 'credito', v_cob.valor_total, 'cessao',
     v_cob.id, v_cob.contrato_id, 'Dívida cedida a ' || v_nome);

  INSERT INTO public.motorista_financeiro
    (org_id, motorista_id, tipo, categoria, descricao, valor, data_movimento, status, cobranca_id)
  VALUES
    (v_cob.org_id, p_motorista_id, 'debito', 'outro',
     'Fatura cedida — ' || COALESCE(v_cob.descricao, 'Cobrança de contrato'),
     v_cob.valor_total, current_date, 'pendente', v_cob.id);
END;
$$;


ALTER FUNCTION "public"."cobranca_ceder_a_motorista"("p_cobranca_id" "uuid", "p_motorista_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cobranca_ceder_a_motorista"("p_cobranca_id" "uuid", "p_motorista_id" "uuid") IS 'Transfere a dívida de uma cobrança recém-emitida para um motorista TVDE: credita o destinatário fiscal (anula o débito automático) e debita motorista_financeiro pelo mesmo valor. Chamar logo a seguir à emissão (Nova Fatura / Faturar contrato), nunca depois de a cobrança já ter recibos/notas de crédito associados.';



CREATE OR REPLACE FUNCTION "public"."cobranca_reverter_cessao_motorista"("p_cobranca_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cob public.contrato_cobrancas%ROWTYPE;
BEGIN
  SELECT * INTO v_cob FROM public.contrato_cobrancas WHERE id = p_cobranca_id;
  IF NOT FOUND OR v_cob.responsavel_motorista_id IS NULL THEN
    RETURN;
  END IF;

  IF NOT COALESCE(
    v_cob.org_id = public.get_current_org_id() AND public.has_renting_faturacao_access(),
    false
  ) THEN
    RAISE EXCEPTION 'Sem permissão para reverter esta cessão.';
  END IF;

  INSERT INTO public.conta_movimentos
    (org_id, entidade_id, tipo, valor, origem, cobranca_id, contrato_id, descricao)
  VALUES
    (v_cob.org_id, v_cob.destinatario_id, 'debito', v_cob.valor_total, 'ajuste',
     v_cob.id, v_cob.contrato_id, 'Ajuste — anulamento de fatura cedida a motorista');

  INSERT INTO public.motorista_financeiro
    (org_id, motorista_id, tipo, categoria, descricao, valor, data_movimento, status, cobranca_id)
  VALUES
    (v_cob.org_id, v_cob.responsavel_motorista_id, 'credito', 'outro',
     'Estorno — fatura cedida foi anulada', v_cob.valor_total, current_date, 'pendente',
     v_cob.id);
END;
$$;


ALTER FUNCTION "public"."cobranca_reverter_cessao_motorista"("p_cobranca_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cobranca_reverter_cessao_motorista"("p_cobranca_id" "uuid") IS 'Reverte cobranca_ceder_a_motorista quando a cobrança cedida é anulada: lança um ajuste ao destinatário fiscal (compensa o crédito de anulamento em duplicado) e um crédito ao motorista (devolve a dívida a zero). No-op silencioso se a cobrança nunca foi cedida.';



CREATE OR REPLACE FUNCTION "public"."cobranca_saldo_por_liquidar"("p_cobranca_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT GREATEST(
    COALESCE((SELECT valor_total FROM public.contrato_cobrancas WHERE id = p_cobranca_id), 0)
    - COALESCE((SELECT SUM(valor) FROM public.recibos
                 WHERE referencia = p_cobranca_id::text AND estado = 'ativo'), 0)
    - COALESCE((SELECT SUM(valor) FROM public.notas_credito
                 WHERE cobranca_id = p_cobranca_id AND estado = 'ativo'), 0),
    0)::numeric(12,2);
$$;


ALTER FUNCTION "public"."cobranca_saldo_por_liquidar"("p_cobranca_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cobranca_saldo_por_liquidar"("p_cobranca_id" "uuid") IS 'Saldo ainda por liquidar de uma cobrança: total − recibos ativos − notas de crédito ativas. Espelha o cálculo de saldoPagar do ecrã de faturação.';



CREATE OR REPLACE FUNCTION "public"."consumir_token_realizacao"("p_token" "uuid") RETURNS TABLE("evento_id" "uuid", "contrato_id" "uuid", "tipo" "text", "matricula" "text", "matricula_devolver" "text", "modelo" "text", "modelo_devolver" "text", "cidade" "text", "data_inicio" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token realizacao_tokens%ROWTYPE;
  v_evento calendario_eventos%ROWTYPE;
  v_org_id uuid;
BEGIN
  SELECT * INTO v_token FROM public.realizacao_tokens WHERE id = p_token;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Token inválido.';
  END IF;
  IF v_token.expires_at < now() THEN
    RAISE EXCEPTION 'Token expirado.';
  END IF;
  IF v_token.used_at IS NOT NULL THEN
    RAISE EXCEPTION 'Token já foi usado.';
  END IF;
  IF v_token.org_id <> get_current_org_id() THEN
    RAISE EXCEPTION 'Token de outra organização.';
  END IF;

  SELECT * INTO v_evento FROM public.calendario_eventos WHERE id = v_token.evento_id;
  IF v_evento.realizado_em IS NOT NULL THEN
    RAISE EXCEPTION 'Evento já realizado.';
  END IF;

  v_org_id := v_token.org_id;

  RETURN QUERY SELECT
    v_evento.id,
    v_token.contrato_id,
    v_token.tipo,
    v_evento.titulo,
    v_evento.matricula_devolver,
    (SELECT vi.modelo FROM public.viaturas vi
       WHERE vi.org_id = v_org_id AND vi.matricula = v_evento.titulo),
    (SELECT vi.modelo FROM public.viaturas vi
       WHERE vi.org_id = v_org_id AND vi.matricula = v_evento.matricula_devolver),
    v_evento.cidade,
    v_evento.data_inicio;
END;
$$;


ALTER FUNCTION "public"."consumir_token_realizacao"("p_token" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consumir_token_realizacao"("p_token" "uuid") IS 'Devolve os dados do evento associado a um token, incluindo matricula_devolver e modelo/modelo_devolver (relevante na troca — mostra a viatura nova e a antiga com identificação inequívoca). Não marca o token como usado — isso só acontece após a realização.';



CREATE OR REPLACE FUNCTION "public"."conta_corrente_saldo"("p_entidade_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(SUM(
    CASE tipo WHEN 'debito' THEN valor ELSE -valor END
  ), 0)::numeric(12,2)
  FROM public.conta_movimentos
  WHERE entidade_id = p_entidade_id
    AND org_id = public.get_current_org_id();
$$;


ALTER FUNCTION "public"."conta_corrente_saldo"("p_entidade_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."conta_corrente_saldo"("p_entidade_id" "uuid") IS 'Saldo da conta-corrente: positivo = a entidade deve; negativo = crédito a favor dela.';



CREATE OR REPLACE FUNCTION "public"."contexto_folha_por_token"("p_token" "uuid") RETURNS TABLE("viatura_id" "uuid", "emissor_id" "uuid", "anexo_danos_template_id" "uuid", "empresa_nome" "text", "empresa_nif" "text", "empresa_sede" "text", "empresa_licenca_tvde" "text", "empresa_licenca_validade" "text", "empresa_representante" "text", "empresa_cargo_representante" "text", "empresa_papel_timbrado" "text", "empresa_logo_url" "text", "condutor_nome" "text", "condutor_email" "text", "cliente_nome" "text", "km_saida" integer, "combustivel_saida" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token     realizacao_tokens%ROWTYPE;
  v_contrato  contratos_renting%ROWTYPE;
  v_cond      RECORD;
  r_nome      text := '';
  r_email     text := '';
  r_cliente   text := '';
  r_emp_nome  text := '';
  r_emp_nif   text := '';
  r_emp_sede  text := '';
  r_emp_tvde  text := '';
  r_emp_val   text := '';
  r_emp_rep   text := '';
  r_emp_cargo text := '';
  r_emp_papel text := NULL;
  r_emp_logo  text := NULL;
  r_tmpl_id   uuid := NULL;
BEGIN
  SELECT * INTO v_token FROM public.realizacao_tokens WHERE id = p_token;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Token inválido.';
  END IF;
  IF v_token.org_id <> get_current_org_id() THEN
    RAISE EXCEPTION 'Token de outra organização.';
  END IF;

  SELECT * INTO v_contrato FROM public.contratos_renting WHERE id = v_token.contrato_id;

  -- Empresa emissora → {{empresa_*}} + fundo de página (papel timbrado/logo).
  IF v_contrato.emissor_id IS NOT NULL THEN
    SELECT
      COALESCE(NULLIF(c.nome_comercial, ''), c.nome, ''),
      COALESCE(c.nif, ''),
      COALESCE(c.sede, ''),
      COALESCE(c.licenca_tvde, ''),
      COALESCE(c.licenca_validade::text, ''),
      COALESCE(c.representante, ''),
      COALESCE(c.cargo_representante, ''),
      c.papel_timbrado,
      c.logo_url
    INTO r_emp_nome, r_emp_nif, r_emp_sede, r_emp_tvde, r_emp_val, r_emp_rep, r_emp_cargo,
         r_emp_papel, r_emp_logo
    FROM public.clientes c
    WHERE c.id = v_contrato.emissor_id;

    SELECT dt.id INTO r_tmpl_id
      FROM public.document_templates dt
     WHERE dt.tipo = 'anexo_danos'
       AND dt.ativo = true
       AND dt.cliente_empresa_id = v_contrato.emissor_id
     ORDER BY dt.versao DESC
     LIMIT 1;
  END IF;

  -- Sem emissor definido, ou sem template dessa empresa: cai para
  -- qualquer 'anexo_danos' activo da mesma org (tolerante, nunca bloqueia
  -- o check-in/out por falta de emissor no contrato).
  IF r_tmpl_id IS NULL THEN
    SELECT dt.id INTO r_tmpl_id
      FROM public.document_templates dt
     WHERE dt.tipo = 'anexo_danos'
       AND dt.ativo = true
       AND dt.org_id = v_token.org_id
     ORDER BY dt.versao DESC
     LIMIT 1;
  END IF;

  -- Condutor principal (contrato_condutores): cliente XOR motorista.
  SELECT cc.cliente_id, cc.motorista_id
    INTO v_cond
    FROM public.contrato_condutores cc
   WHERE cc.contrato_id = v_token.contrato_id
   ORDER BY cc.is_principal DESC NULLS LAST
   LIMIT 1;

  IF v_cond.cliente_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(c.nome, ''), c.nome_comercial, ''), COALESCE(c.email, '')
      INTO r_nome, r_email
      FROM public.clientes c WHERE c.id = v_cond.cliente_id;
  ELSIF v_cond.motorista_id IS NOT NULL THEN
    SELECT COALESCE(m.nome, ''), COALESCE(m.email, '')
      INTO r_nome, r_email
      FROM public.motoristas_ativos m WHERE m.id = v_cond.motorista_id;
  ELSIF v_contrato.viatura_id IS NOT NULL THEN
    -- Fallback: motorista ATIVO associado à viatura (só se o contrato não
    -- define condutor). Nunca um motorista histórico (status <> 'ativo').
    SELECT COALESCE(m.nome, ''), COALESCE(m.email, '')
      INTO r_nome, r_email
      FROM public.motorista_viaturas mv
      JOIN public.motoristas_ativos m ON m.id = mv.motorista_id
     WHERE mv.viatura_id = v_contrato.viatura_id
       AND mv.status = 'ativo'
     ORDER BY mv.data_inicio DESC
     LIMIT 1;
  END IF;

  -- Cliente/locatário → {{cliente_nome}}.
  IF v_contrato.cliente_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(c.nome_comercial, ''), c.nome, '')
      INTO r_cliente
      FROM public.clientes c WHERE c.id = v_contrato.cliente_id;
  END IF;

  RETURN QUERY SELECT
    v_contrato.viatura_id,
    v_contrato.emissor_id,
    r_tmpl_id,
    COALESCE(r_emp_nome, ''),
    COALESCE(r_emp_nif, ''),
    COALESCE(r_emp_sede, ''),
    COALESCE(r_emp_tvde, ''),
    COALESCE(r_emp_val, ''),
    COALESCE(r_emp_rep, ''),
    COALESCE(r_emp_cargo, ''),
    r_emp_papel,
    r_emp_logo,
    COALESCE(r_nome, ''),
    COALESCE(r_email, ''),
    COALESCE(r_cliente, ''),
    v_contrato.km_saida,
    v_contrato.combustivel_saida;
END;
$$;


ALTER FUNCTION "public"."contexto_folha_por_token"("p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_historico_resumo"("p_contrato_id" "uuid") RETURNS TABLE("evento_tipo" "text", "ator_id" "uuid", "ator_nome" "text", "detalhe" "text", "criado_em" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH base AS (
    SELECT h.evento_tipo, h.ator_id, h.detalhe, h.criado_em,
           row_number() OVER (
             PARTITION BY h.evento_tipo ORDER BY h.criado_em DESC
           ) AS rn_por_tipo
    FROM public.contrato_historico h
    WHERE h.contrato_id = p_contrato_id
      AND h.org_id = public.get_current_org_id()
  ),
  ctr AS (
    SELECT estado_operacional::text AS eo, estado_financeiro::text AS ef
    FROM public.contratos_renting
    WHERE id = p_contrato_id
      AND org_id = public.get_current_org_id()
  ),
  marcos AS (
    SELECT b.evento_tipo, b.ator_id, b.detalhe, b.criado_em
    FROM base b
    CROSS JOIN ctr
    WHERE b.rn_por_tipo = 1
      AND (
            b.evento_tipo = 'reserva_criada'
        OR (b.evento_tipo = 'contrato_aberto'   AND ctr.eo <> 'agendado')
        OR (b.evento_tipo = 'contrato_fechado'  AND ctr.eo IN ('devolvido','cancelado'))
        OR (b.evento_tipo = 'contrato_faturado' AND ctr.ef <> 'pendente')
      )
  ),
  ultima AS (
    SELECT 'ultima_alteracao'::text AS evento_tipo, ator_id, detalhe, criado_em
    FROM base
    ORDER BY criado_em DESC
    LIMIT 1
  ),
  todos AS (
    SELECT * FROM marcos
    UNION ALL
    SELECT * FROM ultima
  )
  SELECT t.evento_tipo, t.ator_id, COALESCE(p.nome, 'Sistema') AS ator_nome,
         t.detalhe, t.criado_em
  FROM todos t
  LEFT JOIN public.profiles p ON p.id = t.ator_id
  ORDER BY CASE t.evento_tipo
    WHEN 'reserva_criada'    THEN 1
    WHEN 'contrato_aberto'   THEN 2
    WHEN 'contrato_fechado'  THEN 3
    WHEN 'contrato_faturado' THEN 4
    WHEN 'ultima_alteracao'  THEN 5
    ELSE 9
  END;
$$;


ALTER FUNCTION "public"."contrato_historico_resumo"("p_contrato_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_renting_cascata_data_fim"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_matricula      text;
  v_descricao      text;
  v_cidade_recolha text;
  v_updated_rows   integer;
BEGIN
  IF NEW.data_fim IS NOT DISTINCT FROM OLD.data_fim THEN
    RETURN NEW;
  END IF;

  IF NEW.regime = 'tvde' THEN
    RETURN NEW;
  END IF;

  IF NEW.estado_operacional IN ('cancelado', 'devolvido', 'fechado') THEN
    RETURN NEW;
  END IF;

  IF NEW.data_fim IS NULL THEN
    DELETE FROM public.calendario_eventos
     WHERE origem_tipo = 'contrato_renting'
       AND origem_id   = NEW.id
       AND tipo        = 'recolha';
    RETURN NEW;
  END IF;

  IF NEW.estacao_recolha_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(TRIM(cidade), ''), nome) INTO v_cidade_recolha
      FROM public.estacoes WHERE id = NEW.estacao_recolha_id;
  END IF;

  UPDATE public.calendario_eventos
     SET data_inicio = NEW.data_fim,
         data_fim    = NEW.data_fim,
         cidade      = v_cidade_recolha
   WHERE origem_tipo = 'contrato_renting'
     AND origem_id   = NEW.id
     AND tipo        = 'recolha';

  GET DIAGNOSTICS v_updated_rows = ROW_COUNT;

  IF v_updated_rows = 0 THEN
    IF NEW.viatura_id IS NOT NULL THEN
      SELECT UPPER(REGEXP_REPLACE(matricula, '[\s-]', '', 'g'))
        INTO v_matricula
        FROM public.viaturas
       WHERE id = NEW.viatura_id;
    END IF;

    v_descricao := COALESCE(
      NULLIF(TRIM(NEW.observacoes_internas), ''),
      'Gerado automaticamente pelo contrato #' || NEW.codigo
    );

    INSERT INTO public.calendario_eventos (
      tipo, titulo, descricao, cidade,
      data_inicio, data_fim, dia_todo,
      matricula_devolver, criado_por,
      origem_tipo, origem_id
    )
    VALUES (
      'recolha',
      COALESCE(v_matricula, '?'),
      v_descricao, v_cidade_recolha,
      NEW.data_fim, NEW.data_fim, false,
      v_matricula, COALESCE(auth.uid(), NEW.created_by),
      'contrato_renting', NEW.id
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_cascata_data_fim"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_cascata_data_fim"() IS 'Sincroniza o evento de recolha no calendário quando data_fim muda num contrato rent-a-car ou slot, incluindo a cidade da estação de recolha. Move evento existente, cria se não existia, apaga se data_fim passou a NULL. Ignora contratos TVDE (recolha gerida no fecho) e contratos já fechados.';



CREATE OR REPLACE FUNCTION "public"."contrato_renting_cascata_estacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cidade_entrega text;
  v_cidade_recolha text;
BEGIN
  IF NEW.estacao_entrega_id IS NOT DISTINCT FROM OLD.estacao_entrega_id
     AND NEW.estacao_recolha_id IS NOT DISTINCT FROM OLD.estacao_recolha_id THEN
    RETURN NEW;
  END IF;

  IF NEW.estacao_entrega_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(TRIM(cidade), ''), nome) INTO v_cidade_entrega
      FROM public.estacoes WHERE id = NEW.estacao_entrega_id;
  END IF;
  IF NEW.estacao_recolha_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(TRIM(cidade), ''), nome) INTO v_cidade_recolha
      FROM public.estacoes WHERE id = NEW.estacao_recolha_id;
  END IF;

  UPDATE public.calendario_eventos
     SET cidade = v_cidade_entrega
   WHERE origem_tipo = 'contrato_renting'
     AND origem_id   = NEW.id
     AND tipo        = 'entrega';

  UPDATE public.calendario_eventos
     SET cidade = v_cidade_recolha
   WHERE origem_tipo = 'contrato_renting'
     AND origem_id   = NEW.id
     AND tipo        = 'recolha';

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_cascata_estacao"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_cascata_estacao"() IS 'Sincroniza calendario_eventos.cidade quando estacao_entrega_id/estacao_recolha_id mudam num contrato_renting, sem depender de mudança de data.';



CREATE OR REPLACE FUNCTION "public"."contrato_renting_cascata_estado"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_novo_estado_reserva text;
BEGIN
  IF NEW.estado_operacional IS NOT DISTINCT FROM OLD.estado_operacional THEN
    RETURN NEW;
  END IF;

  IF NEW.substituido_em IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.reserva_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.estado_operacional = 'cancelado' THEN
    v_novo_estado_reserva := 'cancelada';
  ELSIF NEW.estado_operacional IN ('fechado', 'devolvido') THEN
    v_novo_estado_reserva := 'concluida';
  ELSE
    RETURN NEW;
  END IF;

  UPDATE public.reservas
     SET estado = v_novo_estado_reserva::reserva_estado_enum
   WHERE id = NEW.reserva_id;

  IF NEW.estado_operacional = 'cancelado' THEN
    DELETE FROM public.calendario_eventos
     WHERE origem_tipo   = 'contrato_renting'
       AND origem_id     = NEW.id
       AND realizado_em IS NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_cascata_estado"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_cascata_estado"() IS 'Cascata contrato->reserva. fechado/devolvido -> reserva concluida, eventos preservados. cancelado -> reserva cancelada, eventos apagados. Versoes substituidas (substituido_em) nao cascateiam.';



CREATE OR REPLACE FUNCTION "public"."contrato_renting_cascata_observacoes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_descricao text;
BEGIN
  -- Nenhuma alteração efectiva → sair (evita escritas redundantes)
  IF NEW.observacoes_internas IS NOT DISTINCT FROM OLD.observacoes_internas THEN
    RETURN NEW;
  END IF;

  -- Mesma regra do cascata_open: observação interna ou texto automático
  v_descricao := COALESCE(
    NULLIF(TRIM(NEW.observacoes_internas), ''),
    'Gerado automaticamente pelo contrato #' || NEW.codigo
  );

  UPDATE public.calendario_eventos
     SET descricao = v_descricao
   WHERE origem_tipo = 'contrato_renting'
     AND origem_id   = NEW.id
     AND tipo IN ('entrega', 'recolha');

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_cascata_observacoes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_cascata_observacoes"() IS 'Sincroniza a descrição dos eventos (entrega/recolha) no calendário quando observacoes_internas muda num contrato_renting. Espelha a regra do cascata_open. Só atualiza eventos existentes.';



CREATE OR REPLACE FUNCTION "public"."contrato_renting_cascata_open"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_matricula      text;
  v_cliente_nome   text;
  v_descricao      text;
  v_cidade_entrega text;
  v_cidade_recolha text;
BEGIN
  IF NEW.viatura_id IS NOT NULL THEN
    SELECT matricula INTO v_matricula FROM public.viaturas WHERE id = NEW.viatura_id;
    v_matricula := UPPER(REGEXP_REPLACE(v_matricula, '[\s-]', '', 'g'));
  END IF;
  IF NEW.cliente_id IS NOT NULL THEN
    SELECT nome INTO v_cliente_nome FROM public.clientes WHERE id = NEW.cliente_id;
  END IF;
  IF NEW.estacao_entrega_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(TRIM(cidade), ''), nome) INTO v_cidade_entrega
      FROM public.estacoes WHERE id = NEW.estacao_entrega_id;
  END IF;
  IF NEW.estacao_recolha_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(TRIM(cidade), ''), nome) INTO v_cidade_recolha
      FROM public.estacoes WHERE id = NEW.estacao_recolha_id;
  END IF;

  v_descricao := COALESCE(
    NULLIF(TRIM(NEW.observacoes_internas), ''),
    'Gerado automaticamente pelo contrato #' || NEW.codigo
  );

  IF NEW.reserva_id IS NOT NULL THEN
    UPDATE public.reservas
       SET estado = 'em_curso'
     WHERE id = NEW.reserva_id
       AND estado IN ('confirmada', 'pendente');
  END IF;

  INSERT INTO public.calendario_eventos (
    org_id, tipo, titulo, descricao, cidade,
    data_inicio, data_fim, dia_todo,
    matricula_devolver, criado_por,
    origem_tipo, origem_id
  )
  VALUES (
    NEW.org_id, 'entrega',
    COALESCE(v_matricula, '?'),
    v_descricao, v_cidade_entrega,
    NEW.data_inicio, NEW.data_inicio, false,
    v_matricula, COALESCE(NEW.created_by, auth.uid()),
    'contrato_renting', NEW.id
  );

  IF NEW.data_fim IS NOT NULL AND NEW.regime <> 'tvde' THEN
    INSERT INTO public.calendario_eventos (
      org_id, tipo, titulo, descricao, cidade,
      data_inicio, data_fim, dia_todo,
      matricula_devolver, criado_por,
      origem_tipo, origem_id
    )
    VALUES (
      NEW.org_id, 'recolha',
      COALESCE(v_matricula, '?'),
      v_descricao, v_cidade_recolha,
      NEW.data_fim, NEW.data_fim, false,
      v_matricula, COALESCE(NEW.created_by, auth.uid()),
      'contrato_renting', NEW.id
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_cascata_open"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_cascata_open"() IS 'Cascata ao criar contrato_renting: avança reserva, ocupa viatura, gera eventos no calendário com cidade da estação de entrega/recolha. TVDE não gera evento de recolha automático — a recolha/devolução é criada no fecho do contrato.';



CREATE OR REPLACE FUNCTION "public"."contrato_renting_cascata_realizacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_evento_tipo text;
  v_actor       uuid;
BEGIN
  IF NEW.estado_operacional IS NOT DISTINCT FROM OLD.estado_operacional THEN
    RETURN NEW;
  END IF;

  IF NEW.substituido_em IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_evento_tipo := CASE
    WHEN OLD.estado_operacional = 'agendado' AND NEW.estado_operacional = 'em_curso' THEN 'entrega'
    WHEN OLD.estado_operacional = 'em_curso' AND NEW.estado_operacional IN ('fechado', 'devolvido') THEN 'recolha'
    ELSE NULL
  END;

  IF v_evento_tipo IS NULL THEN
    RETURN NEW;
  END IF;

  v_actor := COALESCE(NEW.updated_by, auth.uid());

  UPDATE public.calendario_eventos
     SET realizado_por_id = v_actor,
         realizado_em     = now()
   WHERE origem_tipo      = 'contrato_renting'
     AND origem_id        = NEW.id
     AND tipo             = v_evento_tipo
     AND realizado_em     IS NULL;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_cascata_realizacao"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_cascata_realizacao"() IS 'Propaga transições de estado_operacional do contrato para o evento de calendário correspondente: agendado→em_curso marca entrega como realizada; em_curso→devolvido marca recolha. Quem realiza = updated_by.';



CREATE OR REPLACE FUNCTION "public"."contrato_renting_cascata_versao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_matricula_nova    text;
  v_cidade_entrega    text;
  v_cidade_recolha    text;
BEGIN
  IF OLD.substituido_em IS NULL AND NEW.substituido_em IS NOT NULL THEN
    DELETE FROM public.calendario_eventos
     WHERE origem_tipo = 'contrato_renting'
       AND origem_id   = NEW.id
       AND (
         (tipo = 'entrega' AND data_inicio = OLD.data_inicio)
         OR (
           tipo = 'recolha'
           AND OLD.data_fim IS NOT NULL
           AND data_fim = OLD.data_fim
           AND realizado_em IS NULL
         )
         OR (tipo = 'troca' AND realizado_em IS NULL)
       );
    RETURN NEW;
  END IF;

  IF NEW.contrato_anterior_id IS NOT NULL
     AND NEW.substituido_em IS NULL
     AND OLD.viatura_id IS DISTINCT FROM NEW.viatura_id
  THEN
    SELECT matricula INTO v_matricula_nova
      FROM public.viaturas WHERE id = NEW.viatura_id;

    IF NEW.estacao_entrega_id IS NOT NULL THEN
      SELECT COALESCE(NULLIF(trim(cidade), ''), nome)
        INTO v_cidade_entrega
        FROM public.estacoes WHERE id = NEW.estacao_entrega_id;
    END IF;
    IF NEW.estacao_recolha_id IS NOT NULL THEN
      SELECT COALESCE(NULLIF(trim(cidade), ''), nome)
        INTO v_cidade_recolha
        FROM public.estacoes WHERE id = NEW.estacao_recolha_id;
    END IF;

    DELETE FROM public.calendario_eventos
     WHERE origem_tipo = 'contrato_renting'
       AND origem_id   = NEW.id
       AND tipo IN ('entrega', 'recolha', 'troca');

    INSERT INTO public.calendario_eventos (
      tipo, titulo, descricao, cidade,
      data_inicio, data_fim, dia_todo,
      matricula_devolver, criado_por,
      origem_tipo, origem_id
    )
    VALUES (
      'entrega',
      COALESCE(v_matricula_nova, '?'),
      'Troca de viatura no contrato #' || NEW.codigo || ' — entrega da nova viatura',
      v_cidade_entrega,
      now(), now(), false,
      v_matricula_nova, COALESCE(NEW.updated_by, auth.uid()),
      'contrato_renting', NEW.id
    );

    IF NEW.data_fim IS NOT NULL THEN
      INSERT INTO public.calendario_eventos (
        tipo, titulo, descricao, cidade,
        data_inicio, data_fim, dia_todo,
        matricula_devolver, criado_por,
        origem_tipo, origem_id
      )
      VALUES (
        'recolha',
        v_matricula_nova,
        'Gerado automaticamente pelo contrato #' || NEW.codigo,
        v_cidade_recolha,
        NEW.data_fim, NEW.data_fim, false,
        v_matricula_nova, COALESCE(NEW.updated_by, auth.uid()),
        'contrato_renting', NEW.id
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_cascata_versao"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_cascata_versao"() IS 'Cascateia o versionamento de contratos para o calendário. Ao substituir uma versão, remove só os eventos "base" (entrega em data_inicio, recolha não-realizada em data_fim) — preserva qualquer recolha real já registada pelo fecho formal da troca. Ao mudar de viatura numa versão nova, gera a entrega (pendente) da viatura nova e a recolha final em data_fim; a recolha da viatura antiga já não é gerada aqui — é responsabilidade do fecho formal do contrato anterior (FecharContratoDialog), evitando duplicar o registo da devolução.';



CREATE OR REPLACE FUNCTION "public"."contrato_renting_inativar_motorista_na_devolucao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.estado_operacional IS NOT DISTINCT FROM OLD.estado_operacional THEN
    RETURN NEW;
  END IF;

  IF NEW.substituido_em IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.estado_operacional NOT IN ('cancelado', 'devolvido', 'fechado') THEN
    RETURN NEW;
  END IF;

  UPDATE public.motoristas_ativos
     SET status_ativo = false
   WHERE id IN (
     SELECT motorista_id
       FROM public.contrato_condutores
      WHERE contrato_id = NEW.id
        AND motorista_id IS NOT NULL
   );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_inativar_motorista_na_devolucao"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_inativar_motorista_na_devolucao"() IS 'Marca motoristas_ativos.status_ativo=false para os condutores deste contrato quando ele termina (cancelado/devolvido) — cobre tanto o fecho imediato (FecharContratoTVDEDialog) como a confirmação tardia via realizar_token_realizacao, para a recolha física ficar pendente sem deixar o motorista activo indefinidamente por engano.';



CREATE OR REPLACE FUNCTION "public"."contrato_renting_liga_motorista_close"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_closed_motorista_id uuid;
  v_tem_outro_contrato boolean;
BEGIN
  -- Linha já era história antes desta alteração: o vínculo motorista-viatura
  -- pertence agora ao contrato sucessor — não tocar. (No momento da
  -- substituição OLD.substituido_em ainda é NULL → fecho normal mantém-se.)
  IF OLD.substituido_em IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.viatura_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR v_closed_motorista_id IN
    UPDATE public.motorista_viaturas
       SET status = 'encerrado', data_fim = COALESCE(data_fim, CURRENT_DATE)
     WHERE viatura_id = NEW.viatura_id
       AND status = 'ativo'
    RETURNING motorista_id
  LOOP
    SELECT EXISTS (
      SELECT 1
      FROM public.contratos_renting cr
      WHERE cr.id <> NEW.id
        AND cr.deleted_at IS NULL
        AND cr.substituido_em IS NULL
        AND cr.estado_operacional IN ('agendado', 'em_curso')
        AND (
          EXISTS (
            SELECT 1 FROM public.motoristas_ativos ma
            WHERE ma.id = v_closed_motorista_id AND ma.cliente_id = cr.cliente_id
          )
          OR EXISTS (
            SELECT 1 FROM public.contrato_condutores cc
            WHERE cc.contrato_id = cr.id AND cc.motorista_id = v_closed_motorista_id
          )
        )
    ) INTO v_tem_outro_contrato;

    IF NOT v_tem_outro_contrato THEN
      UPDATE public.motoristas_ativos
         SET status_ativo = false
       WHERE id = v_closed_motorista_id;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_liga_motorista_close"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_liga_motorista_close"() IS 'Ao fechar/cancelar um contrato, fecha TODAS as linhas motorista_viaturas activas da sua viatura (não só a de "um" motorista resolvido por LIMIT 1 — esse caminho deixava o condutor real preso à viatura quando o contrato tinha vários condutores). Para cada motorista efectivamente fechado, inactiva-o só se não tiver outro contrato_renting activo.';



CREATE OR REPLACE FUNCTION "public"."contrato_renting_liga_motorista_open"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_motorista_id uuid;
BEGIN
  IF NEW.viatura_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.cliente_id IS NOT NULL THEN
    SELECT id INTO v_motorista_id
    FROM public.motoristas_ativos
    WHERE cliente_id = NEW.cliente_id
    LIMIT 1;
  END IF;

  IF v_motorista_id IS NULL THEN
    SELECT motorista_id INTO v_motorista_id
    FROM public.contrato_condutores
    WHERE contrato_id = NEW.id AND motorista_id IS NOT NULL
    LIMIT 1;
  END IF;

  IF v_motorista_id IS NULL THEN
    RAISE WARNING 'contrato_renting_liga_motorista_open: motorista não resolvido para contrato % (codigo %, cliente_id %, viatura_id %) — motorista_viaturas não sincronizado',
      NEW.id, NEW.codigo, NEW.cliente_id, NEW.viatura_id;
    RETURN NEW;
  END IF;

  -- Encerra associação activa anterior a outra viatura (troca/upgrade)
  UPDATE public.motorista_viaturas
     SET status = 'encerrado', data_fim = COALESCE(data_fim, NEW.data_inicio::date)
   WHERE motorista_id = v_motorista_id
     AND status = 'ativo'
     AND viatura_id IS DISTINCT FROM NEW.viatura_id;

  -- Cria associação se ainda não existir activa para esta viatura
  IF NOT EXISTS (
    SELECT 1 FROM public.motorista_viaturas
     WHERE motorista_id = v_motorista_id
       AND viatura_id = NEW.viatura_id
       AND status = 'ativo'
  ) THEN
    INSERT INTO public.motorista_viaturas (
      motorista_id, viatura_id, data_inicio, status, org_id, observacoes
    )
    VALUES (
      v_motorista_id, NEW.viatura_id, NEW.data_inicio::date, 'ativo', NEW.org_id,
      'Gerado automaticamente pelo contrato de aluguer #' || NEW.codigo
    );
  END IF;

  -- Garante motorista activo enquanto tiver contrato em curso
  UPDATE public.motoristas_ativos
     SET status_ativo = true
   WHERE id = v_motorista_id
     AND status_ativo = false;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contrato_renting_liga_motorista_open"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contrato_renting_liga_motorista_open"() IS 'Ao abrir/actualizar contrato_renting com viatura, associa a viatura em motorista_viaturas e garante motorista activo. Resolve o motorista por cliente_id directo OU, em fallback, via contrato_condutores.motorista_id (contratos com titular empresa-frota e condutor TVDE real).';



CREATE OR REPLACE FUNCTION "public"."contrato_tem_conflito"("p_viatura_id" "uuid", "p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone, "p_excluir_id" "uuid" DEFAULT NULL::"uuid", "p_reserva_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.contratos_renting
    WHERE org_id = public.get_current_org_id()
      AND viatura_id = p_viatura_id
      AND deleted_at IS NULL
      AND substituido_em IS NULL
      AND estado_operacional IN ('agendado', 'em_curso')
      AND periodo && tstzrange(p_data_inicio, p_data_fim, '[)')
      AND (p_excluir_id IS NULL OR id <> p_excluir_id)
    UNION ALL
    SELECT 1 FROM public.reservas
    WHERE org_id = public.get_current_org_id()
      AND viatura_id = p_viatura_id
      AND deleted_at IS NULL
      AND estado IN ('pendente', 'confirmada', 'em_curso')
      AND periodo && tstzrange(p_data_inicio, p_data_fim, '[)')
      AND (p_reserva_id IS NULL OR id <> p_reserva_id)
  );
$$;


ALTER FUNCTION "public"."contrato_tem_conflito"("p_viatura_id" "uuid", "p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone, "p_excluir_id" "uuid", "p_reserva_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contratos_preencher_data_fim"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.data_fim IS NULL
     AND NEW.data_inicio IS NOT NULL
     AND NEW.duracao_meses IS NOT NULL THEN
    NEW.data_fim := (NEW.data_inicio + (NEW.duracao_meses || ' months')::interval)::date;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."contratos_preencher_data_fim"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_org_definicoes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.org_definicoes (org_id)
  VALUES (NEW.id)
  ON CONFLICT (org_id) DO NOTHING;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_org_definicoes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."criar_versao_contrato_renting"("p_contrato_id" "uuid", "p_motivo" "text") RETURNS "uuid"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  SELECT public.criar_versao_contrato_renting($1, $2, now());
$_$;


ALTER FUNCTION "public"."criar_versao_contrato_renting"("p_contrato_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."criar_versao_contrato_renting"("p_contrato_id" "uuid", "p_motivo" "text") IS 'Cria uma nova versão de um contrato_renting copiando a linha actual + relações (condutores, coberturas, extras, taxas) e marcando a anterior como substituida. A nova versão herda o mesmo codigo da anterior — o numero do contrato nao muda ao editar, so a versao (fix 2026-07-14, ver 20260714130000).';



CREATE OR REPLACE FUNCTION "public"."criar_versao_contrato_renting"("p_contrato_id" "uuid", "p_motivo" "text", "p_data_troca" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_old        contratos_renting%ROWTYPE;
  v_new_id     uuid;
  v_user_id    uuid := auth.uid();
  v_data       timestamptz;
  v_cols       text;
  v_vals       text;
  v_matricula  text;
BEGIN
  SELECT * INTO v_old
    FROM public.contratos_renting
   WHERE id = p_contrato_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contrato % não encontrado.', p_contrato_id;
  END IF;

  IF v_old.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Não podes versionar um contrato eliminado.';
  END IF;

  IF v_old.substituido_em IS NOT NULL THEN
    RAISE EXCEPTION 'Este contrato já foi substituído. Versiona a versão actual.';
  END IF;

  IF v_old.estado_financeiro IN ('facturado', 'pago') THEN
    RAISE EXCEPTION 'Não podes versionar um contrato %. Trata da facturação primeiro.',
      v_old.estado_financeiro;
  END IF;

  IF v_old.org_id <> get_current_org_id() THEN
    RAISE EXCEPTION 'Sem permissão sobre este contrato.';
  END IF;

  v_data := COALESCE(p_data_troca, now());
  IF v_data < v_old.data_inicio THEN
    RAISE EXCEPTION 'A data da troca (%) é anterior ao início do contrato (%).',
      v_data, v_old.data_inicio;
  END IF;

  UPDATE public.contratos_renting
     SET substituido_em     = now(),
         estado_operacional = 'fechado'::contrato_estado_operacional_enum,
         data_fim           = v_data,
         updated_by         = v_user_id
   WHERE id = v_old.id;

  SELECT string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position),
         string_agg(
           CASE c.column_name
             WHEN 'versao'               THEN '$2'
             WHEN 'contrato_anterior_id' THEN '$1'
             WHEN 'motivo_versao'        THEN '$3'
             WHEN 'substituido_em'       THEN 'NULL'
             WHEN 'deleted_at'           THEN 'NULL'
             WHEN 'data_inicio'          THEN '$4'
             WHEN 'data_fim'             THEN '$6'
             WHEN 'estado_operacional'   THEN '''agendado''::contrato_estado_operacional_enum'
             WHEN 'estado_financeiro'    THEN '''pendente''::contrato_estado_financeiro_enum'
             WHEN 'facturado_em'         THEN 'NULL'
             WHEN 'tipo_fecho'           THEN 'NULL'
             WHEN 'km_saida'             THEN 'NULL'
             WHEN 'km_entrada'           THEN 'NULL'
             WHEN 'combustivel_saida'    THEN 'NULL'
             WHEN 'combustivel_entrada'  THEN 'NULL'
             WHEN 'eletricidade_saida'   THEN 'NULL'
             WHEN 'eletricidade_entrada' THEN 'NULL'
             WHEN 'dua_devolvida_em'     THEN 'NULL'
             WHEN 'entrega_via_any_rent' THEN 'false'
             WHEN 'created_by'           THEN '$5'
             WHEN 'updated_by'           THEN '$5'
             WHEN 'created_at'           THEN 'now()'
             WHEN 'updated_at'           THEN 'now()'
             ELSE quote_ident(c.column_name)
           END, ', ' ORDER BY c.ordinal_position)
    INTO v_cols, v_vals
    FROM information_schema.columns c
   WHERE c.table_schema  = 'public'
     AND c.table_name    = 'contratos_renting'
     AND c.is_generated  = 'NEVER'
     AND c.column_name  <> 'id';

  EXECUTE format(
    'INSERT INTO public.contratos_renting (%s) SELECT %s FROM public.contratos_renting WHERE id = $1 RETURNING id',
    v_cols, v_vals
  )
  INTO v_new_id
  USING v_old.id, v_old.versao + 1, p_motivo, v_data, v_user_id, v_old.data_fim;

  INSERT INTO public.contrato_condutores (
    org_id, contrato_id, cliente_id, motorista_id, is_principal
  )
  SELECT org_id, v_new_id, cliente_id, motorista_id, is_principal
    FROM public.contrato_condutores
   WHERE contrato_id = v_old.id;

  INSERT INTO public.contrato_coberturas (
    org_id, contrato_id, cobertura_id, cobertura_nome, preco_dia, franquia_valor
  )
  SELECT org_id, v_new_id, cobertura_id, cobertura_nome, preco_dia, franquia_valor
    FROM public.contrato_coberturas
   WHERE contrato_id = v_old.id;

  INSERT INTO public.contrato_extras (
    org_id, contrato_id, extra_id, extra_nome, preco_unidade, tipo_calculo, quantidade, total
  )
  SELECT org_id, v_new_id, extra_id, extra_nome, preco_unidade, tipo_calculo, quantidade, total
    FROM public.contrato_extras
   WHERE contrato_id = v_old.id;

  INSERT INTO public.contrato_taxas (
    org_id, contrato_id, taxa_id, taxa_nome, percentagem, valor_fixo, base_calculo, valor_calculado
  )
  SELECT org_id, v_new_id, taxa_id, taxa_nome, percentagem, valor_fixo, base_calculo, valor_calculado
    FROM public.contrato_taxas
   WHERE contrato_id = v_old.id;

  UPDATE public.motoristas_ativos ma
     SET status_ativo = true
   WHERE ma.status_ativo = false
     AND (
       EXISTS (
         SELECT 1 FROM public.contrato_condutores cc
          WHERE cc.contrato_id = v_new_id AND cc.motorista_id = ma.id
       )
       OR EXISTS (
         SELECT 1 FROM public.contratos_renting cr
          WHERE cr.id = v_new_id AND cr.cliente_id = ma.cliente_id
       )
     );

  SELECT matricula INTO v_matricula FROM public.viaturas WHERE id = v_old.viatura_id;

  INSERT INTO public.contrato_historico (contrato_id, org_id, evento_tipo, ator_id, detalhe)
  VALUES (
    v_old.id, v_old.org_id, 'troca_viatura', v_user_id,
    format('Substituído pelo contrato %s em %s. Viatura à saída: %s. Motivo: %s',
           v_new_id, to_char(v_data, 'DD/MM/YYYY HH24:MI'),
           COALESCE(v_matricula, v_old.matricula, '—'),
           COALESCE(NULLIF(trim(p_motivo), ''), '—'))
  );

  INSERT INTO public.contrato_historico (contrato_id, org_id, evento_tipo, ator_id, detalhe)
  VALUES (
    v_new_id, v_old.org_id, 'troca_viatura', v_user_id,
    format('Continua o contrato %s (versão %s), a partir de %s. Viatura anterior: %s. Motivo: %s',
           v_old.id, v_old.versao, to_char(v_data, 'DD/MM/YYYY HH24:MI'),
           COALESCE(v_matricula, v_old.matricula, '—'),
           COALESCE(NULLIF(trim(p_motivo), ''), '—'))
  );

  RETURN v_new_id;
END;
$_$;


ALTER FUNCTION "public"."criar_versao_contrato_renting"("p_contrato_id" "uuid", "p_motivo" "text", "p_data_troca" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cron_invocar_edge"("p_jobname" "text", "p_funcao" "text", "p_body" "jsonb" DEFAULT '{}'::"jsonb", "p_timeout_ms" integer DEFAULT 60000) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_url        text := 'https://hkqzzxgeedsmjnhyquke.supabase.co/functions/v1/' || p_funcao;
  v_jwt        text;
  v_request_id bigint;
begin
  select decrypted_secret into v_jwt
  from vault.decrypted_secrets
  where name = 'cron_service_role_jwt';

  if v_jwt is null then
    select decrypted_secret into v_jwt
    from vault.decrypted_secrets
    where name = 'cron_edge_jwt';
    if v_jwt is not null then
      raise notice 'cron_invocar_edge: a usar cron_edge_jwt (chave anon). Criar cron_service_role_jwt para fechar isto.';
    end if;
  end if;

  if v_jwt is null then
    raise exception 'cron_invocar_edge: JWT nao resolvido. Esperava cron_service_role_jwt (ou cron_edge_jwt) no Vault.';
  end if;

  select net.http_post(
    url := v_url,
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_jwt),
    body := p_body,
    timeout_milliseconds := p_timeout_ms
  ) into v_request_id;

  insert into public.cron_http_log (jobname, url, request_id)
  values (p_jobname, v_url, v_request_id);

  delete from public.cron_http_log where invoked_at < now() - interval '7 days';

  return v_request_id;
end;
$$;


ALTER FUNCTION "public"."cron_invocar_edge"("p_jobname" "text", "p_funcao" "text", "p_body" "jsonb", "p_timeout_ms" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cron_invocar_edge"("p_jobname" "text", "p_funcao" "text", "p_body" "jsonb", "p_timeout_ms" integer) IS 'Invoca uma edge function a partir de um cron, registando a invocacao em cron_http_log para poder ser cruzada com net._http_response (ver a vista cron_edge_health). Resolve o JWT do segredo cron_edge_jwt no Vault, com leitura do comando de um cron inline como fallback de transicao.';



CREATE OR REPLACE FUNCTION "public"."current_user_cargo"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT c.nome
        FROM public.user_organizacoes uo
        JOIN public.cargos c ON c.id = uo.cargo_id
       WHERE uo.user_id = auth.uid()
         AND uo.org_id  = public.get_current_org_id()
       LIMIT 1
    ),
    (SELECT cargo FROM public.profiles WHERE id = auth.uid())
  );
$$;


ALTER FUNCTION "public"."current_user_cargo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."devolver_cartao_frota"("p_cartao_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org       uuid;
  v_tipo      text;
  v_numero    text;
  v_motorista uuid;
begin
  v_org := get_current_org_id();
  if v_org is null then
    raise exception 'Sem organização activa';
  end if;

  if not (
    is_current_user_admin()
    or has_permission(auth.uid(), 'administrativo_cartoes', 'editar')
  ) then
    raise exception 'Sem permissão para gerir cartões de frota';
  end if;

  select tipo, numero, motorista_id into v_tipo, v_numero, v_motorista
  from public.cartoes_frota
  where id = p_cartao_id and org_id = v_org
  for update;

  if not found then
    raise exception 'Cartão inexistente ou de outra organização';
  end if;

  update public.cartoes_frota
  set motorista_id        = null,
      ultimo_motorista_id = v_motorista,
      status              = 'disponivel',
      data_devolucao      = current_date
  where id = p_cartao_id and org_id = v_org;

  -- A ficha só é limpa se apontava mesmo para ESTE cartão. Se o gestor já lá
  -- tinha posto outro número à mão, devolver este não pode apagá-lo.
  -- (btrim: a comparação que o frontend fazia era `.trim()` dos dois lados.)
  if v_motorista is not null then
    update public.motoristas_ativos
    set cartao_bp = case
          when v_tipo = 'bp' and btrim(coalesce(cartao_bp, '')) = btrim(v_numero)
          then null else cartao_bp end,
        cartao_repsol = case
          when v_tipo = 'repsol' and btrim(coalesce(cartao_repsol, '')) = btrim(v_numero)
          then null else cartao_repsol end,
        cartao_edp = case
          when v_tipo = 'edp' and btrim(coalesce(cartao_edp, '')) = btrim(v_numero)
          then null else cartao_edp end
    where id = v_motorista and org_id = v_org;
  end if;
end;
$$;


ALTER FUNCTION "public"."devolver_cartao_frota"("p_cartao_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."devolver_cartao_frota"("p_cartao_id" "uuid") IS 'Devolve um cartão de frota: liberta o cartão, guarda quem o tinha em ultimo_motorista_id E limpa a ficha do motorista se ela apontava para este número — numa só transacção.';



CREATE OR REPLACE FUNCTION "public"."email_caixa_tem_credenciais"("_caixa_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.email_caixas_credenciais cr
      JOIN public.email_caixas c ON c.id = cr.caixa_id
     WHERE cr.caixa_id = _caixa_id
       AND c.org_id = public.get_current_org_id()
       AND public.email_caixa_visivel(_caixa_id)
       AND (
         (c.auth_tipo = 'oauth2_m365' AND cr.oauth_client_secret IS NOT NULL)
         OR (c.auth_tipo <> 'oauth2_m365' AND cr.imap_password IS NOT NULL)
       )
  );
$$;


ALTER FUNCTION "public"."email_caixa_tem_credenciais"("_caixa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_caixa_visivel"("_caixa_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.email_caixas c
     WHERE c.id = _caixa_id
       AND c.org_id = public.get_current_org_id()
       AND (
         public.is_current_user_admin()
         OR (
           public.has_permission(auth.uid(), 'email_ver')
           AND (
             c.utilizadores_permitidos IS NULL
             OR cardinality(c.utilizadores_permitidos) = 0
             OR auth.uid() = ANY (c.utilizadores_permitidos)
           )
         )
       )
  );
$$;


ALTER FUNCTION "public"."email_caixa_visivel"("_caixa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_definir_credenciais"("p_caixa_id" "uuid", "p_imap_password" "text" DEFAULT NULL::"text", "p_smtp_password" "text" DEFAULT NULL::"text", "p_oauth_tenant_id" "text" DEFAULT NULL::"text", "p_oauth_client_id" "text" DEFAULT NULL::"text", "p_oauth_client_secret" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT org_id INTO v_org FROM public.email_caixas WHERE id = p_caixa_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Caixa de email inexistente'; END IF;
  IF v_org <> public.get_current_org_id() THEN RAISE EXCEPTION 'Caixa de email de outra organiza????o'; END IF;
  IF NOT public.email_pode_gerir() THEN RAISE EXCEPTION 'Sem permiss??o para gerir caixas de email'; END IF;

  INSERT INTO public.email_caixas_credenciais AS cr
    (caixa_id, imap_password, smtp_password, oauth_tenant_id, oauth_client_id, oauth_client_secret)
  VALUES
    (p_caixa_id, p_imap_password, p_smtp_password, p_oauth_tenant_id, p_oauth_client_id, p_oauth_client_secret)
  ON CONFLICT (caixa_id) DO UPDATE SET
    imap_password       = COALESCE(EXCLUDED.imap_password, cr.imap_password),
    smtp_password       = COALESCE(EXCLUDED.smtp_password, cr.smtp_password),
    oauth_tenant_id     = COALESCE(EXCLUDED.oauth_tenant_id, cr.oauth_tenant_id),
    oauth_client_id     = COALESCE(EXCLUDED.oauth_client_id, cr.oauth_client_id),
    oauth_client_secret = COALESCE(EXCLUDED.oauth_client_secret, cr.oauth_client_secret),
    updated_at = now();
END;
$$;


ALTER FUNCTION "public"."email_definir_credenciais"("p_caixa_id" "uuid", "p_imap_password" "text", "p_smtp_password" "text", "p_oauth_tenant_id" "text", "p_oauth_client_id" "text", "p_oauth_client_secret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_pode_gerir"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public.is_current_user_admin()
      OR public.has_permission(auth.uid(), 'email_gerir');
$$;


ALTER FUNCTION "public"."email_pode_gerir"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_candidaturas_paradas_events"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    c.org_id,
    'motorista.candidatura_parada',
    'motorista_candidaturas',
    c.id,
    jsonb_build_object(
      'nome', c.nome,
      'email', c.email,
      'status', c.status,
      'data_submissao', coalesce(c.data_submissao, c.created_at)
    ),
    'cron'
  from public.motorista_candidaturas c
  where c.status in ('submetido', 'em_analise')
    and c.org_id is not null
    and coalesce(c.data_submissao, c.created_at) <= now() - interval '3 days'
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'motorista_candidaturas'
        and e.entity_id = c.id
        and e.event_type = 'motorista.candidatura_parada'
        and e.processed_at is null
    );
end;
$$;


ALTER FUNCTION "public"."emit_candidaturas_paradas_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_contrato_renting_renovacao_events"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    x.org_id,
    'contrato_renting.renovacao_proxima',
    'contratos_renting',
    x.id,
    jsonb_build_object('codigo', x.codigo, 'matricula', x.matricula, 'cliente_nome', x.cliente_nome, 'prazo', x.prazo),
    'cron'
  from (
    select
      c.id, c.org_id, c.codigo, c.matricula, cl.nome as cliente_nome,
      coalesce(
        c.data_fim,
        public.proxima_data_renovacao(c.data_inicio, c.renovacao_opcao::text, c.renovacao_intervalo_dias)
      )::date as prazo
    from public.contratos_renting c
    join public.clientes cl on cl.id = c.cliente_id
    where c.regime in ('rent_a_car', 'tvde')
      and coalesce(c.is_longa_duracao, false) = true
      and c.substituido_em is null
      and c.deleted_at is null
      and c.estado_operacional = 'em_curso'
      and (c.data_fim is not null or c.regime = 'tvde')
  ) x
  where x.prazo is not null
    and x.prazo <= current_date
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'contratos_renting'
        and e.entity_id = x.id
        and e.event_type = 'contrato_renting.renovacao_proxima'
        and e.processed_at is null
    );
end;
$$;


ALTER FUNCTION "public"."emit_contrato_renting_renovacao_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."emit_expiry_events"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    v.org_id,
    'viatura.seguro_expirando',
    'viaturas',
    v.id,
    jsonb_build_object('seguro_validade', v.seguro_validade, 'matricula', v.matricula),
    'cron'
  from public.viaturas v
  where v.seguro_validade is not null
    and v.seguro_validade <= current_date + 15
    and (v.is_vendida is null or v.is_vendida = false)
    and coalesce(v.status, 'disponivel') <> 'inativo'
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'viaturas'
        and e.entity_id = v.id
        and e.event_type = 'viatura.seguro_expirando'
        and e.processed_at is null
    );

  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    v.org_id,
    'viatura.inspecao_expirando',
    'viaturas',
    v.id,
    jsonb_build_object('inspecao_validade', v.inspecao_validade, 'matricula', v.matricula),
    'cron'
  from public.viaturas v
  where v.inspecao_validade is not null
    and v.inspecao_validade <= current_date + 15
    and (v.is_vendida is null or v.is_vendida = false)
    and coalesce(v.status, 'disponivel') <> 'inativo'
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'viaturas'
        and e.entity_id = v.id
        and e.event_type = 'viatura.inspecao_expirando'
        and e.processed_at is null
    );

  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    v.org_id,
    'viatura.extintor_expirando',
    'viaturas',
    v.id,
    jsonb_build_object('extintor_validade', v.extintor_validade, 'matricula', v.matricula),
    'cron'
  from public.viaturas v
  where v.extintor_validade is not null
    and v.extintor_validade <= current_date + 15
    and (v.is_vendida is null or v.is_vendida = false)
    and coalesce(v.status, 'disponivel') <> 'inativo'
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'viaturas'
        and e.entity_id = v.id
        and e.event_type = 'viatura.extintor_expirando'
        and e.processed_at is null
    );

  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    x.org_id,
    'viatura.iuc_a_pagar',
    'viaturas',
    x.id,
    jsonb_build_object('matricula', x.matricula, 'marca', x.marca, 'modelo', x.modelo, 'proxima_data_iuc', x.proxima_data_iuc),
    'cron'
  from (
    select
      v.id, v.org_id, v.matricula, v.marca, v.modelo,
      (v.data_matricula + make_interval(years => extract(year from age(current_date, v.data_matricula))::int + 1))::date as proxima_data_iuc
    from public.viaturas v
    where v.data_matricula is not null
      and (v.is_vendida is null or v.is_vendida = false)
      and coalesce(v.status, 'disponivel') <> 'inativo'
  ) x
  where x.proxima_data_iuc <= current_date + 15
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'viaturas'
        and e.entity_id = x.id
        and e.event_type = 'viatura.iuc_a_pagar'
        and e.processed_at is null
    );

  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    v.org_id,
    'viatura.manutencao_preventiva_expirando',
    'viaturas',
    v.id,
    jsonb_build_object(
      'matricula', v.matricula,
      'proxima_manutencao_data', v.proxima_manutencao_data,
      'proxima_manutencao_km', v.proxima_manutencao_km,
      'km_atual', v.km_atual
    ),
    'cron'
  from public.viaturas v
  where (v.is_vendida is null or v.is_vendida = false)
    and coalesce(v.status, 'disponivel') <> 'inativo'
    and (
      (v.proxima_manutencao_data is not null and v.proxima_manutencao_data <= current_date + 15)
      or (
        v.proxima_manutencao_km is not null
        and v.km_atual is not null
        and v.km_atual >= v.proxima_manutencao_km - 500
      )
    )
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'viaturas'
        and e.entity_id = v.id
        and e.event_type = 'viatura.manutencao_preventiva_expirando'
        and e.processed_at is null
    );

  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    m.org_id,
    'motorista.carta_expirando',
    'motoristas_ativos',
    m.id,
    jsonb_build_object('carta_validade', m.carta_validade, 'nome', m.nome),
    'cron'
  from public.motoristas_ativos m
  where m.carta_validade is not null
    and m.carta_validade <= current_date + 15
    and coalesce(m.status_ativo, true) = true
    and m.org_id is not null
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'motoristas_ativos'
        and e.entity_id = m.id
        and e.event_type = 'motorista.carta_expirando'
        and e.processed_at is null
    );

  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    m.org_id,
    'motorista.licenca_tvde_expirando',
    'motoristas_ativos',
    m.id,
    jsonb_build_object('licenca_tvde_validade', m.licenca_tvde_validade, 'nome', m.nome),
    'cron'
  from public.motoristas_ativos m
  where m.licenca_tvde_validade is not null
    and m.licenca_tvde_validade <= current_date + 15
    and coalesce(m.status_ativo, true) = true
    and m.org_id is not null
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'motoristas_ativos'
        and e.entity_id = m.id
        and e.event_type = 'motorista.licenca_tvde_expirando'
        and e.processed_at is null
    );
end;
$$;


