CREATE OR REPLACE FUNCTION "public"."emit_motoristas_ficha_incompleta_events"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  select
    m.org_id,
    'motorista.ficha_incompleta',
    'motoristas_ativos',
    m.id,
    jsonb_build_object(
      'nome', m.nome,
      'campos_em_falta', to_jsonb(array_remove(array[
        case when m.nif is null or btrim(m.nif) = '' then 'NIF' end,
        case when m.email is null or btrim(m.email) = '' then 'Email' end,
        case when m.iban is null or btrim(m.iban) = '' then 'IBAN' end,
        case when m.telefone is null or btrim(m.telefone) = '' then 'Telefone' end,
        case when m.documento_tipo is null or btrim(m.documento_tipo) = '' then 'Tipo de documento' end,
        case when m.documento_numero is null or btrim(m.documento_numero) = '' then 'Nº documento' end,
        case when m.documento_validade is null then 'Validade documento' end
      ], null))
    ),
    'cron'
  from public.motoristas_ativos m
  where m.status_ativo = true
    and m.org_id is not null
    and (
      m.nif is null or btrim(m.nif) = ''
      or m.email is null or btrim(m.email) = ''
      or m.iban is null or btrim(m.iban) = ''
      or m.telefone is null or btrim(m.telefone) = ''
      or m.documento_tipo is null or btrim(m.documento_tipo) = ''
      or m.documento_numero is null or btrim(m.documento_numero) = ''
      or m.documento_validade is null
    )
    and not exists (
      select 1 from public.domain_events e
      where e.entity_table = 'motoristas_ativos'
        and e.entity_id = m.id
        and e.event_type = 'motorista.ficha_incompleta'
        and e.processed_at is null
    );
end;
$$;


