CREATE OR REPLACE FUNCTION "public"."ensure_lista_motoristas"() RETURNS "public"."marketing_listas"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid := get_current_org_id();
  v_row public.marketing_listas;
BEGIN
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'sem org no contexto';
  END IF;

  SELECT * INTO v_row
  FROM public.marketing_listas
  WHERE org_id = v_org AND origem = 'motoristas_ativos'
  LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO public.marketing_listas (nome, descricao, origem, org_id)
    VALUES ('Motoristas Ativos',
            'Lista automática — todos os motoristas ativos com email.',
            'motoristas_ativos', v_org)
    ON CONFLICT (org_id) WHERE (origem = 'motoristas_ativos') DO NOTHING
    RETURNING * INTO v_row;

    IF v_row.id IS NULL THEN
      SELECT * INTO v_row
      FROM public.marketing_listas
      WHERE org_id = v_org AND origem = 'motoristas_ativos'
      LIMIT 1;
    END IF;
  END IF;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."ensure_lista_motoristas"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enviar_digests_diarios"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_grupo record;
  v_notification_id uuid;
begin
  for v_grupo in
    select
      n.org_id,
      n.destinatario_user_id,
      u.email,
      count(*)::int as total,
      array_agg(n.id) as notif_ids,
      string_agg(n.titulo || coalesce(': ' || n.mensagem, ''), '<br>' order by n.created_at) as lista_html
    from public.notifications n
    join public.automation_runs r on r.id = n.rule_run_id
    join public.automation_rules ar on ar.id = r.rule_id
    join auth.users u on u.id = n.destinatario_user_id
    where n.digest_enviado_em is null
      and coalesce((ar.acao_config->>'enviar_email_digest')::boolean, false) = true
    group by n.org_id, n.destinatario_user_id, u.email
  loop
    if v_grupo.email is null then
      continue;
    end if;

    insert into public.notifications (org_id, destinatario_user_id, template_codigo, titulo, mensagem, payload)
    values (
      v_grupo.org_id,
      v_grupo.destinatario_user_id,
      'digest.resumo_diario',
      'Resumo diário de automações',
      v_grupo.total || ' aviso(s) novo(s)',
      jsonb_build_object('total', v_grupo.total, 'lista', v_grupo.lista_html)
    )
    returning id into v_notification_id;

    insert into public.notification_queue (notification_id, org_id, canal, destinatario, template_codigo, payload_render)
    values (
      v_notification_id,
      v_grupo.org_id,
      'email',
      v_grupo.email,
      'digest.resumo_diario',
      jsonb_build_object('total', v_grupo.total, 'lista', v_grupo.lista_html)
    );

    update public.notifications
    set digest_enviado_em = now()
    where id = any(v_grupo.notif_ids);
  end loop;
end;
$$;


ALTER FUNCTION "public"."enviar_digests_diarios"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."executar_jobs_automacao_manualmente"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_lock public.automacao_execucao_manual_lock;
  v_intervalo constant interval := interval '5 minutes';
  v_restante interval;
  v_func record;
  v_emitters_executados text[] := '{}';
begin
  if not (is_current_user_admin() or can_edit(auth.uid(), 'automacoes')) then
    raise exception 'Sem permissão para correr as automações manualmente.';
  end if;

  select * into v_lock from public.automacao_execucao_manual_lock for update;

  if v_lock.ultima_execucao_em is not null and now() - v_lock.ultima_execucao_em < v_intervalo then
    v_restante := v_intervalo - (now() - v_lock.ultima_execucao_em);
    raise exception 'Já correu há pouco — aguarda mais % antes de repetir.', to_char(v_restante, 'MI:SS');
  end if;

  update public.automacao_execucao_manual_lock
  set ultima_execucao_em = now(), executado_por = auth.uid()
  where id = true;

  for v_func in
    select p.proname
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname like 'emit\_%'
      and p.pronargs = 0
    order by p.proname
  loop
    execute format('select public.%I()', v_func.proname);
    v_emitters_executados := array_append(v_emitters_executados, v_func.proname);
  end loop;

  perform public.process_domain_events();
  perform public.execute_automation_runs();
  perform public.enviar_digests_diarios();

  return jsonb_build_object(
    'success', true,
    'executado_em', now(),
    'emitters_executados', to_jsonb(v_emitters_executados)
  );
end;
$$;


ALTER FUNCTION "public"."executar_jobs_automacao_manualmente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_automation_runs"("p_max" integer DEFAULT 20) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run public.automation_runs;
  v_rule public.automation_rules;
  v_destinatario record;
  v_notification_id uuid;
  v_cargo_ids uuid[];
  v_user_ids uuid[];
  v_modo text;
  v_enviar_email boolean;
  v_enviar_email_digest boolean;
  v_estrategia text;
  v_gestor_nome text;
  v_gestor_user_id uuid;
  v_notif_count integer;
  v_email_count integer;
  v_tipo_legado text;
  v_link text;
  v_viatura_id uuid;
  v_driver_motorista_id uuid;
  v_driver_user_id uuid;
  v_driver_email text;
begin
  for v_run in select * from public.automation_runs_claim(p_max)
  loop
    begin
      -- (a) A regra tem de pertencer à mesma organização do run.
      select * into v_rule
      from public.automation_rules
      where id = v_run.rule_id
        and org_id = v_run.org_id;

      if not found then
        perform public.automation_runs_fail(
          v_run.id,
          'Regra inexistente ou de outra organização'
        );
        continue;
      end if;

      if v_rule.acao_tipo <> 'notificacao' then
        perform public.automation_runs_complete(v_run.id);
        continue;
      end if;

      v_cargo_ids := array(
        select jsonb_array_elements_text(coalesce(v_rule.acao_config->'destinatarios_cargo_ids', '[]'::jsonb))::uuid
      );
      v_user_ids := array(
        select jsonb_array_elements_text(coalesce(v_rule.acao_config->'destinatarios_user_ids', '[]'::jsonb))::uuid
      );
      v_modo := coalesce(v_rule.acao_config->>'destinatarios_modo', 'grupo');
      v_enviar_email := coalesce((v_rule.acao_config->>'enviar_email')::boolean, false);
      v_enviar_email_digest := coalesce((v_rule.acao_config->>'enviar_email_digest')::boolean, false);
      v_estrategia := coalesce(v_rule.acao_config->>'destinatarios_estrategia', 'cargo');
      v_gestor_nome := null;
      v_gestor_user_id := null;
      v_driver_motorista_id := null;
      v_driver_user_id := null;
      v_driver_email := null;
      -- (1) SEM ISTO, o id da notificação do run anterior sobrevivia para o
      -- run seguinte — foi por aqui que emails saíram com os dados de outra
      -- organização. As variáveis são por chamada, não por iteração.
      v_notification_id := null;
      v_notif_count := 0;
      v_email_count := 0;

      v_tipo_legado := case v_rule.event_type
        when 'viatura.seguro_expirando' then 'viatura_seguro_expirando'
        when 'viatura.inspecao_expirando' then 'viatura_inspecao_expirando'
        when 'motorista.carta_expirando' then 'motorista_carta_expirando'
        when 'motorista.licenca_tvde_expirando' then 'motorista_licenca_tvde_expirando'
        when 'cobranca.gerada' then 'cobranca_gerada'
        when 'utilizador.criado' then 'utilizador_criado'
        when 'contrato_renting.renovacao_proxima' then 'contrato_renting_renovacao_proxima'
        when 'contrato_renting.criado' then 'contrato_renting_criado'
        when 'motorista.candidatura_parada' then 'motorista_candidatura_parada'
        when 'contrato_renting.sem_checkin' then 'contrato_renting_sem_checkin'
        when 'viatura.extintor_expirando' then 'viatura_extintor_expirando'
        when 'viatura.iuc_a_pagar' then 'viatura_iuc_a_pagar'
        when 'viatura.manutencao_preventiva_expirando' then 'viatura_manutencao_preventiva_expirando'
        when 'motorista.reparacao_cobranca' then 'motorista_reparacao_cobranca'
        when 'assistencia_ticket.aberto_demasiado_tempo' then 'assistencia_ticket_aberto_demasiado_tempo'
        when 'motorista.ficha_incompleta' then 'motorista_ficha_incompleta'
        when 'invoice.nao_enviada_ao_cliente' then 'invoice_nao_enviada_ao_cliente'
        when 'seguranca.login_suspeito' then 'seguranca_login_suspeito'
        else null
      end;

      v_viatura_id := case when v_run.entity_table = 'viaturas' then v_run.entity_id else null end;
      v_link := case v_run.entity_table
        when 'viaturas' then '/viaturas/' || v_run.entity_id::text
        when 'motoristas_ativos' then '/motoristas/' || v_run.entity_id::text
        when 'contratos_renting' then '/renting/contratos/' || v_run.entity_id::text
        when 'profiles' then '/admin/utilizadores'
        when 'motorista_candidaturas' then '/motoristas/candidaturas'
        when 'assistencia_tickets' then '/assistencia/' || v_run.entity_id::text
        else null
      end;

      if v_estrategia = 'motorista' then
        -- (b) O motorista tem de ser da org do run. Sem isto, um entity_id
        -- apontado a outra organização punha o email dela na fila de envio.
        if v_run.entity_table = 'motorista_financeiro' then
          select mf.motorista_id, ma.user_id, ma.email
          into v_driver_motorista_id, v_driver_user_id, v_driver_email
          from public.motorista_financeiro mf
          join public.motoristas_ativos ma on ma.id = mf.motorista_id
          where mf.id = v_run.entity_id
            and mf.org_id = v_run.org_id
            and ma.org_id = v_run.org_id;
        elsif v_run.entity_table = 'motoristas_ativos' then
          select ma.id, ma.user_id, ma.email
          into v_driver_motorista_id, v_driver_user_id, v_driver_email
          from public.motoristas_ativos ma
          where ma.id = v_run.entity_id
            and ma.org_id = v_run.org_id;
        end if;

        if v_driver_motorista_id is null then
          perform public.automation_runs_fail(
            v_run.id,
            'Entidade inexistente ou de outra organização'
          );
          continue;
        end if;

        v_link := '/motoristas/' || v_driver_motorista_id::text;

        if v_driver_user_id is not null then
          insert into public.notifications (org_id, destinatario_user_id, template_codigo, titulo, payload, entity_table, entity_id, rule_run_id, link)
          values (
            v_run.org_id,
            v_driver_user_id,
            v_rule.acao_config->>'template_codigo',
            coalesce(v_rule.acao_config->>'titulo', v_rule.nome),
            v_run.payload,
            v_run.entity_table,
            v_run.entity_id,
            v_run.id,
            v_link
          )
          returning id into v_notification_id;
          v_notif_count := v_notif_count + 1;

          if v_tipo_legado is not null then
            insert into public.notificacoes (org_id, tipo, titulo, mensagem, severidade, destinatario_id, link, viatura_id)
            values (
              v_run.org_id,
              v_tipo_legado,
              coalesce(v_rule.acao_config->>'titulo', v_rule.nome),
              null,
              'normal',
              v_driver_user_id,
              v_link,
              v_viatura_id
            );
          end if;
        end if;

        -- (2) `v_notification_id is not null` garante que a linha da fila
        -- aponta para a notificação criada NESTE run e para mais nenhuma.
        if v_enviar_email and v_driver_email is not null and v_notification_id is not null then
          insert into public.notification_queue (notification_id, org_id, canal, destinatario, template_codigo, payload_render)
          values (v_notification_id, v_run.org_id, 'email', v_driver_email, v_rule.acao_config->>'template_codigo', v_run.payload);
          v_email_count := v_email_count + 1;
        end if;

        perform public.automation_runs_complete(
          v_run.id,
          jsonb_build_object(
            'notificacoes_criadas', v_notif_count,
            'emails_enviados', v_email_count,
            -- (3) A lacuna fica registada em vez de desaparecer em silêncio.
            'email_por_enviar', case
              when v_enviar_email
               and v_driver_email is not null
               and v_notification_id is null
              then 'motorista sem conta de utilizador'
              else null
            end
          )
        );
        continue;
      end if;

      if v_estrategia = 'gestor_responsavel' then
        -- Também aqui: o nome do gestor é lido a partir de dados da entidade,
        -- e a entidade tem de ser da org do run.
        if v_run.entity_table = 'motoristas_ativos' then
          select m.gestor_responsavel into v_gestor_nome
          from public.motoristas_ativos m
          where m.id = v_run.entity_id
            and m.org_id = v_run.org_id;
        elsif v_run.entity_table = 'viaturas' then
          select m.gestor_responsavel into v_gestor_nome
          from public.motorista_viaturas mv
          join public.motoristas_ativos m on m.id = mv.motorista_id
          where mv.viatura_id = v_run.entity_id
            and m.org_id = v_run.org_id
            and mv.status = 'ativo'
            and mv.data_fim is null
          limit 1;
        end if;

        if v_gestor_nome is not null and btrim(v_gestor_nome) <> '' then
          select p.id into v_gestor_user_id
          from public.profiles p
          where lower(btrim(p.nome)) = lower(btrim(v_gestor_nome))
            and p.org_id = v_run.org_id
          limit 1;
        end if;
      end if;

      -- Esta parte já estava correcta: os destinatários saem sempre de
      -- user_organizacoes filtrado por `uo.org_id = v_run.org_id`, pelo que
      -- ids de cargo/utilizador vindos da config nunca alcançam outra org.
      for v_destinatario in
        select u.id as user_id, u.email
        from auth.users u
        where (
          v_gestor_user_id is not null and u.id = v_gestor_user_id
        ) or (
          v_gestor_user_id is null and u.id in (
            select uo.user_id
            from public.user_organizacoes uo
            where uo.org_id = v_run.org_id
              and (
                uo.is_admin = true
                or (
                  v_estrategia = 'cargo'
                  and uo.cargo_id is not null
                  and (
                    (v_modo = 'individual' and uo.user_id = any(v_user_ids))
                    or (v_modo <> 'individual' and uo.cargo_id = any(v_cargo_ids))
                  )
                )
              )
          )
        )
      loop
        insert into public.notifications (org_id, destinatario_user_id, template_codigo, titulo, payload, entity_table, entity_id, rule_run_id, link)
        values (
          v_run.org_id,
          v_destinatario.user_id,
          v_rule.acao_config->>'template_codigo',
          coalesce(v_rule.acao_config->>'titulo', v_rule.nome),
          v_run.payload,
          v_run.entity_table,
          v_run.entity_id,
          v_run.id,
          v_link
        )
        returning id into v_notification_id;
        v_notif_count := v_notif_count + 1;

        if v_tipo_legado is not null then
          insert into public.notificacoes (org_id, tipo, titulo, mensagem, severidade, destinatario_id, link, viatura_id)
          values (
            v_run.org_id,
            v_tipo_legado,
            coalesce(v_rule.acao_config->>'titulo', v_rule.nome),
            null,
            'normal',
            v_destinatario.user_id,
            v_link,
            v_viatura_id
          );
        end if;

        if v_enviar_email and not v_enviar_email_digest and v_destinatario.email is not null then
          insert into public.notification_queue (notification_id, org_id, canal, destinatario, template_codigo, payload_render)
          values (v_notification_id, v_run.org_id, 'email', v_destinatario.email, v_rule.acao_config->>'template_codigo', v_run.payload);
          v_email_count := v_email_count + 1;
        end if;
      end loop;

      perform public.automation_runs_complete(
        v_run.id,
        jsonb_build_object('notificacoes_criadas', v_notif_count, 'emails_enviados', v_email_count)
      );
    exception when others then
      perform public.automation_runs_fail(v_run.id, sqlerrm);
    end;
  end loop;
end;
$$;


ALTER FUNCTION "public"."execute_automation_runs"("p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_gestor_assignment"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  updated_count integer := 0;
  assignment_record record;
BEGIN
  FOR assignment_record IN 
    SELECT * FROM assign_gestors_from_history()
  LOOP
    UPDATE leads_dasprent 
    SET gestor_responsavel = assignment_record.gestor_nome
    WHERE id = assignment_record.lead_id;
    
    updated_count := updated_count + 1;
  END LOOP;
  
  RETURN updated_count;
END;
$$;


ALTER FUNCTION "public"."execute_gestor_assignment"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."faturacao_outbox" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "tipo" "text" NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "parcela_id" "uuid",
    "payload" "jsonb" NOT NULL,
    "estado" "text" DEFAULT 'pendente'::"text" NOT NULL,
    "needs_reconcile" boolean DEFAULT false NOT NULL,
    "tentativas" smallint DEFAULT 0 NOT NULL,
    "proxima_tentativa" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ultimo_erro" "text",
    "invoice_id" "uuid",
    "started_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "faturacao_outbox_estado_check" CHECK (("estado" = ANY (ARRAY['pendente'::"text", 'em_curso'::"text", 'sucesso'::"text", 'falhado'::"text", 'suspenso'::"text"]))),
    CONSTRAINT "faturacao_outbox_tipo_check" CHECK (("tipo" = 'RC'::"text"))
);


ALTER TABLE "public"."faturacao_outbox" OWNER TO "postgres";


COMMENT ON TABLE "public"."faturacao_outbox" IS 'Fila de emissão de documentos fiscais com garantia de não-duplicação. estado suspenso = resultado desconhecido no provider, aguarda decisão humana.';



CREATE OR REPLACE FUNCTION "public"."faturacao_outbox_claim"("p_max" integer) RETURNS SETOF "public"."faturacao_outbox"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_capacity integer;
BEGIN
  -- FOR UPDATE SKIP LOCKED sozinho só impede duas invocações agarrarem a MESMA
  -- linha — não impede que duas sobrepostas, cada uma vendo "há folga",
  -- reclamem em conjunto mais do que p_max.
  IF NOT pg_try_advisory_xact_lock(hashtext('faturacao_outbox_claim')) THEN
    RETURN;
  END IF;

  -- Reaper: linha presa vai DIRETO para 'suspenso'. Uma execução interrompida
  -- deixa o resultado no provider desconhecido, e na v1 desconhecido nunca é
  -- reemitido automaticamente. Voltar a 'pendente' só gastaria um ciclo de claim.
  UPDATE public.faturacao_outbox
     SET estado = 'suspenso', needs_reconcile = true,
         ultimo_erro = 'Interrompida — estado no provider desconhecido'
   WHERE estado = 'em_curso' AND started_at < now() - interval '10 minutes';

  SELECT GREATEST(p_max - count(*), 0) INTO v_capacity
    FROM public.faturacao_outbox WHERE estado = 'em_curso';
  IF v_capacity = 0 THEN RETURN; END IF;

  RETURN QUERY
  UPDATE public.faturacao_outbox o
     SET estado = 'em_curso', started_at = now(), tentativas = o.tentativas + 1
    FROM (
      SELECT id FROM public.faturacao_outbox
       WHERE estado = 'pendente' AND proxima_tentativa <= now()
       ORDER BY proxima_tentativa ASC
       LIMIT v_capacity
       FOR UPDATE SKIP LOCKED
    ) c
   WHERE o.id = c.id
  RETURNING o.*;
END;
$$;


ALTER FUNCTION "public"."faturacao_outbox_claim"("p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_acordo_protege_titular"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.titular_id IS DISTINCT FROM OLD.titular_id
  OR NEW.titular_nif IS DISTINCT FROM OLD.titular_nif THEN
    RAISE EXCEPTION
      'Titular do acordo é imutável — é o NIF de todos os recibos emitidos.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_acordo_protege_titular"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_audit_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at := timezone('utc', now());
  NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_audit_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_bolt_recusa_ganhos_sem_atividade"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_sem_metricas boolean;
  v_anterior     numeric;
begin
  if coalesce(NEW.ganhos_liquidos, 0) <= 0
     or coalesce(NEW.viagens_terminadas, 0) <> 0
     or coalesce(NEW.tempo_online_min, 0) <> 0
     or coalesce(NEW.distancia_total_km, 0) <> 0
     or coalesce(NEW.ganhos_campanha, 0) <> 0
     or coalesce(NEW.reembolsos_despesas, 0) <> 0
  then
    return NEW;
  end if;

  select coalesce(p.csv_sem_metricas_atividade, false)
  into v_sem_metricas
  from public.plataformas_configuracao p
  where p.id = NEW.integracao_id;

  if not coalesce(v_sem_metricas, false) then
    raise exception
      'Bolt: % EUR de ganhos sem atividade nenhuma (0 viagens, 0 min online, 0 km, '
      'sem campanha nem reembolso) para "%" no período %. Isto costuma ser um '
      'ficheiro de outra semana importado por engano — confirme o período do CSV '
      'antes de reimportar.',
      NEW.ganhos_liquidos, coalesce(NEW.motorista_nome, NEW.chave_motorista, '?'),
      coalesce(NEW.periodo, NEW.periodo_inicio::text, '?');
  end if;

  select r.ganhos_liquidos
  into v_anterior
  from public.bolt_resumos_semanais r
  where r.integracao_id = NEW.integracao_id
    and r.chave_motorista = NEW.chave_motorista
    and r.periodo_inicio = NEW.periodo_inicio - 7
  limit 1;

  if v_anterior is not null and v_anterior = NEW.ganhos_liquidos then
    raise exception
      'Bolt: % EUR para "%" no período % são cópia exacta da semana anterior. '
      'É a assinatura de um ficheiro da semana errada — confirme o período do '
      'CSV antes de reimportar.',
      NEW.ganhos_liquidos, coalesce(NEW.motorista_nome, NEW.chave_motorista, '?'),
      coalesce(NEW.periodo, NEW.periodo_inicio::text, '?');
  end if;

  return NEW;
end;
$$;


ALTER FUNCTION "public"."fn_bolt_recusa_ganhos_sem_atividade"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_bolt_recusa_ganhos_sem_atividade"() IS 'Trava ganhos Bolt sem atividade nenhuma (incidente de 10/08/2026, ~1.844 EUR fantasma). Nas contas com csv_sem_metricas_atividade=true, onde o relatório nunca traz atividade, troca essa verificação pela recusa de valores que sejam cópia exacta da semana anterior.';



