CREATE OR REPLACE FUNCTION "public"."fn_checkin_abrir_motorista_viatura"("p_motorista_id" "uuid", "p_viatura_id" "uuid", "p_data_inicio" "date", "p_observacoes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid := get_current_org_id();
  v_id uuid;
BEGIN
  IF NOT (
    is_current_user_admin()
    OR has_permission(auth.uid(), 'motoristas_gestao')
    OR has_permission(auth.uid(), 'calendario_recolhas')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para associar motorista a viatura.';
  END IF;

  INSERT INTO public.motorista_viaturas (
    motorista_id, viatura_id, data_inicio, status, org_id, observacoes
  )
  VALUES (
    p_motorista_id, p_viatura_id, p_data_inicio, 'ativo', v_org_id, p_observacoes
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."fn_checkin_abrir_motorista_viatura"("p_motorista_id" "uuid", "p_viatura_id" "uuid", "p_data_inicio" "date", "p_observacoes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_checkin_abrir_motorista_viatura"("p_motorista_id" "uuid", "p_viatura_id" "uuid", "p_data_inicio" "date", "p_observacoes" "text") IS 'Associa motorista a viatura em motorista_viaturas (check-in/troca legacy). Aceita motoristas_gestao OU calendario_recolhas — evita que colaboradores de check-in sem motoristas_gestao vejam o INSERT falhar silenciosamente.';



CREATE OR REPLACE FUNCTION "public"."fn_checkin_fechar_motorista_viatura"("p_motorista_id" "uuid" DEFAULT NULL::"uuid", "p_viatura_id" "uuid" DEFAULT NULL::"uuid", "p_data_fim" "date" DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF p_viatura_id IS NULL THEN
    RAISE EXCEPTION 'p_viatura_id é obrigatório.';
  END IF;

  IF NOT (
    is_current_user_admin()
    OR has_permission(auth.uid(), 'motoristas_gestao')
    OR has_permission(auth.uid(), 'calendario_recolhas')
  ) THEN
    RAISE EXCEPTION 'Sem permissão para desassociar motorista de viatura.';
  END IF;

  UPDATE public.motorista_viaturas
     SET status = 'encerrado', data_fim = COALESCE(data_fim, p_data_fim)
   WHERE viatura_id = p_viatura_id
     AND status = 'ativo'
     AND (p_motorista_id IS NULL OR motorista_id = p_motorista_id);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


