CREATE OR REPLACE FUNCTION "public"."fn_cleanup_on_evento_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.tipo = 'entrega' THEN
    -- Close motorista_viaturas linked via contrato
    UPDATE motorista_viaturas mv
    SET status = 'encerrado', data_fim = CURRENT_DATE
    FROM contratos ct
    WHERE ct.calendario_evento_id = OLD.id
      AND mv.motorista_id = ct.motorista_id
      AND mv.viatura_id = ct.viatura_id
      AND mv.status = 'ativo';

    -- Release viatura linked via contrato
    UPDATE viaturas v
    SET status = 'disponivel'
    FROM contratos ct
    WHERE ct.calendario_evento_id = OLD.id
      AND v.id = ct.viatura_id;

    -- Close the contrato
    UPDATE contratos
    SET status = 'encerrado'
    WHERE calendario_evento_id = OLD.id AND status = 'ativo';
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."fn_cleanup_on_evento_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_clientes_sync_tipo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Se vier is_empresa=true mas tipo ficou no default, ajusta o tipo.
    IF NEW.tipo_cliente = 'particular' AND NEW.is_empresa = true THEN
      NEW.tipo_cliente := 'empresa';
    END IF;
    NEW.is_empresa := (NEW.tipo_cliente = 'empresa');
  ELSE
    -- Update: o lado que mudou manda no outro.
    IF NEW.tipo_cliente IS DISTINCT FROM OLD.tipo_cliente THEN
      NEW.is_empresa := (NEW.tipo_cliente = 'empresa');
    ELSIF NEW.is_empresa IS DISTINCT FROM OLD.is_empresa THEN
      NEW.tipo_cliente := CASE WHEN NEW.is_empresa THEN 'empresa' ELSE 'particular' END;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_clientes_sync_tipo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cobranca_posta_movimento"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.estado = 'emitida' AND NEW.valor_total > 0 THEN
      INSERT INTO public.conta_movimentos
        (org_id, entidade_id, tipo, valor, origem, cobranca_id, contrato_id, descricao)
      VALUES
        (NEW.org_id, NEW.destinatario_id, 'debito', NEW.valor_total, 'cobranca',
         NEW.id, NEW.contrato_id, COALESCE(NEW.descricao, 'Cobrança de contrato'));
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.estado = 'pendente' AND NEW.estado = 'emitida' AND NEW.valor_total > 0 THEN
      INSERT INTO public.conta_movimentos
        (org_id, entidade_id, tipo, valor, origem, cobranca_id, contrato_id, descricao)
      VALUES
        (NEW.org_id, NEW.destinatario_id, 'debito', NEW.valor_total, 'cobranca',
         NEW.id, NEW.contrato_id, COALESCE(NEW.descricao, 'Cobrança de contrato'));

    ELSIF OLD.estado IN ('emitida','paga') AND NEW.estado = 'anulada' AND NEW.valor_total > 0 THEN
      INSERT INTO public.conta_movimentos
        (org_id, entidade_id, tipo, valor, origem, cobranca_id, contrato_id, descricao)
      VALUES
        (NEW.org_id, NEW.destinatario_id, 'credito', NEW.valor_total, 'cobranca',
         NEW.id, NEW.contrato_id,
         'Anulamento de ' || SPLIT_PART(COALESCE(NEW.descricao, 'Cobrança'), ' — ', 1));
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


