CREATE OR REPLACE FUNCTION "public"."fn_contrato_condutor_liga_motorista"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_c public.contratos_renting%ROWTYPE;
  v_inicio date;
  v_fim    date;
BEGIN
  IF NEW.motorista_id IS NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_c FROM public.contratos_renting WHERE id = NEW.contrato_id;
  IF NOT FOUND THEN RETURN NEW; END IF;
  IF v_c.deleted_at IS NOT NULL OR v_c.substituido_em IS NOT NULL THEN RETURN NEW; END IF;
  IF v_c.estado_operacional NOT IN ('agendado', 'em_curso') THEN RETURN NEW; END IF;
  IF v_c.viatura_id IS NULL OR v_c.regime = 'slot' THEN RETURN NEW; END IF;

  IF EXISTS (
    SELECT 1 FROM public.motorista_viaturas
    WHERE motorista_id = NEW.motorista_id AND viatura_id = v_c.viatura_id
      AND status = 'ativo' AND data_fim IS NULL
  ) THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.motorista_viaturas
    WHERE viatura_id = v_c.viatura_id AND status = 'ativo' AND data_fim IS NULL
  ) THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.motorista_viaturas
    WHERE motorista_id = NEW.motorista_id AND status = 'ativo' AND data_fim IS NULL
  ) THEN
    RETURN NEW;
  END IF;

  -- A data do CONDUTOR é a que diz quando ele pegou nesta viatura. A do
  -- contrato só serve quando aquela não existe.
  v_inicio := COALESCE(
    (NEW.data_inicio AT TIME ZONE 'Europe/Lisbon')::date,
    (v_c.data_inicio AT TIME ZONE 'Europe/Lisbon')::date,
    CURRENT_DATE
  );

  v_fim := COALESCE(
    (NEW.data_fim AT TIME ZONE 'Europe/Lisbon')::date,
    (v_c.data_fim AT TIME ZONE 'Europe/Lisbon')::date
  );

  -- Um fim anterior ao início não é um período curto: é lixo. Vale mais uma
  -- atribuição em aberto, que alguém fecha, do que um intervalo impossível
  -- que nenhuma consulta por datas consegue interpretar.
  IF v_fim IS NOT NULL AND v_fim < v_inicio THEN
    v_fim := NULL;
  END IF;

  INSERT INTO public.motorista_viaturas
    (motorista_id, viatura_id, data_inicio, data_fim, status, org_id, observacoes)
  VALUES (
    NEW.motorista_id, v_c.viatura_id, v_inicio, v_fim,
    'ativo', v_c.org_id, 'Gerado ao associar condutor ao contrato #' || v_c.codigo
  );

  UPDATE public.motoristas_ativos SET status_ativo = true
   WHERE id = NEW.motorista_id AND status_ativo = false;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_contrato_condutor_liga_motorista"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_contrato_condutor_liga_motorista"() IS 'Cria a ligacao motorista-viatura ao associar um condutor ao contrato, com o inicio E o FIM do contrato. Sem a data de fim o resumo semanal cobrava os 7 dias para sempre. Ver migracao 20260814140000.';



CREATE OR REPLACE FUNCTION "public"."fn_contrato_dias"("p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  -- Ceil para garantir que 1 dia + 1 hora conta como 2 dias
  -- (alinhado com rent-a-car standard — cobra-se por dia iniciado)
  SELECT GREATEST(
    1,
    CEIL(EXTRACT(epoch FROM (p_data_fim - p_data_inicio)) / 86400)::integer
  );
$$;


ALTER FUNCTION "public"."fn_contrato_dias"("p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_contrato_fechado_com_danos_domain_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_contrato   record;
  v_cliente    text;
  v_matricula  text;
begin
  if new.contrato_renting_id is null then
    return new;
  end if;

  select c.id, c.org_id, c.codigo, c.matricula, c.cliente_id,
         c.data_inicio, c.data_fim, c.km_entrada, c.estado_operacional
    into v_contrato
    from public.contratos_renting c
   where c.id = new.contrato_renting_id
     and c.deleted_at is null;

  if not found then
    return new;
  end if;

  -- Danos registados a mao num contrato a decorrer nao sao um fecho.
  if v_contrato.estado_operacional not in ('fechado', 'devolvido') then
    return new;
  end if;

  select nome into v_cliente from public.clientes where id = v_contrato.cliente_id;
  select v.matricula into v_matricula from public.viaturas v where v.id = new.viatura_id;

  insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
  values (
    v_contrato.org_id,
    'contrato_renting.fechado_com_danos',
    'contratos_renting',
    v_contrato.id,
    jsonb_build_object(
      'codigo',        v_contrato.codigo,
      'matricula',     coalesce(v_matricula, v_contrato.matricula),
      'cliente_nome',  coalesce(v_cliente, '-'),
      'data_inicio',   v_contrato.data_inicio,
      'data_fim',      v_contrato.data_fim,
      'km_entrada',    v_contrato.km_entrada,
      'dano_descricao', coalesce(nullif(btrim(new.descricao), ''), 'Registo de recolha'),
      'dano_observacoes', coalesce(nullif(btrim(new.observacoes), ''), '-'),
      'link', 'https://wegest.pt/renting/contratos/' || v_contrato.id::text
    ),
    'trigger'
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_contrato_fechado_com_danos_domain_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_contrato_herda_cobrancas_reserva"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_tem boolean;
BEGIN
  IF NEW.reserva_id IS NOT NULL THEN
    UPDATE public.contrato_cobrancas
       SET contrato_id = NEW.id
     WHERE reserva_id = NEW.reserva_id
       AND contrato_id IS NULL;

    SELECT EXISTS (
      SELECT 1 FROM public.contrato_cobrancas
       WHERE contrato_id = NEW.id AND estado IN ('emitida', 'paga')
    ) INTO v_tem;

    IF v_tem THEN
      UPDATE public.contratos_renting
         SET estado_financeiro = 'facturado'
       WHERE id = NEW.id AND estado_financeiro = 'pendente';
    END IF;
  END IF;
  RETURN NULL;
END;
$$;


