    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.fn_contrato_historico_log(
    NEW.id, NEW.org_id, 'contrato_aberto', COALESCE(NEW.created_by, auth.uid()),
    'estado inicial: ' || NEW.estado_operacional
  );
  IF NEW.estado_financeiro = 'facturado' THEN
    PERFORM public.fn_contrato_historico_log(
      NEW.id, NEW.org_id, 'contrato_faturado', COALESCE(NEW.created_by, auth.uid()), NULL
    );
  END IF;
  RETURN NEW;
END;
$$;


