    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_res record;
BEGIN
  IF NEW.reserva_id IS NULL THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.contrato_historico
             WHERE contrato_id = NEW.id AND evento_tipo = 'reserva_criada') THEN
    RETURN NEW;
  END IF;
  SELECT created_by, created_at INTO v_res FROM public.reservas WHERE id = NEW.reserva_id;
  IF FOUND THEN
    INSERT INTO public.contrato_historico (contrato_id, org_id, evento_tipo, ator_id, criado_em)
    VALUES (NEW.id, NEW.org_id, 'reserva_criada', v_res.created_by,
            COALESCE(v_res.created_at, timezone('utc', now())));
  END IF;
  RETURN NEW;
END;
$$;


