CREATE OR REPLACE FUNCTION "public"."fn_contratos_renting_freeze_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_dias INTEGER;
  v_cobertura_custo NUMERIC(10, 2);
  v_extra_custo NUMERIC(10, 2);
  v_subtotal_bruto NUMERIC(10, 2);
  v_total_com_iva NUMERIC(10, 2);
  v_subtotal_final NUMERIC(10, 2);
  v_iva NUMERIC(10, 2);
  v_taxa_custo NUMERIC(10, 2);
  v_total NUMERIC(10, 2);
BEGIN
  IF NEW.estado_financeiro = 'facturado'
     AND (OLD.estado_financeiro IS DISTINCT FROM 'facturado'
          OR NEW.total_final IS NULL) THEN

    v_dias := public.fn_contrato_dias(NEW.data_inicio, NEW.data_fim);

    v_cobertura_custo := (
      SELECT COALESCE(SUM(preco_dia), 0) * v_dias
      FROM public.contrato_coberturas
      WHERE contrato_id = NEW.id
    );

    v_extra_custo := (
      SELECT COALESCE(SUM(
        CASE
          WHEN tipo_calculo = 'fixo' THEN preco_unidade * quantidade
          ELSE preco_unidade * quantidade * v_dias
        END
      ), 0)
      FROM public.contrato_extras
      WHERE contrato_id = NEW.id
    );

    v_subtotal_bruto := COALESCE(
      NEW.valor_total_manual,
      COALESCE(NEW.tarifa_diaria, 0) * v_dias
    ) + v_cobertura_custo + v_extra_custo;

    IF NEW.regime = 'rent_a_car' THEN
      v_subtotal_final := ROUND(v_subtotal_bruto * (1 - COALESCE(NEW.desconto_percentagem, 0) / 100), 2);
      v_iva := CASE WHEN NEW.taxa_iva > 0 THEN ROUND(v_subtotal_final * NEW.taxa_iva / 100, 2) ELSE 0 END;
      v_total_com_iva := v_subtotal_final + v_iva;
    ELSE
      v_total_com_iva :=
        ROUND(v_subtotal_bruto * (1 - COALESCE(NEW.desconto_percentagem, 0) / 100), 2);
      IF NEW.taxa_iva > 0 THEN
        v_subtotal_final := ROUND(v_total_com_iva / (1 + NEW.taxa_iva / 100), 2);
      ELSE
        v_subtotal_final := v_total_com_iva;
      END IF;
      v_iva := ROUND(v_total_com_iva - v_subtotal_final, 2);
    END IF;

    v_taxa_custo := (
      SELECT COALESCE(SUM(
        CASE
          WHEN percentagem IS NOT NULL
            THEN ROUND(v_total_com_iva * percentagem / 100, 2)
          ELSE COALESCE(valor_fixo, 0)
        END
      ), 0)
      FROM public.contrato_taxas
      WHERE contrato_id = NEW.id
    );

    v_total := v_total_com_iva + v_taxa_custo;

    NEW.total_subtotal := v_subtotal_final;
    NEW.total_iva := v_iva;
    NEW.total_final := v_total;
    NEW.facturado_em := COALESCE(NEW.facturado_em, timezone('utc', now()));
  END IF;

  IF OLD.estado_financeiro = 'facturado'
     AND NEW.estado_financeiro IN ('pendente', 'anulado') THEN
    NEW.total_subtotal := NULL;
    NEW.total_iva := NULL;
    NEW.total_final := NULL;
    NEW.facturado_em := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_contratos_renting_freeze_totals"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_contratos_renting_freeze_totals"() IS 'Congela total_subtotal/total_iva/total_final ao facturar (compliance SAF-T — imutável depois). Rent-a-Car: preço da tarifa é sem IVA, soma-se por cima. TVDE/slot: preço já com IVA incluído, decompõe-se. Fix 2026-07-10 (regime-aware).';



CREATE OR REPLACE FUNCTION "public"."fn_contratos_renting_versao_imutavel"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.substituido_em IS NOT NULL THEN
    -- Permite só alterar deleted_at (soft-delete administrativo) e
    -- updated_at/updated_by (refrescados por triggers internos).
    IF (NEW.tarifa_diaria          IS DISTINCT FROM OLD.tarifa_diaria)
       OR (NEW.desconto_percentagem IS DISTINCT FROM OLD.desconto_percentagem)
       OR (NEW.taxa_iva             IS DISTINCT FROM OLD.taxa_iva)
       OR (NEW.valor_total_manual   IS DISTINCT FROM OLD.valor_total_manual)
       OR (NEW.franquia_valor       IS DISTINCT FROM OLD.franquia_valor)
       OR (NEW.caucao_valor         IS DISTINCT FROM OLD.caucao_valor)
       OR (NEW.kms_incluidos        IS DISTINCT FROM OLD.kms_incluidos)
       OR (NEW.km_adicional_valor   IS DISTINCT FROM OLD.km_adicional_valor)
       OR (NEW.estado_operacional   IS DISTINCT FROM OLD.estado_operacional)
       OR (NEW.estado_financeiro    IS DISTINCT FROM OLD.estado_financeiro)
       OR (NEW.viatura_id           IS DISTINCT FROM OLD.viatura_id)
       OR (NEW.cliente_id           IS DISTINCT FROM OLD.cliente_id)
       OR (NEW.emissor_id           IS DISTINCT FROM OLD.emissor_id)
       OR (NEW.data_inicio          IS DISTINCT FROM OLD.data_inicio)
       OR (NEW.data_fim             IS DISTINCT FROM OLD.data_fim)
       OR (NEW.regime               IS DISTINCT FROM OLD.regime)
       OR (NEW.transferista_id      IS DISTINCT FROM OLD.transferista_id)
       OR (NEW.motivo_versao        IS DISTINCT FROM OLD.motivo_versao)
       OR (NEW.versao               IS DISTINCT FROM OLD.versao)
       OR (NEW.contrato_anterior_id IS DISTINCT FROM OLD.contrato_anterior_id)
    THEN
      RAISE EXCEPTION
        'Versão substituída de contrato é imutável. Cria uma nova versão se queres editar.'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_contratos_renting_versao_imutavel"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_contratos_validar_reserva"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.viatura_id IS NULL OR NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Estados activos do contrato bloqueiam
  IF NEW.estado_operacional NOT IN ('agendado', 'em_curso') THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.reservas r
    WHERE r.org_id = NEW.org_id
      AND r.viatura_id = NEW.viatura_id
      AND r.deleted_at IS NULL
      AND r.estado IN ('pendente', 'confirmada', 'em_curso')
      AND r.periodo && NEW.periodo
      -- Excepção: reserva que ORIGINOU este contrato não conflita consigo mesma
      AND (NEW.reserva_id IS NULL OR r.id <> NEW.reserva_id)
  ) THEN
    RAISE EXCEPTION
      'Conflito: viatura já tem reserva activa sobreposta para este período.'
      USING ERRCODE = 'exclusion_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_contratos_validar_reserva"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ensure_cliente_condutor"("p_motorista_id" "uuid", "p_org_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mot record;
  v_cli uuid;
BEGIN
  SELECT * INTO v_mot FROM public.motoristas_ativos WHERE id = p_motorista_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fn_ensure_cliente_condutor: motorista % inexistente', p_motorista_id;
  END IF;

  -- 1) já ligado?
  IF v_mot.cliente_id IS NOT NULL THEN
    RETURN v_mot.cliente_id;
  END IF;

  -- 2) procurar cliente condutor existente por NIF (quando há NIF)
  IF v_mot.nif IS NOT NULL AND length(btrim(v_mot.nif)) > 0 THEN
    SELECT id INTO v_cli
    FROM public.clientes
    WHERE org_id = p_org_id
      AND tipo_cliente = 'condutor'
      AND nif = v_mot.nif
      AND deleted_at IS NULL
    LIMIT 1;
  END IF;

  -- 3) criar se não existe
  IF v_cli IS NULL THEN
    INSERT INTO public.clientes (org_id, tipo_cliente, is_empresa, nome, nif, email, telefone)
    VALUES (p_org_id, 'condutor', false, v_mot.nome, v_mot.nif, v_mot.email, v_mot.telefone)
    RETURNING id INTO v_cli;
  END IF;

  -- 4) cache no motorista
  UPDATE public.motoristas_ativos SET cliente_id = v_cli WHERE id = p_motorista_id;

  RETURN v_cli;
END;
$$;


ALTER FUNCTION "public"."fn_ensure_cliente_condutor"("p_motorista_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ensure_cliente_condutor"("p_motorista_id" "uuid", "p_org_id" "uuid") IS 'Garante (cria ou encontra) o cliente fiscal tipo=condutor que representa um motorista e devolve o seu id. Idempotente via cache motoristas_ativos.cliente_id.';



