CREATE OR REPLACE FUNCTION "public"."fn_login_attempts_rate_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_por_email integer;
  v_global integer;
begin
  select count(*) into v_por_email
  from public.login_attempts
  where email = new.email and created_at >= now() - interval '5 minutes';

  if v_por_email >= 20 then
    return null;
  end if;

  select count(*) into v_global
  from public.login_attempts
  where created_at >= now() - interval '1 minute';

  if v_global >= 200 then
    return null;
  end if;

  return new;
end;
$$;


