CREATE OR REPLACE FUNCTION "public"."fn_mapeamento_mesma_org"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_motorista uuid;
begin
  if new.motorista_id is null then
    return new;
  end if;

  select m.org_id into v_org_motorista
  from public.motoristas_ativos m
  where m.id = new.motorista_id;

  if v_org_motorista is null then
    raise exception
      'Motorista % nao existe - ligacao recusada (tabela %).',
      new.motorista_id, tg_table_name
      using errcode = 'foreign_key_violation';
  end if;

  if new.org_id is distinct from v_org_motorista then
    raise exception
      'Ligacao entre empresas recusada: linha da org % a apontar para motorista da org % (tabela %, motorista %). Cada empresa tem de ter a sua propria ficha.',
      new.org_id, v_org_motorista, tg_table_name, new.motorista_id
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


