CREATE OR REPLACE FUNCTION "public"."fn_motorista_financeiro_reparacao_domain_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_matricula text;
  v_ticket_numero int;
begin
  if new.categoria <> 'reparacao' or new.tipo <> 'debito' or new.reparacao_id is null then
    return new;
  end if;

  select ma.org_id into v_org_id
  from public.motoristas_ativos ma
  where ma.id = new.motorista_id;

  select v.matricula into v_matricula
  from public.viatura_reparacoes vr
  join public.viaturas v on v.id = vr.viatura_id
  where vr.id = new.reparacao_id;

  select at.numero into v_ticket_numero
  from public.assistencia_tickets at
  where at.reparacao_id = new.reparacao_id
  limit 1;

  if v_org_id is not null then
    insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
    values (
      v_org_id,
      'motorista.reparacao_cobranca',
      'motorista_financeiro',
      new.id,
      jsonb_build_object(
        'motorista_id', new.motorista_id,
        'valor', new.valor,
        'descricao', new.descricao,
        'matricula', v_matricula,
        'ticket_numero', v_ticket_numero,
        'reparacao_id', new.reparacao_id
      ),
      'trigger'
    );
  end if;

  return new;
end;
$$;


