CREATE OR REPLACE FUNCTION "public"."fn_motorista_historico_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status_ativo IS DISTINCT FROM OLD.status_ativo THEN
    NEW.desativado_em := CASE WHEN NEW.status_ativo = false
                              THEN timezone('utc', now())
                              ELSE NULL END;

    INSERT INTO public.motorista_historico (motorista_id, org_id, evento_tipo, ator_id, detalhe)
    VALUES (
      NEW.id,
      NEW.org_id,
      CASE WHEN NEW.status_ativo = false THEN 'desativado' ELSE 'ativado' END,
      auth.uid(),
      format('status_ativo: %s → %s', OLD.status_ativo, NEW.status_ativo)
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_motorista_historico_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_motorista_viaturas_fecha_anteriores"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- O motorista larga o que tinha: acaba na véspera de pegar no novo.
  UPDATE public.motorista_viaturas
     SET data_fim = NEW.data_inicio - 1
   WHERE motorista_id = NEW.motorista_id
     AND id <> NEW.id
     AND viatura_id IS DISTINCT FROM NEW.viatura_id
     AND data_inicio < NEW.data_inicio
     AND (data_fim IS NULL OR data_fim >= NEW.data_inicio);

  -- E a viatura larga quem a tinha.
  UPDATE public.motorista_viaturas
     SET data_fim = NEW.data_inicio - 1
   WHERE viatura_id = NEW.viatura_id
     AND id <> NEW.id
     AND motorista_id IS DISTINCT FROM NEW.motorista_id
     AND data_inicio < NEW.data_inicio
     AND (data_fim IS NULL OR data_fim >= NEW.data_inicio);

  RETURN NULL;
END $$;


ALTER FUNCTION "public"."fn_motorista_viaturas_fecha_anteriores"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_motorista_viaturas_normaliza"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.data_inicio IS NULL THEN
    NEW.data_inicio := CURRENT_DATE;
  END IF;
  IF NEW.data_fim IS NOT NULL AND NEW.data_fim < NEW.data_inicio THEN
    NEW.data_fim := NULL;
  END IF;
  RETURN NEW;
END $$;


