CREATE OR REPLACE FUNCTION "public"."fn_nota_credito_posta_movimento"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_cobranca_estado text;
  v_motorista       uuid;
  v_anulada         boolean;
  v_precisa_par     boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.estado = 'ativo' THEN
      SELECT estado, responsavel_motorista_id
        INTO v_cobranca_estado, v_motorista
        FROM public.contrato_cobrancas WHERE id = NEW.cobranca_id;

      v_anulada := v_cobranca_estado IS NOT DISTINCT FROM 'anulada';
      v_precisa_par := v_anulada OR (v_motorista IS NOT NULL);

      INSERT INTO public.conta_movimentos
        (org_id, entidade_id, data_movimento, tipo, valor, origem,
         nota_credito_id, cobranca_id, contrato_id, descricao)
      VALUES
        (NEW.org_id, NEW.entidade_id, NEW.data_nota, 'credito', NEW.valor, 'nota_credito',
         NEW.id, NEW.cobranca_id, NEW.contrato_id,
         'Nota de Crédito Nº ' || NEW.codigo || ' — ' || NEW.motivo);

      IF v_precisa_par THEN
        INSERT INTO public.conta_movimentos
          (org_id, entidade_id, data_movimento, tipo, valor, origem,
           nota_credito_id, cobranca_id, contrato_id, descricao)
        VALUES
          (NEW.org_id, NEW.entidade_id, NEW.data_nota, 'debito', NEW.valor, 'nota_credito',
           NEW.id, NEW.cobranca_id, NEW.contrato_id,
           'Nota de Crédito Nº ' || NEW.codigo || ' — ' ||
           CASE WHEN v_anulada THEN 'sem efeito adicional no saldo (fatura já anulada)'
                ELSE 'creditada ao motorista responsável (dívida cedida)' END);
      END IF;

      IF v_motorista IS NOT NULL THEN
        INSERT INTO public.motorista_financeiro
          (org_id, motorista_id, tipo, categoria, descricao, valor,
           data_movimento, status, cobranca_id)
        VALUES
          (NEW.org_id, v_motorista, 'credito', 'outro',
           'Nota de Crédito Nº ' || NEW.codigo || ' — ' || NEW.motivo,
           NEW.valor, NEW.data_nota, 'pendente', NEW.cobranca_id);

        IF v_anulada THEN
          INSERT INTO public.motorista_financeiro
            (org_id, motorista_id, tipo, categoria, descricao, valor,
             data_movimento, status, cobranca_id)
          VALUES
            (NEW.org_id, v_motorista, 'debito', 'outro',
             'Nota de Crédito Nº ' || NEW.codigo ||
             ' — sem efeito adicional no saldo (dívida já revertida na anulação)',
             NEW.valor, NEW.data_nota, 'pendente', NEW.cobranca_id);
        END IF;
      END IF;
    END IF;

  ELSIF TG_OP = 'UPDATE' AND OLD.estado = 'ativo' AND NEW.estado = 'anulado' THEN
    INSERT INTO public.conta_movimentos
      (org_id, entidade_id, tipo, valor, origem, nota_credito_id, cobranca_id, contrato_id, descricao)
    SELECT
      NEW.org_id, NEW.entidade_id,
      CASE WHEN cm.tipo = 'credito' THEN 'debito' ELSE 'credito' END,
      cm.valor, 'nota_credito', NEW.id, NEW.cobranca_id, NEW.contrato_id,
      'Estorno de nota de crédito anulada'
    FROM public.conta_movimentos cm
    WHERE cm.nota_credito_id = NEW.id;

    SELECT responsavel_motorista_id INTO v_motorista
      FROM public.contrato_cobrancas WHERE id = NEW.cobranca_id;
    IF v_motorista IS NOT NULL THEN
      INSERT INTO public.motorista_financeiro
        (org_id, motorista_id, tipo, categoria, descricao, valor,
         data_movimento, status, cobranca_id)
      SELECT NEW.org_id, v_motorista,
             CASE WHEN mf.tipo = 'credito' THEN 'debito' ELSE 'credito' END,
             'outro',
             'Estorno — nota de crédito Nº ' || NEW.codigo || ' anulada',
             mf.valor, current_date, 'pendente', NEW.cobranca_id
        FROM public.motorista_financeiro mf
       WHERE mf.cobranca_id = NEW.cobranca_id
         AND mf.descricao LIKE 'Nota de Crédito Nº ' || NEW.codigo || ' —%';
    END IF;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_nota_credito_posta_movimento"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_nota_credito_posta_movimento"() IS 'Lança a nota de crédito na conta-corrente. Quando a fatura está cedida a um motorista, o crédito real vai para motorista_financeiro (é ele que deve) e o titular leva um par crédito+débito que se auto-cancela, para a NC continuar visível no extrato sem alterar um saldo que já estava a zero.';



CREATE OR REPLACE FUNCTION "public"."fn_nota_credito_valida"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_cob public.contrato_cobrancas%ROWTYPE;
  v_ja  numeric;
BEGIN
  SELECT * INTO v_cob FROM public.contrato_cobrancas WHERE id = NEW.cobranca_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cobrança % não encontrada.', NEW.cobranca_id;
  END IF;

  NEW.org_id      := v_cob.org_id;
  NEW.entidade_id := v_cob.destinatario_id;
  NEW.contrato_id := v_cob.contrato_id;

  IF v_cob.estado NOT IN ('emitida', 'paga', 'anulada') THEN
    RAISE EXCEPTION
      'Só é possível emitir nota de crédito sobre uma cobrança emitida ou paga (estado atual: %).',
      v_cob.estado;
  END IF;

  IF NOT v_cob.emite_fatura_fiscal THEN
    RAISE EXCEPTION
      'Nota de crédito só é aplicável a cobranças com fatura fiscal (cobrança interna não tem fatura a retificar).';
  END IF;

  SELECT COALESCE(SUM(valor), 0) INTO v_ja
    FROM public.notas_credito
    WHERE cobranca_id = NEW.cobranca_id AND estado = 'ativo';

  IF NEW.valor > (v_cob.valor_total - v_ja) + 0.005 THEN
    RAISE EXCEPTION
      'Valor da nota de crédito (%) excede o saldo por creditar da cobrança (%).',
      NEW.valor, round(v_cob.valor_total - v_ja, 2);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_nota_credito_valida"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_nota_credito_valida"() IS 'Valida uma Nota de Crédito: cobrança emitida/paga/anulada (uma cobrança só chega a anulada vindo de emitida/paga — teve sempre fatura fiscal real), com fatura fiscal, e valor dentro do saldo por creditar.';



CREATE OR REPLACE FUNCTION "public"."fn_notificacoes_agrupar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id   uuid;
  v_item jsonb;
begin
  v_item := jsonb_strip_nulls(jsonb_build_object(
    'link', new.link,
    'viatura_id', new.viatura_id,
    'candidatura_id', new.candidatura_id,
    'evento_id', new.evento_id,
    'mensagem', new.mensagem,
    'em', coalesce(new.created_at, now())
  ));

  -- Regra 1 (inalterada): urgentes nunca agrupam.
  if new.severidade = 'urgente' then
    new.itens := jsonb_build_array(v_item);
    return new;
  end if;

  -- Regra 2 (nova): sem destinatário individual não há grupo — é uma colisão
  -- entre pessoas diferentes que vêem a mesma linha por cargo.
  if new.destinatario_id is null then
    new.itens := jsonb_build_array(v_item);
    return new;
  end if;

  -- Regra 3 (nova): uma linha procurável por chave de entidade nunca agrupa.
  if new.candidatura_id is not null or new.evento_id is not null then
    new.itens := jsonb_build_array(v_item);
    return new;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    coalesce(new.org_id::text, '') || '|' ||
    new.destinatario_id::text || '|' ||
    new.tipo || '|' ||
    (coalesce(new.created_at, now()))::date::text, 0));

  select id into v_id
  from public.notificacoes
  where org_id is not distinct from new.org_id
    and destinatario_id = new.destinatario_id
    and tipo = new.tipo
    and resolvida = false
    and severidade <> 'urgente'
    -- Simétrico da Regra 3: nunca fundir PARA DENTRO de uma linha com chave de
    -- entidade (ex.: as 6 linhas infladas que já existem).
    and candidatura_id is null
    and evento_id is null
    and created_at >= date_trunc('day', coalesce(new.created_at, now()))
    and created_at <  date_trunc('day', coalesce(new.created_at, now())) + interval '1 day'
  order by created_at, id
  limit 1;

  if v_id is null then
    new.itens := jsonb_build_array(v_item);
    return new;
  end if;

  update public.notificacoes
  set agrupadas = agrupadas + 1,
      itens = coalesce(itens, '[]'::jsonb) || v_item
  where id = v_id;

  return null;
end;
$$;


ALTER FUNCTION "public"."fn_notificacoes_agrupar"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_notificacoes_agrupar"() IS 'Agrupa notificações in-app por (org, destinatário, tipo, dia), acumulando as entidades afectadas em `itens`. NÃO agrupa: urgentes; avisos sem destinatario_id (dirigidos a cargo); avisos com candidatura_id ou evento_id (outro código procura-os por essa chave e a fusão destruía-a). Devolve NULL para cancelar o INSERT quando o grupo do dia já existe.';



CREATE OR REPLACE FUNCTION "public"."fn_notifications_so_quando_ha_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_email boolean;
begin
  -- Alertas técnicos directos (job falhou, limite de email atingido, ticket ->
  -- gestor do contrato) não passam pelo motor de regras e criam sempre linha
  -- na fila. Nunca cancelar.
  if new.rule_run_id is null then
    return new;
  end if;

  select coalesce((ar.acao_config->>'enviar_email')::boolean, false)
    into v_email
  from public.automation_runs r
  join public.automation_rules ar on ar.id = r.rule_id
  where r.id = new.rule_run_id;

  -- Run ou regra que já não existe: preservar. Na dúvida, guardar — o custo
  -- de uma linha a mais é nulo ao pé do de perder o pai de um email.
  if v_email is null then
    return new;
  end if;

  -- `enviar_email = true` cobre também o modo digest: o digest exige
  -- enviar_email true, e a sua linha na fila só nasce mais tarde, em
  -- enviar_digests_diarios(). Cancelar por "não tem fila agora" partiria-o.
  if v_email then
    return new;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."fn_notifications_so_quando_ha_email"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_notifications_so_quando_ha_email"() IS 'Cancela o INSERT em notifications quando a regra de origem não envia email — essas linhas não têm consumidor nenhum (nenhum frontend lê notifications). Preserva sempre: alertas directos (rule_run_id nulo), modo digest, e runs/regras já inexistentes.';



CREATE OR REPLACE FUNCTION "public"."fn_recibo_anulado_avisos"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_motorista_nome text;
  v_gestor_nome text;
  v_gestor_id uuid;
  v_motivo text;
BEGIN
  IF NOT (OLD.estado = 'ativo' AND NEW.estado = 'anulado') THEN
    RETURN NEW;
  END IF;

  SELECT m.nome, m.gestor_responsavel
    INTO v_motorista_nome, v_gestor_nome
  FROM public.motoristas_ativos m
  WHERE m.cliente_id = NEW.entidade_id
  LIMIT 1;

  IF v_gestor_nome IS NOT NULL AND btrim(v_gestor_nome) <> '' THEN
    SELECT p.id INTO v_gestor_id
    FROM public.profiles p
    WHERE lower(btrim(p.nome)) = lower(btrim(v_gestor_nome))
      AND (NEW.org_id IS NULL OR p.org_id = NEW.org_id)
    LIMIT 1;
  END IF;

  v_motivo := NULLIF(btrim(COALESCE(NEW.observacoes, '')), '');

  IF v_gestor_id IS NOT NULL THEN
    INSERT INTO public.notificacoes (
      org_id, tipo, destinatario_id, titulo, mensagem, severidade, link
    )
    VALUES (
      NEW.org_id,
      'recibo_anulado',
      v_gestor_id,
      'Recibo anulado: nº ' || NEW.codigo,
      'O recibo nº ' || NEW.codigo || ' do motorista ' ||
        COALESCE(v_motorista_nome, 'desconhecido') || ' foi anulado' ||
        CASE WHEN v_motivo IS NOT NULL THEN ' (' || v_motivo || ')' ELSE '' END || '.',
      'normal',
      '/administrativo'
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_recibo_anulado_avisos"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_recibo_anulado_avisos"() IS 'Ao anular um recibo, cria só uma notificação interna (in-app) ao gestor responsável — já não envia email a ninguém (removido a pedido em 30/07/2026; a versão anterior enviava email ao motorista e ao gestor via send-recibo-anulado-email).';



CREATE OR REPLACE FUNCTION "public"."fn_recibo_posta_movimento"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.estado = 'ativo' THEN
      INSERT INTO public.conta_movimentos
        (org_id, entidade_id, tipo, valor, origem, recibo_id, contrato_id, descricao)
      VALUES
        (NEW.org_id, NEW.entidade_id, 'credito', NEW.valor, 'recibo',
         NEW.id, NEW.contrato_id, COALESCE('Recibo nº ' || NEW.codigo, 'Recibo'));
    END IF;
  ELSIF TG_OP = 'UPDATE' AND OLD.estado = 'ativo' AND NEW.estado = 'anulado' THEN
    INSERT INTO public.conta_movimentos
      (org_id, entidade_id, tipo, valor, origem, recibo_id, contrato_id, descricao)
    VALUES
      (NEW.org_id, NEW.entidade_id, 'debito', NEW.valor, 'recibo',
       NEW.id, NEW.contrato_id,
       'Anulamento de Recibo' || COALESCE(' nº ' || NEW.codigo, ''));
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_recibo_posta_movimento"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reject_null_org_id"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.org_id IS NULL AND (TG_OP = 'INSERT' OR OLD.org_id IS NOT NULL) THEN
    RAISE EXCEPTION
      '% : org_id não pode ser NULL (linha rejeitada — evita fuga silenciosa de RLS)',
      TG_TABLE_NAME;
  END IF;
  RETURN NEW;
END;
$$;


