CREATE OR REPLACE FUNCTION "public"."fn_slot_cobranca_entrada"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_entrada date;
  v_de      date;
  v_ate     date;
BEGIN
  -- Só slots ativos com valor mensal definido
  IF NEW.regime IS DISTINCT FROM 'slot'
     OR NEW.estado NOT IN ('confirmada', 'em_curso')
     OR NEW.slot_valor_mensal IS NULL
     OR NEW.condutor_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_entrada := NEW.data_inicio::date;
  -- Mês de calendário completo a seguir (M+1)
  v_de  := (date_trunc('month', v_entrada)::date + interval '1 month')::date;
  v_ate := (date_trunc('month', v_entrada)::date + interval '2 month' - interval '1 day')::date;

  PERFORM public.fn_slot_inserir_cobranca(
    NEW, v_de, v_ate, NEW.slot_valor_mensal,
    'Slot — ' || to_char(v_de, 'TMMonth YYYY')
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_slot_cobranca_entrada"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."reservas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" DEFAULT "public"."get_current_org_id"() NOT NULL,
    "codigo" bigint NOT NULL,
    "viatura_id" "uuid",
    "matricula" character varying(20),
    "grupo" character varying(50),
    "estacao_entrega_id" "uuid",
    "estacao_recolha_id" "uuid",
    "data_inicio" timestamp with time zone NOT NULL,
    "data_fim" timestamp with time zone,
    "cliente_id" "uuid",
    "cliente_nome" character varying(255),
    "condutor_id" "uuid",
    "condutor_nome" character varying(255),
    "estado" "public"."reserva_estado_enum" DEFAULT 'pendente'::"public"."reserva_estado_enum" NOT NULL,
    "valor_total" numeric(10,2),
    "observacoes" "text",
    "deleted_at" timestamp with time zone,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "periodo" "tstzrange" GENERATED ALWAYS AS ("tstzrange"("data_inicio", "data_fim", '[)'::"text")) STORED,
    "is_longa_duracao" boolean DEFAULT false NOT NULL,
    "renovacao_opcao" "text",
    "renovacao_intervalo_dias" integer,
    "franquia_valor" numeric(10,2),
    "caucao_valor" numeric(10,2),
    "kms_incluidos" integer,
    "km_adicional_valor" numeric(10,4),
    "observacoes_internas" "text",
    "grupo_id" "uuid",
    "grupo_nome" "text",
    "tarifa_id" "uuid",
    "tarifa_nome" "text",
    "tarifa_preco_dia" numeric(10,2),
    "cobertura_id" "uuid",
    "cobertura_nome" "text",
    "cobertura_preco_dia" numeric(10,2),
    "cobertura_franquia" numeric(10,2),
    "regime" "public"."contrato_regime_enum" DEFAULT 'rent_a_car'::"public"."contrato_regime_enum" NOT NULL,
    "desconto" numeric(5,2) DEFAULT 0 NOT NULL,
    "valor_total_manual" numeric(12,2),
    "slot_valor_semanal" numeric(10,2),
    "emissor_id" "uuid",
    "gestor_id" "uuid" DEFAULT "auth"."uid"(),
    "slot_valor_mensal" numeric(10,2),
    CONSTRAINT "chk_reservas_desconto" CHECK ((("desconto" >= (0)::numeric) AND ("desconto" <= (100)::numeric))),
    CONSTRAINT "chk_reservas_periodo_valido" CHECK (("data_fim" > "data_inicio")),
    CONSTRAINT "chk_reservas_valor_nao_negativo" CHECK ((("valor_total" IS NULL) OR ("valor_total" >= (0)::numeric))),
    CONSTRAINT "reservas_kms_incluidos_nao_negativos" CHECK ((("kms_incluidos" IS NULL) OR ("kms_incluidos" >= 0))),
    CONSTRAINT "reservas_renovacao_intervalo_positivo" CHECK ((("renovacao_intervalo_dias" IS NULL) OR ("renovacao_intervalo_dias" > 0))),
    CONSTRAINT "reservas_renovacao_opcao_valida" CHECK ((("renovacao_opcao" IS NULL) OR ("renovacao_opcao" = ANY (ARRAY['primeiro_dia_mes'::"text", 'mesmo_dia_cada_mes'::"text", 'intervalo_dias'::"text"])))),
    CONSTRAINT "reservas_valores_nao_negativos" CHECK (((("franquia_valor" IS NULL) OR ("franquia_valor" >= (0)::numeric)) AND (("caucao_valor" IS NULL) OR ("caucao_valor" >= (0)::numeric)) AND (("km_adicional_valor" IS NULL) OR ("km_adicional_valor" >= (0)::numeric))))
);


ALTER TABLE "public"."reservas" OWNER TO "postgres";


COMMENT ON COLUMN "public"."reservas"."deleted_at" IS 'Soft delete. Hard DELETE só por admin. EXCLUDE e SELECT ignoram registos soft-deleted.';



COMMENT ON COLUMN "public"."reservas"."periodo" IS 'Coluna GENERATED ALWAYS — NÃO escrever manualmente. Deriva de [data_inicio, data_fim) semi-aberto para permitir handovers (A termina 18:00, B começa 18:00 = OK). Base do EXCLUDE anti-overbooking.';



COMMENT ON COLUMN "public"."reservas"."is_longa_duracao" IS 'true = reserva de aluguer de longa duração com renovação periódica.';



COMMENT ON COLUMN "public"."reservas"."renovacao_opcao" IS 'Periodicidade de renovação: primeiro_dia_mes | mesmo_dia_cada_mes | intervalo_dias.';



COMMENT ON COLUMN "public"."reservas"."renovacao_intervalo_dias" IS 'Nº de dias entre renovações quando renovacao_opcao = intervalo_dias.';



COMMENT ON COLUMN "public"."reservas"."kms_incluidos" IS 'Nº de kms incluídos no contrato. NULL = ilimitado.';



COMMENT ON COLUMN "public"."reservas"."km_adicional_valor" IS 'Custo por km acima do limite de kms_incluidos (em €/km).';



COMMENT ON COLUMN "public"."reservas"."observacoes_internas" IS 'Observações internas — não aparecem no relatório/contrato apresentado ao cliente.';



COMMENT ON COLUMN "public"."reservas"."grupo_id" IS 'Grupo de viatura reservado. FK para renting_grupos.';



COMMENT ON COLUMN "public"."reservas"."grupo_nome" IS 'Snapshot do nome do grupo no momento da reserva — não muda se o grupo for renomeado.';



COMMENT ON COLUMN "public"."reservas"."tarifa_id" IS 'Tarifa aplicada na reserva. FK para renting_tarifas.';



COMMENT ON COLUMN "public"."reservas"."tarifa_nome" IS 'Snapshot do nome da tarifa no momento da reserva.';



COMMENT ON COLUMN "public"."reservas"."tarifa_preco_dia" IS 'Snapshot do preço/dia da tarifa no momento da reserva.';



COMMENT ON COLUMN "public"."reservas"."regime" IS 'rent_a_car ou tvde. Escolhido na reserva; transita para o contrato gerado.';



COMMENT ON COLUMN "public"."reservas"."desconto" IS 'Percentagem de desconto aplicada ao total (0-100).';



COMMENT ON COLUMN "public"."reservas"."valor_total_manual" IS 'Total introduzido manualmente; NULL = usa o cálculo automático.';



COMMENT ON COLUMN "public"."reservas"."slot_valor_semanal" IS 'Valor semanal cobrado ao motorista no regime slot (por carro). NULL fora do regime slot.';



COMMENT ON COLUMN "public"."reservas"."emissor_id" IS 'Empresa emissora (clientes.id com tipo_cliente=''empresa''). Os documentos gerados usam os templates desta empresa.';



COMMENT ON COLUMN "public"."reservas"."gestor_id" IS 'Gestor responsável (profiles.id). Default = quem criou. Base da privacidade por gestor.';



COMMENT ON COLUMN "public"."reservas"."slot_valor_mensal" IS 'Valor mensal BRUTO (IVA incluído) cobrado ao motorista no regime slot. NULL fora do regime slot.';



CREATE OR REPLACE FUNCTION "public"."fn_slot_inserir_cobranca"("p_reserva" "public"."reservas", "p_de" "date", "p_ate" "date", "p_valor_bruto" numeric, "p_descricao" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_taxa     numeric := 23;
  v_sem_iva  numeric;
  v_cli      uuid;
  v_nome     text;
  v_rowcount integer;
BEGIN
  IF p_reserva.condutor_id IS NULL OR p_valor_bruto IS NULL OR p_valor_bruto <= 0 THEN
    RETURN 0;
  END IF;

  v_sem_iva := round(p_valor_bruto / (1 + v_taxa / 100), 2);
  v_cli := public.fn_ensure_cliente_condutor(p_reserva.condutor_id, p_reserva.org_id);
  SELECT nome INTO v_nome FROM public.clientes WHERE id = v_cli;

  INSERT INTO public.contrato_cobrancas (
    org_id, contrato_id, reserva_id, periodo_de, periodo_ate, descricao,
    destinatario_id, destinatario_papel, destinatario_nome,
    valor_sem_iva, taxa_iva, emite_fatura_fiscal, estado, tipo_cobranca
  )
  VALUES (
    p_reserva.org_id, NULL, p_reserva.id, p_de, p_ate, p_descricao,
    v_cli, 'condutor', v_nome,
    v_sem_iva, v_taxa, true, 'pendente', 'slot_mensal'
  )
  ON CONFLICT (reserva_id, periodo_de, periodo_ate)
    WHERE tipo_cobranca = 'slot_mensal' AND estado <> 'anulada'
  DO NOTHING;

  GET DIAGNOSTICS v_rowcount = ROW_COUNT;
  RETURN v_rowcount;
END;
$$;


ALTER FUNCTION "public"."fn_slot_inserir_cobranca"("p_reserva" "public"."reservas", "p_de" "date", "p_ate" "date", "p_valor_bruto" numeric, "p_descricao" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_viatura_marca_modelo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.marca_id IS DISTINCT FROM OLD.marca_id OR (TG_OP = 'INSERT') THEN
    SELECT nome INTO NEW.marca FROM viatura_marcas WHERE id = NEW.marca_id;
  END IF;
  IF NEW.modelo_id IS DISTINCT FROM OLD.modelo_id OR (TG_OP = 'INSERT') THEN
    SELECT nome INTO NEW.modelo FROM viatura_modelos WHERE id = NEW.modelo_id;
  END IF;
  RETURN NEW;
END;
$$;


