CREATE OR REPLACE FUNCTION "public"."fn_ticket_avisa_gestor_contrato"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_contrato   record;
  v_gestor     record;
  v_matricula  text;
  v_categoria  text;
  v_notif_id   uuid;
begin
  -- Contrato TVDE activo daquela viatura. Só a versão viva conta.
  select ct.id, ct.codigo, ct.gestor_id, ct.regime
    into v_contrato
    from public.contratos_renting ct
   where ct.viatura_id = new.viatura_id
     and ct.deleted_at is null
     and ct.substituido_em is null
     and ct.regime = 'tvde'
     and ct.estado_operacional in ('agendado', 'em_curso')
   order by ct.data_inicio desc
   limit 1;

  -- Sem contrato TVDE activo não há gestor a avisar, e isso é legítimo:
  -- rent-a-car, viatura parada, ou entre contratos.
  if not found or v_contrato.gestor_id is null then
    return new;
  end if;

  select p.id, p.nome, p.email
    into v_gestor
    from public.profiles p
   where p.id = v_contrato.gestor_id;

  if not found then
    return new;
  end if;

  select v.matricula into v_matricula
    from public.viaturas v where v.id = new.viatura_id;

  select c.nome into v_categoria
    from public.assistencia_categorias c where c.id = new.categoria_id;

  insert into public.notifications
    (org_id, destinatario_user_id, template_codigo, severidade, titulo,
     mensagem, link, entity_table, entity_id, payload)
  values (
    new.org_id,
    v_gestor.id,
    'assistencia.ticket_aberto_gestor',
    -- A restrição notifications_severidade_check só aceita
    -- baixa/normal/alta/urgente. A prioridade do ticket é baixa/media/urgente
    -- — 'media' não existe do outro lado, por isso mapeia-se. Sem isto o
    -- INSERT viola a restrição e, por falhar dentro do trigger, arrasta o
    -- ticket com ele: bloqueia as assistências às viaturas com contrato TVDE.
    case new.prioridade
      when 'urgente' then 'urgente'
      when 'baixa'   then 'baixa'
      else 'normal'
    end,
    'Ticket aberto na viatura ' || coalesce(v_matricula, '?'),
    coalesce(nullif(btrim(new.titulo), ''), 'Ticket de assistência'),
    '/assistencia/' || new.id::text,
    'assistencia_tickets',
    new.id,
    jsonb_build_object(
      'titulo',        coalesce(nullif(btrim(new.titulo), ''), 'Ticket de assistência'),
      'descricao',     coalesce(nullif(btrim(new.descricao), ''), '-'),
      'categoria',     coalesce(v_categoria, '-'),
      'prioridade',    coalesce(new.prioridade, '-'),
      'matricula',     coalesce(v_matricula, '?'),
      'contrato',      v_contrato.codigo,
      'gestor_nome',   coalesce(v_gestor.nome, '-'),
      'link',          'https://wegest.pt/assistencia/' || new.id::text
    )
  )
  returning id into v_notif_id;

  -- Sem email no perfil fica só o sino — melhor do que perder o aviso todo.
  if v_gestor.email is not null and btrim(v_gestor.email) <> '' then
    insert into public.notification_queue
      (notification_id, org_id, canal, destinatario, template_codigo, payload_render)
    select v_notif_id, new.org_id, 'email', v_gestor.email,
           'assistencia.ticket_aberto_gestor', n.payload
      from public.notifications n where n.id = v_notif_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_ticket_avisa_gestor_contrato"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_uber_resumo_recalcular"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
  INSERT INTO public.uber_resumos_semanais AS r (
    org_id, integracao_id, periodo, periodo_inicio, periodo_fim,
    chave_motorista, uber_driver_id, motorista_id, motorista_nome,
    ganhos_brutos, ganhos_liquidos, comissoes, gorjetas, viagens,
    fonte, api_sincronizado_em, csv_importado_em
  )
  SELECT g.org_id, a.integracao_id,
         to_char(a.ini, 'YYYY-MM-DD') || ' a ' || to_char(a.ini + 6, 'YYYY-MM-DD'),
         a.ini, a.ini + 6,
         a.uber_driver_id, a.uber_driver_id, g.motorista_id, g.nome,
         g.bruto, g.liquido, g.comissao, g.gorjeta, g.viagens,
         CASE WHEN f.tem_api THEN 'api' ELSE 'csv' END,
         CASE WHEN f.tem_api THEN now() END,
         CASE WHEN NOT f.tem_api THEN now() END
    FROM (
      SELECT DISTINCT integracao_id, uber_driver_id,
             date_trunc('week', occurred_at AT TIME ZONE 'UTC')::date AS ini
        FROM baldes_tocados
       WHERE uber_driver_id IS NOT NULL AND occurred_at IS NOT NULL
    ) a
    CROSS JOIN LATERAL (
      SELECT bool_or(t.fonte = 'api') AS tem_api
        FROM public.uber_transactions t
       WHERE t.integracao_id = a.integracao_id
         AND t.uber_driver_id = a.uber_driver_id
         AND date_trunc('week', t.occurred_at AT TIME ZONE 'UTC')::date = a.ini
    ) f
    CROSS JOIN LATERAL (
      SELECT t.org_id,
             (array_agg(t.motorista_id) FILTER (WHERE t.motorista_id IS NOT NULL))[1] AS motorista_id,
             (array_agg(btrim(
                coalesce(t.raw_transaction->'csv_row'->>'Nome próprio do motorista','') || ' ' ||
                coalesce(t.raw_transaction->'csv_row'->>'Apelido do motorista','')
             )) FILTER (WHERE btrim(
                coalesce(t.raw_transaction->'csv_row'->>'Nome próprio do motorista','') || ' ' ||
                coalesce(t.raw_transaction->'csv_row'->>'Apelido do motorista','')
             ) <> ''))[1]                                     AS nome,
             sum(COALESCE(t.gross_amount, 0))                  AS bruto,
             nullif(sum(COALESCE(t.net_amount, 0)), 0)         AS liquido,
             nullif(sum(COALESCE(t.commission_amount, 0)), 0)  AS comissao,
             COALESCE(sum(gr.valor), 0)                        AS gorjeta,
             count(*)::int                                     AS viagens
        FROM public.uber_transactions t
        LEFT JOIN LATERAL (
          -- A coluna da gratificacao muda de nome entre relatorios; procura-se
          -- pela palavra, como o ecra fazia.
          SELECT sum(replace(kv.value, ',', '.')::numeric) AS valor
            FROM jsonb_each_text(COALESCE(t.raw_transaction->'csv_row', '{}'::jsonb)) kv
           WHERE (kv.key ILIKE '%Gratifica%')
             AND kv.value ~ '^-?[0-9]+([.,][0-9]+)?$'
        ) gr ON true
       WHERE t.integracao_id = a.integracao_id
         AND t.uber_driver_id = a.uber_driver_id
         AND date_trunc('week', t.occurred_at AT TIME ZONE 'UTC')::date = a.ini
         AND t.fonte = CASE WHEN f.tem_api THEN 'api' ELSE 'csv' END
       GROUP BY t.org_id
    ) g
  ON CONFLICT (integracao_id, periodo, chave_motorista) DO UPDATE SET
    motorista_id    = COALESCE(EXCLUDED.motorista_id, r.motorista_id),
    motorista_nome  = COALESCE(EXCLUDED.motorista_nome, r.motorista_nome),
    ganhos_brutos   = EXCLUDED.ganhos_brutos,
    ganhos_liquidos = EXCLUDED.ganhos_liquidos,
    comissoes       = EXCLUDED.comissoes,
    gorjetas        = EXCLUDED.gorjetas,
    viagens         = EXCLUDED.viagens,
    fonte           = EXCLUDED.fonte,
    api_sincronizado_em = COALESCE(EXCLUDED.api_sincronizado_em, r.api_sincronizado_em),
    csv_importado_em    = COALESCE(EXCLUDED.csv_importado_em, r.csv_importado_em),
    updated_at      = now();

  RETURN NULL;
END;
$_$;


