COMMENT ON FUNCTION "public"."fn_uber_resumo_recalcular"() IS 'Recalcula os baldes (integracao, motorista, semana) tocados por um comando em uber_transactions. A API manda: havendo linhas da API no balde, so essas contam. Ver migracao 20260814170000.';



CREATE OR REPLACE FUNCTION "public"."fn_validar_acao_config"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_estrategia text;
  v_modo text;
begin
  if new.acao_tipo <> 'notificacao' then
    return new;
  end if;

  if TG_OP = 'UPDATE' and new.acao_config is not distinct from old.acao_config then
    return new;
  end if;

  if not (new.acao_config ? 'template_codigo') or btrim(coalesce(new.acao_config->>'template_codigo', '')) = '' then
    raise exception 'acao_config inválido: template_codigo é obrigatório.'
      using ERRCODE = 'check_violation', HINT = 'Validação acao_config (automation_rules)';
  end if;

  if not (new.acao_config ? 'titulo') or btrim(coalesce(new.acao_config->>'titulo', '')) = '' then
    raise exception 'acao_config inválido: titulo é obrigatório.'
      using ERRCODE = 'check_violation', HINT = 'Validação acao_config (automation_rules)';
  end if;

  v_estrategia := new.acao_config->>'destinatarios_estrategia';
  if v_estrategia is not null and v_estrategia not in ('cargo', 'gestor_responsavel', 'motorista') then
    raise exception 'acao_config inválido: destinatarios_estrategia "%" desconhecido.', v_estrategia
      using ERRCODE = 'check_violation', HINT = 'Validação acao_config (automation_rules)';
  end if;

  if new.acao_config ? 'destinatarios_cargo_ids' and jsonb_typeof(new.acao_config->'destinatarios_cargo_ids') <> 'array' then
    raise exception 'acao_config inválido: destinatarios_cargo_ids tem de ser um array.'
      using ERRCODE = 'check_violation', HINT = 'Validação acao_config (automation_rules)';
  end if;

  if new.acao_config ? 'destinatarios_user_ids' and jsonb_typeof(new.acao_config->'destinatarios_user_ids') <> 'array' then
    raise exception 'acao_config inválido: destinatarios_user_ids tem de ser um array.'
      using ERRCODE = 'check_violation', HINT = 'Validação acao_config (automation_rules)';
  end if;

  v_modo := new.acao_config->>'destinatarios_modo';
  if v_modo is not null and v_modo not in ('grupo', 'individual') then
    raise exception 'acao_config inválido: destinatarios_modo "%" desconhecido.', v_modo
      using ERRCODE = 'check_violation', HINT = 'Validação acao_config (automation_rules)';
  end if;

  if new.acao_config ? 'enviar_email' and jsonb_typeof(new.acao_config->'enviar_email') <> 'boolean' then
    raise exception 'acao_config inválido: enviar_email tem de ser boolean.'
      using ERRCODE = 'check_violation', HINT = 'Validação acao_config (automation_rules)';
  end if;

  if new.acao_config ? 'enviar_email_digest' and jsonb_typeof(new.acao_config->'enviar_email_digest') <> 'boolean' then
    raise exception 'acao_config inválido: enviar_email_digest tem de ser boolean.'
      using ERRCODE = 'check_violation', HINT = 'Validação acao_config (automation_rules)';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."fn_validar_acao_config"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_validar_nif_iban"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_novo  jsonb := to_jsonb(NEW);
  v_velho jsonb := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL END;
  v_nif   text  := v_novo ->> 'nif';
  v_iban  text  := v_novo ->> 'iban';
BEGIN
  -- NIF: valida apenas valores novos ou alterados (catraca)
  IF v_novo ? 'nif'
     AND v_nif IS NOT NULL AND btrim(v_nif) <> ''
     AND (TG_OP = 'INSERT' OR v_nif IS DISTINCT FROM (v_velho ->> 'nif'))
  THEN
    IF NOT public.nif_pt_valido(v_nif) THEN
      RAISE EXCEPTION 'NIF inválido: "%" — verifica os 9 dígitos e o dígito de controlo.', v_nif
        USING ERRCODE = 'check_violation', HINT = 'Validação NIF (tabela ' || TG_TABLE_NAME || ')';
    END IF;
  END IF;

  -- IBAN: idem
  IF v_novo ? 'iban'
     AND v_iban IS NOT NULL AND btrim(v_iban) <> ''
     AND (TG_OP = 'INSERT' OR v_iban IS DISTINCT FROM (v_velho ->> 'iban'))
  THEN
    IF NOT public.iban_valido(v_iban) THEN
      RAISE EXCEPTION 'IBAN inválido: "%" — verifica os dígitos de controlo.', v_iban
        USING ERRCODE = 'check_violation', HINT = 'Validação IBAN (tabela ' || TG_TABLE_NAME || ')';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_validar_nif_iban"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_viatura_is_slot_do_tipo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.tipo_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.viatura_tipos t
    WHERE t.id = NEW.tipo_id
      AND upper(btrim(t.nome)) = 'SLOT'
  ) THEN
    NEW.is_slot := true;
  END IF;
  RETURN NEW;
END;
$$;


