CREATE OR REPLACE FUNCTION "public"."formulario_publico_por_id"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'id',        f.id,
    'nome',      f.nome,
    'descricao', f.descricao,
    'campos',    f.campos,
    'campanhas', coalesce(
      (select jsonb_agg(fc.campanha_tag order by fc.campanha_tag)
         from public.formulario_campanhas fc
        where fc.formulario_id = f.id),
      '[]'::jsonb
    )
  )
  from public.formularios f
  where f.id = p_id
    and f.ativo = true;
$$;


