CREATE OR REPLACE FUNCTION "public"."gerar_cobranca_dano"("p_dano_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_dano        record;
  v_condutor    record;
  v_data        date;
  v_cobranca_id uuid;
BEGIN
  SELECT * INTO v_dano FROM public.viatura_danos WHERE id = p_dano_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Dano % não encontrado.', p_dano_id;
  END IF;

  IF v_dano.cobranca_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este dano já tem cobrança gerada.';
  END IF;
  IF v_dano.contrato_renting_id IS NULL OR v_dano.condutor_cliente_id IS NULL THEN
    RAISE EXCEPTION 'Dano sem contrato renting ou condutor responsável definido.';
  END IF;
  IF COALESCE(v_dano.valor, 0) <= 0 THEN
    RAISE EXCEPTION 'Dano sem valor a imputar — defina o valor antes de faturar.';
  END IF;

  SELECT * INTO v_condutor FROM public.clientes WHERE id = v_dano.condutor_cliente_id;
  v_data := COALESCE(v_dano.data_ocorrencia, v_dano.data_registo, current_date);

  -- org_id é preenchido pelo trigger de contrato_cobrancas a partir do contrato
  INSERT INTO public.contrato_cobrancas (
    contrato_id, periodo_de, periodo_ate, descricao,
    destinatario_id, destinatario_papel, destinatario_nome,
    valor_sem_iva, taxa_iva, emite_fatura_fiscal, estado
  )
  VALUES (
    v_dano.contrato_renting_id, v_data, v_data,
    'Dano: ' || left(v_dano.descricao, 200),
    v_dano.condutor_cliente_id, 'condutor', v_condutor.nome,
    v_dano.valor, 23, true, 'pendente'
  )
  RETURNING id INTO v_cobranca_id;

  UPDATE public.viatura_danos
     SET cobranca_id = v_cobranca_id,
         updated_at  = now()
   WHERE id = p_dano_id;

  RETURN v_cobranca_id;
END;
$$;


ALTER FUNCTION "public"."gerar_cobranca_dano"("p_dano_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_cobranca_dano"("p_dano_id" "uuid") IS 'Gera a linha de contrato_cobrancas para faturar um dano ao condutor responsável. A cobrança nasce pendente; é emitida pelo fluxo normal de faturação.';



CREATE OR REPLACE FUNCTION "public"."gerar_cobranca_renta_car"("p_contrato_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_contrato    record;
  v_cliente     record;
  v_tarifa      record;
  v_dias        integer;
  v_valor       numeric;
  v_cobranca_id uuid;
BEGIN
  SELECT * INTO v_contrato FROM public.contratos_renting WHERE id = p_contrato_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contrato % não encontrado.', p_contrato_id;
  END IF;
  IF v_contrato.regime <> 'rent_a_car' THEN
    RAISE EXCEPTION 'Função só para contratos rent_a_car — TVDE usa gerar_cobrancas_tvde_semanais().';
  END IF;
  IF v_contrato.data_fim IS NULL THEN
    RAISE EXCEPTION 'Contrato rent_a_car sem data de fim.';
  END IF;
  IF v_contrato.tarifa_id IS NULL THEN
    RAISE EXCEPTION 'Contrato sem tarifa definida.';
  END IF;

  v_dias  := (v_contrato.data_fim::date - v_contrato.data_inicio::date);
  v_valor := public.calcular_valor_aluguer(v_contrato.tarifa_id, 'rent_a_car', v_dias);
  IF v_valor IS NULL THEN
    RAISE EXCEPTION 'Não foi possível calcular o valor — verifique os preços da tarifa.';
  END IF;

  SELECT * INTO v_cliente FROM public.clientes        WHERE id = v_contrato.cliente_id;
  SELECT * INTO v_tarifa  FROM public.renting_tarifas WHERE id = v_contrato.tarifa_id;

  INSERT INTO public.contrato_cobrancas (
    contrato_id, periodo_de, periodo_ate, descricao,
    destinatario_id, destinatario_papel, destinatario_nome,
    tarifa_id, tarifa_nome,
    valor_sem_iva, taxa_iva, emite_fatura_fiscal, estado
  )
  VALUES (
    v_contrato.id, v_contrato.data_inicio::date, v_contrato.data_fim::date,
    'Aluguer ' || to_char(v_contrato.data_inicio::date, 'DD/MM/YYYY') ||
          ' a ' || to_char(v_contrato.data_fim::date,   'DD/MM/YYYY'),
    v_contrato.cliente_id, 'cliente', v_cliente.nome,
    v_contrato.tarifa_id, v_tarifa.nome,
    v_valor, COALESCE(v_contrato.taxa_iva, 23), true, 'pendente'
  )
  ON CONFLICT (contrato_id, destinatario_id, periodo_de, periodo_ate) DO NOTHING
  RETURNING id INTO v_cobranca_id;

  IF v_cobranca_id IS NULL THEN
    RAISE EXCEPTION 'Já existe uma cobrança para este contrato e período.';
  END IF;

  RETURN v_cobranca_id;
END;
$$;


ALTER FUNCTION "public"."gerar_cobranca_renta_car"("p_contrato_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_cobranca_renta_car"("p_contrato_id" "uuid") IS 'Gera a cobrança única (todo o período) de um contrato rent_a_car, ao cliente.';



CREATE OR REPLACE FUNCTION "public"."gerar_cobrancas_slot_mensais"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_reserva   public.reservas;
  v_entrada   date;
  v_ref_mes   date := date_trunc('month', current_date)::date;
  v_meses     integer;
  v_de        date;
  v_ate       date;
  v_dias      integer;
  v_dias_mes  integer;
  v_valor     numeric;
  v_desc      text;
  v_criadas   integer := 0;
BEGIN
  FOR v_reserva IN
    SELECT r.* FROM public.reservas r
    WHERE r.regime = 'slot'
      AND r.estado IN ('confirmada', 'em_curso')
      AND r.slot_valor_mensal IS NOT NULL
      AND r.condutor_id IS NOT NULL
      AND (r.data_fim IS NULL OR r.data_fim::date >= v_ref_mes)
  LOOP
    v_entrada := v_reserva.data_inicio::date;

    -- diferença em meses de calendário entre R e o mês de entrada M
    v_meses := (extract(year FROM v_ref_mes) - extract(year FROM date_trunc('month', v_entrada))) * 12
             + (extract(month FROM v_ref_mes) - extract(month FROM date_trunc('month', v_entrada)));

    IF v_meses = 1 THEN
      -- stub: dia de entrada .. fim do mês M (inclui entrada)
      v_de       := v_entrada;
      v_ate      := (date_trunc('month', v_entrada)::date + interval '1 month' - interval '1 day')::date;
      v_dias     := (v_ate - v_de) + 1;
      v_dias_mes := extract(day FROM (date_trunc('month', v_entrada)::date + interval '1 month' - interval '1 day'))::integer;
      v_valor    := round(v_reserva.slot_valor_mensal * v_dias / v_dias_mes, 2);
      v_desc     := 'Slot — parcial ' || to_char(v_de, 'DD/MM') || ' a ' || to_char(v_ate, 'DD/MM/YYYY');
    ELSIF v_meses >= 2 THEN
      -- mês R inteiro, valor cheio
      v_de    := v_ref_mes;
      v_ate   := (v_ref_mes + interval '1 month' - interval '1 day')::date;
      v_valor := v_reserva.slot_valor_mensal;
      v_desc  := 'Slot — ' || to_char(v_ref_mes, 'TMMonth YYYY');
    ELSE
      CONTINUE;  -- R <= M: nada a gerar
    END IF;

    v_criadas := v_criadas + public.fn_slot_inserir_cobranca(v_reserva, v_de, v_ate, v_valor, v_desc);
  END LOOP;

  RETURN v_criadas;
END;
$$;


ALTER FUNCTION "public"."gerar_cobrancas_slot_mensais"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_cobrancas_slot_mensais"() IS 'Gera as cobranças mensais de slot em falta (stub do mês de entrada em M+1, mês cheio de M+2 em diante). Idempotente. Devolve o nº de cobranças criadas.';



CREATE OR REPLACE FUNCTION "public"."gerar_cobrancas_tvde_semanais"("p_semanas_a_frente" integer DEFAULT 1) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_contrato      record;
  v_condutor      record;
  v_tarifa        record;
  v_cliente       record;
  v_preco_semana  numeric;
  v_proximo_de    date;
  v_proximo_ate   date;
  v_limite        date;
  v_ultima        date;
  v_criadas       integer := 0;
  v_rowcount      integer;
BEGIN
  v_limite := current_date + (GREATEST(p_semanas_a_frente, 0) * 7);

  FOR v_contrato IN
    SELECT c.* FROM public.contratos_renting c
    WHERE c.regime = 'tvde'
      AND c.deleted_at IS NULL
      AND c.estado_operacional IN ('agendado', 'em_curso')
  LOOP
    SELECT max(periodo_ate) INTO v_ultima
    FROM public.contrato_cobrancas
    WHERE contrato_id = v_contrato.id;

    v_proximo_de := COALESCE(v_ultima + 1, v_contrato.data_inicio::date);

    -- Tarifa do contrato. Se não tiver preço direto (caso das tarifas tvde,
    -- que são por modelo), resolve via renting_tarifa_precos_modelo usando
    -- o modelo da viatura do contrato.
    SELECT * INTO v_tarifa
    FROM public.renting_tarifas WHERE id = v_contrato.tarifa_id;

    v_preco_semana := v_tarifa.preco_semana;
    IF v_preco_semana IS NULL AND v_contrato.viatura_id IS NOT NULL THEN
      SELECT rtpm.preco_semana INTO v_preco_semana
      FROM public.renting_tarifa_precos_modelo rtpm
      JOIN public.viaturas vi ON vi.modelo_id = rtpm.modelo_id
      WHERE rtpm.tarifa_id = v_tarifa.id
        AND vi.id = v_contrato.viatura_id;
    END IF;

    WHILE v_proximo_de <= v_limite LOOP
      v_proximo_ate := v_proximo_de + 6;

      EXIT WHEN v_contrato.data_fim IS NOT NULL
            AND v_proximo_de > v_contrato.data_fim::date;

      SELECT cc.* INTO v_condutor
      FROM public.contrato_condutores cc
      WHERE cc.contrato_id = v_contrato.id
        AND cc.is_principal = true
        AND cc.vigencia @> v_proximo_de::timestamptz
      LIMIT 1;

      IF FOUND AND v_preco_semana IS NOT NULL THEN
        SELECT * INTO v_cliente FROM public.clientes WHERE id = v_condutor.cliente_id;

        INSERT INTO public.contrato_cobrancas (
          org_id, contrato_id, periodo_de, periodo_ate, descricao,
          destinatario_id, destinatario_papel, destinatario_nome, contrato_condutor_id,
          tarifa_id, tarifa_nome,
          valor_sem_iva, taxa_iva, emite_fatura_fiscal, estado
        )
        VALUES (
          v_contrato.org_id, v_contrato.id, v_proximo_de, v_proximo_ate,
          'Semana ' || to_char(v_proximo_de, 'DD/MM') ||
                ' a ' || to_char(v_proximo_ate, 'DD/MM/YYYY'),
          v_condutor.cliente_id, 'condutor', v_cliente.nome, v_condutor.id,
          v_tarifa.id, v_tarifa.nome,
          v_preco_semana, COALESCE(v_contrato.taxa_iva, 23),
          false, 'pendente'
        )
        ON CONFLICT (contrato_id, destinatario_id, periodo_de, periodo_ate)
        DO NOTHING;

        GET DIAGNOSTICS v_rowcount = ROW_COUNT;
        IF v_rowcount > 0 THEN
          v_criadas := v_criadas + 1;
        END IF;
      END IF;

      v_proximo_de := v_proximo_ate + 1;
    END LOOP;
  END LOOP;

  RETURN v_criadas;
END;
$$;


ALTER FUNCTION "public"."gerar_cobrancas_tvde_semanais"("p_semanas_a_frente" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_cobrancas_tvde_semanais"("p_semanas_a_frente" integer) IS 'Gera as cobranças semanais em falta dos contratos TVDE abertos, destinadas ao condutor vigente (sem fatura fiscal). Resolve o preço via renting_tarifa_precos_modelo quando a tarifa não tem preco_semana direto (tarifas tvde, por modelo). Idempotente. Devolve o número de cobranças criadas.';



CREATE OR REPLACE FUNCTION "public"."gerar_contrato_atomico"("p_motorista_id" "uuid", "p_empresa_id" "text", "p_motorista_nome" "text", "p_motorista_nif" "text", "p_motorista_email" "text", "p_motorista_telefone" "text", "p_motorista_morada" "text", "p_motorista_documento_tipo" "text", "p_motorista_documento_numero" "text", "p_cidade_assinatura" "text", "p_data_assinatura" "date", "p_data_inicio" "date", "p_duracao_meses" integer, "p_criado_por" "uuid", "p_force_new_version" boolean DEFAULT true, "p_viatura_id" "uuid" DEFAULT NULL::"uuid", "p_calendario_evento_id" "uuid" DEFAULT NULL::"uuid", "p_checkout_pendente" boolean DEFAULT false, "p_template_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "motorista_id" "uuid", "empresa_id" "text", "motorista_nome" "text", "status" "text", "data_assinatura" "date", "data_inicio" "date", "created_at" timestamp with time zone, "is_existing" boolean, "numero_contrato" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_versao_atual INTEGER;
  v_existing_contract RECORD;
  v_org uuid := public.get_current_org_id();
BEGIN
  -- Guarda: quem chama tem de poder criar contratos nesta organização.
  -- Espelha a política de INSERT de public.contratos.
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Sem organização activa.' USING ERRCODE = '42501';
  END IF;
  IF NOT (public.is_current_user_admin()
          OR public.has_permission(auth.uid(), 'motoristas_contratos')
          OR public.has_permission(auth.uid(), 'motoristas_gestao')) THEN
    RAISE EXCEPTION 'Sem permissão para gerar contratos.' USING ERRCODE = '42501';
  END IF;

  -- Se não forçar nova versão, verificar se já existe contrato ativo
  IF NOT p_force_new_version THEN
    SELECT * INTO v_existing_contract
    FROM public.contratos c
    WHERE c.motorista_id = p_motorista_id
      AND c.empresa_id = p_empresa_id
      AND c.status = 'ativo'
      AND c.org_id = v_org
    LIMIT 1;

    -- Se existe, retornar o existente com flag is_existing = true
    IF FOUND THEN
      RETURN QUERY SELECT
        v_existing_contract.id,
        v_existing_contract.motorista_id,
        v_existing_contract.empresa_id,
        v_existing_contract.motorista_nome,
        v_existing_contract.status,
        v_existing_contract.data_assinatura,
        v_existing_contract.data_inicio,
        v_existing_contract.criado_em,
        true::boolean as is_existing,
        v_existing_contract.numero_contrato;
      RETURN;
    END IF;
  END IF;

  -- Buscar versão máxima existente para este motorista+empresa
  SELECT COALESCE(MAX(versao), 0) INTO v_versao_atual
  FROM public.contratos
  WHERE contratos.motorista_id = p_motorista_id
    AND contratos.empresa_id = p_empresa_id
    AND contratos.org_id = v_org;

  -- Marcar contratos ativos anteriores como substituídos
  UPDATE public.contratos
  SET status = 'substituido',
      atualizado_em = now()
  WHERE contratos.motorista_id = p_motorista_id
    AND contratos.empresa_id = p_empresa_id
    AND contratos.status = 'ativo'
    AND contratos.org_id = v_org;

  -- Inserir novo contrato com versão incrementada
  RETURN QUERY
  INSERT INTO public.contratos (
    motorista_id,
    empresa_id,
    motorista_nome,
    motorista_nif,
    motorista_email,
    motorista_telefone,
    motorista_morada,
    motorista_documento_tipo,
    motorista_documento_numero,
    cidade_assinatura,
    data_assinatura,
    data_inicio,
    duracao_meses,
    versao,
    status,
    criado_por,
    viatura_id,
    calendario_evento_id,
    checkout_pendente,
    template_id
  ) VALUES (
    p_motorista_id,
    p_empresa_id,
    p_motorista_nome,
    p_motorista_nif,
    p_motorista_email,
    p_motorista_telefone,
    p_motorista_morada,
    p_motorista_documento_tipo,
    p_motorista_documento_numero,
    p_cidade_assinatura,
    p_data_assinatura,
    p_data_inicio,
    p_duracao_meses,
    v_versao_atual + 1,
    'ativo',
    p_criado_por,
    p_viatura_id,
    p_calendario_evento_id,
    COALESCE(p_checkout_pendente, false),
    p_template_id
  )
  RETURNING
    contratos.id,
    contratos.motorista_id,
    contratos.empresa_id,
    contratos.motorista_nome,
    contratos.status,
    contratos.data_assinatura,
    contratos.data_inicio,
    contratos.criado_em,
    false::boolean as is_existing,
    contratos.numero_contrato;
END;
$$;


ALTER FUNCTION "public"."gerar_contrato_atomico"("p_motorista_id" "uuid", "p_empresa_id" "text", "p_motorista_nome" "text", "p_motorista_nif" "text", "p_motorista_email" "text", "p_motorista_telefone" "text", "p_motorista_morada" "text", "p_motorista_documento_tipo" "text", "p_motorista_documento_numero" "text", "p_cidade_assinatura" "text", "p_data_assinatura" "date", "p_data_inicio" "date", "p_duracao_meses" integer, "p_criado_por" "uuid", "p_force_new_version" boolean, "p_viatura_id" "uuid", "p_calendario_evento_id" "uuid", "p_checkout_pendente" boolean, "p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gerar_movimentos_recorrentes"("p_semanas_a_frente" integer DEFAULT 0) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rec               record;
  v_semana_ref        date;
  v_semana_do_mes     integer;
  v_primeira_segunda  date;
  v_alvo              date;
  v_deve_gerar        boolean;
  v_criadas           integer := 0;
  v_rowcount          integer;
BEGIN
  v_semana_ref := (date_trunc('week', current_date) + (GREATEST(p_semanas_a_frente, 0) || ' weeks')::interval)::date;

  FOR v_rec IN
    SELECT *
    FROM public.motorista_financeiro_recorrencias r
    WHERE r.status = 'ativa'
      AND r.semana_ancora <= v_semana_ref
      AND (r.data_fim IS NULL OR v_semana_ref <= r.data_fim)
      AND (r.max_ocorrencias IS NULL OR r.ocorrencias_geradas < r.max_ocorrencias)
  LOOP
    v_deve_gerar := false;

    IF v_rec.frequencia = 'semanal' THEN
      v_deve_gerar := true;
    ELSE
      v_semana_do_mes := ceil(extract(day FROM v_rec.semana_ancora) / 7.0)::integer;
      v_primeira_segunda := (date_trunc('month', v_semana_ref)::date)
        + ((8 - extract(isodow FROM date_trunc('month', v_semana_ref)::date)::integer) % 7);
      v_alvo := v_primeira_segunda + ((v_semana_do_mes - 1) * 7);
      v_deve_gerar := (v_alvo = v_semana_ref) AND (extract(month FROM v_alvo) = extract(month FROM v_semana_ref));
    END IF;

    CONTINUE WHEN NOT v_deve_gerar;

    INSERT INTO public.motorista_financeiro (
      motorista_id, org_id, tipo, categoria, descricao, valor,
      data_movimento, status, referencia, recorrencia_id
    )
    VALUES (
      v_rec.motorista_id,
      v_rec.org_id,
      v_rec.tipo,
      v_rec.categoria,
      v_rec.descricao,
      v_rec.valor,
      v_semana_ref,
      'pendente',
      v_rec.referencia_base,
      v_rec.id
    )
    ON CONFLICT (recorrencia_id, data_movimento) WHERE recorrencia_id IS NOT NULL
    DO NOTHING;

    GET DIAGNOSTICS v_rowcount = ROW_COUNT;
    IF v_rowcount > 0 THEN
      v_criadas := v_criadas + 1;
      UPDATE public.motorista_financeiro_recorrencias
      SET ocorrencias_geradas = ocorrencias_geradas + 1,
          status = CASE
            WHEN max_ocorrencias IS NOT NULL AND ocorrencias_geradas + 1 >= max_ocorrencias THEN 'concluida'
            ELSE status
          END,
          updated_at = now()
      WHERE id = v_rec.id;
    END IF;
  END LOOP;

  RETURN v_criadas;
END;
$$;


ALTER FUNCTION "public"."gerar_movimentos_recorrentes"("p_semanas_a_frente" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_movimentos_recorrentes"("p_semanas_a_frente" integer) IS 'Gera os lançamentos (débito/crédito) da semana alvo para cada regra ativa em motorista_financeiro_recorrencias — semanal sempre, mensal só na semana-do-mês da âncora. Idempotente por (recorrencia_id, data_movimento). Devolve o nº de linhas criadas.';



CREATE OR REPLACE FUNCTION "public"."gerar_seguros_semanais"("p_semanas_a_frente" integer DEFAULT 0) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_motorista  record;
  v_inicio     date;
  v_fim        date;
  v_ref        text;
  v_criadas    integer := 0;
  v_rowcount   integer;
BEGIN
  v_inicio := (date_trunc('week', current_date) + (GREATEST(p_semanas_a_frente, 0) || ' weeks')::interval)::date;
  v_fim := v_inicio + 6;

  FOR v_motorista IN
    SELECT m.id, m.org_id, m.seguro_valor_semanal
    FROM public.motoristas_ativos m
    WHERE m.status_ativo = true
      AND m.seguro_valor_semanal IS NOT NULL
      AND m.seguro_valor_semanal > 0
  LOOP
    v_ref := 'seguro-auto:' || v_motorista.id || ':' || to_char(v_inicio, 'YYYY-MM-DD');

    INSERT INTO public.motorista_financeiro (
      motorista_id, org_id, tipo, categoria, descricao, valor,
      data_movimento, status, referencia
    )
    VALUES (
      v_motorista.id,
      v_motorista.org_id,
      'debito',
      'seguros',
      'Seguro semanal (' || to_char(v_inicio, 'DD/MM') || ' a ' || to_char(v_fim, 'DD/MM/YYYY') || ')',
      v_motorista.seguro_valor_semanal,
      v_inicio,
      'pendente',
      v_ref
    )
    ON CONFLICT (referencia) WHERE categoria = 'seguros' AND referencia LIKE 'seguro-auto:%'
    DO NOTHING;

    GET DIAGNOSTICS v_rowcount = ROW_COUNT;
    IF v_rowcount > 0 THEN
      v_criadas := v_criadas + 1;
    END IF;
  END LOOP;

  RETURN v_criadas;
END;
$$;


ALTER FUNCTION "public"."gerar_seguros_semanais"("p_semanas_a_frente" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_seguros_semanais"("p_semanas_a_frente" integer) IS 'Lança o seguro semanal (débito, categoria seguros) de cada motorista ativo com seguro_valor_semanal definido. Idempotente por referência. Devolve o nº criado.';



CREATE OR REPLACE FUNCTION "public"."gerar_token_danos"("p_viatura_id" "uuid", "p_contrato_renting_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token_id uuid;
BEGIN
  -- Multi-tenant guard: a viatura tem de ser da org do utilizador.
  IF NOT EXISTS (
    SELECT 1 FROM public.viaturas
     WHERE id = p_viatura_id AND org_id = get_current_org_id()
  ) THEN
    RAISE EXCEPTION 'Sem permissão sobre esta viatura.';
  END IF;

  -- Reutiliza um token válido já existente para a viatura (evita acumular).
  SELECT id INTO v_token_id
  FROM public.danos_tokens
  WHERE viatura_id = p_viatura_id
    AND org_id = get_current_org_id()
    AND expires_at > now()
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_token_id IS NULL THEN
    INSERT INTO public.danos_tokens (org_id, viatura_id, contrato_renting_id, created_by)
    VALUES (get_current_org_id(), p_viatura_id, p_contrato_renting_id, auth.uid())
    RETURNING id INTO v_token_id;
  END IF;

  RETURN v_token_id;
END;
$$;


ALTER FUNCTION "public"."gerar_token_danos"("p_viatura_id" "uuid", "p_contrato_renting_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_token_danos"("p_viatura_id" "uuid", "p_contrato_renting_id" "uuid") IS 'Gera (ou reutiliza) o token público da galeria de danos de uma viatura. Usado no QR da folha de danos. Validade 1 ano, reutilizável.';



CREATE OR REPLACE FUNCTION "public"."gerar_token_realizacao"("p_evento_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_evento     calendario_eventos%ROWTYPE;
  v_contrato_id uuid;
  v_token_id   uuid;
BEGIN
  SELECT * INTO v_evento FROM public.calendario_eventos WHERE id = p_evento_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Evento % não encontrado.', p_evento_id;
  END IF;

  IF v_evento.origem_tipo <> 'contrato_renting' THEN
    RAISE EXCEPTION 'Evento não vem de contrato de renting.';
  END IF;

  IF v_evento.tipo NOT IN ('entrega', 'recolha', 'troca') THEN
    RAISE EXCEPTION 'Apenas eventos de entrega/recolha/troca podem ser pareados.';
  END IF;

  IF v_evento.realizado_em IS NOT NULL THEN
    RAISE EXCEPTION 'Este evento já foi realizado.';
  END IF;

  v_contrato_id := v_evento.origem_id;

  IF NOT EXISTS (
    SELECT 1 FROM public.contratos_renting
     WHERE id = v_contrato_id AND org_id = get_current_org_id()
  ) THEN
    RAISE EXCEPTION 'Sem permissão sobre este contrato.';
  END IF;

  INSERT INTO public.realizacao_tokens (
    org_id, evento_id, contrato_id, tipo, created_by
  )
  VALUES (
    get_current_org_id(), v_evento.id, v_contrato_id, v_evento.tipo, auth.uid()
  )
  RETURNING id INTO v_token_id;

  RETURN v_token_id;
END;
$$;


ALTER FUNCTION "public"."gerar_token_realizacao"("p_evento_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gerar_token_realizacao"("p_evento_id" "uuid") IS 'Cria token de deep-link para realizar entrega/recolha/troca dum evento de contrato_renting.';



CREATE OR REPLACE FUNCTION "public"."get_assistentes_disponiveis"() RETURNS TABLE("cargo_id" "uuid", "cargo_nome" "text", "user_id" "uuid", "nome" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id AS cargo_id, c.nome AS cargo_nome, uo.user_id, p.nome
  FROM public.cargo_permissoes cp
  JOIN public.recursos r
    ON r.id = cp.recurso_id AND r.nome = 'assistencia_disponivel'
  JOIN public.cargos c
    ON c.id = cp.cargo_id
  JOIN public.user_organizacoes uo
    ON uo.cargo_id = c.id AND uo.org_id = cp.org_id
  JOIN public.profiles p
    ON p.id = uo.user_id
  WHERE cp.org_id = public.get_current_org_id()
    AND cp.tem_acesso = true
    AND (
      public.is_current_user_admin()
      OR public.has_permission(auth.uid(), 'assistencia_tickets')
      OR public.has_permission(auth.uid(), 'assistencia_criar')
      OR public.has_permission(auth.uid(), 'assistencia_ver')
    )
  ORDER BY c.nome, p.nome;
$$;


ALTER FUNCTION "public"."get_assistentes_disponiveis"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cartao_historico_consumo"("p_tipo" "text", "p_numero" "text") RETURNS TABLE("transaction_date" timestamp with time zone, "amount" numeric, "station_name" "text", "fuel_type" "text", "quantity" numeric, "motorista_nome" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT t.transaction_date, t.amount, t.station_name, t.fuel_type, t.quantity,
         m.nome
  FROM public.bp_transacoes t
  LEFT JOIN public.motoristas_ativos m ON m.id = t.motorista_id
  WHERE p_tipo = 'bp' AND (t.raw_data->>'Nº cartão') = p_numero
    AND t.org_id = public.get_current_org_id()
    AND (public.can_view_financeiro() OR public.has_permission(auth.uid(), 'administrativo_cartoes'))
  UNION ALL
  SELECT t.transaction_date, t.amount, t.station_name, t.fuel_type, t.quantity,
         m.nome
  FROM public.repsol_transacoes t
  LEFT JOIN public.motoristas_ativos m ON m.id = t.motorista_id
  WHERE p_tipo = 'repsol' AND t.card_number = p_numero
    AND t.org_id = public.get_current_org_id()
    AND (public.can_view_financeiro() OR public.has_permission(auth.uid(), 'administrativo_cartoes'))
  UNION ALL
  SELECT t.transaction_date, t.amount, t.station_name, NULL::text, t.quantity,
         m.nome
  FROM public.edp_transacoes t
  LEFT JOIN public.motoristas_ativos m ON m.id = t.motorista_id
  WHERE p_tipo = 'edp' AND t.card_number = p_numero
    AND t.org_id = public.get_current_org_id()
    AND (public.can_view_financeiro() OR public.has_permission(auth.uid(), 'administrativo_cartoes'))
  ORDER BY transaction_date DESC
  LIMIT 200
$$;


