CREATE OR REPLACE FUNCTION "public"."get_ultima_importacao_por_integracao"("p_plataforma" "text", "p_ids" "uuid"[]) RETURNS TABLE("integracao_id" "uuid", "ultima_data" timestamp with time zone, "periodo_inicio" "date", "periodo_fim" "date")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_plataforma = 'bolt' THEN
    RETURN QUERY
      WITH ultimo_update AS (
        SELECT brs.integracao_id, MAX(COALESCE(brs.updated_at, brs.created_at)) AS d
        FROM public.bolt_resumos_semanais brs
        WHERE brs.integracao_id = ANY(p_ids)
        GROUP BY brs.integracao_id
      ),
      ultimo_periodo AS (
        SELECT DISTINCT ON (brs.integracao_id)
          brs.integracao_id, brs.periodo_inicio, brs.periodo_fim
        FROM public.bolt_resumos_semanais brs
        WHERE brs.integracao_id = ANY(p_ids)
          AND brs.periodo_inicio IS NOT NULL
        ORDER BY brs.integracao_id, brs.periodo_inicio DESC
      )
      SELECT
        COALESCE(uu.integracao_id, up.integracao_id),
        uu.d,
        up.periodo_inicio,
        up.periodo_fim
      FROM ultimo_update uu
      FULL OUTER JOIN ultimo_periodo up ON up.integracao_id = uu.integracao_id;

  ELSIF p_plataforma = 'uber' THEN
    RETURN QUERY
      SELECT
        ut.integracao_id,
        MAX(COALESCE(ut.updated_at, ut.created_at)),
        NULL::date,
        NULL::date
      FROM public.uber_transactions ut
      WHERE ut.integracao_id = ANY(p_ids)
      GROUP BY ut.integracao_id;

  ELSIF p_plataforma = 'bp' THEN
    RETURN QUERY
      SELECT
        bp.integracao_id,
        MAX(COALESCE(bp.updated_at, bp.created_at)),
        NULL::date,
        NULL::date
      FROM public.bp_transacoes bp
      WHERE bp.integracao_id = ANY(p_ids)
      GROUP BY bp.integracao_id;

  ELSIF p_plataforma = 'repsol' THEN
    RETURN QUERY
      SELECT
        rt.integracao_id,
        MAX(rt.created_at),
        NULL::date,
        NULL::date
      FROM public.repsol_transacoes rt
      WHERE rt.integracao_id = ANY(p_ids)
      GROUP BY rt.integracao_id;

  ELSIF p_plataforma = 'edp' THEN
    RETURN QUERY
      SELECT
        et.integracao_id,
        MAX(et.created_at),
        NULL::date,
        NULL::date
      FROM public.edp_transacoes et
      WHERE et.integracao_id = ANY(p_ids)
      GROUP BY et.integracao_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_ultima_importacao_por_integracao"("p_plataforma" "text", "p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_viatura_historico_portagens"("p_viatura_id" "uuid", "p_data_inicio" "date" DEFAULT NULL::"date", "p_data_fim" "date" DEFAULT NULL::"date") RETURNS TABLE("transaction_id" "text", "transaction_date" timestamp with time zone, "amount" numeric, "barreira_entrada" "text", "barreira_saida" "text", "operador" "text", "tipo_evento" "text", "motorista_id" "uuid", "motorista_nome" "text", "contrato_id" "uuid", "contrato_codigo" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    t.transaction_id,
    t.transaction_date,
    t.amount,
    t.barreira_entrada,
    t.barreira_saida,
    t.operador,
    t.tipo_evento,
    t.motorista_id,
    m.nome AS motorista_nome,
    c.id AS contrato_id,
    c.codigo AS contrato_codigo
  FROM public.via_verde_transacoes t
  LEFT JOIN public.motoristas_ativos m ON m.id = t.motorista_id
  LEFT JOIN public.contratos_renting c
    ON c.viatura_id = t.viatura_id
    AND c.deleted_at IS NULL
    AND c.periodo @> t.transaction_date
  WHERE t.viatura_id = p_viatura_id
    AND t.org_id = public.get_current_org_id()
    AND public.can_view_financeiro()
    AND (p_data_inicio IS NULL OR t.transaction_date >= p_data_inicio::timestamptz)
    AND (p_data_fim IS NULL OR t.transaction_date < (p_data_fim + 1)::timestamptz)
  ORDER BY t.transaction_date DESC
  LIMIT 1000
$$;


ALTER FUNCTION "public"."get_viatura_historico_portagens"("p_viatura_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_viatura_historico_portagens"("p_viatura_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") IS 'Passagens Via Verde de uma viatura, limitadas à organização activa do chamador e a quem pode ver financeiro. Ver migração 20260819120000.';



CREATE OR REPLACE FUNCTION "public"."get_viaturas_motorista_atual"("p_org_id" "uuid" DEFAULT "public"."get_current_org_id"()) RETURNS TABLE("viatura_id" "uuid", "motorista_id" "uuid", "motorista_nome" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    v.id AS viatura_id,
    COALESCE(cc.motorista_id, mv.motorista_id) AS motorista_id,
    m.nome AS motorista_nome
  FROM public.viaturas v
  LEFT JOIN LATERAL (
    SELECT cc2.motorista_id
    FROM public.contratos_renting cr
    JOIN public.contrato_condutores cc2 ON cc2.contrato_id = cr.id
    WHERE cr.viatura_id = v.id
      AND cr.deleted_at IS NULL
      AND cr.periodo @> now()
      AND cc2.motorista_id IS NOT NULL
      AND cc2.vigencia @> now()
    ORDER BY cc2.is_principal DESC, cc2.created_at DESC
    LIMIT 1
  ) cc ON true
  LEFT JOIN LATERAL (
    SELECT mv2.motorista_id
    FROM public.motorista_viaturas mv2
    WHERE mv2.viatura_id = v.id
      AND mv2.data_inicio <= CURRENT_DATE
      AND (mv2.data_fim IS NULL OR mv2.data_fim >= CURRENT_DATE)
    ORDER BY mv2.data_inicio DESC
    LIMIT 1
  ) mv ON true
  LEFT JOIN public.motoristas_ativos m ON m.id = COALESCE(cc.motorista_id, mv.motorista_id)
  WHERE v.org_id = p_org_id
    AND COALESCE(cc.motorista_id, mv.motorista_id) IS NOT NULL
$$;


ALTER FUNCTION "public"."get_viaturas_motorista_atual"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_failed_job_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin record;
  v_notification_id uuid;
begin
  for v_admin in
    select u.id as user_id, u.email
    from auth.users u
    join public.user_organizacoes uo on uo.user_id = u.id
    where uo.org_id = new.org_id and uo.is_admin = true
  loop
    insert into public.notifications (org_id, destinatario_user_id, template_codigo, titulo, mensagem, payload, link)
    values (
      new.org_id,
      v_admin.user_id,
      'sistema.job_falhou',
      'Falha num job agendado',
      coalesce(new.last_error, 'Sem detalhe'),
      jsonb_build_object('source_table', new.source_table, 'job_type', new.job_type, 'last_error', new.last_error),
      '/admin/automacao'
    )
    returning id into v_notification_id;

    insert into public.notificacoes (org_id, tipo, titulo, mensagem, severidade, destinatario_id, link)
    values (
      new.org_id,
      'sistema_job_falhou',
      'Falha num job agendado',
      coalesce(new.last_error, 'Sem detalhe'),
      'urgente',
      v_admin.user_id,
      '/admin/automacao'
    );

    if v_admin.email is not null then
      insert into public.notification_queue (notification_id, org_id, canal, destinatario, template_codigo, payload_render)
      values (
        v_notification_id,
        new.org_id,
        'email',
        v_admin.email,
        'sistema.job_falhou',
        jsonb_build_object('source_table', new.source_table, 'job_type', new.job_type, 'last_error', new.last_error)
      );
    end if;
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_failed_job_notify"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_first_user boolean;
  v_user_nome text;
  v_user_phone text;
  v_normalized_phone text;
  v_motorista_id uuid;
  v_is_motorista_signup boolean;
  v_tipo_utilizador text;
BEGIN
  v_is_first_user := (SELECT COUNT(*) = 0 FROM public.profiles);
  v_user_nome := COALESCE(NEW.raw_user_meta_data->>'nome', NEW.email);
  v_user_phone := NEW.raw_user_meta_data->>'telefone';
  v_normalized_phone := public.normalize_phone(v_user_phone);
  v_is_motorista_signup := COALESCE(NEW.raw_user_meta_data->>'cargo_nome', '') = 'Motorista';
  v_tipo_utilizador := COALESCE(NEW.raw_user_meta_data->>'tipo_utilizador',
                         CASE WHEN v_is_motorista_signup THEN 'motorista' ELSE 'colaborador' END);

  IF v_is_first_user THEN
    INSERT INTO public.profiles (id, email, nome, is_admin, tipo_utilizador)
    VALUES (
      NEW.id,
      NEW.email,
      v_user_nome,
      TRUE,
      'colaborador'
    );
  ELSE
    INSERT INTO public.profiles (id, email, nome, cargo, cargo_id, is_admin, tipo_utilizador)
    VALUES (
      NEW.id,
      NEW.email,
      v_user_nome,
      NEW.raw_user_meta_data->>'cargo_nome',
      (NEW.raw_user_meta_data->>'cargo_id')::UUID,
      COALESCE((NEW.raw_user_meta_data->>'is_first_user')::boolean, FALSE),
      v_tipo_utilizador
    );
  END IF;

  -- Ligar motorista existente pelo telefone
  IF v_is_motorista_signup AND v_normalized_phone IS NOT NULL THEN
    SELECT ma.id
    INTO v_motorista_id
    FROM public.motoristas_ativos ma
    WHERE ma.user_id IS NULL
      AND ma.telefone IS NOT NULL
      AND public.normalize_phone(ma.telefone) = v_normalized_phone
    ORDER BY ma.created_at ASC NULLS LAST, ma.id ASC
    LIMIT 1;

    IF v_motorista_id IS NOT NULL THEN
      UPDATE public.motoristas_ativos
      SET user_id = NEW.id,
          updated_at = now()
      WHERE id = v_motorista_id
        AND user_id IS NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user_org"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  _org_id uuid;
  _cargo_id uuid;
  _cargo_nome text;
  _is_first_user boolean;
  _user_nome text;
  _user_phone text;
  _normalized_phone text;
  _motorista_id uuid;
  _is_motorista_signup boolean;
  _tipo_utilizador text;
  _skip_org_assign boolean;
begin
  _is_first_user := (select count(*) = 0 from public.profiles);
  _user_nome := coalesce(new.raw_user_meta_data->>'nome', split_part(new.email, '@', 1));
  _user_phone := new.raw_user_meta_data->>'telefone';
  _normalized_phone := public.normalize_phone(_user_phone);
  _is_motorista_signup := coalesce(new.raw_user_meta_data->>'cargo_nome', '') = 'Motorista';
  _tipo_utilizador := coalesce(new.raw_user_meta_data->>'tipo_utilizador',
                       case when _is_motorista_signup then 'motorista' else 'colaborador' end);

  _skip_org_assign := (_tipo_utilizador = 'colaborador'
                       and new.raw_user_meta_data->>'cargo_nome' is null
                       and new.raw_user_meta_data->>'cargo_id' is null);

  select c.org_id, c.cargo_id, cg.nome
  into _org_id, _cargo_id, _cargo_nome
  from public.convites c
  left join public.cargos cg on cg.id = c.cargo_id
  where c.email = new.email
    and c.usado = false
  order by c.created_at desc
  limit 1;

  if _cargo_id is null and new.raw_user_meta_data->>'cargo_id' is not null then
    _cargo_id := (new.raw_user_meta_data->>'cargo_id')::uuid;
    select nome into _cargo_nome from public.cargos where id = _cargo_id;

    -- Sem convite válido, o cargo vem do cliente e não pode ser privilegiado.
    -- Mesmo critério que sync_uorg_is_admin_from_cargo usa para dar is_admin.
    if coalesce(_cargo_nome, '') ilike '%admin%' then
      _cargo_id := null;
      _cargo_nome := null;
    end if;
  end if;

  if _org_id is null and new.raw_user_meta_data->>'org_id' is not null then
    _org_id := (new.raw_user_meta_data->>'org_id')::uuid;
  end if;

  if _org_id is null and not _skip_org_assign then
    select id into _org_id from public.organizacoes where ativa = true order by created_at asc limit 1;
  end if;

  if _org_id is null then
    select id into _org_id from public.organizacoes
    where ativa = true order by created_at desc limit 1;
  end if;

  insert into public.profiles (id, email, nome, org_id, cargo_id, cargo, is_admin, tipo_utilizador)
  values (
    new.id, new.email, _user_nome, _org_id, _cargo_id, _cargo_nome,
    coalesce(_is_first_user, false), _tipo_utilizador
  )
  on conflict (id) do update set
    org_id = coalesce(excluded.org_id, profiles.org_id),
    cargo_id = coalesce(excluded.cargo_id, profiles.cargo_id),
    cargo = coalesce(excluded.cargo, profiles.cargo),
    tipo_utilizador = coalesce(excluded.tipo_utilizador, profiles.tipo_utilizador);

  if _org_id is not null then
    insert into public.user_organizacoes (user_id, org_id, role, cargo_id, is_admin)
    values (new.id, _org_id, 'member', _cargo_id, coalesce(_is_first_user, false))
    on conflict (user_id, org_id) do nothing;

    insert into public.user_org_ativa (user_id, org_id)
    values (new.id, _org_id)
    on conflict (user_id) do nothing;
  end if;

  if _is_motorista_signup
     and new.email is not null
     and _org_id is not null then
    select ma.id into _motorista_id
    from public.motoristas_ativos ma
    where ma.user_id is null
      and ma.org_id = _org_id
      and ma.email is not null
      and lower(ma.email) = lower(new.email)
    order by ma.created_at asc nulls last, ma.id asc
    limit 1;

    if _motorista_id is not null then
      update public.motoristas_ativos
      set user_id = new.id, updated_at = now()
      where id = _motorista_id and user_id is null;
    end if;
  end if;

  if _is_motorista_signup
     and _motorista_id is null
     and _normalized_phone is not null
     and _org_id is not null then
    select ma.id into _motorista_id
    from public.motoristas_ativos ma
    where ma.user_id is null
      and ma.org_id = _org_id
      and ma.email is null
      and ma.telefone is not null
      and public.normalize_phone(ma.telefone) = _normalized_phone
    order by ma.created_at asc nulls last, ma.id asc
    limit 1;

    if _motorista_id is not null then
      update public.motoristas_ativos
      set user_id = new.id, updated_at = now()
      where id = _motorista_id and user_id is null;
    end if;
  end if;

  if _tipo_utilizador = 'colaborador' and _org_id is not null then
    insert into public.domain_events (org_id, event_type, entity_table, entity_id, payload, emitted_by)
    values (
      _org_id, 'utilizador.criado', 'profiles', new.id,
      jsonb_build_object('nome', _user_nome, 'email', new.email),
      'trigger'
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user_org"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_via_verde_sync_failed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status = 'failed' and old.status is distinct from 'failed' then
    insert into public.failed_jobs (source_table, source_id, org_id, job_type, payload, attempts, last_error)
    values (
      'via_verde_sync_queue',
      new.id,
      new.org_id,
      'via_verde_sync',
      jsonb_build_object(
        'integracao_id', new.integracao_id,
        'periodo_inicio', new.periodo_inicio,
        'periodo_fim', new.periodo_fim
      ),
      1,
      coalesce(new.error_message, 'Sem detalhe')
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_via_verde_sync_failed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_permission"("_user_id" "uuid", "_recurso" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _cargo_id uuid;
  _org_id uuid;
BEGIN
  _org_id := get_current_org_id();

  IF EXISTS (
    SELECT 1 FROM public.user_organizacoes
    WHERE user_id = _user_id AND org_id = _org_id AND is_admin = true
  ) THEN
    RETURN true;
  END IF;

  SELECT cargo_id INTO _cargo_id
  FROM public.user_organizacoes
  WHERE user_id = _user_id AND org_id = _org_id;

  IF _cargo_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.cargo_permissoes cp
    JOIN public.recursos r ON cp.recurso_id = r.id
    WHERE cp.cargo_id = _cargo_id
      AND r.nome = _recurso
      AND cp.tem_acesso = true
  );
END;
$$;


ALTER FUNCTION "public"."has_permission"("_user_id" "uuid", "_recurso" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_permission"("_user_id" "uuid", "_recurso" "text", "_acao" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _cargo_id uuid;
  _org_id uuid;
BEGIN
  _org_id := get_current_org_id();

  IF EXISTS (
    SELECT 1 FROM public.user_organizacoes
    WHERE user_id = _user_id AND org_id = _org_id AND is_admin = true
  ) THEN
    RETURN true;
  END IF;

  SELECT cargo_id INTO _cargo_id
  FROM public.user_organizacoes
  WHERE user_id = _user_id AND org_id = _org_id;

  IF _cargo_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.cargo_permissoes cp
    JOIN public.recursos r ON cp.recurso_id = r.id
    WHERE cp.cargo_id = _cargo_id
      AND r.nome = _recurso
      AND (
        (_acao IN ('ver','criar','deletar') AND cp.tem_acesso = true) OR
        (_acao = 'editar' AND cp.tem_acesso = true AND cp.pode_editar = true)
      )
  );
END;
$$;


ALTER FUNCTION "public"."has_permission"("_user_id" "uuid", "_recurso" "text", "_acao" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_permission_edit"("_user_id" "uuid", "_recurso" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare _cargo_id uuid; _org_id uuid;
begin
  _org_id := get_current_org_id();
  if exists (select 1 from public.user_organizacoes where user_id = _user_id and org_id = _org_id and is_admin = true) then
    return true;
  end if;
  select cargo_id into _cargo_id from public.user_organizacoes where user_id = _user_id and org_id = _org_id;
  if _cargo_id is null then return false; end if;
  return exists (
    select 1 from public.cargo_permissoes cp
    join public.recursos r on cp.recurso_id = r.id
    where cp.cargo_id = _cargo_id and r.nome = _recurso and cp.tem_acesso = true and cp.pode_editar = true
  );
end; $$;


