CREATE OR REPLACE FUNCTION "public"."iban_valido"("p_iban" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
DECLARE
  ib       text := upper(regexp_replace(p_iban, '\s', '', 'g'));
  numerico text := '';
  c        text;
BEGIN
  IF ib !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]+$' THEN
    RETURN false;
  END IF;

  IF ib LIKE 'PT%' AND length(ib) <> 25 THEN
    RETURN false;
  END IF;

  -- Mover os 4 primeiros chars para o fim e expandir letras (A=10 … Z=35)
  FOR i IN 1..length(ib) LOOP
    c := substr(substr(ib, 5) || substr(ib, 1, 4), i, 1);
    IF c BETWEEN 'A' AND 'Z' THEN
      numerico := numerico || (ascii(c) - 55)::text;
    ELSE
      numerico := numerico || c;
    END IF;
  END LOOP;

  -- numeric tem precisão arbitrária — mod-97 directo
  RETURN mod(numerico::numeric, 97) = 1;
END;
$_$;


ALTER FUNCTION "public"."iban_valido"("p_iban" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."iban_valido"("p_iban" "text") IS 'IBAN ISO 13616: formato + comprimento PT + checksum mod-97. Espelha validarIBAN de src/lib/pt-validators.ts — manter em sincronia.';



CREATE TABLE IF NOT EXISTS "public"."failed_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_table" "text" DEFAULT 'automation_runs'::"text" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "org_id" "uuid" NOT NULL,
    "job_type" "text" NOT NULL,
    "payload" "jsonb",
    "attempts" smallint NOT NULL,
    "last_error" "text",
    "failed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved" boolean DEFAULT false NOT NULL,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "resolution_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."failed_jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."failed_jobs" IS 'Dead-letter: jobs que esgotaram as tentativas. Único sítio que a equipa precisa de vigiar (separador "Falhas" do futuro dashboard admin).';



CREATE OR REPLACE FUNCTION "public"."ignorar_failed_job"("p_id" "uuid") RETURNS "public"."failed_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job public.failed_jobs;
begin
  if not (public.is_current_user_admin() or public.can_edit(auth.uid(), 'automacoes')) then
    raise exception 'sem permissão para ignorar jobs falhados';
  end if;

  select * into v_job from public.failed_jobs where id = p_id for update;

  if v_job.id is null then
    raise exception 'failed_job % não encontrado', p_id;
  end if;

  if v_job.org_id <> public.get_current_org_id() then
    raise exception 'sem permissão para ignorar jobs falhados de outra organização';
  end if;

  update public.failed_jobs
  set resolved = true, resolved_by = auth.uid(), resolved_at = now(), resolution_note = 'ignorado manualmente'
  where id = p_id
  returning * into v_job;

  return v_job;
end;
$$;


ALTER FUNCTION "public"."ignorar_failed_job"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."increment_contract_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (
    OLD.empresa_id IS DISTINCT FROM NEW.empresa_id OR
    OLD.data_inicio IS DISTINCT FROM NEW.data_inicio OR
    OLD.data_assinatura IS DISTINCT FROM NEW.data_assinatura OR
    OLD.cidade_assinatura IS DISTINCT FROM NEW.cidade_assinatura OR
    OLD.status IS DISTINCT FROM NEW.status
  ) THEN
    NEW.versao = COALESCE(OLD.versao, 1) + 1;
    NEW.atualizado_em = now();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."increment_contract_version"() OWNER TO "postgres";


