CREATE OR REPLACE FUNCTION "public"."limpar_danos_token"("p_token" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token realizacao_tokens%ROWTYPE;
BEGIN
  SELECT * INTO v_token FROM public.realizacao_tokens WHERE id = p_token;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Token inválido.';
  END IF;
  IF v_token.org_id <> get_current_org_id() THEN
    RAISE EXCEPTION 'Token de outra organização.';
  END IF;
  IF v_token.used_at IS NOT NULL THEN
    RAISE EXCEPTION 'Token já foi usado — não é possível repetir a confirmação.';
  END IF;

  -- viatura_dano_fotos cai com ON DELETE CASCADE.
  -- Ficheiros já enviados ao storage ficam órfãos no bucket — aceitável
  -- (best-effort, mesmo padrão do cleanup client-side em caso de erro).
  DELETE FROM public.viatura_danos
   WHERE realizacao_token_id = p_token;
END;
$$;


ALTER FUNCTION "public"."limpar_danos_token"("p_token" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."limpar_danos_token"("p_token" "uuid") IS 'Apaga danos/fotos criados por uma tentativa anterior falhada do mesmo token, antes do frontend recriar — evita duplicar em retry. SECURITY DEFINER porque quem confirma o token no terreno normalmente não é admin (RLS de DELETE em viatura_danos exige is_current_user_admin()).';



CREATE OR REPLACE FUNCTION "public"."limpar_notificacoes_antigas"("p_dias_resolvidas" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_corte        timestamptz := now() - make_interval(days => p_dias_resolvidas);
  v_legadas      integer;
  v_novas        integer;
begin
  delete from public.notificacoes
  where resolvida = true and created_at < v_corte;
  get diagnostics v_legadas = row_count;

  delete from public.notifications
  where resolvida = true and created_at < v_corte;
  get diagnostics v_novas = row_count;

  return jsonb_build_object(
    'notificacoes_apagadas', v_legadas,
    'notifications_apagadas', v_novas,
    'corte', v_corte,
    'dias', p_dias_resolvidas
  );
end;
$$;


ALTER FUNCTION "public"."limpar_notificacoes_antigas"("p_dias_resolvidas" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."limpar_notificacoes_antigas"("p_dias_resolvidas" integer) IS 'Apaga notificacoes RESOLVIDAS com mais de N dias (default 30). Nunca apaga nao-resolvidas - o volume dessas resolve-se agrupando na criacao, nao apagando.';



CREATE OR REPLACE FUNCTION "public"."limpar_notifications_inertes"("p_dias" integer DEFAULT 14) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_corte       timestamptz := now() - make_interval(days => p_dias);
  v_antes       integer;
  v_apagadas    integer;
  v_fila_antes  integer;
  v_fila_depois integer;
begin
  select count(*) into v_antes      from public.notifications;
  select count(*) into v_fila_antes from public.notification_queue;

  delete from public.notifications n
  where n.created_at < v_corte
    and n.digest_enviado_em is null
    and not exists (select 1 from public.notification_queue    q where q.notification_id = n.id)
    and not exists (select 1 from public.notification_delivery d where d.notification_id = n.id);
  get diagnostics v_apagadas = row_count;

  select count(*) into v_fila_depois from public.notification_queue;

  if v_fila_antes <> v_fila_depois then
    raise exception
      'Abortado: a limpeza tocou na fila de emails (% -> %). O CASCADE apagaria envios pendentes.',
      v_fila_antes, v_fila_depois;
  end if;

  return jsonb_build_object(
    'apagadas',   v_apagadas,
    'antes',      v_antes,
    'restantes',  v_antes - v_apagadas,
    'corte',      v_corte,
    'dias',       p_dias,
    'fila_intacta', true
  );
end;
$$;


ALTER FUNCTION "public"."limpar_notifications_inertes"("p_dias" integer) OWNER TO "postgres";


