CREATE OR REPLACE FUNCTION "public"."log_lead_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    current_user_id UUID;
BEGIN
    -- Tentar obter o ID do usuário atual
    current_user_id := auth.uid();
    
    -- Se o status mudou, registrar no histórico
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO public.lead_status_history (
            lead_id,
            status_anterior,
            status_novo,
            alterado_por,
            observacoes
        ) VALUES (
            NEW.id,
            OLD.status,
            NEW.status,
            current_user_id,
            CASE 
                WHEN current_user_id IS NULL THEN 'Alteração automática do sistema'
                ELSE NULL
            END
        );
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_lead_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manage_cron_job"("p_job_name" "text", "p_action" "text", "p_cron_expression" "text" DEFAULT NULL::"text", "p_function_url" "text" DEFAULT NULL::"text", "p_anon_key" "text" DEFAULT NULL::"text", "p_body" "text" DEFAULT '{}'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_result bigint;
  v_exists boolean;
  v_schedule text;
BEGIN
  IF p_job_name !~ '^(bolt_sync_|robot_exec_|uber_sync_|sync_orchestrator)[a-z0-9_]*$' THEN
    RAISE EXCEPTION 'Nome de job inválido: %', p_job_name;
  END IF;

  IF p_action = 'read' THEN
    SELECT EXISTS(SELECT 1 FROM cron.job WHERE jobname = p_job_name) INTO v_exists;
    IF v_exists THEN
      SELECT schedule INTO v_schedule FROM cron.job WHERE jobname = p_job_name LIMIT 1;
      RETURN jsonb_build_object('success', true, 'exists', true, 'job_name', p_job_name, 'cron_expression', v_schedule);
    ELSE
      RETURN jsonb_build_object('success', true, 'exists', false, 'job_name', p_job_name);
    END IF;

  ELSIF p_action = 'delete' THEN
    SELECT EXISTS(SELECT 1 FROM cron.job WHERE jobname = p_job_name) INTO v_exists;
    IF v_exists THEN
      PERFORM cron.unschedule(p_job_name);
      RETURN jsonb_build_object('success', true, 'action', 'deleted', 'job_name', p_job_name);
    ELSE
      RETURN jsonb_build_object('success', true, 'action', 'noop', 'job_name', p_job_name, 'message', 'Job não existia');
    END IF;

  ELSIF p_action = 'schedule' THEN
    IF p_cron_expression IS NULL OR p_function_url IS NULL OR p_anon_key IS NULL THEN
      RAISE EXCEPTION 'cron_expression, function_url e anon_key são obrigatórios para agendar';
    END IF;

    SELECT EXISTS(SELECT 1 FROM cron.job WHERE jobname = p_job_name) INTO v_exists;
    IF v_exists THEN
      PERFORM cron.unschedule(p_job_name);
    END IF;

    SELECT cron.schedule(
      p_job_name,
      p_cron_expression,
      format(
        'SELECT net.http_post(url:=%L, headers:=%L::jsonb, body:=%L::jsonb) AS request_id',
        p_function_url,
        json_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || p_anon_key)::text,
        p_body
      )
    ) INTO v_result;

    RETURN jsonb_build_object('success', true, 'action', 'scheduled', 'job_name', p_job_name, 'cron_expression', p_cron_expression);
  ELSE
    RAISE EXCEPTION 'Ação inválida: %. Use "schedule", "delete" ou "read"', p_action;
  END IF;
END;
$_$;


ALTER FUNCTION "public"."manage_cron_job"("p_job_name" "text", "p_action" "text", "p_cron_expression" "text", "p_function_url" "text", "p_anon_key" "text", "p_body" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."manage_cron_job"("p_job_name" "text", "p_action" "text", "p_cron_expression" "text", "p_function_url" "text", "p_anon_key" "text", "p_body" "text") IS 'Só service role. O EXECUTE de authenticated foi revogado em 2026-08-19 (migração 20260819120000): permitia a qualquer utilizador autenticado criar tarefas agendadas na base de dados.';



CREATE OR REPLACE FUNCTION "public"."marcar_convite_usado"("p_token" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE public.convites
    SET usado = true
    WHERE token = p_token AND usado = false AND expires_at > now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count > 0;
END;
$$;


ALTER FUNCTION "public"."marcar_convite_usado"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."marcar_refecho_por_atribuicao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_de  date := LEAST(COALESCE(NEW.de, OLD.de), COALESCE(OLD.de, NEW.de));
  v_ate date := GREATEST(
    COALESCE(NEW.ate, CURRENT_DATE), COALESCE(OLD.ate, CURRENT_DATE)
  );
  v_org uuid := COALESCE(NEW.org_id, OLD.org_id);
BEGIN
  INSERT INTO public.refecho_pendente (org_id, semana_inicio, semana_fim, motivo, detalhe)
  SELECT DISTINCT r.org_id, r.semana_inicio, r.semana_fim,
         'atribuicao_de_cartao_alterada',
         jsonb_build_object('cartao_id', COALESCE(NEW.cartao_id, OLD.cartao_id))
  FROM public.motorista_resumo_semanal r
  WHERE r.org_id = v_org
    AND r.semana_fim >= v_de
    AND r.semana_inicio <= v_ate
  ON CONFLICT (org_id, semana_inicio, semana_fim, motivo) DO NOTHING;

  RETURN COALESCE(NEW, OLD);
END $$;


ALTER FUNCTION "public"."marcar_refecho_por_atribuicao"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."marcar_todas_notificacoes_lidas"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org        uuid;
  v_cargo      text;
  v_nome       text;
  v_is_admin   boolean;
  v_pode_gerir boolean;
  v_pode_escalar boolean;
  v_resolvidas integer;
  v_escaladas  integer;
begin
  v_org := get_current_org_id();
  if v_org is null then
    raise exception 'Sem organização activa';
  end if;

  v_cargo := current_user_cargo();
  v_is_admin := is_current_user_admin();

  -- Mesmos conjuntos de cargos da função singular. São DIFERENTES entre si de
  -- propósito: 'Supervisor Gestor TVDE' resolve, mas não escala.
  v_pode_gerir := v_is_admin
    or v_cargo in ('Gestor TVDE', 'Administrador', 'Supervisor Gestor TVDE');
  v_pode_escalar := v_is_admin
    or v_cargo in ('Gestor TVDE', 'Administrador');

  select nome into v_nome from public.profiles where id = auth.uid();

  with feito as (
    update public.notificacoes
    set resolvida = true,
        resolvida_por = auth.uid(),
        resolvida_por_nome = v_nome,
        resolvida_em = now()
    where org_id = v_org
      and resolvida = false
      and (v_pode_gerir or destinatario_id = auth.uid())
    returning tipo, candidatura_id
  ),
  escalados as (
    insert into public.notificacoes
      (org_id, tipo, candidatura_id, titulo, mensagem, severidade)
    select
      v_org,
      'escalonamento',
      f.candidatura_id,
      'Aviso fechado por um gestor',
      coalesce(v_nome, 'Um gestor')
        || ' fechou o aviso de um motorista pendente. Verifique a candidatura.',
      'urgente'
    from feito f
    where v_pode_escalar
      and f.tipo = 'motorista_pendente'
    returning 1
  )
  select (select count(*) from feito), (select count(*) from escalados)
  into v_resolvidas, v_escaladas;

  return jsonb_build_object(
    'resolvidas', v_resolvidas,
    'escalonamentos_criados', v_escaladas
  );
end;
$$;


ALTER FUNCTION "public"."marcar_todas_notificacoes_lidas"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."marcar_todas_notificacoes_lidas"() IS 'Resolve TODAS as notificações não resolvidas da organização activa que o chamador pode resolver, numa só instrução. Replica a autorização e o escalonamento de resolver_notificacao(uuid).';



CREATE OR REPLACE FUNCTION "public"."marketing_lista_contagem"("p_lista_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid := get_current_org_id();
  v_origem text;
  v_lista_org uuid;
  v_count integer;
BEGIN
  SELECT origem, org_id INTO v_origem, v_lista_org
  FROM public.marketing_listas WHERE id = p_lista_id;

  IF v_origem IS NULL THEN
    RETURN 0;
  END IF;
  IF v_lista_org IS DISTINCT FROM v_org THEN
    RAISE EXCEPTION 'lista fora da org';
  END IF;

  IF v_origem = 'motoristas_ativos' THEN
    SELECT count(*) INTO v_count
    FROM public.motoristas_ativos
    WHERE org_id = v_org
      AND status_ativo = true
      AND email IS NOT NULL AND email <> ''
      AND perfil_rascunho IS NOT TRUE;
  ELSE
    SELECT count(*) INTO v_count
    FROM public.marketing_contactos
    WHERE lista_id = p_lista_id;
  END IF;

  RETURN coalesce(v_count, 0);
END;
$$;


ALTER FUNCTION "public"."marketing_lista_contagem"("p_lista_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_motorista_to_platforms"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    found_uber_id TEXT;
BEGIN
    -- Se o motorista não tem UUID, tenta encontrar um 'uber_driver' sem dono com nome parecido
    IF NEW.uber_uuid IS NULL THEN
        SELECT uber_driver_id INTO found_uber_id FROM public.uber_drivers
        WHERE motorista_id IS NULL AND (
            unaccent(lower(full_name)) ILIKE '%' || unaccent(lower(NEW.nome)) || '%' OR 
            unaccent(lower(NEW.nome)) ILIKE '%' || unaccent(lower(full_name)) || '%'
        ) LIMIT 1;

        IF found_uber_id IS NOT NULL THEN
            NEW.uber_uuid := found_uber_id;
            UPDATE public.uber_drivers SET motorista_id = NEW.id WHERE uber_driver_id = found_uber_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."match_motorista_to_platforms"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."match_motorista_to_platforms"() IS 'DESLIGADA em 2026-08-14 (migracao 20260814150000). Ligava identidades Uber por nome parcial, sem filtro de organizacao e com LIMIT 1 sem ordenacao, e gravava ids da tabela legada motoristas que a aplicacao nao resolve. A ligacao faz-se em uber_drivers.motorista_id contra motoristas_ativos.';



CREATE OR REPLACE FUNCTION "public"."merge_motoristas"("p_principal" "uuid", "p_secundaria" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_principal = p_secundaria THEN RETURN; END IF;

  UPDATE contratos sec
  SET status = 'substituido'
  WHERE sec.motorista_id = p_secundaria
    AND sec.status = 'ativo'
    AND EXISTS (
      SELECT 1 FROM contratos pri
      WHERE pri.motorista_id = p_principal
        AND pri.empresa_id = sec.empresa_id
        AND pri.status = 'ativo'
    );

  UPDATE assistencia_tickets        SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE bolt_drivers               SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE bolt_mapeamento_motoristas SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE bolt_resumos_semanais      SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE bolt_viagens               SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE bp_cartoes                 SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE bp_transacoes              SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE calendario_eventos         SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE contrato_condutores        SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE contratos                  SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE edp_transacoes             SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE motorista_custos_adicionais SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE motorista_documentos       SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE motorista_financeiro       SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE motorista_recibos          SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE motorista_viaturas         SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE recibos_importados         SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE reparacao_parcelas         SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE repsol_transacoes          SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE reserva_condutores         SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE reservas                   SET condutor_id  = p_principal WHERE condutor_id  = p_secundaria;
  UPDATE uber_driver_compliance     SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE uber_driver_profiles       SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE uber_driver_risk_profiles  SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE uber_driver_tokens         SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE uber_drivers               SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE uber_transactions          SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE uber_viagens               SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE viatura_danos              SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE viatura_multas             SET motorista_id = p_principal WHERE motorista_id = p_secundaria;
  UPDATE viatura_reparacoes         SET motorista_responsavel_id = p_principal WHERE motorista_responsavel_id = p_secundaria;
  UPDATE viatura_reservas           SET motorista_id = p_principal WHERE motorista_id = p_secundaria;

  UPDATE motoristas_ativos pri
  SET uber_uuid = COALESCE(pri.uber_uuid, sec.uber_uuid),
      bolt_id   = COALESCE(pri.bolt_id,   sec.bolt_id),
      iban      = COALESCE(pri.iban,       sec.iban),
      telefone  = COALESCE(pri.telefone,   sec.telefone),
      email     = COALESCE(pri.email,      sec.email)
  FROM motoristas_ativos sec
  WHERE pri.id = p_principal AND sec.id = p_secundaria;

  DELETE FROM motoristas_ativos WHERE id = p_secundaria;
END;
$$;


ALTER FUNCTION "public"."merge_motoristas"("p_principal" "uuid", "p_secundaria" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_motoristas"("p_principal" "uuid", "p_secundaria" "uuid") IS 'Só service role. O EXECUTE de authenticated foi revogado em 2026-08-19 (migração 20260819120000): permitia fundir motoristas de qualquer organização.';



