COMMENT ON FUNCTION "public"."motorista_meus_acordos_ativos"() IS 'Lista (id, codigo, falta_pagar) dos acordos de pagamento ativos/em incumprimento em que o utilizador autenticado é o motorista responsável. Usada pelo painel do motorista para mostrar um atalho para /motorista/painel/acordos/:id — sem isto não havia forma de o motorista encontrar o próprio acordo sem já saber o id.';



CREATE OR REPLACE FUNCTION "public"."motorista_saldo_pendente"("p_motorista_id" "uuid", "p_ate_data" "date" DEFAULT NULL::"date") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(SUM(CASE tipo WHEN 'credito' THEN valor ELSE -valor END), 0)::numeric(12,2)
  FROM public.motorista_financeiro
  WHERE motorista_id = p_motorista_id
    AND status = 'pendente'
    AND (p_ate_data IS NULL OR data_movimento <= p_ate_data);
$$;


ALTER FUNCTION "public"."motorista_saldo_pendente"("p_motorista_id" "uuid", "p_ate_data" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."motorista_saldo_pendente"("p_motorista_id" "uuid", "p_ate_data" "date") IS 'Saldo por liquidar do motorista (Σcrédito − Σdébito, só status=pendente). Positivo = a favor do motorista (falta receber); negativo = motorista deve. p_ate_data filtra movimentos até essa data (usado para "saldo transportado" de semanas anteriores no resumo semanal); NULL = saldo actual completo.';



CREATE OR REPLACE FUNCTION "public"."motoristas_saldo_pendente_lote"("p_motorista_ids" "uuid"[]) RETURNS TABLE("motorista_id" "uuid", "saldo" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT mf.motorista_id, COALESCE(SUM(CASE mf.tipo WHEN 'credito' THEN mf.valor ELSE -mf.valor END), 0)::numeric(12,2)
  FROM public.motorista_financeiro mf
  WHERE mf.motorista_id = ANY (p_motorista_ids)
    AND mf.status = 'pendente'
  GROUP BY mf.motorista_id;
$$;


