COMMENT ON FUNCTION "public"."motoristas_saldo_pendente_lote"("p_motorista_ids" "uuid"[]) IS 'Mesmo cálculo de motorista_saldo_pendente (sem p_ate_data), para vários motoristas de uma vez — usada na vista semanal de Contas/Resumo. Motoristas sem nenhum movimento pendente não aparecem no resultado (saldo implícito 0) — o chamador trata a ausência como 0.';



CREATE OR REPLACE FUNCTION "public"."movimento_calendario_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_matricula     text;
  v_titulo        text;
  v_tipo_evento   text;
  v_data_inicio   timestamptz;
  v_data_fim      timestamptz;
  v_cidade        text;
  v_estacao_id    uuid;
BEGIN
  IF NEW.viatura_id IS NULL AND NEW.matricula IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.data_partida IS NULL AND NEW.data_chegada IS NULL THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.calendario_eventos
     WHERE origem_tipo = 'movimento' AND origem_id = NEW.id
  ) THEN
    RETURN NEW;
  END IF;

  v_matricula := NEW.matricula;
  IF v_matricula IS NULL AND NEW.viatura_id IS NOT NULL THEN
    SELECT matricula INTO v_matricula FROM public.viaturas WHERE id = NEW.viatura_id;
  END IF;

  v_tipo_evento := NEW.tipo;

  v_data_inicio := COALESCE(NEW.data_partida, NEW.data_chegada);
  v_data_fim := COALESCE(NEW.data_chegada, NEW.data_partida);

  v_estacao_id := COALESCE(NEW.estacao_destino_id, NEW.estacao_origem_id);
  IF v_estacao_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(TRIM(cidade), ''), nome) INTO v_cidade
      FROM public.estacoes WHERE id = v_estacao_id;
  END IF;

  v_titulo := COALESCE(v_matricula, 'Movimento #' || NEW.codigo);

  INSERT INTO public.calendario_eventos (
    tipo, titulo, descricao, cidade,
    data_inicio, data_fim, dia_todo,
    matricula_devolver, criado_por,
    origem_tipo, origem_id
  )
  VALUES (
    v_tipo_evento,
    v_titulo,
    'Gerado automaticamente pelo movimento #' || NEW.codigo,
    v_cidade,
    v_data_inicio, v_data_fim, false,
    v_matricula, COALESCE(NEW.created_by, auth.uid()),
    'movimento', NEW.id
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."movimento_calendario_sync"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."movimento_calendario_sync"() IS 'Cria evento de calendário ao inserir movimento, incluindo a cidade da estação de destino (fallback origem). Idempotente por (origem_tipo, origem_id).';



CREATE OR REPLACE FUNCTION "public"."movimento_sync_viatura"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.viatura_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.estado IS NOT DISTINCT FROM OLD.estado THEN
    RETURN NEW;
  END IF;

  IF NEW.estado = 'a_decorrer' THEN
    IF NEW.tipo = 'impro' THEN
      UPDATE public.viaturas SET status = 'inativo' WHERE id = NEW.viatura_id;
    ELSIF NEW.tipo IN ('reparacao','manutencao','inspecao') THEN
      UPDATE public.viaturas SET status = 'manutencao' WHERE id = NEW.viatura_id;
    END IF;

  ELSIF NEW.estado = 'concluido' THEN
    IF NEW.tipo = 'transferencia' THEN
      UPDATE public.viaturas
         SET estacao_id = COALESCE(NEW.estacao_destino_id, estacao_id),
             km_atual   = CASE
               WHEN NEW.km_final IS NOT NULL AND NEW.km_final >= COALESCE(km_atual, 0)
               THEN NEW.km_final ELSE km_atual END
       WHERE id = NEW.viatura_id;
    ELSE
      UPDATE public.viaturas
         SET status   = 'disponivel',
             km_atual = CASE
               WHEN NEW.km_final IS NOT NULL AND NEW.km_final >= COALESCE(km_atual, 0)
               THEN NEW.km_final ELSE km_atual END
       WHERE id = NEW.viatura_id;
      PERFORM public.recalcular_disponibilidade_viatura(NEW.viatura_id);
    END IF;

  ELSIF NEW.estado = 'cancelado' THEN
    IF NEW.tipo IN ('reparacao','manutencao','impro','inspecao') THEN
      UPDATE public.viaturas SET status = 'disponivel' WHERE id = NEW.viatura_id;
      PERFORM public.recalcular_disponibilidade_viatura(NEW.viatura_id);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."movimento_sync_viatura"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."movimento_sync_viatura"() IS 'Sincroniza viaturas.status a partir do movimento. Ao sair de manutencao/inativo, delega em recalcular_disponibilidade_viatura em vez de assumir disponivel às cegas — fix 2026-07-10: evitava mascarar uma viatura em_curso como disponível.';



CREATE OR REPLACE FUNCTION "public"."nif_pt_valido"("p_nif" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
DECLARE
  n      text := regexp_replace(p_nif, '\s', '', 'g');
  soma   int := 0;
  resto  int;
  digito int;
BEGIN
  -- 9 dígitos exactos
  IF n !~ '^[0-9]{9}$' THEN
    RETURN false;
  END IF;

  -- Dígito de entidade válido (4 não existe em PT, 0 é reservado)
  IF substr(n, 1, 1) NOT IN ('1','2','3','5','6','7','8','9') THEN
    RETURN false;
  END IF;

  -- NIFs fictícios/de teste que passam o checksum
  IF n IN ('999999990', '999999999') THEN
    RETURN false;
  END IF;

  -- Checksum oficial AT: pesos 9→2, módulo 11
  FOR i IN 1..8 LOOP
    soma := soma + (10 - i) * substr(n, i, 1)::int;
  END LOOP;
  resto  := soma % 11;
  digito := CASE WHEN resto < 2 THEN 0 ELSE 11 - resto END;

  RETURN digito = substr(n, 9, 1)::int;
END;
$_$;


ALTER FUNCTION "public"."nif_pt_valido"("p_nif" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."nif_pt_valido"("p_nif" "text") IS 'NIF PT: 9 dígitos + dígito de entidade + checksum AT (mod 11). Espelha validarNIF de src/lib/pt-validators.ts — manter em sincronia.';



