CREATE OR REPLACE FUNCTION "public"."normalize_phone"("input_phone" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  digits text;
BEGIN
  digits := regexp_replace(COALESCE(input_phone, ''), '\D', '', 'g');

  IF digits = '' THEN
    RETURN NULL;
  END IF;

  IF digits ~ '^351\d{9}$' THEN
    RETURN right(digits, 9);
  ELSIF digits ~ '^0\d{9}$' THEN
    RETURN right(digits, 9);
  END IF;

  RETURN digits;
END;
$_$;


