CREATE OR REPLACE FUNCTION "public"."notificar_lista_espera_viatura"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  IF NEW.status = 'disponivel'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'disponivel') THEN
    FOR r IN
      SELECT e.id, e.criado_por, e.org_id
      FROM public.calendario_eventos e
      WHERE e.tipo = 'lista_espera'
        AND e.lista_notificada_em IS NULL
        AND e.criado_por IS NOT NULL
        AND (e.org_id IS NOT DISTINCT FROM NEW.org_id)
        AND (
          -- Match preferido: colunas separadas (fiável p/ modelos com espaço).
          (e.lista_marca IS NOT NULL AND e.lista_modelo IS NOT NULL
             AND lower(btrim(e.lista_marca)) = lower(btrim(NEW.marca))
             AND lower(btrim(e.lista_modelo)) = lower(btrim(NEW.modelo)))
          -- Fallback p/ listas antigas (só titulo "marca modelo").
          OR (e.lista_marca IS NULL
             AND lower(btrim(e.titulo)) = lower(btrim(NEW.marca || ' ' || NEW.modelo)))
        )
      FOR UPDATE OF e SKIP LOCKED
    LOOP
      INSERT INTO public.notificacoes
        (org_id, tipo, destinatario_id, viatura_id, titulo, mensagem, severidade)
      VALUES (
        r.org_id,
        'viatura_disponivel',
        r.criado_por,
        NEW.id,
        'Viatura disponível',
        btrim(COALESCE(NEW.marca, '') || ' ' || COALESCE(NEW.modelo, ''))
          || ' ficou disponível (matrícula ' || COALESCE(NEW.matricula, '—') || ').',
        'normal'
      );
      UPDATE public.calendario_eventos
        SET lista_notificada_em = now()
        WHERE id = r.id;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notificar_lista_espera_viatura"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notificar_motorista_pendente"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_nome text;
BEGIN
  -- (a) Passou a submetido -> cria notificação de pendente (se não existir ativa)
  IF NEW.status = 'submetido'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'submetido') THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.notificacoes
      WHERE candidatura_id = NEW.id
        AND tipo = 'motorista_pendente'
        AND resolvida = false
    ) THEN
      INSERT INTO public.notificacoes (org_id, tipo, candidatura_id, titulo, mensagem, severidade)
      VALUES (
        NEW.org_id,
        'motorista_pendente',
        NEW.id,
        'Novo motorista pendente',
        COALESCE(NEW.nome, 'Um motorista') || ' submeteu a candidatura e aguarda análise.',
        'normal'
      );
    END IF;

  -- (b) Foi tratada (em análise / aprovada / rejeitada) -> fecha o aviso
  --     ativo para TODOS, SEM gerar escalonamento (não foi um "fechar" manual).
  ELSIF NEW.status IN ('em_analise', 'aprovado', 'rejeitado')
        AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    SELECT nome INTO v_nome FROM public.profiles WHERE id = auth.uid();

    UPDATE public.notificacoes
    SET resolvida = true,
        resolvida_por = auth.uid(),
        resolvida_por_nome = COALESCE(v_nome, 'Sistema'),
        resolvida_em = now()
    WHERE candidatura_id = NEW.id
      AND tipo = 'motorista_pendente'
      AND resolvida = false;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notificar_motorista_pendente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notificar_pedido_troca_kms"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_codigo integer;
  v_titulo text;
  v_mensagem text;
BEGIN
  SELECT codigo INTO v_codigo FROM public.contratos_renting WHERE id = NEW.contrato_id;

  v_titulo := CASE NEW.tipo
    WHEN 'franquia' THEN format('Pedido de alteração de franquia — contrato #%s', COALESCE(v_codigo::text, '?'))
    WHEN 'tarifa'   THEN format('Pedido de alteração de tarifa — contrato #%s', COALESCE(v_codigo::text, '?'))
    ELSE format('Pedido de alteração de kms — contrato #%s', COALESCE(v_codigo::text, '?'))
  END;

  v_mensagem := CASE NEW.tipo
    WHEN 'franquia' THEN format('Franquia: %s € → %s €. Motivo: %s', NEW.valor_atual, NEW.valor_pedido, NEW.motivo)
    WHEN 'tarifa'   THEN format('Tarifa diária: %s € → %s €. Motivo: %s', NEW.valor_atual, NEW.valor_pedido, NEW.motivo)
    ELSE format('Kms incluídos: %s → %s. Motivo: %s', NEW.valor_atual, NEW.valor_pedido, NEW.motivo)
  END;

  INSERT INTO public.notificacoes (org_id, tipo, titulo, mensagem, severidade)
  VALUES (NEW.org_id, 'pedido_troca_kms', v_titulo, v_mensagem, 'normal');

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notificar_pedido_troca_kms"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."notification_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "notification_id" "uuid" NOT NULL,
    "org_id" "uuid" NOT NULL,
    "canal" "text" NOT NULL,
    "destinatario" "text" NOT NULL,
    "template_codigo" "text" NOT NULL,
    "payload_render" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "priority" smallint DEFAULT 5 NOT NULL,
    "attempt" smallint DEFAULT 0 NOT NULL,
    "max_attempts" smallint DEFAULT 5 NOT NULL,
    "next_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "notification_queue_canal_check" CHECK (("canal" = ANY (ARRAY['email'::"text", 'whatsapp'::"text", 'sms'::"text", 'push'::"text"]))),
    CONSTRAINT "notification_queue_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'running'::"text", 'sent'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."notification_queue" OWNER TO "postgres";


COMMENT ON TABLE "public"."notification_queue" IS 'Worklist de envio multi-canal — uma linha por (notificação x canal externo). O canal interno não passa aqui (já é imediato via notifications + Realtime). Escrita só via notification_queue_claim()/_complete()/_fail().';



CREATE OR REPLACE FUNCTION "public"."notification_queue_claim"("p_canal" "text", "p_max" integer DEFAULT 10) RETURNS SETOF "public"."notification_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cap_diario_email constant integer := 300;
  v_stale record;
  v_org record;
begin
  -- REGRA A (de 20260729100000, preservada): itens presos há mais de 15 min
  -- voltam ao ciclo via notification_queue_fail() — backoff exponencial,
  -- dead-letter em failed_jobs e alerta aos admins. NUNCA substituir por um
  -- UPDATE directo a status='failed': foi esse o defeito corrigido nessa data.
  for v_stale in
    select id from public.notification_queue
    where status = 'running' and canal = p_canal and started_at < now() - interval '15 minutes'
  loop
    perform public.notification_queue_fail(v_stale.id, 'timeout: running há mais de 15 minutos');
  end loop;

  -- REGRA B (de 20260728110000, reposta): avisar UMA vez por dia e por org
  -- quando o cap é atingido e ainda há coisa em espera. Sem email neste aviso,
  -- de propósito — avisar por email que se atingiu o limite de emails seria
  -- repetir o incidente que a trava existe para evitar.
  if p_canal = 'email' then
    for v_org in
      select q.org_id, count(*) filter (where q.status = 'pending') as pendentes
      from public.notification_queue q
      where q.canal = 'email'
        and q.created_at >= date_trunc('day', now())
      group by q.org_id
      having count(*) filter (where q.status in ('sent', 'running')) >= v_cap_diario_email
         and count(*) filter (where q.status = 'pending') > 0
    loop
      if not exists (
        select 1 from public.notifications
        where org_id = v_org.org_id
          and template_codigo = 'sistema.limite_email_atingido'
          and created_at >= date_trunc('day', now())
      ) then
        insert into public.notifications
          (org_id, destinatario_user_id, template_codigo, titulo, mensagem, link, payload)
        select
          v_org.org_id, uo.user_id,
          'sistema.limite_email_atingido',
          'Limite diário de emails atingido',
          v_org.pendentes || ' email(s) ficam em espera até amanhã (limite de segurança: '
            || v_cap_diario_email || '/dia)',
          '/admin/automacao',
          jsonb_build_object('pendentes', v_org.pendentes, 'limite', v_cap_diario_email)
        from public.user_organizacoes uo
        where uo.org_id = v_org.org_id and uo.is_admin = true;

        insert into public.notificacoes
          (org_id, tipo, titulo, mensagem, severidade, destinatario_id, link)
        select
          v_org.org_id,
          'sistema_limite_email_atingido',
          'Limite diário de emails atingido',
          v_org.pendentes || ' email(s) ficam em espera até amanhã (limite de segurança: '
            || v_cap_diario_email || '/dia)',
          'urgente', uo.user_id, '/admin/automacao'
        from public.user_organizacoes uo
        where uo.org_id = v_org.org_id and uo.is_admin = true;
      end if;
    end loop;
  end if;

  -- REGRA C (de 20260727130100): reclamar com FOR UPDATE SKIP LOCKED, por
  -- prioridade e antiguidade. REGRA D (de 20260728110000, reposta): acima do
  -- cap o item simplesmente não é reclamado — fica 'pending' para amanhã.
  return query
  update public.notification_queue q
  set status = 'running',
      started_at = now(),
      attempt = q.attempt + 1
  from (
    select c.id
    from public.notification_queue c
    where c.status = 'pending'
      and c.canal = p_canal
      and c.next_attempt_at <= now()
      and (
        p_canal <> 'email'
        or (
          select count(*) from public.notification_queue s
          where s.org_id = c.org_id
            and s.canal = 'email'
            and s.status in ('sent', 'running')
            and s.created_at >= date_trunc('day', now())
        ) < v_cap_diario_email
      )
    order by c.priority asc, c.created_at asc
    limit p_max
    for update skip locked
  ) claimed
  where q.id = claimed.id
  returning q.*;
end;
$$;


ALTER FUNCTION "public"."notification_queue_claim"("p_canal" "text", "p_max" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notification_queue_claim"("p_canal" "text", "p_max" integer) IS 'Reclama itens da fila para envio. Faz QUATRO coisas e as quatro têm de sobreviver a qualquer reescrita futura: (A) devolve itens presos ao ciclo de retry via notification_queue_fail(); (B) avisa os admins uma vez por dia quando o cap é atingido; (C) reclama com FOR UPDATE SKIP LOCKED por prioridade/antiguidade; (D) aplica o cap de 300 emails por org por dia. O cap já se perdeu uma vez (28/07 -> 29/07) numa reescrita integral do corpo.';



CREATE OR REPLACE FUNCTION "public"."notification_queue_complete"("p_id" "uuid") RETURNS "public"."notification_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.notification_queue;
begin
  update public.notification_queue
  set status = 'sent'
  where id = p_id
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."notification_queue_complete"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_queue_fail"("p_id" "uuid", "p_error" "text") RETURNS "public"."notification_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.notification_queue;
begin
  select * into v_row from public.notification_queue where id = p_id for update;

  if v_row.attempt >= v_row.max_attempts then
    update public.notification_queue
    set status = 'failed', error_message = p_error
    where id = p_id
    returning * into v_row;

    insert into public.failed_jobs (source_table, source_id, org_id, job_type, payload, attempts, last_error)
    values ('notification_queue', v_row.id, v_row.org_id, v_row.canal, v_row.payload_render, v_row.attempt, p_error);
  else
    update public.notification_queue
    set status = 'pending',
        error_message = p_error,
        next_attempt_at = now() + (power(2, v_row.attempt) * interval '1 minute')
    where id = p_id
    returning * into v_row;
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."notification_queue_fail"("p_id" "uuid", "p_error" "text") OWNER TO "postgres";


