CREATE OR REPLACE FUNCTION "public"."primavera_jobs_claim"("p_org_id" "uuid", "p_max" integer) RETURNS SETOF "public"."primavera_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('primavera_jobs_claim:' || p_org_id::text)) THEN
    RETURN;
  END IF;

  UPDATE public.primavera_jobs
     SET status = 'pending', claimed_at = NULL
   WHERE org_id = p_org_id AND status = 'claimed' AND claimed_at < now() - interval '2 minutes';

  RETURN QUERY
  UPDATE public.primavera_jobs q
     SET status = 'claimed', claimed_at = now()
    FROM (
      SELECT id FROM public.primavera_jobs
       WHERE org_id = p_org_id AND status = 'pending'
       ORDER BY created_at ASC
       LIMIT GREATEST(p_max, 0)
       FOR UPDATE SKIP LOCKED
    ) reclamados
   WHERE q.id = reclamados.id
  RETURNING q.*;
END;
$$;


