CREATE OR REPLACE FUNCTION "public"."realizar_token_realizacao"("p_token" "uuid", "p_km" numeric, "p_combustivel" "text", "p_eletricidade" "text" DEFAULT NULL::"text", "p_dua_original_levada" boolean DEFAULT NULL::boolean, "p_dua_devolvida" boolean DEFAULT NULL::boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token       realizacao_tokens%ROWTYPE;
  v_evento      calendario_eventos%ROWTYPE;
  v_novo_estado text;
  v_actor       uuid;
  v_km          integer := CASE WHEN p_km IS NULL THEN NULL ELSE round(p_km)::integer END;
BEGIN
  SELECT * INTO v_token
    FROM public.realizacao_tokens
   WHERE id = p_token
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Token inválido.';
  END IF;
  IF v_token.expires_at < now() THEN
    RAISE EXCEPTION 'Token expirado.';
  END IF;
  IF v_token.used_at IS NOT NULL THEN
    RAISE EXCEPTION 'Token já foi usado.';
  END IF;
  IF v_token.org_id <> get_current_org_id() THEN
    RAISE EXCEPTION 'Token de outra organização.';
  END IF;

  SELECT * INTO v_evento FROM public.calendario_eventos WHERE id = v_token.evento_id;
  IF v_evento.realizado_em IS NOT NULL THEN
    RAISE EXCEPTION 'Evento já realizado.';
  END IF;

  IF v_token.tipo = 'recolha' AND EXISTS (
       SELECT 1
         FROM public.calendario_eventos
        WHERE origem_tipo   = 'contrato_renting'
          AND origem_id     = v_token.contrato_id
          AND tipo          = 'entrega'
          AND realizado_em IS NULL
     ) THEN
    RAISE EXCEPTION 'Este contrato ainda tem a entrega por confirmar — confirma a entrega da viatura antes de registar a recolha.';
  END IF;

  v_actor := COALESCE(auth.uid(), v_token.created_by);

  IF v_token.tipo = 'troca' THEN
    UPDATE public.contratos_renting
       SET km_saida            = COALESCE(v_km, km_saida),
           combustivel_saida   = COALESCE(p_combustivel, combustivel_saida),
           eletricidade_saida  = COALESCE(p_eletricidade, eletricidade_saida),
           updated_by          = v_actor
     WHERE id = v_token.contrato_id;

    UPDATE public.calendario_eventos
       SET realizado_em     = now(),
           realizado_por_id = v_actor
     WHERE id = v_token.evento_id;

    UPDATE public.realizacao_tokens
       SET used_at = now()
     WHERE id = v_token.id;

    RETURN;
  END IF;

  v_novo_estado := CASE v_token.tipo
    WHEN 'entrega' THEN 'em_curso'
    WHEN 'recolha' THEN 'fechado'
  END;
  IF v_novo_estado IS NULL THEN
    RAISE EXCEPTION 'Tipo de token inesperado: %.', v_token.tipo;
  END IF;

  UPDATE public.contratos_renting
     SET estado_operacional   = v_novo_estado::contrato_estado_operacional_enum,
         km_saida             = CASE WHEN v_token.tipo = 'entrega'
                                     THEN COALESCE(v_km, km_saida) ELSE km_saida END,
         combustivel_saida    = CASE WHEN v_token.tipo = 'entrega'
                                     THEN COALESCE(p_combustivel, combustivel_saida) ELSE combustivel_saida END,
         eletricidade_saida   = CASE WHEN v_token.tipo = 'entrega'
                                     THEN COALESCE(p_eletricidade, eletricidade_saida) ELSE eletricidade_saida END,
         km_entrada           = CASE WHEN v_token.tipo = 'recolha'
                                     THEN COALESCE(v_km, km_entrada) ELSE km_entrada END,
         combustivel_entrada  = CASE WHEN v_token.tipo = 'recolha'
                                     THEN COALESCE(p_combustivel, combustivel_entrada) ELSE combustivel_entrada END,
         eletricidade_entrada = CASE WHEN v_token.tipo = 'recolha'
                                     THEN COALESCE(p_eletricidade, eletricidade_entrada) ELSE eletricidade_entrada END,
         dua_original_com_motorista = CASE
             WHEN v_token.tipo = 'entrega' AND p_dua_original_levada IS TRUE THEN true
             ELSE dua_original_com_motorista END,
         dua_devolvida_em     = CASE
             WHEN v_token.tipo = 'recolha' AND p_dua_devolvida IS TRUE
                  AND dua_original_com_motorista IS TRUE AND dua_devolvida_em IS NULL
             THEN now() ELSE dua_devolvida_em END,
         updated_by           = v_actor
   WHERE id = v_token.contrato_id;

  UPDATE public.realizacao_tokens
     SET used_at = now()
   WHERE id = v_token.id;
END;
$$;


ALTER FUNCTION "public"."realizar_token_realizacao"("p_token" "uuid", "p_km" numeric, "p_combustivel" "text", "p_eletricidade" "text", "p_dua_original_levada" boolean, "p_dua_devolvida" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."realizar_token_troca"("p_token" "uuid", "p_viatura_antiga_id" "uuid", "p_km_antiga" integer, "p_combustivel_antiga" "text", "p_viatura_nova_id" "uuid", "p_km_nova" integer, "p_combustivel_nova" "text", "p_eletricidade_antiga" "text" DEFAULT NULL::"text", "p_eletricidade_nova" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token  realizacao_tokens%ROWTYPE;
  v_evento calendario_eventos%ROWTYPE;
  v_actor  uuid;
BEGIN
  SELECT * INTO v_token
    FROM public.realizacao_tokens
   WHERE id = p_token
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Token inválido.';
  END IF;
  IF v_token.expires_at < now() THEN
    RAISE EXCEPTION 'Token expirado.';
  END IF;
  IF v_token.used_at IS NOT NULL THEN
    RAISE EXCEPTION 'Token já foi usado.';
  END IF;
  IF v_token.tipo <> 'troca' THEN
    RAISE EXCEPTION 'Este token não é de troca.';
  END IF;
  IF v_token.org_id <> get_current_org_id() THEN
    RAISE EXCEPTION 'Token de outra organização.';
  END IF;

  SELECT * INTO v_evento FROM public.calendario_eventos WHERE id = v_token.evento_id;
  IF v_evento.realizado_em IS NOT NULL THEN
    RAISE EXCEPTION 'Evento já realizado.';
  END IF;

  v_actor := COALESCE(auth.uid(), v_token.created_by);

  INSERT INTO public.troca_viatura_registos (
    org_id, evento_id, contrato_id,
    viatura_antiga_id, km_antiga, combustivel_antiga, eletricidade_antiga,
    viatura_nova_id, km_nova, combustivel_nova, eletricidade_nova,
    registado_por
  ) VALUES (
    v_token.org_id, v_token.evento_id, v_token.contrato_id,
    p_viatura_antiga_id, p_km_antiga, p_combustivel_antiga, p_eletricidade_antiga,
    p_viatura_nova_id, p_km_nova, p_combustivel_nova, p_eletricidade_nova,
    v_actor
  )
  ON CONFLICT (evento_id) DO UPDATE SET
    viatura_antiga_id    = EXCLUDED.viatura_antiga_id,
    km_antiga            = EXCLUDED.km_antiga,
    combustivel_antiga   = EXCLUDED.combustivel_antiga,
    eletricidade_antiga  = EXCLUDED.eletricidade_antiga,
    viatura_nova_id      = EXCLUDED.viatura_nova_id,
    km_nova              = EXCLUDED.km_nova,
    combustivel_nova     = EXCLUDED.combustivel_nova,
    eletricidade_nova    = EXCLUDED.eletricidade_nova;

  -- Actualiza km_atual de ambas as viaturas.
  IF p_viatura_antiga_id IS NOT NULL AND p_km_antiga IS NOT NULL THEN
    UPDATE public.viaturas SET km_atual = p_km_antiga WHERE id = p_viatura_antiga_id;
  END IF;
  IF p_viatura_nova_id IS NOT NULL AND p_km_nova IS NOT NULL THEN
    UPDATE public.viaturas SET km_atual = p_km_nova WHERE id = p_viatura_nova_id;
  END IF;

  UPDATE public.calendario_eventos
     SET realizado_em     = now(),
         realizado_por_id = v_actor
   WHERE id = v_token.evento_id;

  UPDATE public.realizacao_tokens
     SET used_at = now()
   WHERE id = v_token.id;
END;
$$;


ALTER FUNCTION "public"."realizar_token_troca"("p_token" "uuid", "p_viatura_antiga_id" "uuid", "p_km_antiga" integer, "p_combustivel_antiga" "text", "p_viatura_nova_id" "uuid", "p_km_nova" integer, "p_combustivel_nova" "text", "p_eletricidade_antiga" "text", "p_eletricidade_nova" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalcular_disponibilidade_viatura"("p_viatura_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
  v_novo   text;
BEGIN
  IF p_viatura_id IS NULL THEN RETURN; END IF;

  SELECT status INTO v_status FROM public.viaturas WHERE id = p_viatura_id;
  IF v_status IS NULL THEN RETURN; END IF;

  IF v_status IN ('manutencao', 'inativo', 'vendida', 'em_recolha') THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.contratos_renting c
    WHERE c.viatura_id = p_viatura_id
      AND c.deleted_at IS NULL
      AND c.estado_operacional = 'em_curso'
  ) THEN
    v_novo := 'em_uso';
  ELSIF EXISTS (
    SELECT 1 FROM public.contratos_renting c
    WHERE c.viatura_id = p_viatura_id
      AND c.deleted_at IS NULL
      AND c.estado_operacional = 'agendado'
  ) OR EXISTS (
    SELECT 1 FROM public.reservas r
    WHERE r.viatura_id = p_viatura_id
      AND r.deleted_at IS NULL
      AND r.estado = 'confirmada'
  ) THEN
    v_novo := 'reservada';
  ELSE
    v_novo := 'disponivel';
  END IF;

  IF v_novo IS DISTINCT FROM v_status THEN
    UPDATE public.viaturas SET status = v_novo WHERE id = p_viatura_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."recalcular_disponibilidade_viatura"("p_viatura_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recalcular_disponibilidade_viatura"("p_viatura_id" "uuid") IS 'Recalcula viaturas.status a partir dos contratos/reservas activos dessa viatura. Não mexe se o status actual for manual/operacional (manutencao/inativo/vendida/em_recolha).';



CREATE OR REPLACE FUNCTION "public"."recalcular_movimentos_do_cartao"("p_cartao_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tipo   text;
  v_numero text;
  v_org    uuid;
BEGIN
  SELECT c.tipo, public.normalizar_numero_cartao(c.numero), c.org_id
    INTO v_tipo, v_numero, v_org
  FROM public.cartoes_frota c WHERE c.id = p_cartao_id;
  IF v_numero IS NULL THEN RETURN; END IF;

  PERFORM set_config('wegest.recalculo_forcado', '1', true);

  IF v_tipo = 'repsol' THEN
    UPDATE public.repsol_transacoes SET updated_at = updated_at
    WHERE org_id = v_org AND public.normalizar_numero_cartao(card_number) = v_numero;
  ELSIF v_tipo = 'edp' THEN
    UPDATE public.edp_transacoes SET updated_at = updated_at
    WHERE org_id = v_org AND public.normalizar_numero_cartao(card_number) = v_numero;
  ELSIF v_tipo = 'bp' THEN
    UPDATE public.bp_transacoes t SET updated_at = t.updated_at
    FROM public.bp_cartoes bc
    WHERE bc.id = t.card_id AND t.org_id = v_org
      AND public.normalizar_numero_cartao(bc.card_number) = v_numero;
  END IF;

  PERFORM set_config('wegest.recalculo_forcado', '0', true);
END $$;


ALTER FUNCTION "public"."recalcular_movimentos_do_cartao"("p_cartao_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculo_e_forcado"() RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  SELECT COALESCE(current_setting('wegest.recalculo_forcado', true), '0') = '1';
$$;


ALTER FUNCTION "public"."recalculo_e_forcado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recount_email_pasta_unread"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  fid uuid;
BEGIN
  fid := COALESCE(NEW.pasta_id, OLD.pasta_id);
  IF fid IS NOT NULL THEN
    UPDATE public.email_pastas p
       SET unread_count = (SELECT count(*) FROM public.email_mensagens m WHERE m.pasta_id = fid AND m.seen = false),
           updated_at = now()
     WHERE p.id = fid;
  END IF;

  -- Numa mudan??a de pasta, a pasta antiga tamb??m precisa de ser recontada.
  IF TG_OP = 'UPDATE' AND NEW.pasta_id IS DISTINCT FROM OLD.pasta_id AND OLD.pasta_id IS NOT NULL THEN
    UPDATE public.email_pastas p
       SET unread_count = (SELECT count(*) FROM public.email_mensagens m WHERE m.pasta_id = OLD.pasta_id AND m.seen = false),
           updated_at = now()
     WHERE p.id = OLD.pasta_id;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."recount_email_pasta_unread"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rejeitar_candidatura_motorista"("p_candidatura_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Verificar se é admin ou tem permissão
  IF NOT (is_current_user_admin() OR has_permission(auth.uid(), 'motoristas_gestao')) THEN
    RAISE EXCEPTION 'Sem permissão para rejeitar candidaturas';
  END IF;

  -- Atualizar status da candidatura
  UPDATE motorista_candidaturas
  SET 
    status = 'rejeitado',
    data_decisao = now(),
    decidido_por = auth.uid(),
    motivo_rejeicao = p_motivo
  WHERE id = p_candidatura_id AND status IN ('submetido', 'em_analise');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Candidatura não encontrada ou não está pendente';
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."rejeitar_candidatura_motorista"("p_candidatura_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."renovar_contrato_renting"("p_contrato_id" "uuid", "p_km_inicio" integer DEFAULT NULL::integer, "p_km_fim" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old            public.contratos_renting%ROWTYPE;
  v_user_id        uuid := auth.uid();
  v_new_id         uuid;
  v_inicio         timestamptz;
  v_fim            timestamptz;
  v_km_percorridos integer;
  v_km_limite      integer;
  v_km_valor       numeric;
  v_km_excesso     integer;
  v_km_total       numeric;
  v_extra_km_id    uuid;
BEGIN
  SELECT * INTO v_old FROM public.contratos_renting WHERE id = p_contrato_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contrato % não encontrado.', p_contrato_id;
  END IF;
  IF v_old.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Este contrato foi eliminado.';
  END IF;
  IF v_old.substituido_em IS NOT NULL THEN
    RAISE EXCEPTION 'Este contrato já foi renovado/substituído. Renova a versão actual.';
  END IF;
  IF v_old.org_id <> get_current_org_id() THEN
    RAISE EXCEPTION 'Sem permissão sobre este contrato.';
  END IF;
  IF NOT COALESCE(v_old.is_longa_duracao, false) THEN
    RAISE EXCEPTION 'A renovação só se aplica a contratos de longa duração.';
  END IF;

  IF v_old.estado_operacional <> 'em_curso' THEN
    RAISE EXCEPTION
      'Só é possível renovar um contrato em curso (estado actual: %). Confirma a entrega/abertura do contrato antes de renovar.',
      v_old.estado_operacional;
  END IF;

  IF v_old.data_fim IS NULL AND v_old.regime <> 'tvde' THEN
    RAISE EXCEPTION 'Contrato sem data de fim — não é possível calcular o novo período.';
  END IF;
  IF p_km_inicio IS NOT NULL AND p_km_fim IS NOT NULL AND p_km_fim < p_km_inicio THEN
    RAISE EXCEPTION 'O km final (%) não pode ser inferior ao km inicial (%).', p_km_fim, p_km_inicio;
  END IF;

  v_inicio := COALESCE(v_old.data_fim, now());
  v_fim    := public.proxima_data_renovacao(
                v_inicio, v_old.renovacao_opcao::text, v_old.renovacao_intervalo_dias);

  UPDATE public.contratos_renting
     SET substituido_em     = now(),
         estado_operacional = 'fechado'::contrato_estado_operacional_enum,
         updated_by         = v_user_id,
         km_saida           = COALESCE(p_km_inicio, km_saida),
         km_entrada         = COALESCE(p_km_fim, km_entrada)
   WHERE id = v_old.id;

  IF p_km_fim IS NOT NULL AND v_old.viatura_id IS NOT NULL THEN
    UPDATE public.viaturas
       SET km_atual = p_km_fim
     WHERE id = v_old.viatura_id
       AND (km_atual IS NULL OR p_km_fim >= km_atual);
  END IF;

  INSERT INTO public.contratos_renting (
    org_id, reserva_id, transferista_id, cliente_id, emissor_id, gestor_id,
    viatura_id, matricula, grupo,
    estacao_entrega_id, data_inicio, estacao_recolha_id, data_fim, estacao_origem_viatura_id,
    estado_operacional, estado_financeiro, origem, regime,
    tarifa_diaria, tarifa_id, desconto_percentagem, taxa_iva, valor_total_manual,
    is_longa_duracao, renovacao_opcao, renovacao_intervalo_dias,
    franquia_valor, caucao_valor, kms_incluidos, km_adicional_valor,
    km_saida,
    dua_original_com_motorista, dua_observacoes,
    voucher_codigo, numero_processo, voo_referencia,
    local_entrega, local_recolha, comentarios_entrega, comentarios_recolha,
    observacoes, observacoes_internas,
    versao, contrato_anterior_id, motivo_versao,
    created_by
  )
  VALUES (
    v_old.org_id, v_old.reserva_id, v_old.transferista_id, v_old.cliente_id, v_old.emissor_id, v_old.gestor_id,
    v_old.viatura_id, v_old.matricula, v_old.grupo,
    v_old.estacao_entrega_id, v_inicio, v_old.estacao_recolha_id, v_fim, v_old.estacao_origem_viatura_id,
    'em_curso'::contrato_estado_operacional_enum,
    'pendente', v_old.origem, v_old.regime,
    v_old.tarifa_diaria, v_old.tarifa_id, v_old.desconto_percentagem, v_old.taxa_iva, v_old.valor_total_manual,
    v_old.is_longa_duracao, v_old.renovacao_opcao, v_old.renovacao_intervalo_dias,
    v_old.franquia_valor, v_old.caucao_valor, v_old.kms_incluidos, v_old.km_adicional_valor,
    p_km_fim,
    v_old.dua_original_com_motorista, v_old.dua_observacoes,
    v_old.voucher_codigo, v_old.numero_processo, v_old.voo_referencia,
    v_old.local_entrega, v_old.local_recolha, v_old.comentarios_entrega, v_old.comentarios_recolha,
    v_old.observacoes, v_old.observacoes_internas,
    v_old.versao + 1, v_old.id,
    'Renovação — período de ' || to_char(v_inicio, 'YYYY-MM-DD') || ' a ' || to_char(v_fim, 'YYYY-MM-DD'),
    v_user_id
  ) RETURNING id INTO v_new_id;

  INSERT INTO public.contrato_condutores (org_id, contrato_id, cliente_id, motorista_id, is_principal)
  SELECT org_id, v_new_id, cliente_id, motorista_id, is_principal
    FROM public.contrato_condutores WHERE contrato_id = v_old.id;

  INSERT INTO public.contrato_coberturas (org_id, contrato_id, cobertura_id, cobertura_nome, preco_dia, franquia_valor)
  SELECT org_id, v_new_id, cobertura_id, cobertura_nome, preco_dia, franquia_valor
    FROM public.contrato_coberturas WHERE contrato_id = v_old.id;

  INSERT INTO public.contrato_extras (org_id, contrato_id, extra_id, extra_nome, preco_unidade, tipo_calculo, quantidade, total)
  SELECT org_id, v_new_id, extra_id, extra_nome, preco_unidade, tipo_calculo, quantidade, total
    FROM public.contrato_extras WHERE contrato_id = v_old.id;

  INSERT INTO public.contrato_taxas (org_id, contrato_id, taxa_id, taxa_nome, percentagem, valor_fixo, base_calculo, valor_calculado)
  SELECT org_id, v_new_id, taxa_id, taxa_nome, percentagem, valor_fixo, base_calculo, valor_calculado
    FROM public.contrato_taxas WHERE contrato_id = v_old.id;

  IF p_km_inicio IS NOT NULL AND p_km_fim IS NOT NULL
     AND v_old.kms_incluidos IS NOT NULL THEN
    v_km_percorridos := p_km_fim - p_km_inicio;
    v_km_limite      := v_old.kms_incluidos;
    v_km_valor       := COALESCE(v_old.km_adicional_valor, 0);

    IF v_km_percorridos > v_km_limite AND v_km_valor > 0 THEN
      v_km_excesso := v_km_percorridos - v_km_limite;
      v_km_total   := v_km_excesso * v_km_valor;

      SELECT id INTO v_extra_km_id
        FROM public.renting_extras
       WHERE org_id = v_old.org_id AND nome = 'Km excedente'
       LIMIT 1;

      IF v_extra_km_id IS NULL THEN
        INSERT INTO public.renting_extras (org_id, nome, descricao, preco_unidade, tipo_calculo, ativo, created_by)
        VALUES (v_old.org_id, 'Km excedente',
                'Km acima do limite mensal — gerado automaticamente na renovação.',
                0, 'fixo', true, v_user_id)
        RETURNING id INTO v_extra_km_id;
      END IF;

      INSERT INTO public.contrato_extras (
        org_id, contrato_id, extra_id, extra_nome, preco_unidade, tipo_calculo, quantidade, total
      )
      VALUES (
        v_old.org_id, v_old.id, v_extra_km_id,
        'Km excedente (' || v_km_excesso || ' km × ' || to_char(v_km_valor, 'FM999990.00') || ' €)',
        v_km_valor, 'fixo', v_km_excesso, v_km_total
      );
    END IF;
  END IF;

  DELETE FROM public.calendario_eventos
   WHERE origem_tipo = 'contrato_renting'
     AND origem_id   = v_new_id
     AND tipo IN ('entrega', 'recolha')
     AND realizado_em IS NULL;

  RETURN v_new_id;
END;
$$;


ALTER FUNCTION "public"."renovar_contrato_renting"("p_contrato_id" "uuid", "p_km_inicio" integer, "p_km_fim" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."renovar_contrato_renting"("p_contrato_id" "uuid", "p_km_inicio" integer, "p_km_fim" integer) IS 'Renova um contrato rent-a-car de longa duração para o mês seguinte, registando os km (saída/entrada) do mês que fecha, atualizando o odómetro da viatura, encadeando o km inicial do novo mês e — se os km percorridos excederem o limite mensal — adicionando uma linha "Km excedente" aos extras do mês que fecha. Km opcionais (retrocompatível). Fix 2026-07-15.';



CREATE OR REPLACE FUNCTION "public"."reserva_slot_evento"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_matricula     text;
  v_motorista_nome text;
BEGIN
  IF NEW.regime <> 'slot' THEN
    RETURN NEW;
  END IF;

  IF NEW.viatura_id IS NOT NULL THEN
    SELECT matricula INTO v_matricula FROM public.viaturas WHERE id = NEW.viatura_id;
  END IF;
  IF NEW.condutor_id IS NOT NULL THEN
    SELECT nome INTO v_motorista_nome FROM public.motoristas_ativos WHERE id = NEW.condutor_id;
  END IF;

  INSERT INTO public.calendario_eventos (
    tipo, titulo, descricao,
    data_inicio, data_fim, dia_todo,
    matricula_devolver, motorista_id, criado_por,
    origem_tipo, origem_id
  )
  VALUES (
    'slot',
    'Slot — ' || COALESCE(v_matricula, '?') ||
      CASE WHEN v_motorista_nome IS NOT NULL THEN ' (' || v_motorista_nome || ')' ELSE '' END,
    'Slot — ' || COALESCE(v_motorista_nome, 'motorista') ||
      COALESCE(' · ' || NEW.slot_valor_semanal::text || ' €/sem', ''),
    NEW.data_inicio, NEW.data_inicio, false,
    v_matricula, NEW.condutor_id, COALESCE(NEW.created_by, auth.uid()),
    'reserva', NEW.id
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."reserva_slot_evento"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reserva_slot_evento"() IS 'Cria um evento calendario_eventos tipo=slot ao inserir uma reserva slot. Aparece só no Relatório (o grid filtra slot).';



CREATE OR REPLACE FUNCTION "public"."reserva_tem_conflito"("p_viatura_id" "uuid", "p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone, "p_excluir_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  -- RLS aplica-se automaticamente (SECURITY INVOKER) — só vê reservas
  -- da org actual do utilizador. Filtro org_id redundante explícito
  -- para clareza e para usar o index idx_reservas_periodo_active.
  SELECT EXISTS (
    SELECT 1 FROM public.reservas
    WHERE org_id = public.get_current_org_id()
      AND viatura_id = p_viatura_id
      AND deleted_at IS NULL
      AND estado IN ('pendente', 'confirmada', 'em_curso')
      AND periodo && tstzrange(p_data_inicio, p_data_fim, '[)')
      AND (p_excluir_id IS NULL OR id <> p_excluir_id)
  );
$$;


ALTER FUNCTION "public"."reserva_tem_conflito"("p_viatura_id" "uuid", "p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone, "p_excluir_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolver_contrato_da_viatura"("p_viatura_id" "uuid", "p_data" "date") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id
  FROM public.contratos_renting c
  WHERE c.viatura_id = p_viatura_id
    AND c.deleted_at IS NULL
    AND c.estado_operacional <> 'cancelado'
    AND (c.created_at AT TIME ZONE 'Europe/Lisbon')::date <= p_data
    AND (c.substituido_em IS NULL
         OR (c.substituido_em AT TIME ZONE 'Europe/Lisbon')::date > p_data)
  -- A viva mais recente à data. Desempate estável por id: sem ele o
  -- resultado depende da ordem que a base devolver.
  ORDER BY c.created_at DESC, c.id
  LIMIT 1;
$$;


ALTER FUNCTION "public"."resolver_contrato_da_viatura"("p_viatura_id" "uuid", "p_data" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolver_devedor_da_viatura"("p_viatura_id" "uuid", "p_data" "date", OUT "contrato_id" "uuid", OUT "cliente_id" "uuid", OUT "motorista_id" "uuid", OUT "devedor_tipo" "text") RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_regime public.contrato_regime_enum;
BEGIN
  contrato_id := public.resolver_contrato_da_viatura(p_viatura_id, p_data);

  IF contrato_id IS NOT NULL THEN
    SELECT c.cliente_id, c.regime INTO cliente_id, v_regime
    FROM public.contratos_renting c WHERE c.id = contrato_id;
  END IF;

  -- O condutor vem do histórico de atribuição, já corrigido e protegido
  -- contra sobreposições. Sem contrato, ainda assim se identifica quem
  -- conduzia — serve para investigar, mesmo que não haja a quem cobrar.
  motorista_id := public.resolver_motorista_por_viatura(p_viatura_id, p_data);

  devedor_tipo := CASE
    WHEN v_regime IN ('tvde', 'slot') THEN 'motorista'
    WHEN v_regime = 'rent_a_car'      THEN 'cliente'
    ELSE NULL
  END;
END $$;


ALTER FUNCTION "public"."resolver_devedor_da_viatura"("p_viatura_id" "uuid", "p_data" "date", OUT "contrato_id" "uuid", OUT "cliente_id" "uuid", OUT "motorista_id" "uuid", OUT "devedor_tipo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolver_motorista_por_cartao"("p_org_id" "uuid", "p_tipo" "text", "p_numero" "text", "p_data" "date") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- Ambíguo devolve NULL de propósito: dois cartões do mesmo tipo acabados nos
  -- mesmos 4 dígitos existem, e atribuir ao motorista errado é pior do que
  -- deixar por atribuir.
  SELECT CASE WHEN count(*) = 1 THEN (array_agg(a.motorista_id))[1] END
  FROM public.cartao_atribuicoes a
  JOIN public.cartoes_frota c ON c.id = a.cartao_id
  WHERE a.org_id = p_org_id
    AND c.tipo = p_tipo
    AND public.normalizar_numero_cartao(c.numero) = public.normalizar_numero_cartao(p_numero)
    AND p_data >= a.de
    AND (a.ate IS NULL OR p_data <= a.ate);
$$;


ALTER FUNCTION "public"."resolver_motorista_por_cartao"("p_org_id" "uuid", "p_tipo" "text", "p_numero" "text", "p_data" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolver_motorista_por_plataforma"("p_org_id" "uuid", "p_plataforma" "text", "p_identificador" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT i.motorista_id
  FROM public.motorista_plataforma_identidades i
  WHERE i.org_id = p_org_id
    AND i.plataforma = p_plataforma
    AND i.identificador = p_identificador
  LIMIT 1;
$$;


ALTER FUNCTION "public"."resolver_motorista_por_plataforma"("p_org_id" "uuid", "p_plataforma" "text", "p_identificador" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolver_motorista_por_viatura"("p_viatura_id" "uuid", "p_data" "date") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE WHEN count(*) = 1 THEN (array_agg(mv.motorista_id))[1] END
  FROM public.motorista_viaturas mv
  WHERE mv.viatura_id = p_viatura_id
    AND p_data >= mv.data_inicio
    AND (mv.data_fim IS NULL OR p_data <= mv.data_fim);
$$;


ALTER FUNCTION "public"."resolver_motorista_por_viatura"("p_viatura_id" "uuid", "p_data" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolver_notificacao"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_notif public.notificacoes;
  v_cargo text;
  v_nome text;
  v_is_admin boolean;
  v_org uuid;
begin
  v_org := get_current_org_id();
  if v_org is null then
    raise exception 'Sem organização activa';
  end if;

  -- O filtro por org entra já aqui: sem ele, o resto da função opera sobre uma
  -- linha que o chamador nunca deveria ter conseguido ler.
  select * into v_notif
  from public.notificacoes
  where id = p_id
    and org_id = v_org;

  -- Silencioso de propósito quando não existe: distinguir "não é sua" de
  -- "não existe" confirmaria a existência de notificações de outras orgs.
  if not found or v_notif.resolvida then
    return;
  end if;

  v_cargo := current_user_cargo();
  v_is_admin := is_current_user_admin();
  select nome into v_nome from public.profiles where id = auth.uid();

  -- O destinatário do aviso pode sempre fechar o seu próprio aviso.
  -- Caso contrário, exige cargo de gestão (fluxo das candidaturas).
  if v_notif.destinatario_id is not null and v_notif.destinatario_id = auth.uid() then
    null;
  elsif not (
    v_is_admin
    or v_cargo in ('Gestor TVDE', 'Administrador', 'Supervisor Gestor TVDE')
  ) then
    raise exception 'Sem permissão para resolver notificações';
  end if;

  update public.notificacoes
  set resolvida = true,
      resolvida_por = auth.uid(),
      resolvida_por_nome = v_nome,
      resolvida_em = now()
  where id = p_id
    and org_id = v_org;

  -- Escalonamento: só para motorista_pendente fechado por gestor/admin.
  -- `v_org` e não `v_notif.org_id`: são agora iguais por construção, e usar a
  -- org do chamador deixa explícito que nunca se escreve fora dela.
  if v_notif.tipo = 'motorista_pendente'
     and (v_is_admin or v_cargo in ('Gestor TVDE', 'Administrador')) then
    insert into public.notificacoes (org_id, tipo, candidatura_id, titulo, mensagem, severidade)
    values (
      v_org,
      'escalonamento',
      v_notif.candidatura_id,
      'Aviso fechado por um gestor',
      coalesce(v_nome, 'Um gestor') || ' fechou o aviso de um motorista pendente. Verifique a candidatura.',
      'urgente'
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."resolver_notificacao"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."responder_pedido_troca_kms"("p_pedido_id" "uuid", "p_aceite" boolean, "p_resposta_motivo" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pedido public.pedidos_alteracao_contrato%ROWTYPE;
BEGIN
  IF NOT (
    public.is_current_user_admin()
    OR public.current_user_cargo() = 'Supervisor Gestor TVDE'
  ) THEN
    RAISE EXCEPTION 'Só o Supervisor Gestor TVDE pode responder a este pedido.';
  END IF;

  SELECT * INTO v_pedido
    FROM public.pedidos_alteracao_contrato
   WHERE id = p_pedido_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pedido não encontrado.';
  END IF;

  IF v_pedido.org_id <> public.get_current_org_id() THEN
    RAISE EXCEPTION 'Sem permissão sobre este pedido.';
  END IF;

  IF v_pedido.estado <> 'pendente' THEN
    RAISE EXCEPTION 'Este pedido já foi respondido.';
  END IF;

  UPDATE public.pedidos_alteracao_contrato
     SET estado           = CASE WHEN p_aceite THEN 'aceite' ELSE 'recusado' END,
         resposta_motivo   = p_resposta_motivo,
         respondido_por    = auth.uid(),
         respondido_em     = now()
   WHERE id = p_pedido_id;

  IF p_aceite THEN
    IF v_pedido.tipo = 'kms' THEN
      UPDATE public.contratos_renting
         SET kms_incluidos      = v_pedido.valor_pedido,
             km_adicional_valor = COALESCE(v_pedido.km_adicional_valor_pedido, km_adicional_valor),
             updated_by         = auth.uid()
       WHERE id = v_pedido.contrato_id;
    ELSIF v_pedido.tipo = 'franquia' THEN
      UPDATE public.contratos_renting
         SET franquia_valor = v_pedido.valor_pedido,
             updated_by     = auth.uid()
       WHERE id = v_pedido.contrato_id;
    ELSIF v_pedido.tipo = 'tarifa' THEN
      UPDATE public.contratos_renting
         SET tarifa_diaria = v_pedido.valor_pedido,
             updated_by    = auth.uid()
       WHERE id = v_pedido.contrato_id;
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "public"."responder_pedido_troca_kms"("p_pedido_id" "uuid", "p_aceite" boolean, "p_resposta_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."responder_pedido_troca_kms"("p_pedido_id" "uuid", "p_aceite" boolean, "p_resposta_motivo" "text") IS 'Supervisor Gestor TVDE aceita ou recusa um pedido de excepção de kms/franquia/tarifa. Se aceite, aplica o valor pedido directamente no campo correspondente do contrato, conforme pedidos_alteracao_contrato.tipo.';



CREATE OR REPLACE FUNCTION "public"."retry_failed_job"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_job public.failed_jobs;
begin
  if not (public.is_current_user_admin() or public.can_edit(auth.uid(), 'automacoes')) then
    raise exception 'sem permissão para reagendar jobs falhados';
  end if;

  select * into v_job from public.failed_jobs where id = p_id for update;

  if v_job.id is null then
    raise exception 'failed_job % não encontrado', p_id;
  end if;

  if v_job.org_id is not null and v_job.org_id <> public.get_current_org_id() then
    raise exception 'sem permissão para reagendar jobs falhados de outra organização';
  end if;

  if v_job.source_table = 'automation_runs' then
    update public.automation_runs
    set status = 'pending', attempt = 0, next_attempt_at = now(), error_message = null
    where id = v_job.source_id;
  elsif v_job.source_table = 'notification_queue' then
    update public.notification_queue
    set status = 'pending', attempt = 0, next_attempt_at = now(), error_message = null
    where id = v_job.source_id;
  else
    raise exception 'source_table % desconhecido', v_job.source_table;
  end if;

  update public.failed_jobs
  set resolved = true, resolved_by = auth.uid(), resolved_at = now(), resolution_note = 'reagendado manualmente'
  where id = p_id;
end;
$$;


ALTER FUNCTION "public"."retry_failed_job"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."salvar_precos_modelo_tarifa"("p_tarifa_id" "uuid", "p_linhas" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  DELETE FROM public.renting_tarifa_precos_modelo WHERE tarifa_id = p_tarifa_id;

  INSERT INTO public.renting_tarifa_precos_modelo (
    org_id, tarifa_id, modelo_id,
    preco_semana, km_mensal, km_adicional_valor, franquia_valor, caucao_valor,
    preco_dia, preco_mes, km_mensal_iva, km_adicional_valor_iva, franquia_valor_iva, caucao_valor_iva
  )
  SELECT
    (r->>'org_id')::uuid,
    (r->>'tarifa_id')::uuid,
    (r->>'modelo_id')::uuid,
    (r->>'preco_semana')::numeric,
    (r->>'km_mensal')::integer,
    (r->>'km_adicional_valor')::numeric,
    (r->>'franquia_valor')::numeric,
    (r->>'caucao_valor')::numeric,
    (r->>'preco_dia')::numeric,
    (r->>'preco_mes')::numeric,
    (r->>'km_mensal_iva')::integer,
    (r->>'km_adicional_valor_iva')::numeric,
    (r->>'franquia_valor_iva')::numeric,
    (r->>'caucao_valor_iva')::numeric
  FROM jsonb_array_elements(p_linhas) AS r;
END;
$$;


ALTER FUNCTION "public"."salvar_precos_modelo_tarifa"("p_tarifa_id" "uuid", "p_linhas" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_automacao_danos_assistencia"("p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_cargo_assistencia jsonb;
begin
  select coalesce(jsonb_agg(c.id), '[]'::jsonb)
    into v_cargo_assistencia
    from public.cargos c
   where c.org_id = p_org_id
     and (c.nome ilike '%gestor de assistência%' or c.nome ilike '%gestor de assistencia%');

  insert into public.automation_rules
    (org_id, codigo, nome, event_type, acao_tipo, acao_config, cooldown_minutos)
  values (
    p_org_id,
    'contrato_renting.fechado_com_danos',
    'Contrato fechado com danos',
    'contrato_renting.fechado_com_danos',
    'notificacao',
    jsonb_build_object(
      'template_codigo', 'contrato_renting.fechado_com_danos',
      'destinatarios_estrategia', 'cargo',
      'destinatarios_cargo_ids', v_cargo_assistencia,
      'enviar_email', true,
      'titulo', 'Contrato fechado com danos'
    ),
    10
  )
  on conflict (codigo, org_id) do nothing;

  insert into public.notification_templates
    (org_id, codigo, canal, idioma, assunto, corpo_template, corpo_formato, variaveis_esperadas)
  values (
    p_org_id,
    'contrato_renting.fechado_com_danos',
    'email',
    'pt-PT',
    'Contrato {{codigo}} ({{matricula}}) fechado com danos',
    'O contrato {{codigo}} foi fechado e a recolha trouxe registo de danos.' || chr(10) || chr(10) ||
    'Viatura: {{matricula}}' || chr(10) ||
    'Cliente: {{cliente_nome}}' || chr(10) ||
    'Período: {{data_inicio}} a {{data_fim}}' || chr(10) ||
    'KM de entrada: {{km_entrada}}' || chr(10) || chr(10) ||
    'Danos: {{dano_descricao}}' || chr(10) ||
    'Observações: {{dano_observacoes}}' || chr(10) || chr(10) ||
    'Abrir o contrato: {{link}}',
    'text',
    array['codigo', 'matricula', 'cliente_nome', 'data_inicio', 'data_fim',
          'km_entrada', 'dano_descricao', 'dano_observacoes', 'link']
  )
  on conflict (codigo, canal, idioma, versao, org_id) do nothing;
end;
$$;


