CREATE OR REPLACE FUNCTION "public"."set_contrato_prestacao_codigo_por_org"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.org_id IS NULL THEN
    RAISE EXCEPTION 'contratos_prestacao.org_id é obrigatório para gerar código por org';
  END IF;

  IF NEW.codigo IS NOT NULL THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext('contratos_prestacao_codigo:' || NEW.org_id::text)
  );

  SELECT COALESCE(MAX(codigo), 0) + 1
    INTO NEW.codigo
    FROM public.contratos_prestacao
   WHERE org_id = NEW.org_id;

  RETURN NEW;
END;
$$;


