CREATE OR REPLACE FUNCTION "public"."sincronizar_ficha_cartao_frota"("p_cartao_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org       uuid;
  v_tipo      text;
  v_numero    text;
  v_motorista uuid;
begin
  v_org := get_current_org_id();
  if v_org is null then
    raise exception 'Sem organização activa';
  end if;

  if not (
    is_current_user_admin()
    or has_permission(auth.uid(), 'administrativo_cartoes', 'editar')
  ) then
    raise exception 'Sem permissão para gerir cartões de frota';
  end if;

  select tipo, numero, motorista_id into v_tipo, v_numero, v_motorista
  from public.cartoes_frota
  where id = p_cartao_id and org_id = v_org;

  if not found then
    raise exception 'Cartão inexistente ou de outra organização';
  end if;

  if v_motorista is null then
    raise exception 'Cartão não está atribuído a nenhum motorista';
  end if;

  if v_tipo not in ('bp', 'repsol', 'edp') then
    raise exception 'Tipo de cartão desconhecido: %', v_tipo;
  end if;

  update public.motoristas_ativos
  set cartao_bp     = case when v_tipo = 'bp'     then v_numero else cartao_bp end,
      cartao_repsol = case when v_tipo = 'repsol' then v_numero else cartao_repsol end,
      cartao_edp    = case when v_tipo = 'edp'    then v_numero else cartao_edp end
  where id = v_motorista and org_id = v_org;
end;
$$;


ALTER FUNCTION "public"."sincronizar_ficha_cartao_frota"("p_cartao_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sincronizar_ficha_cartao_frota"("p_cartao_id" "uuid") IS 'Repõe na ficha do motorista o número do cartão que ele tem mesmo atribuído. tipo/número/destinatário vêm do cartão, não do cliente.';



CREATE OR REPLACE FUNCTION "public"."sync_cargo_name"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Buscar o nome do cargo e atribuir à variável NEW.cargo
  NEW.cargo := (SELECT nome FROM public.cargos WHERE id = NEW.cargo_id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_cargo_name"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_cartao_frota_motorista"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  col text;
BEGIN
  col := CASE NEW.tipo
    WHEN 'bp'     THEN 'cartao_bp'
    WHEN 'repsol' THEN 'cartao_repsol'
    WHEN 'edp'    THEN 'cartao_edp'
  END;

  -- Limpar no motorista anterior (se mudou)
  IF OLD.motorista_id IS NOT NULL AND OLD.motorista_id IS DISTINCT FROM NEW.motorista_id THEN
    EXECUTE format('UPDATE public.motoristas_ativos SET %I = NULL WHERE id = $1 AND %I = $2', col, col)
      USING OLD.motorista_id, OLD.numero;
  END IF;

  -- Atribuir ao novo motorista
  IF NEW.motorista_id IS NOT NULL THEN
    EXECUTE format('UPDATE public.motoristas_ativos SET %I = $1 WHERE id = $2', col)
      USING NEW.numero, NEW.motorista_id;
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."sync_cartao_frota_motorista"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_gestor_names"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Se o nome foi alterado na tabela profiles, atualizar na tabela leads_dasprent
  IF OLD.nome IS DISTINCT FROM NEW.nome THEN
    UPDATE leads_dasprent 
    SET gestor_responsavel = NEW.nome
    WHERE gestor_responsavel = OLD.nome;
    
    RAISE NOTICE 'Atualizados gestores de % para %', OLD.nome, NEW.nome;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_gestor_names"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_grupo_contrato_from_viatura"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.substituido_em IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.viatura_id IS NULL THEN
    NEW.grupo := NULL;
    RETURN NEW;
  END IF;

  SELECT rg.nome INTO NEW.grupo
    FROM public.viaturas v
    LEFT JOIN public.renting_grupos rg ON rg.id = v.grupo_id
   WHERE v.id = NEW.viatura_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_grupo_contrato_from_viatura"() OWNER TO "postgres";


