COMMENT ON FUNCTION "public"."sync_grupo_reserva_from_viatura"() IS 'Mantém reservas.grupo sempre igual ao grupo da viatura associada — corre em qualquer INSERT/UPDATE, não só quando o formulário troca ativamente de viatura. Fix 2026-07-14 (reserva #56 e 149 registos com o mesmo padrão).';



CREATE OR REPLACE FUNCTION "public"."sync_is_admin_from_cargo"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _cargo_nome text;
BEGIN
  -- Nome do cargo: preferir o ligado por cargo_id; senão, o texto em profiles.cargo
  IF NEW.cargo_id IS NOT NULL THEN
    SELECT nome INTO _cargo_nome FROM public.cargos WHERE id = NEW.cargo_id;
  END IF;
  _cargo_nome := COALESCE(_cargo_nome, NEW.cargo, '');

  NEW.is_admin := (_cargo_nome ILIKE '%admin%');
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_is_admin_from_cargo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_motorista_id_to_transactions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.motorista_id IS NOT NULL AND (OLD.motorista_id IS NULL OR OLD.motorista_id <> NEW.motorista_id) THEN
    UPDATE uber_transactions
    SET motorista_id = NEW.motorista_id
    WHERE uber_driver_id = NEW.uber_driver_id
      AND integracao_id = NEW.integracao_id
      AND (motorista_id IS NULL OR motorista_id <> NEW.motorista_id);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_motorista_id_to_transactions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_reserva_viatura_from_contrato"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.substituido_em IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.reserva_id IS NULL OR NEW.viatura_id IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.reservas
     SET viatura_id = NEW.viatura_id,
         matricula  = NEW.matricula
   WHERE id = NEW.reserva_id
     AND deleted_at IS NULL
     AND (viatura_id IS DISTINCT FROM NEW.viatura_id OR matricula IS DISTINCT FROM NEW.matricula);

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_reserva_viatura_from_contrato"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_reserva_viatura_from_contrato"() IS 'Mantém reservas.viatura_id e reservas.matricula sempre iguais aos da versão activa do contrato ligado (via reserva_id) — corre em qualquer INSERT/UPDATE de viatura_id/reserva_id. Fix 2026-07-22, estendido no mesmo dia para incluir matricula (a listagem de reservas lê-a directamente, sem join a viaturas).';



CREATE OR REPLACE FUNCTION "public"."sync_uber_uuid_to_motorista"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.motorista_id IS NOT NULL AND NEW.uber_driver_id IS NOT NULL THEN
    UPDATE motoristas
    SET uber_uuid = NEW.uber_driver_id
    WHERE id = NEW.motorista_id
      AND (uber_uuid IS NULL OR uber_uuid <> NEW.uber_driver_id);
    
    UPDATE motoristas_ativos
    SET uber_uuid = NEW.uber_driver_id
    WHERE id = NEW.motorista_id
      AND (uber_uuid IS NULL OR uber_uuid <> NEW.uber_driver_id);
  END IF;
  RETURN NEW;
END;
$$;


