CREATE OR REPLACE FUNCTION "public"."tg_organizacao_modulos_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at := now();
  if new.ativo and not old.ativo then
    new.ativado_em := now();
    new.desativado_em := null;
  elsif old.ativo and not new.ativo then
    new.desativado_em := now();
  end if;
  return new;
end $$;


