CREATE OR REPLACE FUNCTION "public"."tg_resolver_motorista_cartao"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_numero text;
  v_resolvido uuid;
BEGIN
  IF TG_TABLE_NAME = 'bp_transacoes' THEN
    SELECT bc.card_number INTO v_numero
    FROM public.bp_cartoes bc WHERE bc.id = NEW.card_id;
  ELSE
    v_numero := NEW.card_number;
  END IF;

  v_resolvido := public.resolver_motorista_por_cartao(
    NEW.org_id, TG_ARGV[0], v_numero, NEW.transaction_date::date
  );

  IF v_resolvido IS NOT NULL OR TG_OP = 'INSERT' OR public.recalculo_e_forcado() THEN
    NEW.motorista_id := v_resolvido;
  ELSE
    NEW.motorista_id := OLD.motorista_id;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_resolver_motorista_cartao"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_resolver_motorista_plataforma"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_id text;
  v_resolvido uuid;
BEGIN
  v_id := CASE TG_ARGV[0]
            WHEN 'bolt' THEN NEW.identificador_motorista
            ELSE NEW.uber_driver_id
          END;
  v_resolvido := public.resolver_motorista_por_plataforma(NEW.org_id, TG_ARGV[0], v_id);

  IF v_resolvido IS NOT NULL OR TG_OP = 'INSERT' THEN
    NEW.motorista_id := v_resolvido;
  ELSE
    NEW.motorista_id := OLD.motorista_id;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_resolver_motorista_plataforma"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_resolver_motorista_viatura"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  r record;
BEGIN
  SELECT * INTO r FROM public.resolver_devedor_da_viatura(
    NEW.viatura_id, NEW.transaction_date::date
  );

  NEW.contrato_id  := r.contrato_id;
  NEW.cliente_id   := r.cliente_id;
  NEW.devedor_tipo := r.devedor_tipo;

  -- Mesma guarda de sempre: uma resolução vazia não apaga o que lá está,
  -- excepto quando a correcção do histórico o pede explicitamente.
  IF r.motorista_id IS NOT NULL OR TG_OP = 'INSERT' OR public.recalculo_e_forcado() THEN
    NEW.motorista_id := r.motorista_id;
  ELSE
    NEW.motorista_id := OLD.motorista_id;
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_resolver_motorista_viatura"() OWNER TO "postgres";


