CREATE OR REPLACE FUNCTION "public"."trocar_condutor"("p_contrato_id" "uuid", "p_novo_cliente_id" "uuid", "p_data_troca" timestamp with time zone DEFAULT "now"(), "p_motivo" "text" DEFAULT 'Troca de condutor'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_atual   record;
  v_novo_id uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.contratos_renting WHERE id = p_contrato_id) THEN
    RAISE EXCEPTION 'Contrato % não encontrado.', p_contrato_id;
  END IF;

  -- Condutor principal vigente
  SELECT * INTO v_atual
  FROM public.contrato_condutores
  WHERE contrato_id = p_contrato_id
    AND is_principal = true
    AND data_fim IS NULL
  LIMIT 1;

  IF FOUND THEN
    IF v_atual.cliente_id = p_novo_cliente_id THEN
      RAISE EXCEPTION 'O novo condutor é igual ao condutor atual.';
    END IF;
    -- Fecha a vigência do condutor atual (primeiro, para não sobrepor)
    UPDATE public.contrato_condutores
       SET data_fim = p_data_troca, motivo_fim = p_motivo
     WHERE id = v_atual.id;
  END IF;

  -- Abre o novo condutor principal (org_id preenchido por trigger)
  INSERT INTO public.contrato_condutores
    (contrato_id, cliente_id, is_principal, data_inicio)
  VALUES
    (p_contrato_id, p_novo_cliente_id, true, p_data_troca)
  RETURNING id INTO v_novo_id;

  RETURN v_novo_id;
END;
$$;


ALTER FUNCTION "public"."trocar_condutor"("p_contrato_id" "uuid", "p_novo_cliente_id" "uuid", "p_data_troca" timestamp with time zone, "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trocar_condutor"("p_contrato_id" "uuid", "p_novo_cliente_id" "uuid", "p_data_troca" timestamp with time zone, "p_motivo" "text") IS 'Troca atómica do condutor principal de um contrato — fecha a vigência do atual e abre a do novo, sem cancelar o contrato.';



CREATE OR REPLACE FUNCTION "public"."uber_automap_todas_integracoes"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_integracao record;
  v_invocadas  integer := 0;
begin
  for v_integracao in
    select distinct p.id, p.nome
    from public.plataformas_configuracao p
    join public.uber_drivers u on u.integracao_id = p.id
    where p.ativo = true
      and p.org_id is not null
      and u.motorista_id is null
  loop
    perform public.cron_invocar_edge(
      'uber-automap-' || v_integracao.id::text,
      'uber-auto-map-drivers',
      jsonb_build_object('integracao_id', v_integracao.id),
      120000
    );
    v_invocadas := v_invocadas + 1;
  end loop;

  return v_invocadas;
end;
$$;


ALTER FUNCTION "public"."uber_automap_todas_integracoes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."uber_automap_todas_integracoes"() IS 'Invoca o uber-auto-map-drivers para cada integracao Uber activa com motoristas por ligar. Rede de seguranca para os caminhos de importacao que nao o chamam (uber-webhook).';



CREATE OR REPLACE FUNCTION "public"."uber_resumo_merge"("p_integracao_id" "uuid", "p_org_id" "uuid", "p_periodo_inicio" "date", "p_periodo_fim" "date", "p_fonte" "text", "p_uber_driver_id" "text" DEFAULT NULL::"text", "p_motorista_nome" "text" DEFAULT NULL::"text", "p_motorista_id" "uuid" DEFAULT NULL::"uuid", "p_ganhos_brutos" numeric DEFAULT 0, "p_ganhos_liquidos" numeric DEFAULT NULL::numeric, "p_comissoes" numeric DEFAULT NULL::numeric, "p_viagens" integer DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_chave   text;
  v_periodo text;
  v_org     uuid;
  v_id      uuid;
  v_fonte_actual text;
BEGIN
  IF p_integracao_id IS NULL THEN
    RAISE EXCEPTION 'uber_resumo_merge: p_integracao_id e obrigatorio.'; END IF;
  IF p_periodo_inicio IS NULL OR p_periodo_fim IS NULL THEN
    RAISE EXCEPTION 'uber_resumo_merge: periodo_inicio e periodo_fim sao obrigatorios.'; END IF;
  IF p_fonte NOT IN ('api', 'csv') THEN
    RAISE EXCEPTION 'uber_resumo_merge: fonte tem de ser api ou csv, veio %.', p_fonte; END IF;

  v_periodo := to_char(p_periodo_inicio, 'YYYY-MM-DD') || ' a ' || to_char(p_periodo_fim, 'YYYY-MM-DD');

  v_chave := COALESCE(
    NULLIF(btrim(p_uber_driver_id), ''),
    public.bolt_normalizar_nome(p_motorista_nome)
  );
  IF v_chave IS NULL THEN
    RAISE EXCEPTION 'uber_resumo_merge: motorista sem uuid nem nome (integracao %, periodo %).',
      p_integracao_id, v_periodo; END IF;

  SELECT org_id INTO v_org FROM public.plataformas_configuracao WHERE id = p_integracao_id;
  v_org := COALESCE(v_org, p_org_id);
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'uber_resumo_merge: sem org_id para a integracao %.', p_integracao_id; END IF;

  SELECT fonte INTO v_fonte_actual
    FROM public.uber_resumos_semanais
   WHERE integracao_id = p_integracao_id AND periodo = v_periodo AND chave_motorista = v_chave
   FOR UPDATE;

  IF v_fonte_actual = 'api' AND p_fonte = 'csv' THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.uber_resumos_semanais AS r (
    org_id, integracao_id, periodo, periodo_inicio, periodo_fim,
    chave_motorista, uber_driver_id, motorista_nome, motorista_id,
    ganhos_brutos, ganhos_liquidos, comissoes, viagens,
    fonte, api_sincronizado_em, csv_importado_em
  ) VALUES (
    v_org, p_integracao_id, v_periodo, p_periodo_inicio, p_periodo_fim,
    v_chave, NULLIF(btrim(p_uber_driver_id), ''), NULLIF(btrim(p_motorista_nome), ''), p_motorista_id,
    COALESCE(p_ganhos_brutos, 0), p_ganhos_liquidos, p_comissoes, COALESCE(p_viagens, 0),
    p_fonte,
    CASE WHEN p_fonte = 'api' THEN now() END,
    CASE WHEN p_fonte = 'csv' THEN now() END
  )
  ON CONFLICT (integracao_id, periodo, chave_motorista) DO UPDATE SET
    motorista_nome  = COALESCE(EXCLUDED.motorista_nome, r.motorista_nome),
    motorista_id    = COALESCE(r.motorista_id, EXCLUDED.motorista_id),
    uber_driver_id  = COALESCE(r.uber_driver_id, EXCLUDED.uber_driver_id),
    ganhos_brutos   = EXCLUDED.ganhos_brutos,
    ganhos_liquidos = COALESCE(EXCLUDED.ganhos_liquidos, r.ganhos_liquidos),
    comissoes       = COALESCE(EXCLUDED.comissoes, r.comissoes),
    viagens         = EXCLUDED.viagens,
    fonte           = EXCLUDED.fonte,
    api_sincronizado_em = COALESCE(EXCLUDED.api_sincronizado_em, r.api_sincronizado_em),
    csv_importado_em    = COALESCE(EXCLUDED.csv_importado_em, r.csv_importado_em),
    updated_at      = now()
  RETURNING r.id INTO v_id;

  RETURN v_id;
END;
$$;


