CREATE OR REPLACE FUNCTION "public"."validate_date_year"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Validar data_contratacao em motoristas_ativos
  IF TG_TABLE_NAME = 'motoristas_ativos' THEN
    IF NEW.data_contratacao IS NOT NULL THEN
      IF EXTRACT(YEAR FROM NEW.data_contratacao) < 1900 OR EXTRACT(YEAR FROM NEW.data_contratacao) > 2100 THEN
        RAISE EXCEPTION 'Data de contratação inválida: ano % fora do intervalo permitido (1900-2100)', 
          EXTRACT(YEAR FROM NEW.data_contratacao);
      END IF;
    END IF;
  END IF;
  
  -- Validar datas em contratos
  IF TG_TABLE_NAME = 'contratos' THEN
    IF NEW.data_assinatura IS NOT NULL THEN
      IF EXTRACT(YEAR FROM NEW.data_assinatura::date) < 1900 OR EXTRACT(YEAR FROM NEW.data_assinatura::date) > 2100 THEN
        RAISE EXCEPTION 'Data de assinatura inválida: ano % fora do intervalo permitido (1900-2100)', 
          EXTRACT(YEAR FROM NEW.data_assinatura::date);
      END IF;
    END IF;
    
    IF NEW.data_inicio IS NOT NULL THEN
      IF EXTRACT(YEAR FROM NEW.data_inicio::date) < 1900 OR EXTRACT(YEAR FROM NEW.data_inicio::date) > 2100 THEN
        RAISE EXCEPTION 'Data de início inválida: ano % fora do intervalo permitido (1900-2100)', 
          EXTRACT(YEAR FROM NEW.data_inicio::date);
      END IF;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_date_year"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verificar_lista_espera_disponibilidade"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_entrada record;
  v_matricula_livre text;
  v_criadas integer := 0;
begin
  for v_entrada in
    select id, titulo, criado_por, org_id
    from public.calendario_eventos
    where tipo = 'lista_espera'
      and titulo is not null
      and criado_por is not null
  loop
    -- Guard anti-duplicação. Depende de `evento_id` sobreviver ao INSERT —
    -- garantido desde que fn_notificacoes_agrupar() deixou de fundir linhas
    -- com chave de entidade. O ramo notificacao_dispensas foi retirado: a
    -- tabela não tem escritores desde 20260629000004.
    if exists (
      select 1 from public.notificacoes n
      where n.evento_id = v_entrada.id
        and n.tipo = 'viatura_disponivel'
        and n.resolvida = false
    ) then
      continue;
    end if;

    select v.matricula into v_matricula_livre
    from public.viaturas v
    where v.is_vendida is not true
      and (v_entrada.org_id is null or v.org_id = v_entrada.org_id)
      and lower(regexp_replace(btrim(v.marca || ' ' || v.modelo), '\s+', ' ', 'g'))
        = lower(regexp_replace(btrim(v_entrada.titulo), '\s+', ' ', 'g'))
      and public.viatura_totalmente_livre(v.id)
    limit 1;

    if v_matricula_livre is not null then
      insert into public.notificacoes (
        org_id, tipo, evento_id, destinatario_id, titulo, mensagem, severidade, link
      )
      values (
        v_entrada.org_id,
        'viatura_disponivel',
        v_entrada.id,
        -- `destinatario_id`: a coluna que a policy de SELECT lê e que
        -- resolver_notificacao() consulta. Era este o bug.
        v_entrada.criado_por,
        'Viatura disponível: ' || v_entrada.titulo,
        'Já existe uma ' || v_entrada.titulo || ' disponível (' || v_matricula_livre ||
          '). Pode avançar com a reserva da lista de espera.',
        'normal',
        '/calendario'
      );
      v_criadas := v_criadas + 1;
    end if;
  end loop;

  return v_criadas;
end;
$$;


