CREATE TABLE IF NOT EXISTS "public"."via_verde_sync_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "integracao_id" "uuid" NOT NULL,
    "org_id" "uuid" NOT NULL,
    "periodo_inicio" "date",
    "periodo_fim" "date",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "error_message" "text",
    "alertado_em" timestamp with time zone,
    CONSTRAINT "via_verde_sync_queue_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'running'::"text", 'completed'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."via_verde_sync_queue" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."via_verde_sync_queue_claim"("p_max" integer) RETURNS SETOF "public"."via_verde_sync_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_running_count integer;
  v_capacity integer;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('via_verde_sync_queue_claim')) THEN
    RETURN; -- outro drain já está a reclamar; tenta na próxima tick
  END IF;

  UPDATE public.via_verde_sync_queue
     SET status = 'failed',
         completed_at = now(),
         error_message = 'Timeout: execução ultrapassou 15 minutos'
   WHERE status = 'running'
     AND started_at < now() - interval '15 minutes';

  SELECT count(*) INTO v_running_count
    FROM public.via_verde_sync_queue
   WHERE status = 'running';

  v_capacity := GREATEST(p_max - v_running_count, 0);
  IF v_capacity = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  UPDATE public.via_verde_sync_queue q
     SET status = 'running', started_at = now()
    FROM (
      SELECT id FROM public.via_verde_sync_queue
       WHERE status = 'pending'
       ORDER BY created_at ASC
       LIMIT v_capacity
       FOR UPDATE SKIP LOCKED
    ) claimed
   WHERE q.id = claimed.id
  RETURNING q.*;
END;
$$;


ALTER FUNCTION "public"."via_verde_sync_queue_claim"("p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."viatura_ocupacao_intervalos"("p_viatura_id" "uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("fonte" "text", "fonte_id" "uuid", "codigo" integer, "data_inicio" timestamp with time zone, "data_fim" timestamp with time zone, "estado" "text", "tipo" "text", "descricao" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH janela AS (
    SELECT tstzrange(
      COALESCE(p_from, '-infinity'::timestamptz),
      COALESCE(p_to,   'infinity'::timestamptz),
      '[)'
    ) AS r
  )
  SELECT
    'contrato'::text                         AS fonte,
    c.id                                     AS fonte_id,
    c.codigo                                 AS codigo,
    c.data_inicio                            AS data_inicio,
    c.data_fim                               AS data_fim,
    c.estado_operacional::text               AS estado,
    NULL::text                               AS tipo,
    'Contrato #' || c.codigo::text           AS descricao
  FROM public.contratos_renting c
  CROSS JOIN janela
  WHERE c.viatura_id = p_viatura_id
    AND c.deleted_at IS NULL
    AND c.substituido_em IS NULL
    AND c.estado_operacional::text IN ('agendado', 'em_curso')
    AND tstzrange(c.data_inicio, c.data_fim, '[)') && janela.r

  UNION ALL

  SELECT
    'reserva'::text,
    r.id,
    r.codigo,
    r.data_inicio,
    r.data_fim,
    r.estado::text,
    NULL::text,
    'Reserva #' || r.codigo::text
  FROM public.reservas r
  CROSS JOIN janela
  WHERE r.viatura_id = p_viatura_id
    AND r.estado::text IN ('pendente', 'confirmada', 'em_curso')
    AND NOT EXISTS (
      SELECT 1 FROM public.contratos_renting c2
       WHERE c2.reserva_id = r.id
         AND c2.deleted_at IS NULL
         AND c2.substituido_em IS NULL
         AND c2.estado_operacional::text IN ('agendado', 'em_curso')
    )
    AND tstzrange(r.data_inicio, r.data_fim, '[)') && janela.r

  UNION ALL

  SELECT
    'movimento'::text,
    m.id,
    m.codigo,
    m.data_partida,
    m.data_chegada,
    m.estado::text,
    m.tipo::text,
    'Movimento #' || m.codigo::text || ' (' || m.tipo::text || ')'
  FROM public.movimentos m
  CROSS JOIN janela
  WHERE m.viatura_id = p_viatura_id
    AND m.estado::text IN ('planeado', 'a_decorrer')
    AND m.data_partida IS NOT NULL
    AND tstzrange(
          m.data_partida,
          COALESCE(m.data_chegada, 'infinity'::timestamptz),
          '[)'
        ) && janela.r

  UNION ALL

  SELECT
    'reparacao'::text,
    rep.id,
    NULL::integer,
    rep.data_entrada::timestamptz,
    rep.data_saida::timestamptz,
    NULL::text,
    NULL::text,
    'Reparação' || COALESCE(' — ' || rep.oficina, '')
  FROM public.viatura_reparacoes rep
  CROSS JOIN janela
  WHERE rep.viatura_id = p_viatura_id
    AND rep.data_entrada IS NOT NULL
    AND tstzrange(
          rep.data_entrada::timestamptz,
          COALESCE(rep.data_saida::timestamptz, 'infinity'::timestamptz),
          '[)'
        ) && janela.r

  ORDER BY data_inicio NULLS FIRST;
$$;


ALTER FUNCTION "public"."viatura_ocupacao_intervalos"("p_viatura_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."viatura_ocupacao_intervalos"("p_viatura_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Timeline de ocupação de uma viatura cruzando contratos, reservas, movimentos e reparações activos. Janela opcional [p_from, p_to). Ignora versões de contrato substituídas (substituido_em).';



CREATE OR REPLACE FUNCTION "public"."viatura_totalmente_livre"("p_viatura_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT NOT (
    EXISTS (
      SELECT 1 FROM public.reservas r
      WHERE r.viatura_id = p_viatura_id
        AND r.deleted_at IS NULL
        AND r.estado IN ('pendente', 'confirmada', 'em_curso')
    )
    OR EXISTS (
      SELECT 1 FROM public.contratos_renting c
      WHERE c.viatura_id = p_viatura_id
        AND c.deleted_at IS NULL
        AND c.estado_operacional IN ('agendado', 'em_curso')
    )
    OR EXISTS (
      SELECT 1 FROM public.movimentos m
      WHERE m.viatura_id = p_viatura_id
        AND m.estado IN ('planeado', 'a_decorrer')
    )
    OR EXISTS (
      SELECT 1 FROM public.viatura_reparacoes vr
      WHERE vr.viatura_id = p_viatura_id
        AND vr.data_entrada IS NOT NULL
        AND vr.data_saida IS NULL
    )
    OR EXISTS (
      SELECT 1 FROM public.motorista_viaturas mv
      WHERE mv.viatura_id = p_viatura_id
        AND mv.status = 'ativo'
        AND mv.data_fim IS NULL
    )
  );
$$;


ALTER FUNCTION "public"."viatura_totalmente_livre"("p_viatura_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."viaturas_com_disponibilidade"("p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone, "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("viatura_id" "uuid", "disponivel" boolean, "conflitos" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH org AS (
    SELECT COALESCE(p_org_id, public.get_current_org_id()) AS org_id
  ),
  janela AS (
    SELECT tstzrange(p_data_inicio, p_data_fim, '[)') AS r
  ),
  conflitos AS (
    SELECT
      c.viatura_id,
      jsonb_build_object(
        'fonte',       'contrato',
        'fonte_id',    c.id,
        'codigo',      c.codigo,
        'data_inicio', c.data_inicio,
        'data_fim',    c.data_fim,
        'estado',      c.estado_operacional::text,
        'descricao',   'Contrato #' || c.codigo::text
      ) AS conflito
    FROM public.contratos_renting c
    CROSS JOIN org
    CROSS JOIN janela
    WHERE c.org_id = org.org_id
      AND c.viatura_id IS NOT NULL
      AND c.deleted_at IS NULL
      AND c.substituido_em IS NULL
      AND c.estado_operacional::text IN ('agendado', 'em_curso')
      AND tstzrange(c.data_inicio, c.data_fim, '[)') && janela.r

    UNION ALL

    SELECT
      r.viatura_id,
      jsonb_build_object(
        'fonte',       'reserva',
        'fonte_id',    r.id,
        'codigo',      r.codigo,
        'data_inicio', r.data_inicio,
        'data_fim',    r.data_fim,
        'estado',      r.estado::text,
        'descricao',   'Reserva #' || r.codigo::text
      )
    FROM public.reservas r
    CROSS JOIN org
    CROSS JOIN janela
    WHERE r.org_id = org.org_id
      AND r.viatura_id IS NOT NULL
      AND r.estado::text IN ('pendente', 'confirmada', 'em_curso')
      AND NOT EXISTS (
        SELECT 1 FROM public.contratos_renting c2
         WHERE c2.reserva_id = r.id
           AND c2.deleted_at IS NULL
           AND c2.substituido_em IS NULL
           AND c2.estado_operacional::text IN ('agendado', 'em_curso')
      )
      AND tstzrange(r.data_inicio, COALESCE(r.data_fim, 'infinity'::timestamptz), '[)') && janela.r

    UNION ALL

    SELECT
      m.viatura_id,
      jsonb_build_object(
        'fonte',       'movimento',
        'fonte_id',    m.id,
        'codigo',      m.codigo,
        'data_inicio', m.data_partida,
        'data_fim',    m.data_chegada,
        'estado',      m.estado::text,
        'tipo',        m.tipo::text,
        'descricao',   'Movimento #' || m.codigo::text || ' (' || m.tipo::text || ')'
      )
    FROM public.movimentos m
    CROSS JOIN org
    CROSS JOIN janela
    WHERE m.org_id = org.org_id
      AND m.viatura_id IS NOT NULL
      AND m.estado::text IN ('planeado', 'a_decorrer')
      AND m.data_partida IS NOT NULL
      AND tstzrange(
            m.data_partida,
            COALESCE(m.data_chegada, 'infinity'::timestamptz),
            '[)'
          ) && janela.r

    UNION ALL

    SELECT
      rep.viatura_id,
      jsonb_build_object(
        'fonte',       'reparacao',
        'fonte_id',    rep.id,
        'data_inicio', rep.data_entrada,
        'data_fim',    rep.data_saida,
        'descricao',   'Reparação' || COALESCE(' — ' || rep.oficina, '')
      )
    FROM public.viatura_reparacoes rep
    JOIN public.viaturas vw ON vw.id = rep.viatura_id
    CROSS JOIN org
    CROSS JOIN janela
    WHERE vw.org_id = org.org_id
      AND rep.viatura_id IS NOT NULL
      AND rep.data_entrada IS NOT NULL
      AND tstzrange(
            rep.data_entrada::timestamptz,
            COALESCE(rep.data_saida::timestamptz, 'infinity'::timestamptz),
            '[)'
          ) && janela.r
  ),
  agg AS (
    SELECT
      conflitos.viatura_id,
      jsonb_agg(conflitos.conflito ORDER BY (conflitos.conflito->>'data_inicio')) AS conflitos
    FROM conflitos
    GROUP BY conflitos.viatura_id
  )
  SELECT
    v.id                                                AS viatura_id,
    COALESCE(agg.conflitos, '[]'::jsonb) = '[]'::jsonb  AS disponivel,
    COALESCE(agg.conflitos, '[]'::jsonb)                AS conflitos
  FROM public.viaturas v
  CROSS JOIN org
  LEFT JOIN agg ON agg.viatura_id = v.id
  WHERE v.org_id = org.org_id
    AND (v.is_vendida IS NULL OR v.is_vendida = false)
    AND (v.is_slot IS NULL OR v.is_slot = false);
$$;


ALTER FUNCTION "public"."viaturas_com_disponibilidade"("p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone, "p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."viaturas_com_disponibilidade"("p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone, "p_org_id" "uuid") IS 'Disponibilidade unificada por viatura num intervalo. Exclui viaturas vendidas e viaturas slot (carros externos do motorista). Ignora versões de contrato substituídas (substituido_em).';



CREATE OR REPLACE FUNCTION "public"."vigiar_cron_edge"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_linha    record;
  v_alertas  integer := 0;
  v_job_type text;
  v_erro     text;
begin
  for v_linha in
    select l.id, l.jobname, l.url, l.request_id, l.invoked_at,
           r.id as resposta_id, r.status_code, r.error_msg,
           left(coalesce(r.content, ''), 500) as content
    from public.cron_http_log l
    left join net._http_response r on r.id = l.request_id
    where l.alertado_em is null
      and l.invoked_at < now() - interval '2 minutes'
      and l.invoked_at > now() - interval '3 hours'
    order by l.invoked_at
  loop
    if v_linha.resposta_id is null and v_linha.invoked_at > now() - interval '10 minutes' then
      continue;
    end if;

    if v_linha.resposta_id is null then
      v_erro := 'Sem resposta HTTP (timeout ou pedido perdido).';
    elsif v_linha.error_msg is not null then
      v_erro := 'Erro de rede: ' || v_linha.error_msg;
    elsif v_linha.status_code is null or v_linha.status_code >= 300 then
      v_erro := format('HTTP %s - %s',
                       coalesce(v_linha.status_code::text, '?'),
                       coalesce(nullif(v_linha.content, ''), 'sem corpo'));
    else
      update public.cron_http_log set alertado_em = now() where id = v_linha.id;
      continue;
    end if;

    -- SO FALHA SUSTENTADA. Um 502 do gateway da Supabase num drain de 5 em 5
    -- minutos resolve-se sozinho no ciclo seguinte; avisar sobre isso treina
    -- toda a gente a ignorar os emails, e entao o aviso a serio tambem passa
    -- despercebido. Se o mesmo job teve algum 2xx na ultima meia hora e tal,
    -- a falha ja passou: marca-se como vista e nao se avisa.
    --
    -- A mesma regra serve os jobs raros sem excepcao nenhuma: o
    -- bolt-weekly-enqueue so corre a segunda, portanto nao ha 2xx nenhum na
    -- janela e o aviso sai a primeira. E o que se queria nos dois casos.
    if exists (
      select 1
      from public.cron_http_log l2
      join net._http_response r2 on r2.id = l2.request_id
      where l2.jobname = v_linha.jobname
        and l2.invoked_at > now() - interval '45 minutes'
        and r2.status_code between 200 and 299
    ) then
      update public.cron_http_log set alertado_em = now() where id = v_linha.id;
      continue;
    end if;

    v_job_type := 'cron_edge:' || v_linha.jobname;

    if not exists (
      select 1 from public.failed_jobs f
      where f.job_type = v_job_type
        and f.resolved = false
        and f.failed_at > now() - interval '6 hours'
    ) then
      insert into public.failed_jobs (source_table, source_id, org_id, job_type, payload, attempts, last_error)
      values (
        'cron_http_log',
        gen_random_uuid(),
        public.org_sistema(),
        v_job_type,
        jsonb_build_object(
          'cron_http_log_id', v_linha.id,
          'jobname',          v_linha.jobname,
          'url',              v_linha.url,
          'request_id',       v_linha.request_id,
          'invoked_at',       v_linha.invoked_at,
          'status_code',      v_linha.status_code
        ),
        1,
        format('Cron "%s" falhou a invocar a edge function, e nao recuperou: %s', v_linha.jobname, v_erro)
      );
      v_alertas := v_alertas + 1;
    end if;

    update public.cron_http_log set alertado_em = now() where id = v_linha.id;
  end loop;

  return v_alertas;
end;
$$;


ALTER FUNCTION "public"."vigiar_cron_edge"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."vigiar_cron_edge"() IS 'Regista em failed_jobs as invocacoes cron->edge que falharam E nao recuperaram (sem nenhum 2xx do mesmo job nos ultimos 45 min). Ignora blips transitorios para o alerta nao virar ruido.';



CREATE OR REPLACE FUNCTION "public"."vigiar_filas_sync"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_linha   record;
  v_alertas integer := 0;
begin
  for v_linha in
    select 'bolt'::text as fila, q.id, q.org_id, q.status, q.created_at,
           q.started_at, q.periodo_inicio, q.periodo_fim, q.error_message
    from public.bolt_sync_queue q
    where q.alertado_em is null
      and (
        q.status = 'failed'
        or (q.status = 'pending' and q.created_at < now() - interval '2 hours')
        or (q.status = 'running' and q.started_at < now() - interval '1 hour')
      )
    union all
    select 'via_verde', q.id, q.org_id, q.status, q.created_at,
           q.started_at, q.periodo_inicio, q.periodo_fim, q.error_message
    from public.via_verde_sync_queue q
    where q.alertado_em is null
      and (
        q.status = 'failed'
        or (q.status = 'pending' and q.created_at < now() - interval '2 hours')
        or (q.status = 'running' and q.started_at < now() - interval '1 hour')
      )
    order by created_at
  loop
    if not exists (
      select 1 from public.failed_jobs f
      where f.job_type = 'sync_fila:' || v_linha.fila
        and f.resolved = false
        and f.failed_at > now() - interval '6 hours'
    ) then
      insert into public.failed_jobs (source_table, source_id, org_id, job_type, payload, attempts, last_error)
      values (
        v_linha.fila || '_sync_queue',
        v_linha.id,
        v_linha.org_id,
        'sync_fila:' || v_linha.fila,
        jsonb_build_object(
          'fila',           v_linha.fila,
          'queue_id',       v_linha.id,
          'status',         v_linha.status,
          'periodo_inicio', v_linha.periodo_inicio,
          'periodo_fim',    v_linha.periodo_fim,
          'created_at',     v_linha.created_at
        ),
        1,
        case v_linha.status
          when 'failed' then
            format('Sincronizacao %s falhou (%s a %s): %s',
                   v_linha.fila,
                   coalesce(v_linha.periodo_inicio::text, '?'),
                   coalesce(v_linha.periodo_fim::text, '?'),
                   coalesce(nullif(v_linha.error_message, ''), 'sem detalhe'))
          when 'running' then
            format('Sincronizacao %s encravada em execucao desde %s (%s a %s).',
                   v_linha.fila, v_linha.started_at,
                   coalesce(v_linha.periodo_inicio::text, '?'),
                   coalesce(v_linha.periodo_fim::text, '?'))
          else
            format('Sincronizacao %s na fila sem ser processada desde %s (%s a %s) - o drain esta a correr?',
                   v_linha.fila, v_linha.created_at,
                   coalesce(v_linha.periodo_inicio::text, '?'),
                   coalesce(v_linha.periodo_fim::text, '?'))
        end
      );
      v_alertas := v_alertas + 1;
    end if;

    if v_linha.fila = 'bolt' then
      update public.bolt_sync_queue set alertado_em = now() where id = v_linha.id;
    else
      update public.via_verde_sync_queue set alertado_em = now() where id = v_linha.id;
    end if;
  end loop;

  return v_alertas;
end;
$$;


ALTER FUNCTION "public"."vigiar_filas_sync"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."vigiar_filas_sync"() IS 'Regista em failed_jobs cada linha das filas de sync que falhou ou encravou. Fecha o buraco do bolt-sync-drain, que responde 200 mesmo quando todas as linhas falham.';



