CREATE OR REPLACE VIEW "public"."automacao_estatisticas_por_regra" WITH ("security_invoker"='true') AS
 SELECT "aru"."id" AS "rule_id",
    "aru"."org_id",
    "aru"."nome",
    "aru"."event_type",
    "aru"."ativo",
    "aru"."cooldown_minutos",
    "count"("al"."id") FILTER (WHERE ("al"."evento" = 'executada'::"text")) AS "execucoes",
    "count"("al"."id") FILTER (WHERE ("al"."evento" = 'falhou'::"text")) AS "falhas",
    "max"("al"."created_at") AS "ultima_execucao",
    "avg"("al"."duracao_ms") FILTER (WHERE ("al"."evento" = 'executada'::"text")) AS "duracao_media_ms"
   FROM ("public"."automation_rules" "aru"
     LEFT JOIN "public"."automation_logs" "al" ON (("al"."rule_id" = "aru"."id")))
  GROUP BY "aru"."id", "aru"."org_id", "aru"."nome", "aru"."event_type", "aru"."ativo", "aru"."cooldown_minutos";


