 SELECT "nq"."org_id",
    "nq"."canal",
    "count"(*) FILTER (WHERE (("nq"."status" = 'failed'::"text") AND ("nq"."created_at" > ("now"() - '01:00:00'::interval)))) AS "falhas_ultima_hora",
    "count"(*) FILTER (WHERE (("nq"."status" = 'sent'::"text") AND ("nq"."created_at" > ("now"() - '01:00:00'::interval)))) AS "enviados_ultima_hora",
    "avg"((EXTRACT(epoch FROM ("nd"."enviado_em" - "nq"."created_at")) * (1000)::numeric)) FILTER (WHERE (("nq"."created_at" > ("now"() - '24:00:00'::interval)) AND ("nd"."enviado_em" IS NOT NULL))) AS "tempo_resposta_medio_ms"
   FROM ("public"."notification_queue" "nq"
     LEFT JOIN "public"."notification_delivery" "nd" ON (("nd"."notification_queue_id" = "nq"."id")))
  GROUP BY "nq"."org_id", "nq"."canal";


