CREATE OR REPLACE VIEW "public"."automacao_timeline_recente" WITH ("security_invoker"='true') AS
 SELECT "de"."id" AS "event_id",
    "de"."org_id",
    "de"."event_type",
    "de"."occurred_at",
    "de"."entity_table",
    "de"."entity_id",
    "ar"."id" AS "run_id",
    "ar"."rule_id",
    "aru"."nome" AS "regra_nome",
    "ar"."status" AS "run_status",
    "ar"."started_at",
    "ar"."completed_at",
    "ar"."attempt",
    "al"."evento" AS "ultimo_evento_log",
    "al"."duracao_ms",
    "al"."detalhe"
   FROM ((("public"."domain_events" "de"
     LEFT JOIN "public"."automation_runs" "ar" ON (("ar"."trigger_event_id" = "de"."id")))
     LEFT JOIN "public"."automation_rules" "aru" ON (("aru"."id" = "ar"."rule_id")))
     LEFT JOIN LATERAL ( SELECT "l"."evento",
            "l"."duracao_ms",
            "l"."detalhe",
            "l"."created_at"
           FROM "public"."automation_logs" "l"
          WHERE ("l"."run_id" = "ar"."id")
          ORDER BY "l"."created_at" DESC
         LIMIT 1) "al" ON (true))
  ORDER BY "de"."occurred_at" DESC;


