CREATE TABLE IF NOT EXISTS "public"."contrato_cobrancas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "contrato_id" "uuid",
    "periodo_de" "date" NOT NULL,
    "periodo_ate" "date" NOT NULL,
    "descricao" "text",
    "destinatario_id" "uuid" NOT NULL,
    "destinatario_papel" "text" NOT NULL,
    "destinatario_nome" "text" NOT NULL,
    "contrato_condutor_id" "uuid",
    "tarifa_id" "uuid",
    "tarifa_nome" "text",
    "valor_sem_iva" numeric(10,2) NOT NULL,
    "taxa_iva" numeric(5,2) DEFAULT 23 NOT NULL,
    "valor_iva" numeric(10,2) GENERATED ALWAYS AS ("round"((("valor_sem_iva" * "taxa_iva") / (100)::numeric), 2)) STORED,
    "valor_total" numeric(10,2) GENERATED ALWAYS AS (("valor_sem_iva" + "round"((("valor_sem_iva" * "taxa_iva") / (100)::numeric), 2))) STORED,
    "emite_fatura_fiscal" boolean DEFAULT true NOT NULL,
    "estado" "public"."cobranca_estado_enum" DEFAULT 'pendente'::"public"."cobranca_estado_enum" NOT NULL,
    "emitida_em" timestamp with time zone,
    "documento_externo_ref" "text",
    "pago_em" timestamp with time zone,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reserva_id" "uuid",
    "manual" boolean DEFAULT false NOT NULL,
    "tipo_cobranca" "text" DEFAULT 'tvde_semanal'::"text" NOT NULL,
    "lembrete_atraso_enviado_em" timestamp with time zone,
    "responsavel_motorista_id" "uuid",
    CONSTRAINT "chk_contrato_cobrancas_alvo" CHECK ((("contrato_id" IS NOT NULL) OR ("reserva_id" IS NOT NULL))),
    CONSTRAINT "chk_contrato_cobrancas_periodo" CHECK (("periodo_ate" >= "periodo_de")),
    CONSTRAINT "contrato_cobrancas_destinatario_papel_check" CHECK (("destinatario_papel" = ANY (ARRAY['cliente'::"text", 'condutor'::"text"]))),
    CONSTRAINT "contrato_cobrancas_taxa_iva_check" CHECK ((("taxa_iva" >= (0)::numeric) AND ("taxa_iva" <= (100)::numeric))),
    CONSTRAINT "contrato_cobrancas_tipo_chk" CHECK (("tipo_cobranca" = ANY (ARRAY['tvde_semanal'::"text", 'slot_mensal'::"text"]))),
    CONSTRAINT "contrato_cobrancas_valor_sem_iva_check" CHECK (("valor_sem_iva" >= (0)::numeric))
);


ALTER TABLE "public"."contrato_cobrancas" OWNER TO "postgres";


COMMENT ON TABLE "public"."contrato_cobrancas" IS 'Linhas de faturação por período de um contrato. Destinatário (cliente ou condutor) escolhido por período. Cada linha = débito na conta-corrente do destinatário.';



COMMENT ON COLUMN "public"."contrato_cobrancas"."destinatario_papel" IS 'cliente = titular do contrato; condutor = um dos condutores. Ambos são registos de clientes.';



COMMENT ON COLUMN "public"."contrato_cobrancas"."emite_fatura_fiscal" IS 'true = gera fatura fiscal (Primavera). false = cobrança interna sem fatura (ex: motorista TVDE que paga a semana mas não recebe fatura).';



COMMENT ON COLUMN "public"."contrato_cobrancas"."manual" IS 'true = fatura adicional criada à mão ("Nova Fatura") com linhas livres. Fica fora do índice único de período (permite várias faturas por contrato).';



COMMENT ON COLUMN "public"."contrato_cobrancas"."lembrete_atraso_enviado_em" IS 'Marca quando o aviso único de atraso (>30 dias) foi enviado ao devedor. NULL = ainda não avisado.';



COMMENT ON COLUMN "public"."contrato_cobrancas"."responsavel_motorista_id" IS 'Motorista TVDE responsável pela dívida desta cobrança, cedida no momento da emissão (Nova Fatura / Faturar contrato) — NÃO é o destinatário fiscal (esse continua sempre em destinatario_id/destinatario_papel, que tem FK para clientes e é imutável por SAF-T). NULL = a dívida fica com o destinatário normal.';



CREATE TABLE IF NOT EXISTS "public"."contrato_condutores" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "contrato_id" "uuid" NOT NULL,
    "cliente_id" "uuid",
    "is_principal" boolean DEFAULT false NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "data_inicio" timestamp with time zone DEFAULT "now"() NOT NULL,
    "data_fim" timestamp with time zone,
    "motivo_fim" "text",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "vigencia" "tstzrange" GENERATED ALWAYS AS ("tstzrange"("data_inicio", "data_fim", '[)'::"text")) STORED,
    "motorista_id" "uuid",
    CONSTRAINT "chk_contrato_condutor_pessoa" CHECK (("num_nonnulls"("cliente_id", "motorista_id") = 1)),
    CONSTRAINT "chk_contrato_condutores_vigencia" CHECK ((("data_fim" IS NULL) OR ("data_fim" > "data_inicio"))),
    CONSTRAINT "contrato_condutores_xor_cliente_motorista" CHECK ((("cliente_id" IS NULL) <> ("motorista_id" IS NULL)))
);


ALTER TABLE "public"."contrato_condutores" OWNER TO "postgres";


COMMENT ON TABLE "public"."contrato_condutores" IS 'Condutores autorizados por contrato, com vigência. Permite trocar condutor sem cancelar o contrato e imputar danos a quem conduzia na data do facto.';



COMMENT ON COLUMN "public"."contrato_condutores"."data_fim" IS 'Fim da vigência do condutor. NULL = ainda vigente. Preenchido ao trocar de condutor.';



COMMENT ON COLUMN "public"."contrato_condutores"."vigencia" IS 'Coluna GENERATED — NÃO escrever manualmente. Base dos EXCLUDE de sobreposição.';



COMMENT ON COLUMN "public"."contrato_condutores"."motorista_id" IS 'Motorista parceiro (apenas TVDE). XOR com cliente_id — exactamente um dos dois é preenchido.';



