    "tarifa_id" "uuid",
    "tarifa_nome" "text",
    "cobertura_id" "uuid",
    "cobertura_nome" "text",
    "cobertura_preco_dia" numeric(10,2),
    "cobertura_franquia" numeric(10,2),
    "is_longa_duracao" boolean DEFAULT false NOT NULL,
    "regime" "public"."contrato_regime_enum" DEFAULT 'rent_a_car'::"public"."contrato_regime_enum" NOT NULL,
    "transferista_id" "uuid",
    "versao" integer DEFAULT 1 NOT NULL,
    "contrato_anterior_id" "uuid",
    "substituido_em" timestamp with time zone,
    "motivo_versao" "text",
    "emissor_id" "uuid",
    "gestor_id" "uuid" DEFAULT "auth"."uid"(),
    "km_saida" integer,
    "km_entrada" integer,
    "combustivel_saida" "text",
    "combustivel_entrada" "text",
    "eletricidade_saida" "text",
    "eletricidade_entrada" "text",
    "dua_original_com_motorista" boolean DEFAULT false NOT NULL,
    "dua_devolvida_em" timestamp with time zone,
    "dua_observacoes" "text",
    "entrega_via_any_rent" boolean DEFAULT false NOT NULL,
    "cidade_assinatura" "text",
    "tipo_fecho" "text",
    CONSTRAINT "chk_contratos_desconto_valido" CHECK ((("desconto_percentagem" IS NULL) OR (("desconto_percentagem" >= (0)::numeric) AND ("desconto_percentagem" <= (100)::numeric)))),
    CONSTRAINT "chk_contratos_iva_valido" CHECK ((("taxa_iva" >= (0)::numeric) AND ("taxa_iva" <= (100)::numeric))),
    CONSTRAINT "chk_contratos_kms_incluidos_nao_negativos" CHECK ((("kms_incluidos" IS NULL) OR ("kms_incluidos" >= 0))),
    CONSTRAINT "chk_contratos_periodo_valido" CHECK ((("data_fim" IS NULL) OR ("data_fim" > "data_inicio"))),
    CONSTRAINT "chk_contratos_renovacao_coerente" CHECK (((NOT "aluguer_longa_duracao") OR ("renovacao_opcao" IS NOT NULL))),
    CONSTRAINT "chk_contratos_renovacao_intervalo_obrigatorio" CHECK ((("renovacao_opcao" IS DISTINCT FROM 'intervalo_dias'::"public"."contrato_renovacao_opcao_enum") OR ("renovacao_intervalo_dias" IS NOT NULL))),
    CONSTRAINT "chk_contratos_renovacao_intervalo_positivo" CHECK ((("renovacao_intervalo_dias" IS NULL) OR ("renovacao_intervalo_dias" > 0))),
    CONSTRAINT "chk_contratos_snapshot_totais_validos" CHECK (((("total_subtotal" IS NULL) OR ("total_subtotal" >= (0)::numeric)) AND (("total_iva" IS NULL) OR ("total_iva" >= (0)::numeric)) AND (("total_final" IS NULL) OR ("total_final" >= (0)::numeric)))),
    CONSTRAINT "chk_contratos_tarifa_diaria_valida" CHECK ((("tarifa_diaria" IS NULL) OR ("tarifa_diaria" >= (0)::numeric))),
    CONSTRAINT "chk_contratos_totais_facturados" CHECK ((("estado_financeiro" <> 'facturado'::"public"."contrato_estado_financeiro_enum") OR (("total_final" IS NOT NULL) AND ("facturado_em" IS NOT NULL)))),
    CONSTRAINT "chk_contratos_valor_total_manual_valido" CHECK ((("valor_total_manual" IS NULL) OR ("valor_total_manual" >= (0)::numeric))),
    CONSTRAINT "chk_contratos_valores_financeiros_validos" CHECK (((("franquia_valor" IS NULL) OR ("franquia_valor" >= (0)::numeric)) AND (("caucao_valor" IS NULL) OR ("caucao_valor" >= (0)::numeric)) AND (("km_adicional_valor" IS NULL) OR ("km_adicional_valor" >= (0)::numeric)))),
    CONSTRAINT "contratos_intervalo_dias_coerente" CHECK ((("renovacao_intervalo_dias" IS NULL) OR (("renovacao_opcao" = 'intervalo_dias'::"public"."contrato_renovacao_opcao_enum") AND ("renovacao_intervalo_dias" > 0)))),
    CONSTRAINT "contratos_kms_incluidos_nao_negativos" CHECK ((("kms_incluidos" IS NULL) OR ("kms_incluidos" >= 0))),
    CONSTRAINT "contratos_renovacao_requer_longa_duracao" CHECK ((("renovacao_opcao" IS NULL) OR ("is_longa_duracao" = true))),
    CONSTRAINT "contratos_renting_tipo_fecho_check" CHECK ((("tipo_fecho" IS NULL) OR ("tipo_fecho" = ANY (ARRAY['recolhido'::"text", 'devolvido'::"text"])))),
    CONSTRAINT "contratos_valores_nao_negativos" CHECK (((("franquia_valor" IS NULL) OR ("franquia_valor" >= (0)::numeric)) AND (("caucao_valor" IS NULL) OR ("caucao_valor" >= (0)::numeric)) AND (("km_adicional_valor" IS NULL) OR ("km_adicional_valor" >= (0)::numeric))))
);


ALTER TABLE "public"."contratos_renting" OWNER TO "postgres";


COMMENT ON TABLE "public"."contratos_renting" IS 'Tabela unificada de contratos. Suporta ambos os regimes via coluna `regime`: "rent_a_car" e "tvde". O nome histórico "renting" mantém-se enquanto a tabela `contratos` legacy continuar em uso (fluxo TVDE antigo via gerar_contrato_atomico). Quando o legacy for descontinuado, renomear para `contratos` simples.';



COMMENT ON COLUMN "public"."contratos_renting"."reserva_id" IS 'FK opcional à reserva de origem. UNIQUE — 1 reserva = 1 contrato. NULL para walk-ins.';



COMMENT ON COLUMN "public"."contratos_renting"."matricula" IS 'Snapshot da matrícula no momento do contrato. Viatura pode mudar matrícula (legalmente raro mas possível).';



COMMENT ON COLUMN "public"."contratos_renting"."data_fim" IS 'Fim do contrato. NULL = contrato aberto/recorrente (típico tvde). Quando NULL, a coluna gerada `periodo` fica com limite superior infinito.';



COMMENT ON COLUMN "public"."contratos_renting"."estado_operacional" IS 'Ciclo físico: agendado → em_curso → devolvido. cancelado é terminal.';



COMMENT ON COLUMN "public"."contratos_renting"."estado_financeiro" IS 'Ciclo de facturação: pendente → facturado → pago. anulado retorna a fluxo.';



COMMENT ON COLUMN "public"."contratos_renting"."total_final" IS 'Snapshot do total facturado. NULL enquanto estado_financeiro=pendente. Congelado quando muda para facturado (compliance SAF-T — não altera retroactivamente).';



COMMENT ON COLUMN "public"."contratos_renting"."periodo" IS 'Coluna GENERATED ALWAYS — NÃO escrever manualmente. Base do EXCLUDE anti-overbooking.';



COMMENT ON COLUMN "public"."contratos_renting"."aluguer_longa_duracao" IS 'ALD: true quando contrato representa aluguer longa duração com renovação periódica. Copiado da reserva.';



COMMENT ON COLUMN "public"."contratos_renting"."renovacao_opcao" IS 'Periodicidade da renovação. Só válido quando is_longa_duracao = true.';



COMMENT ON COLUMN "public"."contratos_renting"."renovacao_intervalo_dias" IS 'Nº de dias entre renovações. Só preenchido quando renovacao_opcao = intervalo_dias.';



COMMENT ON COLUMN "public"."contratos_renting"."franquia_valor" IS 'Valor da franquia em caso de dano. Copiado da reserva como ponto de partida; pode ser editado no contrato.';



COMMENT ON COLUMN "public"."contratos_renting"."caucao_valor" IS 'Valor da caução pré-autorizada no cartão. Copiado da reserva.';



COMMENT ON COLUMN "public"."contratos_renting"."kms_incluidos" IS 'Nº de kms incluídos no contrato. NULL = ilimitado.';



COMMENT ON COLUMN "public"."contratos_renting"."km_adicional_valor" IS 'Custo por km acima de kms_incluidos (€/km).';



COMMENT ON COLUMN "public"."contratos_renting"."observacoes_internas" IS 'Notas internas — não aparecem em documentos do cliente.';



COMMENT ON COLUMN "public"."contratos_renting"."grupo_id" IS 'Grupo de viatura do contrato. FK para renting_grupos.';



COMMENT ON COLUMN "public"."contratos_renting"."grupo_nome" IS 'Snapshot do nome do grupo no momento do contrato — imutável para efeitos fiscais.';



COMMENT ON COLUMN "public"."contratos_renting"."tarifa_id" IS 'Tarifa aplicada no contrato. FK para renting_tarifas.';



COMMENT ON COLUMN "public"."contratos_renting"."tarifa_nome" IS 'Snapshot do nome da tarifa no momento do contrato — imutável para efeitos fiscais.';



COMMENT ON COLUMN "public"."contratos_renting"."is_longa_duracao" IS 'true = contrato de aluguer de longa duração com renovação periódica.';



COMMENT ON COLUMN "public"."contratos_renting"."regime" IS 'rent_a_car = tarifa diária/mensal, período fixo. tvde = tarifa semanal, contrato aberto/recorrente. Escolhe a coluna de preço da tarifa.';



COMMENT ON COLUMN "public"."contratos_renting"."transferista_id" IS 'Colaborador interno responsável pela entrega e recolha física da viatura. FK para profiles. Obrigatório no novo fluxo de criação (validado pelo schema Zod no client).';



COMMENT ON COLUMN "public"."contratos_renting"."versao" IS 'Número da versão. Começa em 1. Incrementa em cada upgrade/downgrade.';



COMMENT ON COLUMN "public"."contratos_renting"."contrato_anterior_id" IS 'FK self-referencial para a versão anterior. NULL na versão original.';



COMMENT ON COLUMN "public"."contratos_renting"."substituido_em" IS 'NULL = versão actual. NOT NULL = foi substituído nesta data por uma nova versão.';



COMMENT ON COLUMN "public"."contratos_renting"."motivo_versao" IS 'Razão da nova versão (ex. "upgrade Compact → Premium", "mudança de regime").';



COMMENT ON COLUMN "public"."contratos_renting"."emissor_id" IS 'Empresa emissora (clientes.id com tipo_cliente=''empresa''). Herdado da reserva na conversão; os documentos usam os templates desta empresa.';



COMMENT ON COLUMN "public"."contratos_renting"."gestor_id" IS 'Gestor responsável (profiles.id). Default = quem criou. Base da privacidade por gestor.';



COMMENT ON COLUMN "public"."contratos_renting"."eletricidade_saida" IS 'Nível de bateria (%) na entrega, para viaturas elétricas/híbridas. Paralelo a combustivel_saida.';



COMMENT ON COLUMN "public"."contratos_renting"."eletricidade_entrada" IS 'Nível de bateria (%) na recolha, para viaturas elétricas/híbridas. Paralelo a combustivel_entrada.';



COMMENT ON COLUMN "public"."contratos_renting"."dua_original_com_motorista" IS 'true = o motorista levou a DUA ORIGINAL (física) da viatura. Aviso de devolução ativo enquanto dua_devolvida_em IS NULL.';



COMMENT ON COLUMN "public"."contratos_renting"."dua_devolvida_em" IS 'Quando a DUA original foi devolvida. Escrito só no fecho do contrato (FecharContratoDialog), não no formulário.';



COMMENT ON COLUMN "public"."contratos_renting"."dua_observacoes" IS 'Nota livre sobre a DUA original que o motorista levou (opcional).';



COMMENT ON COLUMN "public"."contratos_renting"."entrega_via_any_rent" IS 'true quando a entrega foi marcada via o atalho "Any Rent" (sem check-in) — usado para restringir o preenchimento manual de km/combustível/bateria de saída só a estes contratos.';



COMMENT ON COLUMN "public"."contratos_renting"."cidade_assinatura" IS 'Cidade de assinatura vigente deste contrato. Gravada por ContratoDocumentosDialog apos cada geracao bem-sucedida; lida por ele proprio e por FecharContratoDialog (Folha de Danos) para nao voltar a perguntar. NULL ate a primeira geracao.';



COMMENT ON COLUMN "public"."contratos_renting"."tipo_fecho" IS 'Como o contrato acabou: "devolvido" (o motorista trouxe a viatura, fim normal) ou "recolhido" (não a entregou e a empresa foi buscá-la — há conflito e quase sempre dívida). NULL = contrato ainda não fechado, ou fechado antes desta coluna existir. Escrito por useFecharContrato; NUNCA transita para a versão seguinte numa troca de viatura.';



CREATE OR REPLACE VIEW "public"."contrato_renting_totais" WITH ("security_invoker"='true') AS
 WITH "cob" AS (
         SELECT "contrato_coberturas"."contrato_id",
            COALESCE("sum"("contrato_coberturas"."preco_dia"), (0)::numeric) AS "cob_preco_dia"
           FROM "public"."contrato_coberturas"
          GROUP BY "contrato_coberturas"."contrato_id"
        ), "ext" AS (
         SELECT "ce"."contrato_id",
            COALESCE("sum"(
                CASE
                    WHEN ("ce"."tipo_calculo" = 'fixo'::"text") THEN ("ce"."preco_unidade" * ("ce"."quantidade")::numeric)
                    ELSE (("ce"."preco_unidade" * ("ce"."quantidade")::numeric) * ("public"."fn_contrato_dias"("c"."data_inicio", "c"."data_fim"))::numeric)
                END), (0)::numeric) AS "extra_custo"
           FROM ("public"."contrato_extras" "ce"
             JOIN "public"."contratos_renting" "c" ON (("c"."id" = "ce"."contrato_id")))
          GROUP BY "ce"."contrato_id"
        ), "base" AS (
         SELECT "c"."id" AS "contrato_id",
            "c"."estado_financeiro",
            "c"."regime",
            "public"."fn_contrato_dias"("c"."data_inicio", "c"."data_fim") AS "dias",
            (COALESCE("cob"."cob_preco_dia", (0)::numeric) * ("public"."fn_contrato_dias"("c"."data_inicio", "c"."data_fim"))::numeric) AS "cobertura_custo",
            COALESCE("ext"."extra_custo", (0)::numeric) AS "extra_custo",
            COALESCE("c"."taxa_iva", (0)::numeric) AS "taxa_iva",
            "c"."total_subtotal" AS "snap_subtotal",
            "c"."total_iva" AS "snap_iva",
            "c"."total_final" AS "snap_final",
            "c"."facturado_em",
            "round"((((COALESCE("c"."valor_total_manual", (COALESCE("c"."tarifa_diaria", (0)::numeric) * ("public"."fn_contrato_dias"("c"."data_inicio", "c"."data_fim"))::numeric)) + (COALESCE("cob"."cob_preco_dia", (0)::numeric) * ("public"."fn_contrato_dias"("c"."data_inicio", "c"."data_fim"))::numeric)) + COALESCE("ext"."extra_custo", (0)::numeric)) * ((1)::numeric - (COALESCE("c"."desconto_percentagem", (0)::numeric) / (100)::numeric))), 2) AS "subtotal_bruto_desc"
           FROM (("public"."contratos_renting" "c"
             LEFT JOIN "cob" ON (("cob"."contrato_id" = "c"."id")))
             LEFT JOIN "ext" ON (("ext"."contrato_id" = "c"."id")))
          WHERE ("c"."deleted_at" IS NULL)
        ), "decomp" AS (
         SELECT "b"."contrato_id",
            "b"."estado_financeiro",
            "b"."regime",
            "b"."dias",
            "b"."cobertura_custo",
            "b"."extra_custo",
            "b"."taxa_iva",
            "b"."snap_subtotal",
            "b"."snap_iva",
            "b"."snap_final",
            "b"."facturado_em",
            "b"."subtotal_bruto_desc",
                CASE
                    WHEN ("b"."regime" = 'rent_a_car'::"public"."contrato_regime_enum") THEN "b"."subtotal_bruto_desc"
                    WHEN ("b"."taxa_iva" > (0)::numeric) THEN "round"(("b"."subtotal_bruto_desc" / ((1)::numeric + ("b"."taxa_iva" / (100)::numeric))), 2)
                    ELSE "b"."subtotal_bruto_desc"
                END AS "subtotal_calc",
                CASE
                    WHEN (("b"."regime" = 'rent_a_car'::"public"."contrato_regime_enum") AND ("b"."taxa_iva" > (0)::numeric)) THEN "round"(("b"."subtotal_bruto_desc" * ((1)::numeric + ("b"."taxa_iva" / (100)::numeric))), 2)
                    ELSE "b"."subtotal_bruto_desc"
                END AS "total_com_iva"
           FROM "base" "b"
        ), "tax" AS (
         SELECT "ct"."contrato_id",
            COALESCE("sum"(
                CASE
                    WHEN ("ct"."percentagem" IS NOT NULL) THEN "round"((("d_1"."total_com_iva" * "ct"."percentagem") / (100)::numeric), 2)
                    ELSE COALESCE("ct"."valor_fixo", (0)::numeric)
                END), (0)::numeric) AS "taxa_custo"
           FROM ("public"."contrato_taxas" "ct"
             JOIN "decomp" "d_1" ON (("d_1"."contrato_id" = "ct"."contrato_id")))
          GROUP BY "ct"."contrato_id"
        )
 SELECT "d"."contrato_id",
    "d"."dias",
    "d"."estado_financeiro",
    "d"."cobertura_custo",
    "d"."extra_custo",
    COALESCE("t"."taxa_custo", (0)::numeric) AS "taxa_custo",
        CASE
            WHEN (("d"."estado_financeiro" = 'facturado'::"public"."contrato_estado_financeiro_enum") AND ("d"."snap_subtotal" IS NOT NULL)) THEN "d"."snap_subtotal"
            ELSE "d"."subtotal_calc"
        END AS "subtotal",
        CASE
            WHEN (("d"."estado_financeiro" = 'facturado'::"public"."contrato_estado_financeiro_enum") AND ("d"."snap_iva" IS NOT NULL)) THEN "d"."snap_iva"
            ELSE "round"(("d"."total_com_iva" - "d"."subtotal_calc"), 2)
        END AS "iva",
        CASE
            WHEN (("d"."estado_financeiro" = 'facturado'::"public"."contrato_estado_financeiro_enum") AND ("d"."snap_final" IS NOT NULL)) THEN "d"."snap_final"
            ELSE "round"(("d"."total_com_iva" + COALESCE("t"."taxa_custo", (0)::numeric)), 2)
        END AS "total",
    "d"."facturado_em",
    (("d"."estado_financeiro" = 'facturado'::"public"."contrato_estado_financeiro_enum") AND ("d"."snap_final" IS NOT NULL)) AS "is_snapshot"
   FROM ("decomp" "d"
     LEFT JOIN "tax" "t" ON (("t"."contrato_id" = "d"."contrato_id")));


ALTER VIEW "public"."contrato_renting_totais" OWNER TO "postgres";


COMMENT ON VIEW "public"."contrato_renting_totais" IS 'Totais do contrato (coberturas + extras + taxas). Rent-a-Car: o preço da tarifa é SEM IVA — soma-se por cima. TVDE/slot: o preço já vem com IVA incluído — decompõe-se (divide), nunca soma. Snapshot quando facturado. RLS via underlying table contratos_renting.';



