ALTER TABLE "public"."cron_http_log" OWNER TO "postgres";


COMMENT ON TABLE "public"."cron_http_log" IS 'Request_id de cada invocacao de edge function por cron, para correlacionar com net._http_response. Sem isto, cron.job_run_details reporta sucesso mesmo quando a funcao falha (ver migracao 20260729170000).';



CREATE OR REPLACE VIEW "public"."cron_edge_health" WITH ("security_invoker"='true') AS
 SELECT "l"."jobname",
    "l"."invoked_at",
    "l"."url",
    "r"."status_code",
    "r"."timed_out",
    "r"."error_msg",
        CASE
            WHEN ("r"."id" IS NULL) THEN 'sem resposta registada'::"text"
            WHEN "r"."timed_out" THEN 'TIMEOUT'::"text"
            WHEN (("r"."status_code" >= 200) AND ("r"."status_code" <= 299)) THEN 'ok'::"text"
            ELSE ('ERRO HTTP '::"text" || ("r"."status_code")::"text")
        END AS "resultado"
   FROM ("public"."cron_http_log" "l"
     LEFT JOIN "net"."_http_response" "r" ON (("r"."id" = "l"."request_id")))
  ORDER BY "l"."invoked_at" DESC;


ALTER VIEW "public"."cron_edge_health" OWNER TO "postgres";


