COMMENT ON COLUMN "public"."motorista_financeiro"."cobranca_id" IS 'Cobrança que originou este movimento, quando a dívida foi cedida ao motorista na emissão (cobranca_ceder_a_motorista). Junto com acordo_id marca os movimentos geridos pela faturação — a UI não deixa marcá-los como pagos, cancelá-los nem editá-los à mão.';



CREATE TABLE IF NOT EXISTS "public"."motorista_financeiro_recorrencias" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" DEFAULT "public"."get_current_org_id"() NOT NULL,
    "motorista_id" "uuid" NOT NULL,
    "tipo" "text" NOT NULL,
    "categoria" "text",
    "descricao" "text" NOT NULL,
    "valor" numeric NOT NULL,
    "frequencia" "text" NOT NULL,
    "semana_ancora" "date" NOT NULL,
    "data_fim" "date",
    "max_ocorrencias" integer,
    "ocorrencias_geradas" integer DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'ativa'::"text" NOT NULL,
    "referencia_base" "text",
    "criado_por" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "motorista_financeiro_recorrencias_frequencia_check" CHECK (("frequencia" = ANY (ARRAY['semanal'::"text", 'mensal'::"text"]))),
    CONSTRAINT "motorista_financeiro_recorrencias_max_ocorrencias_check" CHECK ((("max_ocorrencias" IS NULL) OR ("max_ocorrencias" > 0))),
    CONSTRAINT "motorista_financeiro_recorrencias_status_check" CHECK (("status" = ANY (ARRAY['ativa'::"text", 'pausada'::"text", 'cancelada'::"text", 'concluida'::"text"]))),
    CONSTRAINT "motorista_financeiro_recorrencias_tipo_check" CHECK (("tipo" = ANY (ARRAY['credito'::"text", 'debito'::"text"]))),
    CONSTRAINT "motorista_financeiro_recorrencias_valor_check" CHECK (("valor" > (0)::numeric))
);


ALTER TABLE "public"."motorista_financeiro_recorrencias" OWNER TO "postgres";


COMMENT ON TABLE "public"."motorista_financeiro_recorrencias" IS 'Regras de lançamento recorrente (semanal ou mensal) no financeiro do motorista. O cron gerar_movimentos_recorrentes lê estas regras e cria as linhas em motorista_financeiro.';



COMMENT ON COLUMN "public"."motorista_financeiro_recorrencias"."semana_ancora" IS 'Segunda-feira da 1ª semana. Para frequência mensal, determina a semana do mês (1ª..5ª) em que repete todos os meses; meses sem essa semana (ex.: 5ª) não geram ocorrência.';



COMMENT ON COLUMN "public"."motorista_financeiro_recorrencias"."status" IS 'ativa = gera normalmente; pausada = suspensa manualmente; cancelada = terminada manualmente; concluida = atingiu max_ocorrencias ou data_fim.';



