    "slot_valor_semanal" numeric,
    "gestor_responsavel" "text",
    "cartao_bp" "text",
    "cartao_repsol" "text",
    "cartao_edp" "text",
    "carta_conducao_verso_url" "text",
    "documento_identificacao_verso_url" "text",
    "documento_ficheiro_url" "text",
