    "iban" "text",
    "org_id" "uuid" DEFAULT "public"."get_current_org_id"(),
    "data_renovacao_contratacao" "date",
    "perfil_rascunho" boolean DEFAULT false NOT NULL,
    "cliente_id" "uuid",
    "seguro_valor_semanal" numeric,
    "caucao_valor" numeric(10,2),
