CREATE TABLE IF NOT EXISTS "public"."movimentos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "codigo" integer NOT NULL,
    "org_id" "uuid" DEFAULT "public"."get_current_org_id"() NOT NULL,
    "tipo" "text" NOT NULL,
    "estado" "text" DEFAULT 'a_decorrer'::"text" NOT NULL,
    "viatura_id" "uuid",
    "matricula" "text",
    "estacao_origem_id" "uuid",
    "estacao_destino_id" "uuid",
    "data_partida" timestamp with time zone,
    "data_chegada" timestamp with time zone,
    "colaborador_id" "uuid",
    "colaborador_nome" "text",
    "km_inicial" integer,
    "km_final" integer,
    "combustivel_inicial" smallint,
    "combustivel_final" smallint,
    "motivo" "text",
    "prestador" "text",
    "custo_estimado" numeric(10,2),
    "custo_final" numeric(10,2),
    "info" "text",
    "observacoes" "text",
    "observacoes_internas" "text",
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "eletricidade_inicial" "text",
    "eletricidade_final" "text",
    "gpl_inicial" "text",
    "gpl_final" "text",
    CONSTRAINT "movimentos_chegada_coerente" CHECK ((("data_chegada" IS NULL) OR ("data_partida" IS NULL) OR ("data_chegada" >= "data_partida"))),
    CONSTRAINT "movimentos_combustivel_final_check" CHECK ((("combustivel_final" IS NULL) OR (("combustivel_final" >= 0) AND ("combustivel_final" <= 8)))),
    CONSTRAINT "movimentos_combustivel_inicial_check" CHECK ((("combustivel_inicial" IS NULL) OR (("combustivel_inicial" >= 0) AND ("combustivel_inicial" <= 8)))),
    CONSTRAINT "movimentos_custo_estimado_check" CHECK ((("custo_estimado" IS NULL) OR ("custo_estimado" >= (0)::numeric))),
    CONSTRAINT "movimentos_custo_final_check" CHECK ((("custo_final" IS NULL) OR ("custo_final" >= (0)::numeric))),
    CONSTRAINT "movimentos_estado_check" CHECK (("estado" = ANY (ARRAY['planeado'::"text", 'a_decorrer'::"text", 'concluido'::"text", 'cancelado'::"text"]))),
    CONSTRAINT "movimentos_km_coerente" CHECK ((("km_final" IS NULL) OR ("km_inicial" IS NULL) OR ("km_final" >= "km_inicial"))),
