ALTER TABLE "public"."renting_tarifa_precos_modelo" OWNER TO "postgres";


COMMENT ON TABLE "public"."renting_tarifa_precos_modelo" IS 'Preço semanal por modelo de viatura, específico de uma tarifa TVDE (renting_tarifas.tipo = tvde). Ao criar contrato/reserva TVDE, o preço aplicado é o da linha (tarifa, modelo da viatura).';



COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."preco_semana" IS 'Preço por semana (€) para este modelo nesta tarifa TVDE.';



COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."km_mensal" IS 'Km incluídos por mês para este modelo nesta tarifa TVDE. NULL = não definido.';



