COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."franquia_valor" IS 'Franquia (€) aplicável a este modelo nesta tarifa TVDE.';



COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."preco_dia" IS 'Diária s/IVA para este modelo nesta tarifa Rent-a-Car. NULL = não definido.';



COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."preco_mes" IS 'Mensal s/IVA para este modelo nesta tarifa Rent-a-Car. NULL = não definido.';



COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."km_adicional_valor_iva" IS 'Custo (€) por km extra c/IVA para este modelo nesta tarifa Rent-a-Car.';



COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."franquia_valor_iva" IS 'Franquia (€) c/IVA aplicável a este modelo nesta tarifa Rent-a-Car.';



COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."km_mensal_iva" IS 'Km incluídos por mês para este modelo nesta tarifa Rent-a-Car. Separado do km_mensal (TVDE).';



COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."caucao_valor" IS 'Caução (€) para este modelo nesta tarifa TVDE.';



COMMENT ON COLUMN "public"."renting_tarifa_precos_modelo"."caucao_valor_iva" IS 'Caução (€) para este modelo nesta tarifa Rent-a-Car.';



CREATE TABLE IF NOT EXISTS "public"."renting_tarifas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "org_id" "uuid" NOT NULL,
    "grupo_id" "uuid",
    "nome" "text" NOT NULL,
    "preco_dia" numeric(10,2),
    "preco_fim_semana" numeric(10,2),
    "preco_semana" numeric(10,2),
    "preco_mes" numeric(10,2),
    "kms_incluidos" integer,
    "km_adicional_valor" numeric(10,4),
    "valido_de" "date",
    "valido_ate" "date",
    "ativa" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tipo" "text" DEFAULT 'renting'::"text" NOT NULL,
    "reserva_min_minutos" integer,
    "reserva_max_minutos" integer,
    CONSTRAINT "renting_tarifas_km_adicional_valor_check" CHECK (("km_adicional_valor" >= (0)::numeric)),
    CONSTRAINT "renting_tarifas_kms_incluidos_check" CHECK (("kms_incluidos" >= 0)),
    CONSTRAINT "renting_tarifas_periodo_valido" CHECK ((("valido_de" IS NULL) OR ("valido_ate" IS NULL) OR ("valido_ate" >= "valido_de"))),
    CONSTRAINT "renting_tarifas_preco_dia_check" CHECK (("preco_dia" >= (0)::numeric)),
    CONSTRAINT "renting_tarifas_preco_fim_semana_check" CHECK (("preco_fim_semana" >= (0)::numeric)),
    CONSTRAINT "renting_tarifas_preco_mes_check" CHECK (("preco_mes" >= (0)::numeric)),
    CONSTRAINT "renting_tarifas_preco_semana_check" CHECK (("preco_semana" >= (0)::numeric)),
    CONSTRAINT "renting_tarifas_reserva_max_minutos_check" CHECK ((("reserva_max_minutos" IS NULL) OR ("reserva_max_minutos" >= 0))),
    CONSTRAINT "renting_tarifas_reserva_min_minutos_check" CHECK ((("reserva_min_minutos" IS NULL) OR ("reserva_min_minutos" >= 0))),
    CONSTRAINT "renting_tarifas_tipo_check" CHECK (("tipo" = ANY (ARRAY['renting'::"text", 'tvde'::"text"])))
);


ALTER TABLE "public"."renting_tarifas" OWNER TO "postgres";


COMMENT ON TABLE "public"."renting_tarifas" IS 'Tarifas de aluguer por grupo de viatura. Suporta sazonalidade via valido_de/valido_ate.';



COMMENT ON COLUMN "public"."renting_tarifas"."preco_dia" IS 'Preço base por dia (€). Obrigatório.';



COMMENT ON COLUMN "public"."renting_tarifas"."preco_fim_semana" IS 'Preço por dia aplicado ao fim de semana. NULL = usa preco_dia.';



COMMENT ON COLUMN "public"."renting_tarifas"."preco_semana" IS 'Preço por semana completa (7 dias). NULL = 7 × preco_dia.';



COMMENT ON COLUMN "public"."renting_tarifas"."preco_mes" IS 'Preço por mês completo (30 dias). NULL = 30 × preco_dia.';



COMMENT ON COLUMN "public"."renting_tarifas"."kms_incluidos" IS 'Km incluídos no aluguer. NULL = ilimitado.';



COMMENT ON COLUMN "public"."renting_tarifas"."valido_de" IS 'Início do período de validade (sazonalidade). NULL = sem limite de início.';



COMMENT ON COLUMN "public"."renting_tarifas"."valido_ate" IS 'Fim do período de validade (sazonalidade). NULL = sem limite de fim.';



COMMENT ON COLUMN "public"."renting_tarifas"."tipo" IS 'Regime da tarifa: renting (rent-a-car) ou tvde. Tarifas tvde só ficam disponíveis em contratos/reservas TVDE e usam preço por modelo (renting_tarifa_precos_modelo).';



COMMENT ON COLUMN "public"."renting_tarifas"."reserva_min_minutos" IS 'Tempo mínimo de reserva (min) para esta tarifa. NULL = herda do grupo.';



COMMENT ON COLUMN "public"."renting_tarifas"."reserva_max_minutos" IS 'Tempo máximo de reserva (min) para esta tarifa. NULL = herda do grupo.';



