COMMENT ON COLUMN "public"."via_verde_transacoes"."imputado_motorista_id" IS 'Rent-a-car: condutor a quem se decidiu imputar a portagem, em vez do cliente.';



CREATE OR REPLACE VIEW "public"."v_atraso_das_fontes" AS
 WITH "fontes" AS (
         SELECT 'via_verde'::"text" AS "fonte",
            "via_verde_transacoes"."org_id",
            ("max"("via_verde_transacoes"."transaction_date"))::"date" AS "ultimo_dado"
           FROM "public"."via_verde_transacoes"
          GROUP BY "via_verde_transacoes"."org_id"
        UNION ALL
         SELECT 'repsol'::"text",
            "repsol_transacoes"."org_id",
            ("max"("repsol_transacoes"."transaction_date"))::"date" AS "max"
           FROM "public"."repsol_transacoes"
          GROUP BY "repsol_transacoes"."org_id"
        UNION ALL
         SELECT 'edp'::"text",
            "edp_transacoes"."org_id",
            ("max"("edp_transacoes"."transaction_date"))::"date" AS "max"
           FROM "public"."edp_transacoes"
          GROUP BY "edp_transacoes"."org_id"
        UNION ALL
         SELECT 'bp'::"text",
            "bp_transacoes"."org_id",
            ("max"("bp_transacoes"."transaction_date"))::"date" AS "max"
           FROM "public"."bp_transacoes"
          GROUP BY "bp_transacoes"."org_id"
        UNION ALL
         SELECT 'bolt'::"text",
            "bolt_resumos_semanais"."org_id",
            "max"("bolt_resumos_semanais"."periodo_fim") AS "max"
           FROM "public"."bolt_resumos_semanais"
          GROUP BY "bolt_resumos_semanais"."org_id"
        UNION ALL
         SELECT 'uber'::"text",
            "uber_resumos_semanais"."org_id",
            "max"("uber_resumos_semanais"."periodo_fim") AS "max"
           FROM "public"."uber_resumos_semanais"
          GROUP BY "uber_resumos_semanais"."org_id"
        )
 SELECT "f"."fonte",
    "o"."nome" AS "organizacao",
    "f"."org_id",
    "f"."ultimo_dado",
    (CURRENT_DATE - "f"."ultimo_dado") AS "dias_de_atraso",
        CASE
            WHEN ("f"."fonte" = ANY (ARRAY['bolt'::"text", 'uber'::"text"])) THEN ((CURRENT_DATE - "f"."ultimo_dado") > 10)
            ELSE ((CURRENT_DATE - "f"."ultimo_dado") > 2)
        END AS "atrasada"
   FROM ("fontes" "f"
     LEFT JOIN "public"."organizacoes" "o" ON (("o"."id" = "f"."org_id")))
  ORDER BY (CURRENT_DATE - "f"."ultimo_dado") DESC;


ALTER VIEW "public"."v_atraso_das_fontes" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_atraso_das_fontes" IS 'Dias de atraso de cada fonte de dados por organização. Serve para apanhar paragens silenciosas — o sintoma é sempre o mesmo, seja qual for a causa.';



CREATE TABLE IF NOT EXISTS "public"."via_verde_contas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "integracao_id" "uuid" NOT NULL,
    "nome_conta" "text" NOT NULL,
    "codigo_rac" "text" NOT NULL,
    "ftp_host" "text" NOT NULL,
    "ftp_porta" integer DEFAULT 21 NOT NULL,
    "ftp_protocolo" "text" DEFAULT 'ftp'::"text" NOT NULL,
    "ftp_modo_passivo" boolean DEFAULT true NOT NULL,
    "ftp_utilizador" "text" NOT NULL,
    "ftp_password" "text" NOT NULL,
    "ftp_ativo" boolean DEFAULT true NOT NULL,
    "sync_email" "text" NOT NULL,
    "sync_password" "text" NOT NULL,
    "sync_ativo" boolean DEFAULT true NOT NULL,
    "criado_por" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "logo_url" "text",
    "org_id" "uuid" DEFAULT "public"."get_current_org_id"(),
    CONSTRAINT "via_verde_contas_codigo_rac_len_check" CHECK ((("char_length"(TRIM(BOTH FROM "codigo_rac")) >= 1) AND ("char_length"(TRIM(BOTH FROM "codigo_rac")) <= 60))),
    CONSTRAINT "via_verde_contas_ftp_host_len_check" CHECK ((("char_length"(TRIM(BOTH FROM "ftp_host")) >= 0) AND ("char_length"(TRIM(BOTH FROM "ftp_host")) <= 255))),
    CONSTRAINT "via_verde_contas_ftp_porta_check" CHECK ((("ftp_porta" >= 1) AND ("ftp_porta" <= 65535))),
    CONSTRAINT "via_verde_contas_ftp_protocolo_check" CHECK (("ftp_protocolo" = ANY (ARRAY['ftp'::"text", 'sftp'::"text"]))),
    CONSTRAINT "via_verde_contas_ftp_user_len_check" CHECK ((("char_length"(TRIM(BOTH FROM "ftp_utilizador")) >= 0) AND ("char_length"(TRIM(BOTH FROM "ftp_utilizador")) <= 255))),
    CONSTRAINT "via_verde_contas_nome_len_check" CHECK ((("char_length"(TRIM(BOTH FROM "nome_conta")) >= 1) AND ("char_length"(TRIM(BOTH FROM "nome_conta")) <= 120))),
    CONSTRAINT "via_verde_contas_sync_email_len_check" CHECK ((("char_length"(TRIM(BOTH FROM "sync_email")) >= 3) AND ("char_length"(TRIM(BOTH FROM "sync_email")) <= 255)))
);


ALTER TABLE "public"."via_verde_contas" OWNER TO "postgres";


